INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-62504d3c56', 'p-b5bd663dcf', 'orchestrator-p2', 'Make mcp-orchestration production-grade per owner directives: (1) fleet tracing - workers report via worker_report, leader verifies in track history, paseo notifyOnFinish wakes leader; (2) enforceable knowledge lifecycle (lesson_add, OKF v0.2); (3) MCP resources for cheap resume; (4) quota-aware automation (usage auto-poll once PASEO_PASSWORD provided); (5) backend hardening (REST auth token). Priority order per owner.', 'ddvnguyen/LLM-Agents-Orchestration', 'main', 'active', '{"agent_id": "4774f61c-0dca-4331-9a91-46e0ee32b238", "model": "opencode-go/mimo-v2.6-flash", "harness": "omp", "contract_version": "0.0.1", "signed_at": "2026-09-30T15:20:56.569Z", "model_verified": true, "override_reason": null}', '{"checkup_id": null, "deep_id": "cabf0f13", "confirmed_at": "2026-10-03T17:31:31.780Z", "schedule_id": null, "orchestrator_checkup_id": null, "generation_started_at": null, "digest_last_written_at": null}', '{"state": "completed", "from_agent": "f402afc7-55ed-4284-913b-8f576642bf5d", "to_agent": "4774f61c-0dca-4331-9a91-46e0ee32b238", "reason": "User-directed takeover of leader work from f402afc7-55ed-4284-913b-8f576642bf5d", "started_at": "2026-09-30T15:20:49.142Z", "completed_at": "2026-09-30T15:20:56.569Z"}', '{}', '{}', 374, '2026-09-02T14:39:43.298Z', '2026-10-03T17:32:48.604Z');
INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-a4d9544ed8', 'p-b5bd663dcf', 'lead-contract-v2.2.0', 'Lead contract v2.2.0 (owner directives): (1) fleet model constraint — LEADER=command_code/z-ai/glm-5.3-flash, ALL subagents (dev/QA/review)=command_code/minimax/minimax-m3-free, CONSULT carve-out=claude tier; (2) simplify install for all harness providers to thin POINTER stubs with orchestration/ as the single source of truth (no content copies); (3) enforce knowledge lifecycle — seeded Lessons.md + lessons/ (OKF v0.2 / Karpathy wiki), new references/docs-wiki.md, KNOWLEDGE: clause in the final-summary contract. Deliverable: commit + push to branch feat/lead-contract-v2.1 (PR #19) and verify the PR carries v2.2.0.', 'ddvnguyen/LLM-Agents-Orchestration', 'feat/lead-contract-v2.1', 'active', NULL, '{"checkup_id": null, "deep_id": null, "confirmed_at": null}', '{"state": "none", "from_agent": null, "to_agent": null, "reason": "", "started_at": null, "completed_at": null}', '{}', '{}', 0, '2026-09-11T17:03:30.587Z', '2026-09-11T17:04:47.504Z');
