INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-d94162d3f0', 'p-58c3ab092b', 'colibri-atlas-771', 'Port Colibri expert-observability stack (Brain page #126, Atlas labels/#175 probe methodology) into ddvnguyen/llama.cpp fork branch baseline-qwen4exp-mtp as the Hydra LLM engine: env-gated expert telemetry (HYDRA_EXPERT_STATS), RPC 0x33 EXPERT_META + GET /experts, offline artifacts experts.json + expert-ranks.json (dual-score heat + reap_saliency, REAP-style ranking never-removed tier-to-RAM), atlas-web service in parent repo, Hydra Core/Head integration. Scoping invariant: observability + artifacts only, no routing policy change, default-off env-gated.', 'ddvnguyen/hydra_vortex', '771-colibri-expert-atlas', 'archived', '{"agent_id": "34364388-dca6-49d4-a643-0d4c161825d0", "model": "opencode-go/muse-spark-1.3-contributor", "harness": "omp", "contract_version": "0.0.1", "signed_at": "2026-09-20T03:44:09.191Z", "model_verified": false, "override_reason": "Owner-directed handoff 2026-09-20: new lead is this paseo session (muse-spark-1.3-contributor); architect 5c3486e5 initiated handoff pending to this agent. Requesting allowlist override to complete the pending handoff."}', '{"checkup_id": "ec17c603", "deep_id": "bf17ad7c", "confirmed_at": "2026-09-20T03:44:25.980Z"}', '{"state": "completed", "from_agent": "5c3486e5-c962-4be8-a963-22d3fa7236be", "to_agent": "34364388-dca6-49d4-a643-0d4c161825d0", "reason": "owner-directed handoff to new lead per 2026-09-20 directive", "started_at": "2026-09-20T03:43:57.377Z", "completed_at": "2026-09-20T03:44:09.191Z"}', '{}', '{}', 157, '2026-09-17T14:41:43.345Z', '2026-09-23T04:04:47.514Z');
