INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-34d7bdf5d6', 'p-7719544617', '787-per-turn-telemetry', 'S-E1 Hydra registration + live capture E2E on P100 (Wave D, fork+parent). Build sm60 at merged SHA b975d87b1, HYDRA_EXPERT_CAPTURE=1, decode probes, flush, analyze. Document geometry KV requirement. Parent lane: node YAML + workers.json E2E.', 'showy-termite', 'epic/787-per-turn-telemetry', 'active', '{"agent_id": "a572d1d1-ff0a-4988-9594-480f05d7cbdf", "model": "z-ai/glm-5.3-flash", "harness": "omp", "contract_version": "0.0.1", "signed_at": "2026-09-26T15:14:41.983Z", "model_verified": false, "override_reason": "Owner directive 2026-09-26 (d-806eef7490 precedent): \"handoff current track to new leader using paseo tool with freebuff account #04 and model glm 5.3 flash\". Incoming leader a572d1d1 (freebuff plugin, z-ai/glm-5.3-flash) completing pending handoff from 5fff297b on track t-34d7bdf5d6."}', '{"checkup_id": "621f4ccc", "deep_id": "a39ea34c", "confirmed_at": "2026-09-26T15:15:04.830Z", "schedule_id": null, "orchestrator_checkup_id": null, "generation_started_at": null}', '{"state": "completed", "from_agent": "5fff297b-9fcc-415b-8bd6-c34d9b7086e6", "to_agent": "a572d1d1-ff0a-4988-9594-480f05d7cbdf", "reason": "Redirect handoff to concrete successor session: a572d1d1-ff0a-4988-9594-480f05d7cbdf (freebuff-plugin account #04, z-ai/glm-5.3-flash), created per owner directive.", "started_at": "2026-09-26T15:10:30.930Z", "completed_at": "2026-09-26T15:14:41.983Z"}', '{}', '{}', 62, '2026-09-20T12:04:28.106Z', '2026-09-28T04:25:21.104Z');
INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-abf10888f3', 'p-b5bd663dcf', 'freebuff-acp-paseo', 'Make the Freebuff ACP provider production-grade inside Paseo (ddvnguyen/paseo, packages/freebuff-acp + plugins/freebuff, PR #21). Order per owner: (1) narrow turn-by-turn code review of the adapter (turn 1 seat admission/release done; 2 agent.ts+accounts.ts; 3 requireApproval host change; 4 Stage 6 workflow + quota provider), fixing findings (probe-failure must be ''unknown seat'', not ''no seat''); (2) then implement the queue: LLM-Agents-Orchestration#40 remaining steps (e2e acceptance tests, host/auth verification, shutdown/recovery) and #41 Freebuff settings page (add account, account status, CLI settings). Constraints: dev only in the orchestration repo folder (worktrees/paseo-freebuff); Freebuff dev/review agents run on acct2 glm-5.3-flash from a clean workspace (/tmp/fbcwd) because dead MCP servers in repo .agents/mcp.json abort Freebuff runs; PROD daemon deploy needs owner approval (drops agents). State: adapter release 08a17bfe4 (fork SDK, resume fix) live on TEST and PROD adapter path; PROD daemon still 0.9.2-hub-2339924d4.', 'ddvnguyen/paseo', 'feat/freebuff-plugin', 'active', '{"agent_id": "14fe3d01-2197-4583-ae27-83b16e1acb96", "model": "command_code/z-ai/glm-5.3-flash", "harness": "omp", "contract_version": "0.0.1", "signed_at": "2026-09-26T15:34:12.818Z", "model_verified": true, "override_reason": null}', '{"checkup_id": "2aad08c6", "deep_id": "d63a7b98", "confirmed_at": "2026-09-26T15:34:36.791Z", "schedule_id": null, "orchestrator_checkup_id": null, "generation_started_at": null}', '{"state": "completed", "from_agent": "90df864d-21ce-4a6d-ac28-51116fc39fa4", "to_agent": "14fe3d01-2197-4583-ae27-83b16e1acb96", "reason": "Owner directive 2026-09-26: hand off the Freebuff leader role to a fresh freebuff GLM 5.3 agent on account #05 (agent 14fe3d01). Handoff brief embedded in its initial prompt: deploy verification of pipeline 36251838727 @ 4e0686f47 (requirements.paseo >=0.9.2-0 fix), BETA web, TEST verification pass, then the F1-F8 queue per d-6f77fc7963. Outgoing leader 90df864d will idle after the successor registers.", "started_at": "2026-09-26T15:30:15.667Z", "completed_at": "2026-09-26T15:34:12.818Z"}', '{}', '{}', 32, '2026-09-25T00:31:54.734Z', '2026-09-28T10:03:30.859Z');
INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-f3ba82ac9c', 'p-b5bd663dcf', 'paseo-customize', 'Paseo customization lane in ddvnguyen/paseo (plugin-first, upstream-merge-safe): (1) agent Trajectory view with dsh parity (plugins/trajectory: recorder + sequenced event log + ledger UI) and an agent-header button that opens it; (2) merge of the paseo-fleet work of TEST agent 3f3f86fd (branch feat/paseo-fleet-plugin, PR #44) minus its custom parts, with its review findings fixed; (3) later: managed orchestration view, chat context-inject info, agent-to-agent vs user-to-agent distinction. Works in parallel with track t-abf10888f3 (freebuff-acp): follow lane rules in decision d-12a0c8b77a there (file ownership, separate branches/worktrees, shared-file announcements, leader-only deploys per full SHA, TEST first, PROD needs owner approval).', 'ddvnguyen/paseo', 'feat/trajectory-plugin', 'active', '{"agent_id": "787b4912-a127-44b9-b0d2-bd881c5c1a0b", "model": "opencode/fledge-alpha-free", "harness": "omp", "contract_version": "0.0.1", "signed_at": "2026-10-03T14:07:51.956Z", "model_verified": false, "override_reason": "owner picked this agent directly 2026-10-03"}', '{"checkup_id": null, "deep_id": "0cb68187", "confirmed_at": "2026-10-03T00:50:30.137Z", "schedule_id": null, "orchestrator_checkup_id": null, "generation_started_at": null, "digest_last_written_at": null, "checkup_history": []}', '{"state": "completed", "from_agent": "b7bec94b-5394-453f-987a-6cb49107ad71", "to_agent": "787b4912-a127-44b9-b0d2-bd881c5c1a0b", "reason": "owner 2026-10-03: leadership transfer to 787b4912 (opencode/fledge-alpha-free)", "started_at": "2026-10-03T14:07:46.803Z", "completed_at": "2026-10-03T14:07:51.956Z"}', '{"dev_model": "opencode-go/space-bunny-free"}', '{"dev_model": {"evidence": "start using opencode-go/space-bunny-free as your dev model", "a