INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-a124729a8a', 'p-b5bd663dcf', 'paseo-customize', 'Read-only audit: compare the trajectory ledger render list in the paseo fork (plugins/trajectory client) against dsh''s ui-trajectory render list, and answer whether lazy rendering is implemented such that a large/merged agent history still renders well. Deliverable = gap inventory + verdict + concrete fix plan. No code until owner approves.', 'ddvnguyen/paseo', 'feat/trajectory-plugin', 'active', '{"agent_id": "e6e9642e-6e48-4b67-8773-3dd3967b9f1a", "model": "opencode-go/space-bunny-free", "harness": "opencode", "contract_version": "0.0.1", "signed_at": "2026-09-28T14:39:24.726Z", "model_verified": false, "override_reason": "Live user directive 2026-09-28: dispatch /epic-track-leader for a read-only render-list audit (no model named). The running model is recorded as-is rather than substituting an allowed leader model, so the ledger shows the model that actually executed. Disclosed to owner in the turn report."}', '{"checkup_id": null, "deep_id": null, "confirmed_at": null, "schedule_id": null, "orchestrator_checkup_id": null, "generation_started_at": null, "digest_last_written_at": null, "checkup_history": []}', '{"state": "none", "from_agent": null, "to_agent": null, "reason": "", "started_at": null, "completed_at": null}', '{}', '{}', 36, '2026-09-28T14:38:56.757Z', '2026-10-03T17:06:12.639Z');
INSERT INTO orch_tracks(id, project_id, epic, goal, repo, branch, status, leader_binding, heartbeats, handoff, overrides, overrides_provenance, turn_count, created_at, updated_at) VALUES('t-1d514bb795', 'p-faa757b48d', 'orchestrator-collector', 'System-owned state for the ORCHESTRATOR collector: one track for all projects, holding this generation''s heartbeat binding and its wake count. Not a unit of work — the server refuses queue writes, worker reports and track closure on it, and it never takes a leader. It exists so the collector never writes into a leader''s track and inflates that leader''s turn_count and last_turn_age_s.', '', '', 'active', NULL, '{"checkup_id": null, "deep_id": null, "confirmed_at": null, "schedule_id": null, "orchestrator_checkup_id": "8e944c52", "generation_started_at": "2026-10-03T17:00:18.110Z", "digest_last_written_at": null, "checkup_history": ["8e63f989", "dd4d5754", "96ed402d", "4baa4de2", "4c65264c", "355567f1", "ae306a51", "887ff444", "bab8d71a", "641457d2", "4f5c6e65", "ede3a5a2", "8d1f08fb", "d2f14467", "dd08a80a", "8e944c52"]}', '{"state": "none", "from_agent": null, "to_agent": null, "reason": "", "started_at": null, "completed_at": null}', '{}', '{}', 0, '2026-09-30T17:00:22.292Z', '2026-10-03T17:00:18.111Z');
