INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-9de9ff8a13', 't-d94162d3f0', 'p-58c3ab092b', 'S-A2 exit dump + per-probe reset (.coli_usage triples)', '.coli_usage-compatible triples dump + per-probe reset affordance. Accept: dump consumes-unchanged by ported analyzer; reset supports snapshot/restore probe protocol.', 'gated', 'done', 100, '', '2026-09-17T14:47:58.003Z', '2026-09-20T12:02:12.972Z', '', '[]');
INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-4cc2f9648a', 't-d94162d3f0', 'p-58c3ab092b', 'S-B1 RPC 0x33 EXPERT_META + HTTP GET /experts', 'Binary op 0x33 on existing --rpc-port listener (0x3x range) + HTTP GET /experts; geometry + EMAP hex + hits bitmap; Colibri EMAP byte encoding verbatim (tier=byte>>6, heat=byte&63); geometry payload carries per-model mapping (dense prefix, MoE layers, NextN rows) so no model is hardcoded in UI. Env-gated no-op when telemetry off. Accept: curl + RPC client read same payload; OFF state returns clean geometry with zero counters.', 'gated', 'done', 100, '', '2026-09-17T14:47:58.017Z', '2026-09-17T17:05:16.035Z', '', '[]');
INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-bca3c3b5e2', 't-d94162d3f0', 'p-58c3ab092b', 'S-C1 probe harness port -> tools/expert-atlas/', 'Port of Colibri tools/expert_atlas/: probes.json from Colibri 10 categories; TOPP=0 greedy; MTP/draft off; per-probe reset; decode-only split; confound traps enforced by harness not memory. Accept: run on qwen4exp produces raw spectra.', 'gated', 'done', 100, '', '2026-09-17T14:47:58.033Z', '2026-09-19T17:26:49.676Z', '', '[]');
INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-2f45c12b54', 't-d94162d3f0', 'p-58c3ab092b', 'S-C2 atlas artifacts: experts.json + expert-ranks.json per-model', 'Per schema: experts.json (Colibri shape + spec/reliability/provenance); expert-ranks.json (per-layer hot-first lists, dual-score heat + reap_saliency, cold rule = low demand AND low removal-safety, exporter -> pin-file "L <il> <ids...>"). Provenance mandatory (model, engine_id, commit, probe set). Accept: leave-one-prompt-out validation >= chance-level separation reported; replication check.', 'gated', 'done', 100, '', '2026-09-17T14:47:58.046Z', '2026-09-19T17:26:49.699Z', '', '[]');
