INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-0d35b16283', 't-d94162d3f0', 'p-58c3ab092b', 'S-D1 atlas-web service in parent repo + Brain page port', 'Parent-repo separated service atlas-web/; Brain port (React, web/src/Brain.tsx + lib/api.ts from Colibri JustVugg/colibri#126); polls N engines; per-model mapping from Stage B geometry; tooltip = atlas lookup + weak qualifier below spec~0.7. Accept: visual verification against live rig (one engine, then multi-engine).', 'ready', 'done', 100, '', '2026-09-17T14:47:58.078Z', '2026-09-17T15:42:22.467Z', '', '[]');
