INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-2d1e69dd5b', 't-34d7bdf5d6', 'p-7719544617', 'Close-gate review of PR #789 (787-per-turn-telemetry)', 'Close-gate step 1: review PR #789 diff (epic/787-per-turn-telemetry -> main) against track goal acceptance: (a) S-E1 live capture E2E on P100 incl. n_embd sidecar fix, (b) geometry KV documented (expert_count/expert_used_count, dense exclusion), (c) Galaxy tab self-contained + tsc clean, (d) turn-record schema v2. Repo: ddvnguyen/hydra_vortex; worktree: /path/to/work/workspace/worktree/1q3ry0vb/showy-termite. PR healthy: MERGEABLE, checks green, 39 commits, 61 files.', 'ready', 'done', 100, '554dec00-a67c-48f6-9162-bfa2b535868c', '2026-09-26T06:54:04.071Z', '2026-09-26T07:32:46.742Z', '', '[]');
INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-182c0b78c5', 't-34d7bdf5d6', 'p-7719544617', 'Profiling: full Colibri upstream parity (fork instrumentation + #803 UI)', 'Port full Colibri upstream Profiling feature set to the fork + #803 UI, as owner-directed (main developer). Scope: (1) Fork instrumentation — graph-section phase timing events (attention / expert matmul / lm head / other / I-O wait) so /profile serves real phases instead of honest zeros; per-layer and per-expert profiling hooks feeding /turns/:seq records. (2) UI — full upstream parity on the Profiling tab: per-layer breakdown, per-expert profiling view, KV/disk-service detail, comparisons. Current state: 74-75% ''Other'' bucket (uninstrumented), minimal turn table. Sequencing: fork instrumentation first (phases), then UI parity layers, then per-expert views.', 'gated', 'running', 12, '', '2026-09-26T14:31:32.409Z', '2026-09-26T14:41:56.001Z', '', '[]');
