INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-a74b032852', 't-d1cf43b723', 'p-7719544617', 'C1 arm: isolate --decode-overlap value (no MTP)', 'Arm: --cpu-moe + --decode-overlap, NO MTP, everything else identical to arm000. Compare vs arm000 (21.23 t/s) and a --cpu-moe-only control on the SAME binary. Same-binary controls only, never across builds. Report tok/s + usual dispatch counters. BLOCKING: report the number to leader before any surgery; if decode-overlap ~= worthless, STOP before Task 2.', 'ready', 'done', 100, '', '2026-09-16T14:17:55.546Z', '2026-09-16T15:08:08.060Z', '', '[]');
