INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-ec7dae4b31', 't-62504d3c56', 'p-b5bd663dcf', 'P2-6 summary validator anti-repetition guard', 'Smoke-test orchestration.md padded ''Recent Progress'' 4x to clear MD_TOKEN_MIN=4000 - cheap summarizers loop instead of padding honestly. Add near-duplicate block/line detection to validate.py (shingle or normalized-line repeat ratio) that rejects summaries with >30% repeated blocks; consider whether floor should drop to 2k. Owner contract note: floor is contract-set, so flag before changing the constant.', 'ready', 'done', 100, 'ad76cfb6-632d-4af8-b161-d0e2ba2935fc', '2026-09-02T15:30:07.775Z', '2026-09-02T16:33:37.323Z', '', '[]');
