INSERT INTO orch_tasks(id, track_id, project_id, title, detail, gate, status, progress, assignee, added_at, updated_at, note, detail_amendments) VALUES('task-91fa40c940', 't-62504d3c56', 'p-b5bd663dcf', 'P2-9 suggestion flow fleet->leader', 'suggestion_add (any fleet role): kind lesson|reference|process + title/body/tags -> pending; suggestion_review by leader approve/reject; approve+lesson -> auto lesson_add; approve+reference -> writes references/<slug>.md; decision trail in events', 'ready', 'done', 100, 'feee5bb8-cecf-4c8d-b52b-d13634f3caa1', '2026-09-02T15:40:26.402Z', '2026-09-02T16:01:59.475Z', '', '[]');
