INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1225, 'p-7719544617', 't-d1cf43b723', '2026-09-20T03:43:56.714Z', 'Phase 2 launch required 3 verify fixes (instrument, not physics): (1) ncmoe emits no -ot override lines initially assumed — it DOES emit override lines but buffer type is CUDA_Host not CPU; (2) dose assert must count CUDA_Host expert layers: 48 for dose-0 OT legs, 48-exp for ncmoe (MP4: 44x6=264 overrides verified); (3) CUDA_VISIBLE_DEVICES=1 means the 3060 is CUDA0 in-process, no CUDA1 exists. Also killed orphaned leg/server from cancelled jobs (lesson reinforced: cancel mid-leg leaves leg-script children running). Phase 2 now RUNNING clean: MP4 x5 (dose verified), MP4off, REPRO @81920 x5, REPROoff.', 'running', '["verify regex fixed (CUDA_Host, dose-aware)", "phase 2 running"]', '["phase 2 results -> P_max comparison + REPRO attribution"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '0082a065-08b4-49fa-bd6e-5333e1ec31ba', '', '{"n": 1225, "ts": "2026-09-20T03:43:56.714Z", "summary": "Phase 2 launch required 3 verify fixes (instrument, not physics): (1) ncmoe emits no -ot override lines initially assumed — it DOES emit override lines but buffer type is CUDA_Host not CPU; (2) dose assert must count CUDA_Host expert layers: 48 for dose-0 OT legs, 48-exp for ncmoe (MP4: 44x6=264 overrides verified); (3) CUDA_VISIBLE_DEVICES=1 means the 3060 is CUDA0 in-process, no CUDA1 exists. Also killed orphaned leg/server from cancelled jobs (lesson reinforced: cancel mid-leg leaves leg-script children running). Phase 2 now RUNNING clean: MP4 x5 (dose verified), MP4off, REPRO @81920 x5, REPROoff.", "status": "running", "done": ["verify regex fixed (CUDA_Host, dose-aware)", "phase 2 running"], "next": ["phase 2 results -> P_max comparison + REPRO attribution"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "0082a065-08b4-49fa-bd6e-5333e1ec31ba", "author_model": ""}');
