INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1466, 'p-7719544617', 't-d1cf43b723', '2026-09-27T17:53:12.564Z', '[#Leader] DEEP TICK - 3060 is Gen1 x4 UNDER LOAD (30/30 samples at 100% util). NOT ASPM (policy [default]; 5060 Ti trains to gen=5 under load). Card max Gen4 x16 => a BIOS CONFIG state, not hardware. So the 3060 is PCIe-limited and residency N is its ONLY decode lever: owner''s thesis vindicated for a LINK reason, architect''s ''depth-limited'' premise superseded. d-255055e394 conflated width (real) with generation (BIOS, not a purchase) => OWNER re-opens. Self-correction: ''PCIe is not the wall'' was 5060 Ti-only; the bound is device-asymmetric. Worker bytes 1.831 MiB/slab vs 2.148 assumed, closing the 09-16 discrepancy and my Q4. Rig idle.', 'running', '["PCIe gate measured by leader; ASPM ruled out; d-255055e394 premise-falsified, no BIOS/purchase touched", "Bytes reconciled 1.831 vs 2.148; bytes-h now primary", "Rig cleaned; dev lane recovered (cell d8k-n28, CHECKPOINT.md); heartbeat replaced on new owner spec"]', '["DEFERRED visibly: orchestration.md rebuild - top item at the 18:00 tick", "Grid continues, Gen1 x4 constant, FAIL rule unchanged", "OWNER: re-open d-255055e394, check host BIOS PCIe speed/bifurcation (~16x headroom)"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1466, "ts": "2026-09-27T17:53:12.564Z", "summary": "[#Leader] DEEP TICK - 3060 is Gen1 x4 UNDER LOAD (30/30 samples at 100% util). NOT ASPM (policy [default]; 5060 Ti trains to gen=5 under load). Card max Gen4 x16 => a BIOS CONFIG state, not hardware. So the 3060 is PCIe-limited and residency N is its ONLY decode lever: owner''s thesis vindicated for a LINK reason, architect''s ''depth-limited'' premise superseded. d-255055e394 conflated width (real) with generation (BIOS, not a purchase) => OWNER re-opens. Self-correction: ''PCIe is not the wall'' was 5060 Ti-only; the bound is device-asymmetric. Worker bytes 1.831 MiB/slab vs 2.148 assumed, closing the 09-16 discrepancy and my Q4. Rig idle.", "status": "running", "done": ["PCIe gate measured by leader; ASPM ruled out; d-255055e394 premise-falsified, no BIOS/purchase touched", "Bytes reconciled 1.831 vs 2.148; bytes-h now primary", "Rig cleaned; dev lane recovered (cell d8k-n28, CHECKPOINT.md); heartbeat replaced on new owner spec"], "next": ["DEFERRED visibly: orchestration.md rebuild - top item at the 18:00 tick", "Grid continues, Gen1 x4 constant, FAIL rule unchanged", "OWNER: re-open d-255055e394, check host BIOS PCIe speed/bifurcation (~16x headroom)"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1467, 'p-7719544617', 't-d1cf43b723', '2026-09-27T17:55:57.312Z', 'PCIe GATE: accepted as settled by the leader''s measurement (3060 Gen1 x4, 30/30 in-flight). I did not re-measure or re-litigate it. CHECKPOINT.md rewritten with the settled constant, the capacity law (1.831 MiB/expert-slab vs ledger 2.148), the family split (down 48.0/up 27.3/gate 24.7%) and bytes-h-as-primary. Q2 N-ladder RELAUNCHED under setsid (driver pid 947631, cell d8k-n28 loading). Per-cell now records: N, depth, tok/s with n/sd/spread, family-weighted bytes-h PRIMARY + count-h alongside, MiB/token, achieved MB/s, slab MiB, link state, loaded/dropped-reason. Also fixed: TERM-ignored -> explicit SIGKILL + both-GPU idle assertion before a cell is called done. No grid numbers yet; 8K row is ~20 min/cell. Rig idle on exit.', 'running', '[]', '[]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '6a24a038-c371-4830-9b2a-84a8a55f1289', 'opencode-go/space-bunny-free', '{"n": 1467, "ts": "2026-09-27T17:55:57.312Z", "summary": "PCIe GATE: accepted as settled by the leader''s measurement (3060 Gen1 x4, 30/30 in-flight). I did not re-measure or re-litigate it. CHECKPOINT.md rewritten with the settled constant, the capacity law (1.831 MiB/expert-slab vs ledger 2.148), the family split (down 48.0/up 27.3/gate 24.7%) and bytes-h-as-primary. Q2 N-ladder RELAUNCHED under setsid (driver pid 947631, cell d8k-n28 loading). Per-cell now records: N, depth, tok/s with n/sd/spread, family-weighted bytes-h PRIMARY + count-h alongside, MiB/token, achieved MB/s, slab MiB, link state, loaded/dropped-reason. Also fixed: TERM-ignored -> explicit SIGKILL + both-GPU idle assertion before a cell is called done. No grid numbers yet; 8K row is ~20 min/cell. Rig idle on exit.", "status": "running", "done": [], "next": [], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "6a24a038-c371-4830-9b2a-84a8a55f1289", "author_model": "opencode-go/space-bunny-free"}');
