INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1469, 'p-7719544617', 't-d1cf43b723', '2026-09-27T18:26:56.757Z', '[#Leader] DEEP TICK v3 - read both cells directly, HALTED the ladder. Defect 1: h2d_bytes divided by plan_calls=1350, but probes asked 4x64=256 tokens at MTP mean len ~3 (~85 steps), so the counter spans prefill AND decode - bytes-h, the PRIMARY metric, is not computable. Defect 2: probes measure overhead (4-token prompt = 5.5s). UNEXPLAINED: decode 0.59-0.67 t/s vs historical 10.52-12.42 t/s at 53K depth, at 1/10th the depth. AMENDED my own d-a2e5620c47: ''residency is the only lever'' is config-conditional - this cell carried ~5.7 MB/s vs the 573 MB/s ceiling, so the link was not binding. Gen1 x4 stands (664/664 in-flight). Cache clean, MTP 0.92-0.97. Rig dirty a 3rd time, SIGKILL''d.', 'blocked', '["Read both cell artifacts; halted before ~17h of unjudgeable cells", "2 instrument defects; 16-20x gap flagged; flag diff ordered", "Amended d-a2e5620c47; rig reclaimed, verified idle"]', '["Worker: flag diff vs the 10.52 t/s cell, then ONE corrected d8k-n28 re-run", "No ladder resume until both resolve", "OWNER: re-open d-255055e394; merge #808+#159, then PROJECT_STATUS.md"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1469, "ts": "2026-09-27T18:26:56.757Z", "summary": "[#Leader] DEEP TICK v3 - read both cells directly, HALTED the ladder. Defect 1: h2d_bytes divided by plan_calls=1350, but probes asked 4x64=256 tokens at MTP mean len ~3 (~85 steps), so the counter spans prefill AND decode - bytes-h, the PRIMARY metric, is not computable. Defect 2: probes measure overhead (4-token prompt = 5.5s). UNEXPLAINED: decode 0.59-0.67 t/s vs historical 10.52-12.42 t/s at 53K depth, at 1/10th the depth. AMENDED my own d-a2e5620c47: ''residency is the only lever'' is config-conditional - this cell carried ~5.7 MB/s vs the 573 MB/s ceiling, so the link was not binding. Gen1 x4 stands (664/664 in-flight). Cache clean, MTP 0.92-0.97. Rig dirty a 3rd time, SIGKILL''d.", "status": "blocked", "done": ["Read both cell artifacts; halted before ~17h of unjudgeable cells", "2 instrument defects; 16-20x gap flagged; flag diff ordered", "Amended d-a2e5620c47; rig reclaimed, verified idle"], "next": ["Worker: flag diff vs the 10.52 t/s cell, then ONE corrected d8k-n28 re-run", "No ladder resume until both resolve", "OWNER: re-open d-255055e394; merge #808+#159, then PROJECT_STATUS.md"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
