INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1471, 'p-7719544617', 't-d1cf43b723', '2026-09-27T18:50:17.126Z', '[#Leader] DEEP TICK v4 - HEADLINE: MTP COSTS 2x THROUGHPUT DESPITE ~95% ACCEPTANCE. No-MTP arm: decode 1.321/1.317/1.324 t/s (n=3) vs 0.648 with MTP. Acceptance 0.92-0.97, mean len 2.89-3.25, so NOT low-acceptance. Likely cause: draft head on CPU (--spec-draft-ngl 0) competing for the same -t 6 threads. p50_gap_ms flipped 0.05-0.21 to 742-751 - scheduling, not accuracy. This is a defect in the SERVED profile. FLAG DIFF: MTP is the ONLY material difference (historical cell had no MTP flags); -t 6 confirmed IDENTICAL both. THIRD CORRECTION OF MINE, accepted: the 10463 vs 7387 MiB VRAM gap is the -c difference (~1.99 GiB KV + GDN state), not placement - and the cache delta runs the OPPOSITE way. Withdrawn. ngl99 cell authorised; ladder halted. Residual ~8x gap unexplained.', 'running', '["Confirmed MTP 2x cost (0.648 -> 1.321 t/s); flag diff isolates MTP as the sole difference", "Withdrew my own VRAM-placement claim; ladder halted pending ngl99"]', '["Worker: ngl99 cell to separate ''MTP harmful'' from ''ngl=0 harmful''", "Residual ~8x gap: suspect sustained-vs-probe mismatch, not hardware", "OWNER: MTP may be net-harmful; re-open d-255055e394; merge #808+#159 then PROJECT_STATUS.md"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1471, "ts": "2026-09-27T18:50:17.126Z", "summary": "[#Leader] DEEP TICK v4 - HEADLINE: MTP COSTS 2x THROUGHPUT DESPITE ~95% ACCEPTANCE. No-MTP arm: decode 1.321/1.317/1.324 t/s (n=3) vs 0.648 with MTP. Acceptance 0.92-0.97, mean len 2.89-3.25, so NOT low-acceptance. Likely cause: draft head on CPU (--spec-draft-ngl 0) competing for the same -t 6 threads. p50_gap_ms flipped 0.05-0.21 to 742-751 - scheduling, not accuracy. This is a defect in the SERVED profile. FLAG DIFF: MTP is the ONLY material difference (historical cell had no MTP flags); -t 6 confirmed IDENTICAL both. THIRD CORRECTION OF MINE, accepted: the 10463 vs 7387 MiB VRAM gap is the -c difference (~1.99 GiB KV + GDN state), not placement - and the cache delta runs the OPPOSITE way. Withdrawn. ngl99 cell authorised; ladder halted. Residual ~8x gap unexplained.", "status": "running", "done": ["Confirmed MTP 2x cost (0.648 -> 1.321 t/s); flag diff isolates MTP as the sole difference", "Withdrew my own VRAM-placement claim; ladder halted pending ngl99"], "next": ["Worker: ngl99 cell to separate ''MTP harmful'' from ''ngl=0 harmful''", "Residual ~8x gap: suspect sustained-vs-probe mismatch, not hardware", "OWNER: MTP may be net-harmful; re-open d-255055e394; merge #808+#159 then PROJECT_STATUS.md"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
