INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1472, 'p-7719544617', 't-d1cf43b723', '2026-09-27T19:02:09.759Z', '[#Leader] DEEP TICK v5 - PER-EXPERT VRAM COST MEASURED CLEANLY; IT CONFIRMS RATHER THAN CORRECTS. d8k-n42-nomtp gives a second N point at the SAME ctx as d8k-n28-nomtp (both c=8192, no-MTP) - the uncontaminated N-derivative, since the earlier pair was ctx-confounded. N=28 -> 6941 MiB, N=42 -> 8111 MiB, slope 83.6 MiB/N-unit = 1.741 MiB per (expert,layer). Model: BASE + N x 83.6, base ~4600 MiB, reproduces N=42 exactly. The worker''s 1.831 is within 5% of the measured 1.741 - VALIDATED; the ledger''s 2.148 is ~19-23% too high. The earlier ''35-45%'' conflict was MY units error (marginal vs total including the base). PREDICTIVE: at c=81920, N=84 needs 13.6 GiB vs the 3060''s 12.0 - reproducing the historical OOM. CONSEQUENCE: 3060 max N at c=8192 is ~92, not ~57; sizing must be redone. ngl99 still owed.', 'running', '["Clean N-derivative: 1.741 MiB/(expert,layer), base ~4600 MiB, cache = N x 83.6; reproduces N=42 exactly; predicts the 80K OOM", "CONFIRMED worker''s 1.831 (within 5%); ledger 2.148 ~19-23% high; owned my units error"]', '["Worker: ngl99 owed, then re-size ladder (3060 max N ~92 at c=8192, not ~57)", "OWNER: MTP may be a 2x net loss; re-open d-255055e394; merge #808+#159 then PROJECT_STATUS.md"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1472, "ts": "2026-09-27T19:02:09.759Z", "summary": "[#Leader] DEEP TICK v5 - PER-EXPERT VRAM COST MEASURED CLEANLY; IT CONFIRMS RATHER THAN CORRECTS. d8k-n42-nomtp gives a second N point at the SAME ctx as d8k-n28-nomtp (both c=8192, no-MTP) - the uncontaminated N-derivative, since the earlier pair was ctx-confounded. N=28 -> 6941 MiB, N=42 -> 8111 MiB, slope 83.6 MiB/N-unit = 1.741 MiB per (expert,layer). Model: BASE + N x 83.6, base ~4600 MiB, reproduces N=42 exactly. The worker''s 1.831 is within 5% of the measured 1.741 - VALIDATED; the ledger''s 2.148 is ~19-23% too high. The earlier ''35-45%'' conflict was MY units error (marginal vs total including the base). PREDICTIVE: at c=81920, N=84 needs 13.6 GiB vs the 3060''s 12.0 - reproducing the historical OOM. CONSEQUENCE: 3060 max N at c=8192 is ~92, not ~57; sizing must be redone. ngl99 still owed.", "status": "running", "done": ["Clean N-derivative: 1.741 MiB/(expert,layer), base ~4600 MiB, cache = N x 83.6; reproduces N=42 exactly; predicts the 80K OOM", "CONFIRMED worker''s 1.831 (within 5%); ledger 2.148 ~19-23% high; owned my units error"], "next": ["Worker: ngl99 owed, then re-size ladder (3060 max N ~92 at c=8192, not ~57)", "OWNER: MTP may be a 2x net loss; re-open d-255055e394; merge #808+#159 then PROJECT_STATUS.md"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
