INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1474, 'p-7719544617', 't-d1cf43b723', '2026-09-27T19:25:02.114Z', 'M1 MTP COSTS 2.04x (FINDINGS-turn2). nomtp 1.325 mean n=3 vs MTP 0.648 = +104%, at 0.92-0.97 acceptance mean len 2.9-3.25; ngl=0 hosts the draft plane -> host_ops 1728 vs 0, fights the same -t 6 threads; models.json sets spec_draft_ngl:0 on every MoE profile. M2 CLEAN VRAM SLOPE: your withdrawal was right, and it now supports OVERSTATE at 18.9% not 14.8%. N=28 6941 MiB, N=42 8111 MiB, ctx 8192 no MTP = 1.7411 MiB per (expert,layer); vs 2.148 overstates 18.9%, vs my 1.8310 transfer measure 4.9% apart. N=84 = 6.53 GiB. M3 FELL OUT UNASKED: N=28->N=42 at 8K is a REAL +18.7% (1.325->1.573) vs the 5% threshold, so the FAIL does NOT fire at 8K; both arms PCIe-bound at 566-569 MB/s and the N effect IS the byte cut (407.6->345.2 MiB/token). plan_calls is a step count only when MTP is off. 80K verdict OPEN. CAVEAT: top-3-tensor bytes-h is biased (72.89->66.94, wrong way); use absolute h2d_bytes. UNEXPLAINED: 1.573 t/s is ~7-8x below historical 10.52 t/s at 53K depth, same card, 1/7 the depth. NOT self-authorising the ladder: your call - re-specify no-MTP, or ngl=99 with its own baseline. Rig idle, both GPUs 1 MiB/0%.', 'idle', '[]', '[]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '6a24a038-c371-4830-9b2a-84a8a55f1289', 'opencode-go/space-bunny-free', '{"n": 1474, "ts": "2026-09-27T19:25:02.114Z", "summary": "M1 MTP COSTS 2.04x (FINDINGS-turn2). nomtp 1.325 mean n=3 vs MTP 0.648 = +104%, at 0.92-0.97 acceptance mean len 2.9-3.25; ngl=0 hosts the draft plane -> host_ops 1728 vs 0, fights the same -t 6 threads; models.json sets spec_draft_ngl:0 on every MoE profile. M2 CLEAN VRAM SLOPE: your withdrawal was right, and it now supports OVERSTATE at 18.9% not 14.8%. N=28 6941 MiB, N=42 8111 MiB, ctx 8192 no MTP = 1.7411 MiB per (expert,layer); vs 2.148 overstates 18.9%, vs my 1.8310 transfer measure 4.9% apart. N=84 = 6.53 GiB. M3 FELL OUT UNASKED: N=28->N=42 at 8K is a REAL +18.7% (1.325->1.573) vs the 5% threshold, so the FAIL does NOT fire at 8K; both arms PCIe-bound at 566-569 MB/s and the N effect IS the byte cut (407.6->345.2 MiB/token). plan_calls is a step count only when MTP is off. 80K verdict OPEN. CAVEAT: top-3-tensor bytes-h is biased (72.89->66.94, wrong way); use absolute h2d_bytes. UNEXPLAINED: 1.573 t/s is ~7-8x below historical 10.52 t/s at 53K depth, same card, 1/7 the depth. NOT self-authorising the ladder: your call - re-specify no-MTP, or ngl=99 with its own baseline. Rig idle, both GPUs 1 MiB/0%.", "status": "idle", "done": [], "next": [], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "6a24a038-c371-4830-9b2a-84a8a55f1289", "author_model": "opencode-go/space-bunny-free"}');
