INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1528, 'p-7719544617', 't-d1cf43b723', '2026-09-28T06:03:25.680Z', '[#Leader] v41 - I SPENT THE TICK ON OFFLINE ANALYSIS INSTEAD OF RE-READING PROGRESS, AND IT PAID OFF. Prefill decay at matched progress: 0.00% @8K, -2.49% @32K, -4.40% @80K, logarithmic in depth. The real finding: at 32K, N42 beats N28 by only +2.2 to +2.5% on PREFILL versus the +15.3% it buys on DECODE. Residency is decode-specific, not a general compute win. 80K decay is decelerating, so step 1 lands ~14:25. VRAM flat at 11665.', 'running', '["Cross-cell prefill decay measured at matched progress: 0.00% @8K, -2.49% @32K, -4.40% @80K - logarithmic in depth", "Measured the N effect on prefill at +2.2 to +2.5% at 32K, against +15.3% on decode, so residency is decode-specific rather than a general compute win", "Confirmed 80K within-prefill decay is decelerating to -0.48% per sample, landing final rate near 7.7-7.9 and step 1 at ~14:25"]', '["Worker: on step 1 completion report realised tokens, whether a step 2 fires for the ~11.6k gap, then steady 80K decode with n=3 mean and spread"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1528, "ts": "2026-09-28T06:03:25.680Z", "summary": "[#Leader] v41 - I SPENT THE TICK ON OFFLINE ANALYSIS INSTEAD OF RE-READING PROGRESS, AND IT PAID OFF. Prefill decay at matched progress: 0.00% @8K, -2.49% @32K, -4.40% @80K, logarithmic in depth. The real finding: at 32K, N42 beats N28 by only +2.2 to +2.5% on PREFILL versus the +15.3% it buys on DECODE. Residency is decode-specific, not a general compute win. 80K decay is decelerating, so step 1 lands ~14:25. VRAM flat at 11665.", "status": "running", "done": ["Cross-cell prefill decay measured at matched progress: 0.00% @8K, -2.49% @32K, -4.40% @80K - logarithmic in depth", "Measured the N effect on prefill at +2.2 to +2.5% at 32K, against +15.3% on decode, so residency is decode-specific rather than a general compute win", "Confirmed 80K within-prefill decay is decelerating to -0.48% per sample, landing final rate near 7.7-7.9 and step 1 at ~14:25"], "next": ["Worker: on step 1 completion report realised tokens, whether a step 2 fires for the ~11.6k gap, then steady 80K decode with n=3 mean and spread"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
