INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1557, 'p-7719544617', 't-d1cf43b723', '2026-09-28T12:46:22.854Z', '[#Leader] - OWNER INTERRUPTED: github.com/Niko1221/Strata runs the SAME 125B MoE base model on one 12-24GB card with experts in HOST RAM, decoding 60-90 tok/s where my 12GB 3060 gets 1.53. Chunk-amortised prefill (8192-token chunks, ring-streamed non-resident experts) is my leading hypothesis for part of the gap, explicitly not a conclusion. GPU untouched: probecheck is live. No LICENSE FILE exists.', 'running', '["Surveyed Niko1221/Strata: same 125B MoE base, C++, 733 stars, one 12-24GB card with experts in HOST RAM rather than VRAM", "Recorded a 40-50x decode gap against my 3060 while declining to diagnose it, since their largest single optimisation step is +23% and quantization is confounded", "Flagged chunk-amortised prefill as a HYPOTHESIS: chunked to 8192 with ring-streamed experts is +23% at chunk-size alone, and their longest prompts run faster per token while my rate falls within one prefill"]', '["After probecheck resolves, diff my moe-cache-mm telemetry against Strata''s cache-parity bench", "Worker: report all four 32K probes with a genuine PROBES_DONE"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1557, "ts": "2026-09-28T12:46:22.854Z", "summary": "[#Leader] - OWNER INTERRUPTED: github.com/Niko1221/Strata runs the SAME 125B MoE base model on one 12-24GB card with experts in HOST RAM, decoding 60-90 tok/s where my 12GB 3060 gets 1.53. Chunk-amortised prefill (8192-token chunks, ring-streamed non-resident experts) is my leading hypothesis for part of the gap, explicitly not a conclusion. GPU untouched: probecheck is live. No LICENSE FILE exists.", "status": "running", "done": ["Surveyed Niko1221/Strata: same 125B MoE base, C++, 733 stars, one 12-24GB card with experts in HOST RAM rather than VRAM", "Recorded a 40-50x decode gap against my 3060 while declining to diagnose it, since their largest single optimisation step is +23% and quantization is confounded", "Flagged chunk-amortised prefill as a HYPOTHESIS: chunked to 8192 with ring-streamed experts is +23% at chunk-size alone, and their longest prompts run faster per token while my rate falls within one prefill"], "next": ["After probecheck resolves, diff my moe-cache-mm telemetry against Strata''s cache-parity bench", "Worker: report all four 32K probes with a genuine PROBES_DONE"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
