INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(51, 'p-b5bd663dcf', 't-62504d3c56', '2026-09-28T14:00:30.935Z', 'Planned and queued track-status-since-X-minutes plus paging/time/type filtering for tasks, events and history as tasks A/B/C; owner chose additive new param with unchanged behaviour when unset.', 'idle', '["Researched the read/query surface: store helpers, event vocabulary, task model, tool schemas, and every exact-set test gate", "Delivered the plan with the three decisions that shape it (relative time, filter-before-slice, extend-before-mint)", "Queued task A (event vocabulary + since_iso helper) — gate ready", "Queued task B (store paging correctness + first test_store.py) — gate gated", "Queued task C (track_status since_minutes + task query + history fan-out) — gate gated"]', '["Execute A (independent, mergeable alone), then B, then C", "Confirm leadership before dispatching dev agents — this track''s registered leader is 57747c50-08c6-48a8-9442-aeaa0b92a134, not this session"]', '["Track t-62504d3c56 has a different registered leader; tasks were queued with the owner''s approval but no dev agent has been dispatched"]', '["Add the new param; when not supplied, run exactly as before (owner, 2026-09-28)", "New `recent` delta block rather than filtering existing top-level keys, to keep the test_server_clock contract pin intact", "No `task_list` tool: extend track_status, per docs/DESIGN.md:89-95", "Separate `decision_limit` (default 0 = all) so the lossless decision ledger is never truncated by default (d-7)", "Relative-time `since_minutes` computed server-side is the primary primitive, since age_seconds forbids caller-side timestamp arithmetic (issue #48)", "Filter-before-slice in both JSON and SQL branches; O(offset+limit) paging accepted, no cursor"]', '{"lesson_topic": null, "docs_updated": []}', 'space-bunny-free', 'opencode-go/space-bunny-free', '{"n": 51, "ts": "2026-09-28T14:00:30.935Z", "summary": "Planned and queued track-status-since-X-minutes plus paging/time/type filtering for tasks, events and history as tasks A/B/C; owner chose additive new param with unchanged behaviour when unset.", "status": "idle", "done": ["Researched the read/query surface: store helpers, event vocabulary, task model, tool schemas, and every exact-set test gate", "Delivered the plan with the three decisions that shape it (relative time, filter-before-slice, extend-before-mint)", "Queued task A (event vocabulary + since_iso helper) — gate ready", "Queued task B (store paging correctness + first test_store.py) — gate gated", "Queued task C (track_status since_minutes + task query + history fan-out) — gate gated"], "next": ["Execute A (independent, mergeable alone), then B, then C", "Confirm leadership before dispatching dev agents — this track''s registered leader is 57747c50-08c6-48a8-9442-aeaa0b92a134, not this session"], "blockers": ["Track t-62504d3c56 has a different registered leader; tasks were queued with the owner''s approval but no dev agent has been dispatched"], "decisions": ["Add the new param; when not supplied, run exactly as before (owner, 2026-09-28)", "New `recent` delta block rather than filtering existing top-level keys, to keep the test_server_clock contract pin intact", "No `task_list` tool: extend track_status, per docs/DESIGN.md:89-95", "Separate `decision_limit` (default 0 = all) so the lossless decision ledger is never truncated by default (d-7)", "Relative-time `since_minutes` computed server-side is the primary primitive, since age_seconds forbids caller-side timestamp arithmetic (issue #48)", "Filter-before-slice in both JSON and SQL branches; O(offset+limit) paging accepted, no cursor"], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "space-bunny-free", "author_model": "opencode-go/space-bunny-free"}');
INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1576, 'p-7719544617', 't-d1cf43b723', '2026-09-28T14:04:18.816Z', '[#Leader] v72: Retraction - the /tmp loss was the owner''s restart, not my 4G cap. tmpfs is RAM, so a reboot empties it regardless of cap size; the harness could never have survived a reboot on /tmp. That validates the new directive by the exact incident it was written to prevent.', 'running', '["Directive durable in CLAUDE.md + .gitignore and in my handoff; rebuilt scripts must derive their own root, not hardcode it", ".local/q2g absent, GPUs idle, 86.9 GB free; worker mid-rebuild, nothing launched; not re-prompting a mid-turn agent"]', '["Worker: rebuild at .local/q2g, pick the archived binary with the expert-cache path, then launch Job A (d64k-n42-5060ti-A)"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1576, "ts": "2026-09-28T14:04:18.816Z", "summary": "[#Leader] v72: Retraction - the /tmp loss was the owner''s restart, not my 4G cap. tmpfs is RAM, so a reboot empties it regardless of cap size; the harness could never have survived a reboot on /tmp. That validates the new directive by the exact incident it was written to prevent.", "status": "running", "done": ["Directive durable in CLAUDE.md + .gitignore and in my handoff; rebuilt scripts must derive their own root, not hardcode it", ".local/q2g absent, GPUs idle, 86.9 GB free; worker mid-rebuild, nothing launched; not re-prompting a mid-turn agent"], "next": ["Worker: rebuild at .local/q2g, pick the archived binary with the expert-cache path, then launch Job A (d64k-n42-5060ti-A)"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
