INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1585, 'p-7719544617', 't-d1cf43b723', '2026-09-28T15:01:16.379Z', '[#Leader] v77: t0003 BLOCKED, cause was my error. Strata built clean off /tmp but is a PLE/QSA research prototype, not a general MoE runtime: pretokenized token IDs not text, no pack converter, and its vendored llama.cpp at arg.cpp:564 reads only the first split while our model is split.count=6. I told the owner it was viable because their reader accepts qwen4exp and IQ1_S, but I jumped from quant support to model support without testing loadability.', 'running', '["Marked t0003 BLOCKED with first-split and no-converter evidence, attributed the cause to my own over-claim, kept the /mnt/SSD/strata clone since it is off /tmp and its parity harnesses are reusable", "Dispatched the t0002 unblocking read to the worker as CPU-only work, requiring file:line evidence on what N bounds, what the registered field counts, and the real N=42 streaming fraction", "Recorded trap (e): utilization.gpu stuck at 100% on GPU0 after SIGKILL while memory.used was 1 MiB and compute-apps empty - trust memory.used, utilization.memory and the compute-apps list"]', '["Worker: return N semantics, the registered-field meaning and the code-derived N=42 streaming fraction, then propose 35B arms without launching until approved"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b82111f4', 'opencode-go/space-bunny-free', '{"n": 1585, "ts": "2026-09-28T15:01:16.379Z", "summary": "[#Leader] v77: t0003 BLOCKED, cause was my error. Strata built clean off /tmp but is a PLE/QSA research prototype, not a general MoE runtime: pretokenized token IDs not text, no pack converter, and its vendored llama.cpp at arg.cpp:564 reads only the first split while our model is split.count=6. I told the owner it was viable because their reader accepts qwen4exp and IQ1_S, but I jumped from quant support to model support without testing loadability.", "status": "running", "done": ["Marked t0003 BLOCKED with first-split and no-converter evidence, attributed the cause to my own over-claim, kept the /mnt/SSD/strata clone since it is off /tmp and its parity harnesses are reusable", "Dispatched the t0002 unblocking read to the worker as CPU-only work, requiring file:line evidence on what N bounds, what the registered field counts, and the real N=42 streaming fraction", "Recorded trap (e): utilization.gpu stuck at 100% on GPU0 after SIGKILL while memory.used was 1 MiB and compute-apps empty - trust memory.used, utilization.memory and the compute-apps list"], "next": ["Worker: return N semantics, the registered-field meaning and the code-derived N=42 streaming fraction, then propose 35B arms without launching until approved"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b82111f4", "author_model": "opencode-go/space-bunny-free"}');
INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1, 'p-b5bd663dcf', 't-a124729a8a', '2026-09-28T15:01:30.877Z', 'Read-only render-list audit done. VERDICT: lazy render NOT implemented. (1) CORRECTNESS: trajectory.list SQL is ORDER BY seq ASC LIMIT 500 (node-store.ts:109) = OLDEST 500, but headSeq is MAX(seq) (node-store.ts:117, returned verbatim rpc.ts:37). Delta loop then polls afterSeq=MAX, gets 0 rows, parks (use-trajectory-delta.ts:80-93) - events 501..N never fetched, refresh re-runs the same loop. Ledger silently frozen on the oldest 500. (2) PERF: ledger-screen.tsx:303-314 passes NO getItemLayout/windowSize/maxToRenderPerBatch/removeClippedSubviews; the precomputed row height is dead (only write at :141; the sole getItemLayout mention in the plugin is a false comment at virtual-rows.ts:6). 6 full Theta(N) passes per append; fresh row objects defeat React.memo. TrajectoryTimelineStrip renders one View per record, non-virtualized. No load-older anywhere. Largest fixture 8 rows; FlatList mocked so virtualization is untested. dsh reference: tanstack useVirtualizer, a-priori 30/20/9px heights, useStableVirtualRowStructure, tail-page 50, 3s search throttle.', 'running', '[]', '[]', '[]', '["Lead model override recorded: space-bunny-free is not an allowed leader model; user named no model, so the running model is recorded as-is rather than substituting an allowed one. Disclosed.", "Audit kept read-only per track goal; no code written pending owner approval."]', '{"lesson_topic": null, "docs_updated": []}', 'e6e9642e-6e48-4b67-8773-3dd3967b9f1a', 'opencode-go/space-bunny-free', '{"n": 1, "ts": "2026-09-28T15:01:30.877Z", "summary": "Read-only render-list audit done. VERDICT: lazy render NOT implemented. (1) CORRECTNESS: trajectory.list SQL is ORDER BY seq ASC LIMIT 500 (node-store.ts:109) = OLDEST 500, but headSeq is MAX(seq) (node-store.ts:117, returned verbatim rpc.ts:37). Delta loop then polls afterSeq=MAX, gets 0 rows, parks (use-trajectory-delta.ts:80-93) - events 501..N never fetched, refresh re-runs the same loop. Ledger silently frozen on the oldest 500. (2) PERF: ledger-screen.tsx:303-314 passes NO getItemLayout/windowSize/maxToRenderPerBatch/removeClippedSubviews; the precomputed row height is dead (only write at :141; the sole getItemLayout mention in the plugin is a false comment at virtual-rows.ts:6). 6 full Theta(N) passes per append; fresh row objects defeat React.memo. TrajectoryTimelineStrip renders one View per record, non-virtualized. No load-older anywhere. Largest fixture 8 rows; FlatList mocked so virtualization is untested. dsh reference: tanstack useVirtualizer, a-priori 30/20/9px heights, useStableVirtualRowStructure, tail-page 50, 3s search throttle.", "status": "running", "done": [], "next": [], "blockers": [], "decisions": ["Lead model override recorded: space-bunny-free is not an allowed leader model; user named no model, so the running model is recorded as-is rather than substituting an allowed one. Disclosed.", "Audit kept read-only per track goal; no code written pending owner approval."], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "e6e9642e-6e48-4b67-8773-3dd3967b9f1a", "author_model": "opencode-go/space-bunny-free"}');
