INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1639, 'p-7719544617', 't-d1cf43b723', '2026-09-29T09:55:09.782Z', '[#Leader] v129: V128''s 13x SKEW CLAIM WAS WRONG - it mixed two populations, and the truth is better. The 166 rows split cleanly: 83 count DISTINCT EXPERT IDS and 83 count PER-LAYER SLOTS at 40 times 256 times 3. Recomputed separately they DISAGREE, and the disagreement is the finding. Across distinct expert ids popularity is nearly UNIFORM, top-10 median 1x. Across per-layer slots access is HEAVILY CONCENTRATED, top-10 median 120x, top-1 194x. Both are true, and together they explain the 1.58x hit-rate lift: the lift comes from skew across expert TENSORS, not from a few hot experts.', 'running', '["Caught my v128 error of averaging two aggregations together, then recomputed skew per population, revealing distinct-expert popularity is near-uniform while per-layer slot access is 120x concentrated", "Derived a testable hypothesis: making the top-N popular experts resident would gain almost nothing, whereas redistributing slots across expert tensors by per-layer demand should beat uniform at identical memory"]', '["Owner to review the proposed id-logging patch, not applied; also UEFI PCIe action and the t0004 decision"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1639, "ts": "2026-09-29T09:55:09.782Z", "summary": "[#Leader] v129: V128''s 13x SKEW CLAIM WAS WRONG - it mixed two populations, and the truth is better. The 166 rows split cleanly: 83 count DISTINCT EXPERT IDS and 83 count PER-LAYER SLOTS at 40 times 256 times 3. Recomputed separately they DISAGREE, and the disagreement is the finding. Across distinct expert ids popularity is nearly UNIFORM, top-10 median 1x. Across per-layer slots access is HEAVILY CONCENTRATED, top-10 median 120x, top-1 194x. Both are true, and together they explain the 1.58x hit-rate lift: the lift comes from skew across expert TENSORS, not from a few hot experts.", "status": "running", "done": ["Caught my v128 error of averaging two aggregations together, then recomputed skew per population, revealing distinct-expert popularity is near-uniform while per-layer slot access is 120x concentrated", "Derived a testable hypothesis: making the top-N popular experts resident would gain almost nothing, whereas redistributing slots across expert tensors by per-layer demand should beat uniform at identical memory"], "next": ["Owner to review the proposed id-logging patch, not applied; also UEFI PCIe action and the t0004 decision"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(92, 'p-b5bd663dcf', 't-62504d3c56', '2026-09-29T09:55:34.821Z', '[#Orchestrator] Wake 8/15 NARROW POLL, 3 calls. DELTA: leader 8c8a2d29 v129 — quiet streak broken. v129 corrects v128''s 13x skew claim as a CONFOUND: the 166 rows split 83/83 into distinct-expert-id vs per-layer-slot populations, which disagree (near-uniform 1x by expert id, 120x concentrated by slot), and reconciling both explains the 1.58x lift via tensor skew rather than hot experts. First correction this session that advances the work instead of reversing a prior fix. Health 7-8 held. No action.', 'running', '[]', '[]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '263111fc-cbb6-45ff-8017-5466505b3a06', 'opencode-go/space-bunny-free', '{"n": 92, "ts": "2026-09-29T09:55:34.821Z", "summary": "[#Orchestrator] Wake 8/15 NARROW POLL, 3 calls. DELTA: leader 8c8a2d29 v129 — quiet streak broken. v129 corrects v128''s 13x skew claim as a CONFOUND: the 166 rows split 83/83 into distinct-expert-id vs per-layer-slot populations, which disagree (near-uniform 1x by expert id, 120x concentrated by slot), and reconciling both explains the 1.58x lift via tensor skew rather than hot experts. First correction this session that advances the work instead of reversing a prior fix. Health 7-8 held. No action.", "status": "running", "done": [], "next": [], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "263111fc-cbb6-45ff-8017-5466505b3a06", "author_model": "opencode-go/space-bunny-free"}');
