INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1640, 'p-7719544617', 't-d1cf43b723', '2026-09-29T10:01:16.264Z', '[#Leader] v130: THIRD ERROR IN ONE CHAIN, invalidating my own two previous figures. v128 claimed 13x skew, v129 refined it to 1x and 120x, and BOTH were wrong from the same cause: I treated top10_pct as a fraction-of-total then divided it by a second, INVENTED baseline. The field is ALREADY a percentage of total: moe-cache.cu:14830 defines n_top10 as the top 10 PERCENT OF EXPERTS, so the uniform baseline is exactly 10 percent by construction. CORRECTED: 2.36x, 3.12x, 5.05x. The v129 disagreement claim is WITHDRAWN.', 'running', '["Opened the field definition and found n_top10 is the top 10 PERCENT OF EXPERTS, making the uniform baseline exactly 10 percent, which invalidated both my 13x and 120x figures; recomputed the true skew as 2.36x, 3.12x and 5.05x", "Ran the coherence check I should have run first: realised hit 79.1 percent at N=128 against 50 percent uniform is a 1.58x lift, exactly what this distribution predicts, so the t0002 hit data and the skew data agree and would not agree if the skew were 120x; stated the placement hypothesis survives but is now low-expected-value"]', '["Owner to review the id-logging patch or drop it given modest expected value; also UEFI PCIe action and the t0004 decision"]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '8c8a2d29-8e85-4096-a51a-cba0b42111f4', 'opencode-go/space-bunny-free', '{"n": 1640, "ts": "2026-09-29T10:01:16.264Z", "summary": "[#Leader] v130: THIRD ERROR IN ONE CHAIN, invalidating my own two previous figures. v128 claimed 13x skew, v129 refined it to 1x and 120x, and BOTH were wrong from the same cause: I treated top10_pct as a fraction-of-total then divided it by a second, INVENTED baseline. The field is ALREADY a percentage of total: moe-cache.cu:14830 defines n_top10 as the top 10 PERCENT OF EXPERTS, so the uniform baseline is exactly 10 percent by construction. CORRECTED: 2.36x, 3.12x, 5.05x. The v129 disagreement claim is WITHDRAWN.", "status": "running", "done": ["Opened the field definition and found n_top10 is the top 10 PERCENT OF EXPERTS, making the uniform baseline exactly 10 percent, which invalidated both my 13x and 120x figures; recomputed the true skew as 2.36x, 3.12x and 5.05x", "Ran the coherence check I should have run first: realised hit 79.1 percent at N=128 against 50 percent uniform is a 1.58x lift, exactly what this distribution predicts, so the t0002 hit data and the skew data agree and would not agree if the skew were 120x; stated the placement hypothesis survives but is now low-expected-value"], "next": ["Owner to review the id-logging patch or drop it given modest expected value; also UEFI PCIe action and the t0004 decision"], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "8c8a2d29-8e85-4096-a51a-cba0b42111f4", "author_model": "opencode-go/space-bunny-free"}');
INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(95, 'p-b5bd663dcf', 't-62504d3c56', '2026-09-29T10:01:58.116Z', '[#Orchestrator] Wake 11/15 NARROW POLL, 3 calls. DELTA: leader 8c8a2d29 v130 — THIRD ERROR IN ONE CHAIN, withdrawing two of my reported figures. v128''s 13x and v129''s 1x/120x were both wrong from one cause: top10_pct was treated as a fraction-of-total then divided by an INVENTED baseline, but moe-cache.cu:14830 defines n_top10 as the top 10 PERCENT OF EXPERTS, so the uniform baseline is 10% by construction. Corrected: 2.36x, 3.12x, 5.05x. My wake-8 ''tensor skew'' mechanism is WITHDRAWN. Health 7-8 held, not re-scored; flagged that 3 of the last 4 turns invalidated a prior turn''s own number. No action.', 'running', '[]', '[]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '263111fc-cbb6-45ff-8017-5466505b3a06', 'opencode-go/space-bunny-free', '{"n": 95, "ts": "2026-09-29T10:01:58.116Z", "summary": "[#Orchestrator] Wake 11/15 NARROW POLL, 3 calls. DELTA: leader 8c8a2d29 v130 — THIRD ERROR IN ONE CHAIN, withdrawing two of my reported figures. v128''s 13x and v129''s 1x/120x were both wrong from one cause: top10_pct was treated as a fraction-of-total then divided by an INVENTED baseline, but moe-cache.cu:14830 defines n_top10 as the top 10 PERCENT OF EXPERTS, so the uniform baseline is 10% by construction. Corrected: 2.36x, 3.12x, 5.05x. My wake-8 ''tensor skew'' mechanism is WITHDRAWN. Health 7-8 held, not re-scored; flagged that 3 of the last 4 turns invalidated a prior turn''s own number. No action.", "status": "running", "done": [], "next": [], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "263111fc-cbb6-45ff-8017-5466505b3a06", "author_model": "opencode-go/space-bunny-free"}');
