INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(207, 'p-b5bd663dcf', 't-62504d3c56', '2026-10-01T17:29:25.351Z', 'Answered collector claim-mismatch rows with code-level root causes. ROW1: workers[] is a REPORT table (only worker_report terminal-status + worker_evaluate inserts exist; NO dispatch path ever wrote it) — my dev 1d604efb is in paseo-repo worktree with no orchestration MCP and my prompt override dropped the report instruction, so its row lands ONLY when I record completion via worker_report at done-time; absence now is expected, verified via track_status. Accepted wording fix: future claims say paseo-verified vs MOCT-at-report-time. ROW2: heartbeat_stale rule = confirmed_at < last turn AND handoff pending (handoff-retirement signal, NOT cadence liveness); confirmed_at-age is the cadence evidence; model_verified never re-checked anywhere. Promised coordination: heads-up to t-a124729a8a leader before my stage5 restart (drops agents, incl. their session). Naming worker 1d604efb in flight.', 'running', '[]', '[]', '["TEST collector boot blocked at step 1 — paseo tools never injected on TEST daemon (task-12f20731ef; TEST daemon restarted 13:0xZ, retest pending) — plus orphan heartbeats 08c2b0ba/7e0a1707 and 16 idle collector sessions await creator/owner cleanup", "Collector roster still needs PR #69 merge (owner-gated) for track_list; sqlite fallback disclosed per wake until then"]', '[]', '{"lesson_topic": "field names outlive their semantics - heartbeat_stale reads as cadence liveness but only encodes handoff retirement, and workers reads as dispatch but only encodes reporting; read the rule before trusting the flag", "docs_updated": []}', '4774f61c-0dca-4331-9a91-46e0ee32b238', 'opencode-go/mimo-v2.6-flash', '{"n": 207, "ts": "2026-10-01T17:29:25.351Z", "summary": "Answered collector claim-mismatch rows with code-level root causes. ROW1: workers[] is a REPORT table (only worker_report terminal-status + worker_evaluate inserts exist; NO dispatch path ever wrote it) — my dev 1d604efb is in paseo-repo worktree with no orchestration MCP and my prompt override dropped the report instruction, so its row lands ONLY when I record completion via worker_report at done-time; absence now is expected, verified via track_status. Accepted wording fix: future claims say paseo-verified vs MOCT-at-report-time. ROW2: heartbeat_stale rule = confirmed_at < last turn AND handoff pending (handoff-retirement signal, NOT cadence liveness); confirmed_at-age is the cadence evidence; model_verified never re-checked anywhere. Promised coordination: heads-up to t-a124729a8a leader before my stage5 restart (drops agents, incl. their session). Naming worker 1d604efb in flight.", "status": "running", "done": [], "next": [], "blockers": ["TEST collector boot blocked at step 1 — paseo tools never injected on TEST daemon (task-12f20731ef; TEST daemon restarted 13:0xZ, retest pending) — plus orphan heartbeats 08c2b0ba/7e0a1707 and 16 idle collector sessions await creator/owner cleanup", "Collector roster still needs PR #69 merge (owner-gated) for track_list; sqlite fallback disclosed per wake until then"], "decisions": [], "knowledge": {"lesson_topic": "field names outlive their semantics - heartbeat_stale reads as cadence liveness but only encodes handoff retirement, and workers reads as dispatch but only encodes reporting; read the rule before trusting the flag", "docs_updated": []}, "author_agent": "4774f61c-0dca-4331-9a91-46e0ee32b238", "author_model": "opencode-go/mimo-v2.6-flash"}');
