INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(263, 'p-b5bd663dcf', 't-62504d3c56', '2026-10-02T09:05:27.153Z', 'task_update persists note and amends a task body in place: QueueItem gains note + append-only detail_amendments; task_update gains detail/amend_reason/author, keeping id/assignee/progress and recording the prior body in changes.previous_detail (no-op on an unchanged body). Migration covers six sites plus an idempotent ensure-column on open, rehearsed on a byte copy of the live sqlite, which stayed untouched. da31acb, not pushed. 533 green.', 'idle', '["QueueItem.note persisted; ledger keeps its own copy", "task_update(detail=) amends in place, id/assignee/progress kept, prior body in changes.previous_detail + detail_amendments", "author/amend_reason provenance; author separate because assignee also reassigns", "Unchanged body = no-op (amended:false)", "6th site found: state/migration.py would have wiped both columns on a re-run", "Migration: tasks DDL + ADDITIVE_COLUMNS + SCHEMA_VERSION 2; save_track/get_track/list_tracks/parity projection", "track_status carries both fields; 2 stale prose strings corrected", "Parity queue check strengthened count-only -> content", "Live-copy rehearsal green; live file untouched", "533 green (494+39); tools/§5/client/mirror unmoved"]', '["QA the no-op rule and the parity asymmetry"]', '[]', '["Reused task_updated (prior body in changes.previous_detail); no new event type", "Trail persisted as a column, not derived at read time: keeps track_status one bounded read", "Only the body is amendable; no backfill of historical notes"]', '{"lesson_topic": "A count-only parity check is theatre: normalise the JSON side through the model, keep the DB side raw, so a forgotten projection FAILS instead of passing.", "docs_updated": []}', '4f309f31-5c00-4bbe-801a-7c8e2fb6d706', 'opencode-go/space-bunny-free', '{"n": 263, "ts": "2026-10-02T09:05:27.153Z", "summary": "task_update persists note and amends a task body in place: QueueItem gains note + append-only detail_amendments; task_update gains detail/amend_reason/author, keeping id/assignee/progress and recording the prior body in changes.previous_detail (no-op on an unchanged body). Migration covers six sites plus an idempotent ensure-column on open, rehearsed on a byte copy of the live sqlite, which stayed untouched. da31acb, not pushed. 533 green.", "status": "idle", "done": ["QueueItem.note persisted; ledger keeps its own copy", "task_update(detail=) amends in place, id/assignee/progress kept, prior body in changes.previous_detail + detail_amendments", "author/amend_reason provenance; author separate because assignee also reassigns", "Unchanged body = no-op (amended:false)", "6th site found: state/migration.py would have wiped both columns on a re-run", "Migration: tasks DDL + ADDITIVE_COLUMNS + SCHEMA_VERSION 2; save_track/get_track/list_tracks/parity projection", "track_status carries both fields; 2 stale prose strings corrected", "Parity queue check strengthened count-only -> content", "Live-copy rehearsal green; live file untouched", "533 green (494+39); tools/§5/client/mirror unmoved"], "next": ["QA the no-op rule and the parity asymmetry"], "blockers": [], "decisions": ["Reused task_updated (prior body in changes.previous_detail); no new event type", "Trail persisted as a column, not derived at read time: keeps track_status one bounded read", "Only the body is amendable; no backfill of historical notes"], "knowledge": {"lesson_topic": "A count-only parity check is theatre: normalise the JSON side through the model, keep the DB side raw, so a forgotten projection FAILS instead of passing.", "docs_updated": []}, "author_agent": "4f309f31-5c00-4bbe-801a-7c8e2fb6d706", "author_model": "opencode-go/space-bunny-free"}');
