INSERT INTO orch_turns(n, project_id, track_id, ts, summary, status, done, next, blockers, decisions, knowledge, author_agent, author_model, raw) VALUES(1819, 'p-7719544617', 't-d1cf43b723', '2026-10-03T04:08:41.647Z', 'Ruling on t0011 mem gate: the >=67 GiB gate is PRE-ARM only (as t0006/profile-decode/P3 always did); my ''keep >=67'' wording was wrong for mid-run. Worker measured the fork server self-holds ~48 GB shmem-dirty while serving (MemAvailable ~27 GiB mid-run, 75 GiB after kill), so mid-run >=67 is impossible; abort only on external pressure (sustained swap si/so>0 or VM growth). Mid-run dip is a documented workload property. Worker told to proceed with nsys capture.', 'running', '[]', '[]', '[]', '[]', '{"lesson_topic": null, "docs_updated": []}', '01afbe44-302f-485f-93d3-a170d036352e', '', '{"n": 1819, "ts": "2026-10-03T04:08:41.647Z", "summary": "Ruling on t0011 mem gate: the >=67 GiB gate is PRE-ARM only (as t0006/profile-decode/P3 always did); my ''keep >=67'' wording was wrong for mid-run. Worker measured the fork server self-holds ~48 GB shmem-dirty while serving (MemAvailable ~27 GiB mid-run, 75 GiB after kill), so mid-run >=67 is impossible; abort only on external pressure (sustained swap si/so>0 or VM growth). Mid-run dip is a documented workload property. Worker told to proceed with nsys capture.", "status": "running", "done": [], "next": [], "blockers": [], "decisions": [], "knowledge": {"lesson_topic": null, "docs_updated": []}, "author_agent": "01afbe44-302f-485f-93d3-a170d036352e", "author_model": ""}');
