INSERT INTO orch_events(id, project_id, track_id, type, ts, payload) VALUES(3418, 'p-7719544617', 't-d1cf43b723', 'heartbeat_spec_issued', '2026-09-27T16:57:26.745Z', '{"specs": [{"step_name": "checkup", "cron": "*/6 * * * *", "timezone": "Asia/Ho_Chi_Minh", "prompt": "LEAD CHECKUP (6-min) track t-d1cf43b723: 1) ONE narrow count query only: omp ps list --json | jq ''[.[].daemons[]]|length'' 2) ready-queue from latest track_status: pending->advance, ready non-GPU->dispatch, GPU item->poll, gated->hold 3) GO IDLE only when queue empty AND nothing to prepare. 4) QUIET TICK: zero change since last tick (same queue, same worker states, no new events/decisions) -> SKIP turn_report; the LEAD TICK reply alone is the record. A no-change turn_report wastes tokens. End each changed turn with turn_report.", "tool_mcp": "create_heartbeat", "tool_cli": "no omp-native heartbeat CLI — execute via MCP create_heartbeat (agent-scoped); opencode CLI fallback only when the MCP tool is unreachable"}, {"step_name": "deep", "cron": "*/24 * * * *", "timezone": "Asia/Ho_Chi_Minh", "prompt": "LEAD DEEP TICK (24-min) track t-d1cf43b723: 1) consult quota check: printf ''/usage\\n'' | timeout 30 claude 2) research/complex-problem work on track goal 3) build summary: summary_read(action=''spec'', track_id=''t-d1cf43b723''), `paseo send` the EXISTING summarizer (spawn fresh via fleet(mode=''spawn'', position=''summarizer'') ONLY when none live or ctx>160K — never fresh-per-tick), then summary_write(track_id, <its content>) 4) reconcile lessons + docs (OKF v0.2) 5) end with turn_report.", "tool_mcp": "create_heartbeat", "tool_cli": "no omp-native heartbeat CLI — execute via MCP create_heartbeat (agent-scoped); opencode CLI fallback only when the MCP tool is unreachable"}], "harness": "omp"}');
