INSERT INTO orch_events(id, project_id, track_id, type, ts, payload) VALUES(3909, 'p-b5bd663dcf', 't-f3ba82ac9c', 'task_updated', '2026-09-28T08:42:40.108Z', '{"task_id": "task-a3072d4fff", "title": "C4 trajectory v2: agent-header button + full-screen view + dsh feature/styling parity", "changes": {"status": "ready", "progress": 95, "note": "QC r13 conditional PASS (A9/A7/dup/regressions green); A1 partial — button dead after client-side tab navigation (silence, no toast). Fix round 2 dispatched (d-5498f04414)."}, "by": "leader"}');
