INSERT INTO orch_events(id, project_id, track_id, type, ts, payload) VALUES(4145, 'p-b5bd663dcf', 't-62504d3c56', 'task_updated', '2026-09-28T15:04:55.660Z', '{"task_id": "task-23876ada06", "title": "B: store-layer paging correctness (filter-before-slice) + first Store tests", "changes": {"status": "blocked", "note": "SUPERSEDED by task-0d58a40c62. DO NOT IMPLEMENT FROM THIS BODY — it is wrong about the storage backend. It describes the JSON backward-chunked scanner as the production path and cites its bounded memory as the design basis; in production (SQL, MCP_ORCH_DB_PATH set) tail_jsonl issues no LIMIT and iterates cur.fetchall(), so there is no bounded memory and no backward scan. The corrected body is task-0d58a40c62. Left in place unedited because task_update cannot amend `detail` — the write-once defect tracked as its own task."}, "by": "leader"}');
