INSERT INTO orch_events(id, project_id, track_id, type, ts, payload) VALUES(6138, 'p-7719544617', 't-d1cf43b723', 'worker_reported', '2026-10-03T05:14:02.532Z', '{"agent_id": "01afbe44-302f-485f-93d3-a170d036352e", "role": "lead", "model": "", "task": "t0011", "summary": "t0011 done: PR #817 (docs/811-nsys-decode, stacked on #816; base epic/811, no merge). nsys 106-tok decode window on 3060: 84.9 ms/tok traced (untraced rep0 72.5), GPU-active 27.6 ms (32.5%), GPU-idle 57.3 ms (67.5%) owned by ~4.1 cores of CPU-MoE expert GEMM (86% of 39.5K symbolized samples); 380 cudaStreamSynchronize/token nest inside GPU-active, not wall-additive. The ~32 ms unattributed bucket = CPU-MoE compute on the critical path; IMPL-GAP item 2 (split sync) demoted, item 3 (threads) ~1.8 ms. Open: NVML-vs-nsys PCIe discrepancy; post-window 12.46 tok/s residue. Dispatched t0012: Atlas rebuilt on served GSQ-RCO via --dump-routing (held-out train/eval prompts), n=3 interleaved S/A/R arms, primary metric T1 cold-start hit rate.", "status": "partial", "pr": "", "artifacts": [], "reported_at": "2026-10-03T05:14:02.532Z"}');
