INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-2f229f1a04', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T12:48:24.672Z', 'Owner directive 2026-09-02: new leader = session 57747c50 (glm-5.3-flash on opencode-go harness). fleet.json updated: leader.models += opencode-go/glm-5.3-flash (same model family, harness routing variant). Old leader 20619da6 registered as HISTORICAL BINDING (baseline/local, crashed, never signed v2.2.0) purely for takeover provenance, then handed off.', 'crash takeover per contract takeover protocol; handoff executed through MCP', 'user', 0, '57747c50', '{"id": "d-2f229f1a04", "ts": "2026-09-02T12:48:24.672Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "Owner directive 2026-09-02: new leader = session 57747c50 (glm-5.3-flash on opencode-go harness). fleet.json updated: leader.models += opencode-go/glm-5.3-flash (same model family, harness routing variant). Old leader 20619da6 registered as HISTORICAL BINDING (baseline/local, crashed, never signed v2.2.0) purely for takeover provenance, then handed off.", "rationale": "crash takeover per contract takeover protocol; handoff executed through MCP", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d31311aa48', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T13:19:18.613Z', 'Fleet registry v2 shipped (d-15): <state>/fleet.json is the DB for models/harness/provider per position (records: model, harness, provider_arg, mode, max_concurrent, notes, spawn defaults; flat and nested shapes accepted). New tool fleet_spawn_spec returns the EXACT paseo create_agent command per position (leader refused - filled via handoff). baseline/local registered for leader position (owner directive, hydra leader on local Qwen, max_concurrent=2). Handoff 57747c50 -> c865947e executed: redirected while pending (new redirect path), successor registered via registry (no override), handoff_completed.', 'owner asked for model/harness/provider registry + exact paseo commands; JSON config chosen over YAML (no new deps) and over sqlite (small read-mostly owner-curated table; change history already lossless in decisions.jsonl)', 'user', 0, '57747c50', '{"id": "d-d31311aa48", "ts": "2026-09-02T13:19:18.613Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "Fleet registry v2 shipped (d-15): <state>/fleet.json is the DB for models/harness/provider per position (records: model, harness, provider_arg, mode, max_concurrent, notes, spawn defaults; flat and nested shapes accepted). New tool fleet_spawn_spec returns the EXACT paseo create_agent command per position (leader refused - filled via handoff). baseline/local registered for leader position (owner directive, hydra leader on local Qwen, max_concurrent=2). Handoff 57747c50 -> c865947e executed: redirected while pending (new redirect path), successor registered via registry (no override), handoff_completed.", "rationale": "owner asked for model/harness/provider registry + exact paseo commands; JSON config chosen over YAML (no new deps) and over sqlite (small read-mostly owner-curated table; change history already lossless in decisions.jsonl)", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d1411a1f07', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T13:29:37.584Z', 'Registry records gained tier + quality_index (+thinking) properties (d-16, owner request). dev += command_code/xiaomi/mimo-v2.5 (free, qi 68) and opencode-go/mimo-v2.5 (paid, qi 75). consult += opencode-go/glm-5.3-flash with thinking=high (qi 85). fleet_spawn_spec emits set_thinking post-spawn step. Quality indices are owner-tunable estimates pending real evals.', 'owner directive 2026-09-02; tier/quality enable cheap-first or best-first spawn ordering later', 'user', 0, '57747c50', '{"id": "d-d1411a1f07", "ts": "2026-09-02T13:29:37.584Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "Registry records gained tier + quality_index (+thinking) properties (d-16, owner request). dev += command_code/xiaomi/mimo-v2.5 (free, qi 68) and opencode-go/mimo-v2.5 (paid, qi 75). consult += opencode-go/glm-5.3-flash with thinking=high (qi 85). fleet_spawn_spec emits set_thinking post-spawn step. Quality indices are owner-tunable estimates pending real evals.", "rationale": "owner directive 2026-09-02; tier/quality enable cheap-first or best-first spawn ordering later", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-19d2e01744', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T13:41:18.767Z', 'Registry v2.2 (d-17): priority property added (scheme: 1 capped-local dynamic, 2 owner free pair, 3 research zen free, 4 paid, 5 fallback; dynamic models carry priority_degraded + degrade_when_usage). baseline/local = Qwen 3.8 27B (qi 55, owner correction) now also a dev model: priority 1 -> 3 when usage>=1, cap 2. dev += opencode/mimo-v2.5-free (pri 2, qi 60), opencode/muse-spark-1.2-contributor-free (pri 2, qi 62), + researched zen free: nemotron-3-ultra-free (qi 63), nemotron-3.5-lightning-free (qi 58). New tool fleet_recommend(position, usage, quota) ranks models by effective priority x quality with cap/quota blocking - leader-observed usage, zero-trust.', 'owner directive 2026-09-02; quota+concurrency-aware model suggestion for spawn decisions; zen free ids verified against local `opencode models` CLI + dev.opencode.ai/docs/zen', 'user', 0, '57747c50', '{"id": "d-19d2e01744", "ts": "2026-09-02T13:41:18.767Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "Registry v2.2 (d-17): priority property added (scheme: 1 capped-local dynamic, 2 owner free pair, 3 research zen free, 4 paid, 5 fallback; dynamic models carry priority_degraded + degrade_when_usage). baseline/local = Qwen 3.8 27B (qi 55, owner correction) now also a dev model: priority 1 -> 3 when usage>=1, cap 2. dev += opencode/mimo-v2.5-free (pri 2, qi 60), opencode/muse-spark-1.2-contributor-free (pri 2, qi 62), + researched zen free: nemotron-3-ultra-free (qi 63), nemotron-3.5-lightning-free (qi 58). New tool fleet_recommend(position, usage, quota) ranks models by effective priority x quality with cap/quota blocking - leader-observed usage, zero-trust.", "rationale": "owner directive 2026-09-02; quota+concurrency-aware model suggestion for spawn decisions; zen free ids verified against local `opencode models` CLI + dev.opencode.ai/docs/zen", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-eb1864039d', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T13:59:39.121Z', 'Registry v2.3 (d-18): nemotron free models removed from dev (owner). family property added - same logical model via multiple providers (mimo-v2.5: opencode-go + command_code; glm-5.3-flash: command_code + opencode-go); fleet_recommend aggregates usage/quota across a family; model-keyed usage hits one record, family-keyed bleeds across all. Zero-trust usage pipeline shipped: fleet_usage_report (leader reports paseo-observed running counts, stored state/mcp/usage.json) + fleet_usage_get + fleet_recommend(live=true) consumes snapshots fresher than 15min. paseo CLI fixed (npm install commander) but CLI->daemon needs password; adapter auto-poll deferred until owner provides PASEO_PASSWORD. First live report: W1+c865947e on baseline/local -> fleet_recommend correctly blocks baseline/local (cap 2) and recommends muse-spark-free.', 'owner directive 2026-09-02; quota-aware recommendations need accurate usage; zero-trust: server never probes harness, leaders report observations', 'user', 0, '57747c50', '{"id": "d-eb1864039d", "ts": "2026-09-02T13:59:39.121Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "Registry v2.3 (d-18): nemotron free models removed from dev (owner). family property added - same logical model via multiple providers (mimo-v2.5: opencode-go + command_code; glm-5.3-flash: command_code + opencode-go); fleet_recommend aggregates usage/quota across a family; model-keyed usage hits one record, family-keyed bleeds across all. Zero-trust usage pipeline shipped: fleet_usage_report (leader reports paseo-observed running counts, stored state/mcp/usage.json) + fleet_usage_get + fleet_recommend(live=true) consumes snapshots fresher than 15min. paseo CLI fixed (npm install commander) but CLI->daemon needs password; adapter auto-poll deferred until owner provides PASEO_PASSWORD. First live report: W1+c865947e on baseline/local -> fleet_recommend correctly blocks baseline/local (cap 2) and recommends muse-spark-free.", "rationale": "owner directive 2026-09-02; quota-aware recommendations need accurate usage; zero-trust: server never probes harness, leaders report observations", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f3fb703811', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T14:06:35.673Z', 'leader_runbook shipped (d-19): canonical operating procedure served AT SIGN TIME inside the leader_register response (runbook v1.0.0: 4 principles, phases takeover/turn/heartbeats/handoff, budgets, 18-tool index) and re-fetchable via leader_runbook tool. Closes the gap proven by the c865947e takeover: register payload listed obligations (WHAT) but not the step-by-step procedure (HOW); takeover briefs had to be hand-written twice. Tool count 22 -> 23, tests 90/90.', 'instruction-following needs 4 channels: sign-time payload, heartbeat prompts, tool guardrails, orchestration.md - the runbook makes channel 1 procedural and compact enough for weak local models', 'user', 0, '57747c50', '{"id": "d-f3fb703811", "ts": "2026-09-02T14:06:35.673Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "leader_runbook shipped (d-19): canonical operating procedure served AT SIGN TIME inside the leader_register response (runbook v1.0.0: 4 principles, phases takeover/turn/heartbeats/handoff, budgets, 18-tool index) and re-fetchable via leader_runbook tool. Closes the gap proven by the c865947e takeover: register payload listed obligations (WHAT) but not the step-by-step procedure (HOW); takeover briefs had to be hand-written twice. Tool count 22 -> 23, tests 90/90.", "rationale": "instruction-following needs 4 channels: sign-time payload, heartbeat prompts, tool guardrails, orchestration.md - the runbook makes channel 1 procedural and compact enough for weak local models", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-691d1fdcfe', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T14:09:33.688Z', 'Skill epic-track-leader shipped (d-20): thin trigger skill (~350 tokens) that guides an agent to sign via leader_register (runbook embedded in response) and follow the MCP-served runbook phases; canonical file mcp-orchestration/skills/epic-track-leader/SKILL.md symlinked into repo .agents/skills/ and ~/.agents/skills/ (no copies). Bidirectional binding: runbook v1.1.0 embeds skill_reference; on version mismatch MCP wins. Runbook stays the single source of procedure; skill stays bloat-free.', 'owner directive 2026-09-02: skill must be simple (no ctx bloat) and MCP must reference the same instruction; pointer+symlink model matches the v2.2.0 install philosophy', 'user', 0, '57747c50', '{"id": "d-691d1fdcfe", "ts": "2026-09-02T14:09:33.688Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "Skill epic-track-leader shipped (d-20): thin trigger skill (~350 tokens) that guides an agent to sign via leader_register (runbook embedded in response) and follow the MCP-served runbook phases; canonical file mcp-orchestration/skills/epic-track-leader/SKILL.md symlinked into repo .agents/skills/ and ~/.agents/skills/ (no copies). Bidirectional binding: runbook v1.1.0 embeds skill_reference; on version mismatch MCP wins. Runbook stays the single source of procedure; skill stays bloat-free.", "rationale": "owner directive 2026-09-02: skill must be simple (no ctx bloat) and MCP must reference the same instruction; pointer+symlink model matches the v2.2.0 install philosophy", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-98b57c4bf7', 'p-7719544617', 't-8d42fb7e63', '2026-09-02T14:39:42.673Z', 'd-21: track_close DELIVERY GATE - DONE requires gh-verified merged/approved PR; ARCHIVED for superseded tracks (no PR). d-22: worker_report tool - fleet agents report work summaries to track history themselves (WorkerRecord upsert + worker_reported event), track_status exposes last 5 worker_reports, fleet_spawn_spec scaffold now embeds the report duty so every spawned agent knows to report. Owner pivot: hydra recovery superseded; focus = mcp-orchestration.', 'owner directive: close only on delivered PR, focus on track PROGRESS + fleet tracing; workers report like the leader does, paseo wakes the leader to verify', 'user', 0, '57747c50', '{"id": "d-98b57c4bf7", "ts": "2026-09-02T14:39:42.673Z", "track_id": "t-8d42fb7e63", "project_id": "p-7719544617", "decision": "d-21: track_close DELIVERY GATE - DONE requires gh-verified merged/approved PR; ARCHIVED for superseded tracks (no PR). d-22: worker_report tool - fleet agents report work summaries to track history themselves (WorkerRecord upsert + worker_reported event), track_status exposes last 5 worker_reports, fleet_spawn_spec scaffold now embeds the report duty so every spawned agent knows to report. Owner pivot: hydra recovery superseded; focus = mcp-orchestration.", "rationale": "owner directive: close only on delivered PR, focus on track PROGRESS + fleet tracing; workers report like the leader does, paseo wakes the leader to verify", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1435d8ba9d', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T15:01:34.466Z', 'd-23 task tracking + ralph loop + md restructure shipped: QueueItem -> full task record (id/status/progress/assignee/updated_at); task_add + task_update tools (workers update progress each turn); track_status exposes .tasks; fleet_spawn_spec scaffold embeds WORK LOOP (Ralph) = task_update each turn -> work step -> native todo in parallel -> repeat -> worker_report; orchestration.md section schema now: Track Goal / Leader / Fleet Status / Tasks / Track Summary / Blockers & Decisions / Lessons Snapshot / Resume Instructions (validator + diff updated to match).', 'owner directive: tasks tracked on MCP + native todos, md = goal+tasks+leader+fleet+summary, each fleet agent follows ralph per turn', 'user', 0, '57747c50', '{"id": "d-1435d8ba9d", "ts": "2026-09-02T15:01:34.466Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-23 task tracking + ralph loop + md restructure shipped: QueueItem -> full task record (id/status/progress/assignee/updated_at); task_add + task_update tools (workers update progress each turn); track_status exposes .tasks; fleet_spawn_spec scaffold embeds WORK LOOP (Ralph) = task_update each turn -> work step -> native todo in parallel -> repeat -> worker_report; orchestration.md section schema now: Track Goal / Leader / Fleet Status / Tasks / Track Summary / Blockers & Decisions / Lessons Snapshot / Resume Instructions (validator + diff updated to match).", "rationale": "owner directive: tasks tracked on MCP + native todos, md = goal+tasks+leader+fleet+summary, each fleet agent follows ralph per turn", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-424d7af4d5', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T15:08:25.005Z', 'd-24: fleet_spawn_spec gains model param - recommend->spawn is now deterministic (spawn_spec served registry insertion order, ignoring fleet_recommend''s priority pick; live bug caught in checkup T6 when it offered baseline/local while recommend said muse-free). spawn_spec(model=...) filters registry records by model or family.', 'leader flow = fleet_recommend -> fleet_spawn_spec(model=top); registry order must not override priority pick', 'leader', 0, '57747c50', '{"id": "d-424d7af4d5", "ts": "2026-09-02T15:08:25.005Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-24: fleet_spawn_spec gains model param - recommend->spawn is now deterministic (spawn_spec served registry insertion order, ignoring fleet_recommend''s priority pick; live bug caught in checkup T6 when it offered baseline/local while recommend said muse-free). spawn_spec(model=...) filters registry records by model or family.", "rationale": "leader flow = fleet_recommend -> fleet_spawn_spec(model=top); registry order must not override priority pick", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-945f899e3d', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T15:40:26.404Z', 'd-25 owner directive batch: (1) orchestration.md must be a TRUE summary - detail moves to references/ folder (sibling of lessons/), md max 8K stays, floor effectively drops (2000); (2) fleet evaluation framework: workers self-evaluate P1 summary + P3 scored 0-100 (confidence, effectiveness, guideline_adherence); leader evaluates fleet/model adding hallucination + truthfulness; (3) fleet proposals (suggestions/lessons/references/KNOWLEDGE) flow to leader, leader approves before lesson/reference updates; (4) leader updates lessons/references from fleet session results; (5) track override protocol exists but requires owner approval + evidence.', 'owner message 2026-09-02: summary not really a summary; add validation/evaluation of fleet working status; suggestions gated by leader; overrides approved by owner', 'user', 0, '57747c50', '{"id": "d-945f899e3d", "ts": "2026-09-02T15:40:26.404Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-25 owner directive batch: (1) orchestration.md must be a TRUE summary - detail moves to references/ folder (sibling of lessons/), md max 8K stays, floor effectively drops (2000); (2) fleet evaluation framework: workers self-evaluate P1 summary + P3 scored 0-100 (confidence, effectiveness, guideline_adherence); leader evaluates fleet/model adding hallucination + truthfulness; (3) fleet proposals (suggestions/lessons/references/KNOWLEDGE) flow to leader, leader approves before lesson/reference updates; (4) leader updates lessons/references from fleet session results; (5) track override protocol exists but requires owner approval + evidence.", "rationale": "owner message 2026-09-02: summary not really a summary; add validation/evaluation of fleet working status; suggestions gated by leader; overrides approved by owner", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b545ff0df3', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T15:45:39.197Z', 'd-26 MD_TOKEN_MIN 4000->1500 (via 2000 interim): owner ruled the md must be a TRUE summary - detail lives in references/. Honest lean summary measured 1510 tokens; floor set just under honest-lean, not over it. P2-6 repetition guard remains the anti-padding protection. MD_TOKEN_MAX stays 8000.', '3 expansion rounds to clear 4000 proved the floor manufactures bloat; smoke file padded 4x; owner critique d-25', 'leader', 0, '57747c50', '{"id": "d-b545ff0df3", "ts": "2026-09-02T15:45:39.197Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-26 MD_TOKEN_MIN 4000->1500 (via 2000 interim): owner ruled the md must be a TRUE summary - detail lives in references/. Honest lean summary measured 1510 tokens; floor set just under honest-lean, not over it. P2-6 repetition guard remains the anti-padding protection. MD_TOKEN_MAX stays 8000.", "rationale": "3 expansion rounds to clear 4000 proved the floor manufactures bloat; smoke file padded 4x; owner critique d-25", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-429c517995', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T15:48:46.423Z', 'd-27 leader model evaluation (manual until P2-10): muse-spark-1.2-contributor-free on P2-2 - hallucination 95, truthfulness 100, confidence 90, effectiveness 95, guideline_adherence 100. Contrast baseline/local (77d6cc99): zero checkpoints in 25min, killed. Muse-free confirmed as primary dev free model; baseline/local demote candidate for protocol-heavy tasks (owner call on registry change).', 'owner directive: leader evaluates fleet/model on hallucination+truthfulness (+worker criteria); P2-1 vs P2-2 cycle contrast gives clean signal', 'leader', 0, '57747c50', '{"id": "d-429c517995", "ts": "2026-09-02T15:48:46.423Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-27 leader model evaluation (manual until P2-10): muse-spark-1.2-contributor-free on P2-2 - hallucination 95, truthfulness 100, confidence 90, effectiveness 95, guideline_adherence 100. Contrast baseline/local (77d6cc99): zero checkpoints in 25min, killed. Muse-free confirmed as primary dev free model; baseline/local demote candidate for protocol-heavy tasks (owner call on registry change).", "rationale": "owner directive: leader evaluates fleet/model on hallucination+truthfulness (+worker criteria); P2-1 vs P2-2 cycle contrast gives clean signal", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-83d78465b2', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T15:55:02.335Z', 'd-28 leader model evaluation: muse-spark-1.2-contributor-free on P2-8 - hallucination 98, truthfulness 100, confidence 95, effectiveness 95, guideline_adherence 100. Two consecutive clean cycles (P2-2, P2-8); self-eval calibration accurate (88/92/95 vs verified reality). Muse-free = primary free dev model, confirmed by evidence.', 'owner evaluation framework now operating: P1 summary + P3 self-eval (88/92/95) + leader independent eval; contrast with baseline/local informs registry policy', 'leader', 0, '57747c50', '{"id": "d-83d78465b2", "ts": "2026-09-02T15:55:02.335Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-28 leader model evaluation: muse-spark-1.2-contributor-free on P2-8 - hallucination 98, truthfulness 100, confidence 95, effectiveness 95, guideline_adherence 100. Two consecutive clean cycles (P2-2, P2-8); self-eval calibration accurate (88/92/95 vs verified reality). Muse-free = primary free dev model, confirmed by evidence.", "rationale": "owner evaluation framework now operating: P1 summary + P3 self-eval (88/92/95) + leader independent eval; contrast with baseline/local informs registry policy", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d7f258b566', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T16:01:59.477Z', 'd-29 leader model evaluation: muse-free on P2-9 - hallucination 97, truthfulness 100, confidence 95, effectiveness 95, guideline_adherence 100. THREE consecutive clean cycles (P2-2, P2-8, P2-9). Suggestion flow live: 33 tools (suggestion_add/review/list), leader-gated knowledge updates enforced at tool level.', 'owner framework operating: fleet -> suggest -> leader gate -> lesson/reference/process side effects, all journaled', 'leader', 0, '57747c50', '{"id": "d-d7f258b566", "ts": "2026-09-02T16:01:59.477Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-29 leader model evaluation: muse-free on P2-9 - hallucination 97, truthfulness 100, confidence 95, effectiveness 95, guideline_adherence 100. THREE consecutive clean cycles (P2-2, P2-8, P2-9). Suggestion flow live: 33 tools (suggestion_add/review/list), leader-gated knowledge updates enforced at tool level.", "rationale": "owner framework operating: fleet -> suggest -> leader gate -> lesson/reference/process side effects, all journaled", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-13653a5bbc', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T16:10:08.825Z', 'd-30 leader model evaluation: muse-free on P2-4 - hallucination 100, truthfulness 100, confidence 92, effectiveness 95, guideline_adherence 100. FOUR consecutive clean cycles. REST auth live: MCP_ORCH_AUTH_TOKEN empty=disabled (prod now), set=Bearer enforcement verified (401 x2, 200, health open). Owner sets token via systemd unit Environment line when ready.', 'backend hardening milestone (owner goal #5) delivered; token activation is an owner ops decision', 'leader', 0, '57747c50', '{"id": "d-13653a5bbc", "ts": "2026-09-02T16:10:08.825Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-30 leader model evaluation: muse-free on P2-4 - hallucination 100, truthfulness 100, confidence 92, effectiveness 95, guideline_adherence 100. FOUR consecutive clean cycles. REST auth live: MCP_ORCH_AUTH_TOKEN empty=disabled (prod now), set=Bearer enforcement verified (401 x2, 200, health open). Owner sets token via systemd unit Environment line when ready.", "rationale": "backend hardening milestone (owner goal #5) delivered; token activation is an owner ops decision", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0dc2b28fe7', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T16:15:59.049Z', 'd-31 leader model evaluation: muse-free on P2-11 - hallucination 100, truthfulness 100, confidence 95, effectiveness 92, guideline_adherence 100. FIVE consecutive clean cycles (P2-2/8/9/4/11). track_override live: owner gate enforced (approval AND evidence required, refusals non-mutating), 34 tools.', 'owner override protocol (d-25 #5) delivered with the gate as the load-bearing feature', 'leader', 0, '57747c50', '{"id": "d-0dc2b28fe7", "ts": "2026-09-02T16:15:59.049Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-31 leader model evaluation: muse-free on P2-11 - hallucination 100, truthfulness 100, confidence 95, effectiveness 92, guideline_adherence 100. FIVE consecutive clean cycles (P2-2/8/9/4/11). track_override live: owner gate enforced (approval AND evidence required, refusals non-mutating), 34 tools.", "rationale": "owner override protocol (d-25 #5) delivered with the gate as the load-bearing feature", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-c28963ab4d', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T16:33:37.324Z', 'd-33 owner evaluation framework COMPLETE + leader incident note: (a) P2-10 model_evaluate/model_evaluations live (36 tools) - merged truthfulness(hallucination) 4-criteria schema enforced server-side, old 5-key input rejected with hint, task_complexity/task_size + telemetry (compactions/tokens_in/tokens_out/cache_pct nullable) recorded per d-32; (b) P2-6 anti-repetition guard live in validate_and_commit (normalized line/block ratio >30% -> reject). LEADER INCIDENT: my own live repetition test committed a padded md to disk (4x-one-block = 20% ratio under threshold) - caught and restored from git same turn; lesson: leader live-tests destructive-capability tools against scratch state or with post-test restore. (c) Model evals: af2ae768 (P2-10) truthfulness 100/effectiveness 80 (turn-boundary stalls); ad76cfb6 (P2-6) truthfulness 100/guideline 100.', 'owner framework fully delivered: worker P1/P3 + leader 4-criteria + telemetry + anti-padding validator; leader self-audit recorded for the same standard', 'leader', 0, '57747c50', '{"id": "d-c28963ab4d", "ts": "2026-09-02T16:33:37.324Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-33 owner evaluation framework COMPLETE + leader incident note: (a) P2-10 model_evaluate/model_evaluations live (36 tools) - merged truthfulness(hallucination) 4-criteria schema enforced server-side, old 5-key input rejected with hint, task_complexity/task_size + telemetry (compactions/tokens_in/tokens_out/cache_pct nullable) recorded per d-32; (b) P2-6 anti-repetition guard live in validate_and_commit (normalized line/block ratio >30% -> reject). LEADER INCIDENT: my own live repetition test committed a padded md to disk (4x-one-block = 20% ratio under threshold) - caught and restored from git same turn; lesson: leader live-tests destructive-capability tools against scratch state or with post-test restore. (c) Model evals: af2ae768 (P2-10) truthfulness 100/effectiveness 80 (turn-boundary stalls); ad76cfb6 (P2-6) truthfulness 100/guideline 100.", "rationale": "owner framework fully delivered: worker P1/P3 + leader 4-criteria + telemetry + anti-padding validator; leader self-audit recorded for the same standard", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e7cafde7aa', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-02T16:42:03.479Z', 'd-34 (owner directive): data layer migrates to SQLite (stdlib, WAL) for query speed; config layer STAYS file-based (fleet.json registry stays owner-editable files, usage.json snapshots, lessons/references markdown). Ledgers (events/decisions) become insert-only tables - lossless semantics preserved as schema constraints. Migration idempotent with frozen JSON backup + dual-verify before cutover. Tool surface unchanged.', 'owner: ''SQLite for data mainly, config keep as current''; cheap now at 316K state; SQLite->Postgres later is easy if multi-host ever needed', 'user', 0, '57747c50', '{"id": "d-e7cafde7aa", "ts": "2026-09-02T16:42:03.479Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-34 (owner directive): data layer migrates to SQLite (stdlib, WAL) for query speed; config layer STAYS file-based (fleet.json registry stays owner-editable files, usage.json snapshots, lessons/references markdown). Ledgers (events/decisions) become insert-only tables - lossless semantics preserved as schema constraints. Migration idempotent with frozen JSON backup + dual-verify before cutover. Tool surface unchanged.", "rationale": "owner: ''SQLite for data mainly, config keep as current''; cheap now at 316K state; SQLite->Postgres later is easy if multi-host ever needed", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a32a5dece7', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-07T00:19:58.946Z', 'd-35 (owner clarification): (a) worker session stops mid-task are SYSTEM stops, not model behavior - leader remedy is re-dispatch/nudge (paseo_send_agent_prompt), NOT effectiveness demotion; muse streak amended: P2-10 effectiveness 80 -> 92 (two stops were systemic). (b) P2-3 unblocked without PASEO_PASSWORD: usage automation delivered by leader zero-trust fleet_usage_report per checkup heartbeat (operating since T6); backend daemon-polling design dropped. Stay-wake discipline: on worker ''finished'' notifications, leader checks task state first - mid-work turn-ends get re-dispatch, only worker_report+done = completion.', 'owner: ''You could re-dispatch subagent it mainly due to system stop, no paseo password need''', 'user', 0, '57747c50', '{"id": "d-a32a5dece7", "ts": "2026-09-07T00:19:58.946Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-35 (owner clarification): (a) worker session stops mid-task are SYSTEM stops, not model behavior - leader remedy is re-dispatch/nudge (paseo_send_agent_prompt), NOT effectiveness demotion; muse streak amended: P2-10 effectiveness 80 -> 92 (two stops were systemic). (b) P2-3 unblocked without PASEO_PASSWORD: usage automation delivered by leader zero-trust fleet_usage_report per checkup heartbeat (operating since T6); backend daemon-polling design dropped. Stay-wake discipline: on worker ''finished'' notifications, leader checks task state first - mid-work turn-ends get re-dispatch, only worker_report+done = completion.", "rationale": "owner: ''You could re-dispatch subagent it mainly due to system stop, no paseo password need''", "source": "user", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ab46519aad', 'p-b5bd663dcf', 't-62504d3c56', '2026-09-07T00:37:40.210Z', 'd-36 SQLite cutover EXECUTED by leader per CUTOVER.md: backup (368K frozen) -> migrate live -> PARITY OK (233 events/23 decisions/41 turns) -> unit env MCP_ORCH_DB_PATH -> restart -> SQL mode live (36 tools, writable). Pre/post track comparison: 12 tasks identical, 13 workers, turns preserved. Rollback documented in CUTOVER.md (unset env + restart).', 'owner: SQLite for data, config stays files; cheap while state small; INSERT-only enforced at DB level', 'leader', 0, '57747c50', '{"id": "d-ab46519aad", "ts": "2026-09-07T00:37:40.210Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "d-36 SQLite cutover EXECUTED by leader per CUTOVER.md: backup (368K frozen) -> migrate live -> PARITY OK (233 events/23 decisions/41 turns) -> unit env MCP_ORCH_DB_PATH -> restart -> SQL mode live (36 tools, writable). Pre/post track comparison: 12 tasks identical, 13 workers, turns preserved. Rollback documented in CUTOVER.md (unset env + restart).", "rationale": "owner: SQLite for data, config stays files; cheap while state small; INSERT-only enforced at DB level", "source": "leader", "irreversible": false, "author": "57747c50"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-cc302efc0f', 'p-b5bd663dcf', 't-a4d9544ed8', '2026-09-11T17:04:48.190Z', 'Commit contract v2.2.0 + mcp-orchestration to branch feat/lead-contract-v2.1 and update the existing open PR #19 rather than opening a new PR.', 'Owner chose to reuse the open contract PR (#19) and include the mcp-orchestration P2 work in the same commit. Runtime state (.venv, egg-info, orchestration/state/mcp) excluded as build/runtime artifacts. PR #19 remains open and mergeable (clean) at head 6ab1214.', 'leader', 0, 'opencode-lead', '{"id": "d-cc302efc0f", "ts": "2026-09-11T17:04:48.190Z", "track_id": "t-a4d9544ed8", "project_id": "p-b5bd663dcf", "decision": "Commit contract v2.2.0 + mcp-orchestration to branch feat/lead-contract-v2.1 and update the existing open PR #19 rather than opening a new PR.", "rationale": "Owner chose to reuse the open contract PR (#19) and include the mcp-orchestration P2 work in the same commit. Runtime state (.venv, egg-info, orchestration/state/mcp) excluded as build/runtime artifacts. PR #19 remains open and mergeable (clean) at head 6ab1214.", "source": "leader", "irreversible": false, "author": "opencode-lead"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-35e315d036', 'p-7719544617', 't-d1cf43b723', '2026-09-15T15:28:42.926Z', 'leader model override: opencode-go/muse-spark-1.3-contributor', 'Session already running opencode-go/muse-spark-1.3-contributor on baseline-flash-next worktree (prior MoE expert-cache work 2026-09-14); track goal requires continuing llama.cpp fork for Qwen3.8-Flash-Next on live rig. Requesting leader binding under current model.', 'owner-directive', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-35e315d036", "ts": "2026-09-15T15:28:42.926Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "leader model override: opencode-go/muse-spark-1.3-contributor", "rationale": "Session already running opencode-go/muse-spark-1.3-contributor on baseline-flash-next worktree (prior MoE expert-cache work 2026-09-14); track goal requires continuing llama.cpp fork for Qwen3.8-Flash-Next on live rig. Requesting leader binding under current model.", "source": "owner-directive", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e3175aa3c9', 'p-7719544617', 't-d1cf43b723', '2026-09-15T15:37:18.145Z', 'MoE-cache + MTP combine is two-stage: (1) now = CUDA early-router predictor (GGML_CUDA_MOE_EARLY_ROUTER, DECODE_GROUPED-only, ffn_gate_inp input -> predicted/positions/staging) as prefetch-only with trunk verify and legacy spec-type (MTP graph OFF, REQUIRED_GROUPED never stamped); (2) later = real block-48 draft head (Q4_K_M 1818MiB via -md shared borrow, MTP ctx il>=n_layer plain KV, small draft cache) as verifier after fixing #124 stamp sites llama-context.cpp:4142/4170/4176 + server ubatch assembly, ehead demoted to reject-fallback. No ehead/ahead symbol exists; maps to NEXTN_EH_PROJ + HC_HEAD.', '3-scout sweep: EheadLookupNow (no ehead symbol; early-router moe-cache.cu:3741/8896/9171; t_h_nextn handoff llama-graph.h), GroupedExecGap (AND-gate :62, CUDA advertises :8293, stamps :4121/:4142/:4170, fail-closed :4176 + ggml-backend:2188 + cuda:6772), MoeMtpWiring (load_mtp/borrow_shared_tensor, qwen4exp n_layer split, draft slot inherit/override speculative.cpp, grouped fast path main-only). Stage 1 avoids the stamp; stage 2 fixes it before spending VRAM.', 'leader', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-e3175aa3c9", "ts": "2026-09-15T15:37:18.145Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "MoE-cache + MTP combine is two-stage: (1) now = CUDA early-router predictor (GGML_CUDA_MOE_EARLY_ROUTER, DECODE_GROUPED-only, ffn_gate_inp input -> predicted/positions/staging) as prefetch-only with trunk verify and legacy spec-type (MTP graph OFF, REQUIRED_GROUPED never stamped); (2) later = real block-48 draft head (Q4_K_M 1818MiB via -md shared borrow, MTP ctx il>=n_layer plain KV, small draft cache) as verifier after fixing #124 stamp sites llama-context.cpp:4142/4170/4176 + server ubatch assembly, ehead demoted to reject-fallback. No ehead/ahead symbol exists; maps to NEXTN_EH_PROJ + HC_HEAD.", "rationale": "3-scout sweep: EheadLookupNow (no ehead symbol; early-router moe-cache.cu:3741/8896/9171; t_h_nextn handoff llama-graph.h), GroupedExecGap (AND-gate :62, CUDA advertises :8293, stamps :4121/:4142/:4170, fail-closed :4176 + ggml-backend:2188 + cuda:6772), MoeMtpWiring (load_mtp/borrow_shared_tensor, qwen4exp n_layer split, draft slot inherit/override speculative.cpp, grouped fast path main-only). Stage 1 avoids the stamp; stage 2 fixes it before spending VRAM.", "source": "leader", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f0f5fb9f63', 'p-7719544617', 't-d1cf43b723', '2026-09-15T16:33:59.994Z', 'Redirect: dequeue N=36/N=42 MoE-cache sweep and Colibri-combine arm (superseded baselines); MTP-at-cache-0 already answers consult action 1 (21.36 t/s, acc 0.88); next is production-depth verify then DDR-contention pricing', 'exp1: CPU-MoE 16.09 vs staging ceiling ~11.8 (+38%). MTP cache-OFF: 21.36 t/s, acceptance 0.88194, zero grouped-plan errors — #124 moot at cache 0. Colibri only regains value in a hybrid (resident GPU + cold CPU). Risk: DDR/CPU contention unmeasured, COMBINED needs both GPUs.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-f0f5fb9f63", "ts": "2026-09-15T16:33:59.994Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Redirect: dequeue N=36/N=42 MoE-cache sweep and Colibri-combine arm (superseded baselines); MTP-at-cache-0 already answers consult action 1 (21.36 t/s, acc 0.88); next is production-depth verify then DDR-contention pricing", "rationale": "exp1: CPU-MoE 16.09 vs staging ceiling ~11.8 (+38%). MTP cache-OFF: 21.36 t/s, acceptance 0.88194, zero grouped-plan errors — #124 moot at cache 0. Colibri only regains value in a hybrid (resident GPU + cold CPU). Risk: DDR/CPU contention unmeasured, COMBINED needs both GPUs.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b97918cd12', 'p-7719544617', 't-d1cf43b723', '2026-09-15T16:41:44.745Z', 'Adopt consult sequencing update: 21.36 backs out linear expert union (~1.0x/position), owner-design question closed at ~13.2 t/s measured; insert --spec-draft-n-max sweep (predict ~25 t/s at n=6, continue while acc>=0.6) ahead of hybrid; exp2 already done (no-op); depth falsifier noted (needs non-MTP 14K control for strict MTP-gain comparison)', 'MTP gain is fixed-term amortization (ceiling ~1.84x, at 1.33x); acceptance 0.88 + len 2.76 says n-cap binding; union linear => adjacent-token reuse nil, long-range r=58% motivates hybrid last.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-b97918cd12", "ts": "2026-09-15T16:41:44.745Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Adopt consult sequencing update: 21.36 backs out linear expert union (~1.0x/position), owner-design question closed at ~13.2 t/s measured; insert --spec-draft-n-max sweep (predict ~25 t/s at n=6, continue while acc>=0.6) ahead of hybrid; exp2 already done (no-op); depth falsifier noted (needs non-MTP 14K control for strict MTP-gain comparison)", "rationale": "MTP gain is fixed-term amortization (ceiling ~1.84x, at 1.33x); acceptance 0.88 + len 2.76 says n-cap binding; union linear => adjacent-token reuse nil, long-range r=58% motivates hybrid last.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-14afc765bc', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:04:31.901Z', 'Cap --spec-draft-n-max at 2-3 (n exploration DONE, peak n=5 recorded); future gains from other params/places. Fleet model policy: opencode-go/muse-spark-1.3-contributor for all new agent spawns, free tier retired (also fault-prone). Running workers grandfathered.', 'Owner directive 2026-09-16.', 'owner-directive', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-14afc765bc", "ts": "2026-09-15T17:04:31.901Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Cap --spec-draft-n-max at 2-3 (n exploration DONE, peak n=5 recorded); future gains from other params/places. Fleet model policy: opencode-go/muse-spark-1.3-contributor for all new agent spawns, free tier retired (also fault-prone). Running workers grandfathered.", "rationale": "Owner directive 2026-09-16.", "source": "owner-directive", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e427ce7cfa', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:36:53.917Z', 'Phase 0 GATE FAIL (h@53 45-48% vs 0.70, structural: in-sample cap 67%, transfer ~chance). Static uniform-N tiers dead — publish as negative result. Phase 1 static variant cancelled; re-plan around dynamic per-layer allocation or slow-adapting seeded prior (+16pp). Only 7/48 layers clear 0.70: uniform-N pinning is the wrong shape.', 'Worker REAL_RESULTS.md: heldout h-table both traces, sweep+stability agree exactly, Jaccard transfer ~chance.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-e427ce7cfa", "ts": "2026-09-15T17:36:53.917Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase 0 GATE FAIL (h@53 45-48% vs 0.70, structural: in-sample cap 67%, transfer ~chance). Static uniform-N tiers dead — publish as negative result. Phase 1 static variant cancelled; re-plan around dynamic per-layer allocation or slow-adapting seeded prior (+16pp). Only 7/48 layers clear 0.70: uniform-N pinning is the wrong shape.", "rationale": "Worker REAL_RESULTS.md: heldout h-table both traces, sweep+stability agree exactly, Jaccard transfer ~chance.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0124675ce4', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:38:55.958Z', 'Re-sequence per consult: Phase 2 hybrid FIRST (never needed the gate; +72% alone at h=0.58); per-layer table redirects to Phase 2 PLACEMENT (first-order) not allocation (DP-closed +0.29%); T0.6 shipped-LFU control blocking; Phase 1 re-scoped last/small (seed + half-life on existing LFU, gate +3pp over sim-shipped). Static + per-workload tiers cancelled.', 'Consult verdict: (a) closed by 7.26.1 DP + failed holdout; (b) re-sized +3-6.5pp over shipped (not +16pp); sim-vs-rig half-life contradiction must be explained via T0.6.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-0124675ce4", "ts": "2026-09-15T17:38:55.958Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Re-sequence per consult: Phase 2 hybrid FIRST (never needed the gate; +72% alone at h=0.58); per-layer table redirects to Phase 2 PLACEMENT (first-order) not allocation (DP-closed +0.29%); T0.6 shipped-LFU control blocking; Phase 1 re-scoped last/small (seed + half-life on existing LFU, gate +3pp over sim-shipped). Static + per-workload tiers cancelled.", "rationale": "Consult verdict: (a) closed by 7.26.1 DP + failed holdout; (b) re-sized +3-6.5pp over shipped (not +16pp); sim-vs-rig half-life contradiction must be explained via T0.6.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-9315e1c79f', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:44:11.074Z', 'T0.6 STOP accepted: sim-shipped LFU 61.86/65.40 vs rig 58% (overshoot, outside ±3pp); seeded HL-200 delta -0.9pp fails +3pp bar; seeded-vs-bare hypothesis refuted. No Phase-1 re-scope on sim numbers. Unblock needs rig §§7.16/7.17 regime specs from plan knowledge.', 'Worker calibration report: stock sim, real traces, bit-exact harness; gap is regime-definition, not mechanics.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-9315e1c79f", "ts": "2026-09-15T17:44:11.074Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T0.6 STOP accepted: sim-shipped LFU 61.86/65.40 vs rig 58% (overshoot, outside ±3pp); seeded HL-200 delta -0.9pp fails +3pp bar; seeded-vs-bare hypothesis refuted. No Phase-1 re-scope on sim numbers. Unblock needs rig §§7.16/7.17 regime specs from plan knowledge.", "rationale": "Worker calibration report: stock sim, real traces, bit-exact harness; gap is regime-definition, not mechanics.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-2337602c1f', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:46:21.417Z', 'Adopt slope-based sim acceptance (slope ±25% rel [PASSES 4%]; rank LFU-16>LRU>no-decay [FAILS]; offset stable across N; level not gated). Sim cleared for capacity/placement, blocked for policy. Half-life change ON HOLD (sim ranks rig-last arm first). Strike 7.16 one-third-token story (unit error: 16 tokens). Model three mismatches: prefill pollution, span target 56.3%, 144-cell geometry.', 'Consult regime audit: rig never tested long half-life (256/2048 never tick); HL-200 IS rig no-decay (54.4%, worst).', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-2337602c1f", "ts": "2026-09-15T17:46:21.417Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Adopt slope-based sim acceptance (slope ±25% rel [PASSES 4%]; rank LFU-16>LRU>no-decay [FAILS]; offset stable across N; level not gated). Sim cleared for capacity/placement, blocked for policy. Half-life change ON HOLD (sim ranks rig-last arm first). Strike 7.16 one-third-token story (unit error: 16 tokens). Model three mismatches: prefill pollution, span target 56.3%, 144-cell geometry.", "rationale": "Consult regime audit: rig never tested long half-life (256/2048 never tick); HL-200 IS rig no-decay (54.4%, worst).", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-8cd0383783', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:52:11.954Z', 'T0.7 ACCEPTED: slope PASS-ish, rank FAIL confirmed (LRU first), prefill-pollution closes coding to +0.64pp; geometry confirms sim. Open: LFU-16 definition (d16 flips rank to PASS) — asked consult. Sim usable for capacity/placement with prefill-seeded pipeline.', 'Worker T0.7 report: slope/rank/offset measured, mismatches tested, scripts re-runnable.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-8cd0383783", "ts": "2026-09-15T17:52:11.954Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T0.7 ACCEPTED: slope PASS-ish, rank FAIL confirmed (LRU first), prefill-pollution closes coding to +0.64pp; geometry confirms sim. Open: LFU-16 definition (d16 flips rank to PASS) — asked consult. Sim usable for capacity/placement with prefill-seeded pipeline.", "rationale": "Worker T0.7 report: slope/rank/offset measured, mismatches tested, scripts re-runnable.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-926308cf83', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:53:24.552Z', 'LFU-16 = decay_interval 16 in grouped planning steps (48/decode token; half-life ~1/3 token, zeroed ~10.7). Unstrike 7.16 (consult correction was wrong; source 899d8ec7a). Half-life change stays BLOCKED (rig rejection now stronger). T0.7 must verify planning-step indexing then re-run rank vs rig 58.0/55.6/54.4.', 'Consult source ruling + self-correction.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-926308cf83", "ts": "2026-09-15T17:53:24.552Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "LFU-16 = decay_interval 16 in grouped planning steps (48/decode token; half-life ~1/3 token, zeroed ~10.7). Unstrike 7.16 (consult correction was wrong; source 899d8ec7a). Half-life change stays BLOCKED (rig rejection now stronger). T0.7 must verify planning-step indexing then re-run rank vs rig 58.0/55.6/54.4.", "rationale": "Consult source ruling + self-correction.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-9e911a5583', 'p-7719544617', 't-d1cf43b723', '2026-09-15T17:56:14.066Z', 'T0.7b ACCEPTED: corrected grouped clock (4.8x not 48x — worker corrected premise with receipts) reproduces rig rank d16>LRU>NODECAY on both traces. Level overshoots (ungated); pipeline seed ties d16~LRU leaving rig d16 edge unexplained (open). Sim ranking now trustworthy for policy questions modulo level offset.', 'Worker T0.7b report: clock verified in source, counters verified, rank reproduced exactly.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-9e911a5583", "ts": "2026-09-15T17:56:14.066Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T0.7b ACCEPTED: corrected grouped clock (4.8x not 48x — worker corrected premise with receipts) reproduces rig rank d16>LRU>NODECAY on both traces. Level overshoots (ungated); pipeline seed ties d16~LRU leaving rig d16 edge unexplained (open). Sim ranking now trustworthy for policy questions modulo level offset.", "rationale": "Worker T0.7b report: clock verified in source, counters verified, rank reproduced exactly.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0d73b4e1ee', 'p-7719544617', 't-d1cf43b723', '2026-09-15T18:25:57.447Z', 'Phase 2: T2.1 ACCEPTED (prepend->append verified minimal in diff; default path byte-identical proven by A2==A1 md5). Bit-identity bar = STATISTICAL: PPL equality + fluent-paraphrase divergence accepted as CPU/CUDA rounding, not corruption (row-0-garbage test would catch placement bugs). T2.2 step 1 APPROVED (plan-readback + miss-rate telemetry, zero behavior change, off by default); step 2 (compute move) needs step-1 data + design review first.', 'Worker report + own diff review; llama-context.cpp 84-line dirt is another worker''s, untouched.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-0d73b4e1ee", "ts": "2026-09-15T18:25:57.447Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase 2: T2.1 ACCEPTED (prepend->append verified minimal in diff; default path byte-identical proven by A2==A1 md5). Bit-identity bar = STATISTICAL: PPL equality + fluent-paraphrase divergence accepted as CPU/CUDA rounding, not corruption (row-0-garbage test would catch placement bugs). T2.2 step 1 APPROVED (plan-readback + miss-rate telemetry, zero behavior change, off by default); step 2 (compute move) needs step-1 data + design review first.", "rationale": "Worker report + own diff review; llama-context.cpp 84-line dirt is another worker''s, untouched.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-7e209fac11', 'p-7719544617', 't-d1cf43b723', '2026-09-15T19:00:59.251Z', 'P1 telemetry crash = graph-capture violation (quantize_row_q8_1_cuda during capture) — the worker''s own flagged risk. Fix direction: capture-safe readback (after capture, zero behavior change). Re-dispatched to same worker.', 'server-P1-on.log CUDA error + backtrace; rig idle; P0-off control holds.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-7e209fac11", "ts": "2026-09-15T19:00:59.251Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "P1 telemetry crash = graph-capture violation (quantize_row_q8_1_cuda during capture) — the worker''s own flagged risk. Fix direction: capture-safe readback (after capture, zero behavior change). Re-dispatched to same worker.", "rationale": "server-P1-on.log CUDA error + backtrace; rig idle; P0-off control holds.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0e0a116d88', 'p-7719544617', 't-d1cf43b723', '2026-09-15T19:13:34.994Z', 'T2.2-step1 ACCEPTED (diff matches claim +108/+8; h=0.5834 confirms 0.58; off-path 11.60 zero-change; crash root-caused to in-capture stream ops, fixed capture-safe). Step 2 (compute move) APPROVED with gates: (a) off by default, (b) P0 parity when off, (c) zero stream ops inside capture, (d) statistical bar (PPL equality + no row-0 garbage), (e) target ~37 t/s vs 21.36 priced at live h=0.58. Worker earned direct approval by clean capture diagnosis.', 'Step-1 data in hand; worker demonstrated capture discipline; gates enforce safety without extra round trip.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-0e0a116d88", "ts": "2026-09-15T19:13:34.994Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T2.2-step1 ACCEPTED (diff matches claim +108/+8; h=0.5834 confirms 0.58; off-path 11.60 zero-change; crash root-caused to in-capture stream ops, fixed capture-safe). Step 2 (compute move) APPROVED with gates: (a) off by default, (b) P0 parity when off, (c) zero stream ops inside capture, (d) statistical bar (PPL equality + no row-0 garbage), (e) target ~37 t/s vs 21.36 priced at live h=0.58. Worker earned direct approval by clean capture diagnosis.", "rationale": "Step-1 data in hand; worker demonstrated capture discipline; gates enforce safety without extra round trip.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ca543da92e', 'p-7719544617', 't-d1cf43b723', '2026-09-15T19:30:16.209Z', 'Step-2 design ACCEPTED (Approach A row-overwrite, B rejected with reason). Rulings: (1) Phase C shadow APPROVED (graphs ON, zero behavior change, numerics proof); (2) gate-(a) baseline: Phase D/E MUST compare against a no-graph P0 arm measured in the same config — 11.6-with-graphs is invalid there; worker to capture no-graph P0 as part of Phase D; (3) Phase D approved CONDITIONAL on Phase C max-abs-diff passing + no-graph P0 in hand; Phase E held for D data. Perf honesty accepted: step 2 is a correctness vehicle, report numbers without perf bar.', 'Design note is complete: hard constraint proven, hook point legal, fallback identified, gates mapped.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-ca543da92e", "ts": "2026-09-15T19:30:16.209Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Step-2 design ACCEPTED (Approach A row-overwrite, B rejected with reason). Rulings: (1) Phase C shadow APPROVED (graphs ON, zero behavior change, numerics proof); (2) gate-(a) baseline: Phase D/E MUST compare against a no-graph P0 arm measured in the same config — 11.6-with-graphs is invalid there; worker to capture no-graph P0 as part of Phase D; (3) Phase D approved CONDITIONAL on Phase C max-abs-diff passing + no-graph P0 in hand; Phase E held for D data. Perf honesty accepted: step 2 is a correctness vehicle, report numbers without perf bar.", "rationale": "Design note is complete: hard constraint proven, hook point legal, fallback identified, gates mapped.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a70f47f663', 'p-7719544617', 't-d1cf43b723', '2026-09-15T21:02:41.583Z', 'Phase C compare-as-designed INVALID: finish-time D2H reads allocator-recycled buffers (dst!=down.h with W proven identical — airtight). Option E APPROVED: strip finish hook to record-only (live x + miss-expert list), validate CPU-vs-GPU out-of-band in standalone binary (no cache/graph/allocator); integration covered by PPL/greedy gates in D. Reject A (invasive to llama-graph, perturbs P0 layout). Also: strip ~700 lines debug over 7 files back to the chosen path.', 'Worker evidence chain (slotbytes exact, plan consistent, yet dst!=down.h) leaves only dead-buffer reads; E proves numerics without touching the allocator.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-a70f47f663", "ts": "2026-09-15T21:02:41.583Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase C compare-as-designed INVALID: finish-time D2H reads allocator-recycled buffers (dst!=down.h with W proven identical — airtight). Option E APPROVED: strip finish hook to record-only (live x + miss-expert list), validate CPU-vs-GPU out-of-band in standalone binary (no cache/graph/allocator); integration covered by PPL/greedy gates in D. Reject A (invasive to llama-graph, perturbs P0 layout). Also: strip ~700 lines debug over 7 files back to the chosen path.", "rationale": "Worker evidence chain (slotbytes exact, plan consistent, yet dst!=down.h) leaves only dead-buffer reads; E proves numerics without touching the allocator.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-bb3d28a894', 'p-7719544617', 't-d1cf43b723', '2026-09-15T21:09:20.037Z', 'Sim residual RESOLVED mechanistically by consult: (b) d16 erases prefill by decode ~11 (32-epoch zeroing), so rig pollution handicaps only LRU/NODECAY — pipeline seed must apply decay law to seeded history (refinement 1, nearly free). (a) spread compression = policy-blind taxes (unconditional admission 32% once-touched + slot pinning ~10/cell + possible prefetch path) — refinements 2/3. Verdict: sim cleared for capacity/placement PENDING gate 3 (offset stable across N, residual ±2pp no monotone trend). Do not chase spread before Phase 2 needs it.', 'Consult source-grounded answers (899d8ec7a zeroing, 7.15 admission, slot_pin_count); gates 1-2 pass, gate 3 outstanding.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-bb3d28a894", "ts": "2026-09-15T21:09:20.037Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Sim residual RESOLVED mechanistically by consult: (b) d16 erases prefill by decode ~11 (32-epoch zeroing), so rig pollution handicaps only LRU/NODECAY — pipeline seed must apply decay law to seeded history (refinement 1, nearly free). (a) spread compression = policy-blind taxes (unconditional admission 32% once-touched + slot pinning ~10/cell + possible prefetch path) — refinements 2/3. Verdict: sim cleared for capacity/placement PENDING gate 3 (offset stable across N, residual ±2pp no monotone trend). Do not chase spread before Phase 2 needs it.", "rationale": "Consult source-grounded answers (899d8ec7a zeroing, 7.15 admission, slot_pin_count); gates 1-2 pass, gate 3 outstanding.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-124dda3236', 'p-7719544617', 't-d1cf43b723', '2026-09-15T21:14:10.672Z', 'T0.7c ACCEPTED: snap-back half-confirmed (d16 step-8, NODECAY depressed; LRU refutes — adapts in ~5-12 steps, edge unexplained); Gate-3 offset constant per workload (±0.4pp) — sim shape conditionally cleared pending rig mids; uniform capacity-cut ruled out (N* diverges); admission matches (34% vs 32%). Rig-side closeout by lead: prefetch CONFIRMED ON+active on N53 arms (exp1 --ple-prefetch + log prefetch_used=29 at 100%) — a real policy-blind tax supporting the compression story. Anchor ruling: 58.0 measured aggregate (56.3 span variant stays as sensitivity). No further sim work until Phase 2 needs it.', 'Worker report + own flag/log verification.', 'consult', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-124dda3236", "ts": "2026-09-15T21:14:10.672Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T0.7c ACCEPTED: snap-back half-confirmed (d16 step-8, NODECAY depressed; LRU refutes — adapts in ~5-12 steps, edge unexplained); Gate-3 offset constant per workload (±0.4pp) — sim shape conditionally cleared pending rig mids; uniform capacity-cut ruled out (N* diverges); admission matches (34% vs 32%). Rig-side closeout by lead: prefetch CONFIRMED ON+active on N53 arms (exp1 --ple-prefetch + log prefetch_used=29 at 100%) — a real policy-blind tax supporting the compression story. Anchor ruling: 58.0 measured aggregate (56.3 span variant stays as sensitivity). No further sim work until Phase 2 needs it.", "rationale": "Worker report + own flag/log verification.", "source": "consult", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6f2a347bbd', 'p-7719544617', 't-d1cf43b723', '2026-09-15T21:17:53.340Z', 'Option E ACCEPTED under bounded equivalence (maxd_out 0.039-0.095 ≤ 0.15 + sign agreement; mechanism = CUDA fp16 scale products vs CPU fp32, CPU side more accurate; exact-equality bar was wrong). Phase D (move, graphs OFF) APPROVED: must capture no-graph P0 baseline first, then overwrite with staging on (correct-then-fast), gates = PPL equality + greedy statistical bar + t/s vs no-graph P0 and 21.36. Fallback (fp16-scale emulation) only on PPL signal. Diff scope verified (+354/+11, ours only).', 'Standalone validator bounds the error and names the mechanism; end-to-end gates are the correct arbiter; kernel alignment out of scope.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-6f2a347bbd", "ts": "2026-09-15T21:17:53.340Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Option E ACCEPTED under bounded equivalence (maxd_out 0.039-0.095 ≤ 0.15 + sign agreement; mechanism = CUDA fp16 scale products vs CPU fp32, CPU side more accurate; exact-equality bar was wrong). Phase D (move, graphs OFF) APPROVED: must capture no-graph P0 baseline first, then overwrite with staging on (correct-then-fast), gates = PPL equality + greedy statistical bar + t/s vs no-graph P0 and 21.36. Fallback (fp16-scale emulation) only on PPL signal. Diff scope verified (+354/+11, ours only).", "rationale": "Standalone validator bounds the error and names the mechanism; end-to-end gates are the correct arbiter; kernel alignment out of scope.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-929376401d', 'p-7719544617', 't-d1cf43b723', '2026-09-15T21:34:59.841Z', 'Phase D ACCEPTED: byte-identical greedy (6ceeb608) + exact PPL (15.7524) + zero off-path change (OFFCHECK identical); 5.89 vs 11.05 regression expected (CPU on critical path, staging still on — Phase E''s job). Scope verified (ours +686/+14; others'' dirt untouched; stray orchestration.md removed; PROJECT_STATUS.md +32 kept). Phase E (staging skip for CPU-owned misses) dispatched as DESIGN-FIRST: design note with hook point, fallback, and priced win before any code.', 'Correctness vehicle delivered exactly as priced; perf payoff needs its own design review.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-929376401d", "ts": "2026-09-15T21:34:59.841Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase D ACCEPTED: byte-identical greedy (6ceeb608) + exact PPL (15.7524) + zero off-path change (OFFCHECK identical); 5.89 vs 11.05 regression expected (CPU on critical path, staging still on — Phase E''s job). Scope verified (ours +686/+14; others'' dirt untouched; stray orchestration.md removed; PROJECT_STATUS.md +32 kept). Phase E (staging skip for CPU-owned misses) dispatched as DESIGN-FIRST: design note with hook point, fallback, and priced win before any code.", "rationale": "Correctness vehicle delivered exactly as priced; perf payoff needs its own design review.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-2b41453f92', 'p-7719544617', 't-d1cf43b723', '2026-09-15T21:40:43.872Z', 'Phase E NO-GO ACCEPTED: priced net loss (7-7.6 vs 11.05; CPU 395us/row vs fill ~140us — skipping the cheaper op), failure mode degrades best-effort to silent-corruption, structural not tunable. Phase 2 CLOSES as correctness vehicle: T2.1 + step-1 + Phase D all proven (identical greedy, exact PPL, h=0.5834). Close-out = selective commit of our 4 files only (never others'' dirt), build verify, PROJECT_STATUS + lessons. Compaction/mask is a future epic, not this track.', 'Worker priced the win honestly as requested; NO-GO is the deliverable-grade answer.', 'user', 0, 'd6cc5704-6ad0-4248-9639-f14ca6958cb5', '{"id": "d-2b41453f92", "ts": "2026-09-15T21:40:43.872Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase E NO-GO ACCEPTED: priced net loss (7-7.6 vs 11.05; CPU 395us/row vs fill ~140us — skipping the cheaper op), failure mode degrades best-effort to silent-corruption, structural not tunable. Phase 2 CLOSES as correctness vehicle: T2.1 + step-1 + Phase D all proven (identical greedy, exact PPL, h=0.5834). Close-out = selective commit of our 4 files only (never others'' dirt), build verify, PROJECT_STATUS + lessons. Compaction/mask is a future epic, not this track.", "rationale": "Worker priced the win honestly as requested; NO-GO is the deliverable-grade answer.", "source": "user", "irreversible": false, "author": "d6cc5704-6ad0-4248-9639-f14ca6958cb5"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f1b813dd2c', 'p-7719544617', 't-d1cf43b723', '2026-09-16T00:39:44.866Z', 'Combine: owner override — implement prefetch-fed MTP verify within n<=3 cap; literal block-48 parked pending cap lift + multi-head formulation', 'Owner directive 2026-09-16 overrides d-f0f5fb9f63 dequeue of the Colibri-combine arm. Two-scout maps (EarlyRouterMap, MtpVerifyMap) force a re-scope: (1) MTP draft() is strictly sequential 1-token-per-decode (speculative.cpp:1834-1851), no block-48 exists anywhere in the MTP path; (2) qwen4exp::graph_mtp asserts n_layer_nextn==1 (qwen4exp.cpp:509-510) — a 48-deep speculative chain is structurally impossible with the single MTP head (needs 48 heads or a reused-head recurrent formulation); (3) owner cap d-14afc765bc holds --spec-draft-n-max at 2-3, in direct conflict with literal block-48; (4) early-router predictor is complete but same-layer staging-assist only — predictions never drive cache residency (no acquire/pin from predicted ids), copy-engine H2D is dormant without CUDA-graph capture, and MTP verify has no dedicated wiring; (5) cache+MTP are mutually exclusive today (REQUIRED_GROUPED cert, llama-context.cpp:62-65). Staged plan honoring all constraints: S1 admit MTP to grouped-plan as record-only telemetry (env-gated, OFF=byte-identical); S2 wire predicted ids to acquire/pin ahead of verify dispatch; S3 copy-engine eager bring-up for MTP verify only if S2 needs it; S4 rig A/B (Q4 head, DRAFT_N=2, n unchanged) with priced GO/NO-GO. Fallback at every stage: telemetry-only, zero behavior change (established pattern). Block-48 stays parked until owner lifts the n-cap AND a multi-head/recurrent formulation is designed.', 'owner-directive', 0, '', '{"id": "d-f1b813dd2c", "ts": "2026-09-16T00:39:44.866Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Combine: owner override — implement prefetch-fed MTP verify within n<=3 cap; literal block-48 parked pending cap lift + multi-head formulation", "rationale": "Owner directive 2026-09-16 overrides d-f0f5fb9f63 dequeue of the Colibri-combine arm. Two-scout maps (EarlyRouterMap, MtpVerifyMap) force a re-scope: (1) MTP draft() is strictly sequential 1-token-per-decode (speculative.cpp:1834-1851), no block-48 exists anywhere in the MTP path; (2) qwen4exp::graph_mtp asserts n_layer_nextn==1 (qwen4exp.cpp:509-510) — a 48-deep speculative chain is structurally impossible with the single MTP head (needs 48 heads or a reused-head recurrent formulation); (3) owner cap d-14afc765bc holds --spec-draft-n-max at 2-3, in direct conflict with literal block-48; (4) early-router predictor is complete but same-layer staging-assist only — predictions never drive cache residency (no acquire/pin from predicted ids), copy-engine H2D is dormant without CUDA-graph capture, and MTP verify has no dedicated wiring; (5) cache+MTP are mutually exclusive today (REQUIRED_GROUPED cert, llama-context.cpp:62-65). Staged plan honoring all constraints: S1 admit MTP to grouped-plan as record-only telemetry (env-gated, OFF=byte-identical); S2 wire predicted ids to acquire/pin ahead of verify dispatch; S3 copy-engine eager bring-up for MTP verify only if S2 needs it; S4 rig A/B (Q4 head, DRAFT_N=2, n unchanged) with priced GO/NO-GO. Fallback at every stage: telemetry-only, zero behavior change (established pattern). Block-48 stays parked until owner lifts the n-cap AND a multi-head/recurrent formulation is designed.", "source": "owner-directive", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b090dc64c6', 'p-7719544617', 't-d1cf43b723', '2026-09-16T01:15:03.843Z', 'Combine S1+S2 ACCEPTED as record-only scaffolding (proven no-op); S4 full verify-fed loop NO-GO structural; S3 copy-engine CONDITIONAL-GO on cache-ON arm', 'Worker CombineImpl1 (34.5m) delivered + leader verified: build exit 0 (build-gs-cuda1322, llama-server+perplexity); OFF parity exact (PPL 31.7412 exact, token-sig 9d8341a1756e7064 identical 4 legs, telemetry silent OFF); ON record-only engaged with output identity (acceptance 0.86897 bit-stable all legs, t/s deltas within noise — no perf claim). Diff verified ours-only 4 files (moe-cache.cu +250/-2, cuh +11, llama-context.cpp +~230/-~20, llama-context.h +5); speculative.cpp untouched; CMake hunks confirmed pre-existing co-worker dirt (LLAMA_MOE_GROUPED_DEBUG); co-worker hunks intact. Key structural finding: memory-module ubatch re-split breaks span shape so every record-only intent drops to legacy (admitted=200+, fallback~admitted); CUDA telemetry all-zero structurally expected (cache-OFF+cpu-moe = no CUDA MoE resources, nothing to sample). S4 NO-GO: grouped-plan/MTP exclusivity is structural and re-split breaks the only admission shape — needs MTP-aware planner or eagle-style path. S3 CONDITIONAL: (1) align ubatch spans with batch spans first, (2) stand up cache-ON+GPU-MoE MTP arm, (3) then staging->residency via copy_worker/mailbox; do NOT start in cache-OFF rig (zero signal). All default-OFF, zero behavior change.', 'user', 0, '', '{"id": "d-b090dc64c6", "ts": "2026-09-16T01:15:03.843Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Combine S1+S2 ACCEPTED as record-only scaffolding (proven no-op); S4 full verify-fed loop NO-GO structural; S3 copy-engine CONDITIONAL-GO on cache-ON arm", "rationale": "Worker CombineImpl1 (34.5m) delivered + leader verified: build exit 0 (build-gs-cuda1322, llama-server+perplexity); OFF parity exact (PPL 31.7412 exact, token-sig 9d8341a1756e7064 identical 4 legs, telemetry silent OFF); ON record-only engaged with output identity (acceptance 0.86897 bit-stable all legs, t/s deltas within noise — no perf claim). Diff verified ours-only 4 files (moe-cache.cu +250/-2, cuh +11, llama-context.cpp +~230/-~20, llama-context.h +5); speculative.cpp untouched; CMake hunks confirmed pre-existing co-worker dirt (LLAMA_MOE_GROUPED_DEBUG); co-worker hunks intact. Key structural finding: memory-module ubatch re-split breaks span shape so every record-only intent drops to legacy (admitted=200+, fallback~admitted); CUDA telemetry all-zero structurally expected (cache-OFF+cpu-moe = no CUDA MoE resources, nothing to sample). S4 NO-GO: grouped-plan/MTP exclusivity is structural and re-split breaks the only admission shape — needs MTP-aware planner or eagle-style path. S3 CONDITIONAL: (1) align ubatch spans with batch spans first, (2) stand up cache-ON+GPU-MoE MTP arm, (3) then staging->residency via copy_worker/mailbox; do NOT start in cache-OFF rig (zero signal). All default-OFF, zero behavior change.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-2063e47df8', 'p-7719544617', 't-d1cf43b723', '2026-09-16T02:08:34.055Z', 'Accept tiering design PR #131 as implementation sequence T-1..T-6; T-1 dispatched first; 64K probe pulled forward after T-2', 'Design reviewed in full (206 lines). Agree: prediction dead, tiering by execution site, f_link=0.171, numeric gates with stop-on-failure. T-1 blocking (#124 cache+MTP exclusivity). Two deviations: (1) pull a 64K capacity probe forward right after T-2 — T-4 N~65-70 sizing assumes freed VRAM that 64K KV may eat; (2) reconcile per-expert bytes (2.15 vs 1.79-1.88) during T-1/T-2, before T-3 tunes against them. Fresh evidence for T-1: combine S1 found the ubatch re-split drops every batch-span intent to legacy — same intent machinery as #124, likely same root.', 'user', 0, '', '{"id": "d-2063e47df8", "ts": "2026-09-16T02:08:34.055Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Accept tiering design PR #131 as implementation sequence T-1..T-6; T-1 dispatched first; 64K probe pulled forward after T-2", "rationale": "Design reviewed in full (206 lines). Agree: prediction dead, tiering by execution site, f_link=0.171, numeric gates with stop-on-failure. T-1 blocking (#124 cache+MTP exclusivity). Two deviations: (1) pull a 64K capacity probe forward right after T-2 — T-4 N~65-70 sizing assumes freed VRAM that 64K KV may eat; (2) reconcile per-expert bytes (2.15 vs 1.79-1.88) during T-1/T-2, before T-3 tunes against them. Fresh evidence for T-1: combine S1 found the ubatch re-split drops every batch-span intent to legacy — same intent machinery as #124, likely same root.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-c729833741', 'p-7719544617', 't-d1cf43b723', '2026-09-16T02:12:13.263Z', 'Accept architect adjudication: T-4 demoted to last-or-never (ceiling N~53-57, N=64 measured OOM); use 2.148 MiB for VRAM-shaped sizing; T-3 +5% gate is the design''s deciding gate', 'Architect vs plan 7.15: 64K KV already paid (all capacity arms ran -c 81920, eager alloc) — no 64K capacity probe needed. But T-4''s premise is dead: N=64 hard OOM measured, marginal 103 MiB/slot, base 6409 MiB, hybrid saves 1-2 slots => ceiling N~53-57, already sitting on it; §4 corrected in PR (8f8c227e0, re-pull before T-4), §5 top row ~44.5. T-3 now carries all remaining upside (~40 -> ~44); if it misses +5%, design is done at MTP+CPU-MoE. Byte figure: 2.148 MiB (falsified prediction behind it) for VRAM-shaped, ledger 1.793 for transfer-time. T-1 plan approved unchanged.', 'user', 0, '', '{"id": "d-c729833741", "ts": "2026-09-16T02:12:13.263Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Accept architect adjudication: T-4 demoted to last-or-never (ceiling N~53-57, N=64 measured OOM); use 2.148 MiB for VRAM-shaped sizing; T-3 +5% gate is the design''s deciding gate", "rationale": "Architect vs plan 7.15: 64K KV already paid (all capacity arms ran -c 81920, eager alloc) — no 64K capacity probe needed. But T-4''s premise is dead: N=64 hard OOM measured, marginal 103 MiB/slot, base 6409 MiB, hybrid saves 1-2 slots => ceiling N~53-57, already sitting on it; §4 corrected in PR (8f8c227e0, re-pull before T-4), §5 top row ~44.5. T-3 now carries all remaining upside (~40 -> ~44); if it misses +5%, design is done at MTP+CPU-MoE. Byte figure: 2.148 MiB (falsified prediction behind it) for VRAM-shaped, ledger 1.793 for transfer-time. T-1 plan approved unchanged.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-3c10df42db', 'p-7719544617', 't-d1cf43b723', '2026-09-16T02:40:30.229Z', 'Close T-1 as resolved-in-tree: #124 verified absent on current tree with Q4 head, no fix landed (zero source edits)', 'Gate met directly: draft acceptance present with cache on (0.86897 cpu-moe / 0.88194 no-cpu-moe) + parity vs same-session cache-0 control (0.86897, identical 126/145 streams) + required_unsupported=0 + covered 49/49 + no grouped-plan-unavailable in any of 5 cache-ON legs. Prescribed prime suspect refuted with mechanism: :472 hard-requires cache_slots>0, so cache-0 match=0 (223/223) is gate artifact, cache-32 match=1 (584/584) with certs stamped. Historical Q8-head failure predates f6301d4ee (#121, same machinery) + T2.1; attribution to f6301d4ee is likely-but-unproven. Landing a fix for absent bug = weightless dead code, refused per contract. Residuals carried: Q8 head never tested; 14K-prompt split path with intents untested.', 'user', 0, '', '{"id": "d-3c10df42db", "ts": "2026-09-16T02:40:30.229Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Close T-1 as resolved-in-tree: #124 verified absent on current tree with Q4 head, no fix landed (zero source edits)", "rationale": "Gate met directly: draft acceptance present with cache on (0.86897 cpu-moe / 0.88194 no-cpu-moe) + parity vs same-session cache-0 control (0.86897, identical 126/145 streams) + required_unsupported=0 + covered 49/49 + no grouped-plan-unavailable in any of 5 cache-ON legs. Prescribed prime suspect refuted with mechanism: :472 hard-requires cache_slots>0, so cache-0 match=0 (223/223) is gate artifact, cache-32 match=1 (584/584) with certs stamped. Historical Q8-head failure predates f6301d4ee (#121, same machinery) + T2.1; attribution to f6301d4ee is likely-but-unproven. Landing a fix for absent bug = weightless dead code, refused per contract. Residuals carried: Q8 head never tested; 14K-prompt split path with intents untested.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ce1e9913f5', 'p-7719544617', 't-d1cf43b723', '2026-09-16T02:50:33.421Z', 'T-2 gate FAIL (10.40 vs 21.36); tiering design terminal one gate early — recommend stopping T-3..T-5 implementation, holding for architect closeout call', 'Not a near-miss: projection ~40 refuted. Control reproduces gate ref (21.23 vs 21.36, acc identical). Hybrid equals cache-32 no-split (10.4 vs 10.53): the split adds nothing — unengaged under graphs (production path, defer_completion), skip-heavy off-graphs (3456 skips/777 rows). T-3''s +5% over T-2 (~10.9) cannot bridge to 21.36; T-4 already dead; T-5''s +3pp h on a 10.4 base irrelevant. Architect''s own stop rule (''MTP + CPU-MoE at 21.4 was most of what the rig had'') triggers here, one gate early. Correctness held (acceptance bit-stable 0.88194 vs control 0.86897 streams). Hygiene verified by leader: land commit 7e9cbdc40 real, -dirty = pre-existing 6-file dirt intact, combine diff left uncommitted per d-b090dc64c6. Open closeout Qs: revert gitlink or keep env-gated no-op; submodule 0fc51e039 unpushed; T-6 64K verify of what (nothing to verify).', 'user', 0, '', '{"id": "d-ce1e9913f5", "ts": "2026-09-16T02:50:33.421Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T-2 gate FAIL (10.40 vs 21.36); tiering design terminal one gate early — recommend stopping T-3..T-5 implementation, holding for architect closeout call", "rationale": "Not a near-miss: projection ~40 refuted. Control reproduces gate ref (21.23 vs 21.36, acc identical). Hybrid equals cache-32 no-split (10.4 vs 10.53): the split adds nothing — unengaged under graphs (production path, defer_completion), skip-heavy off-graphs (3456 skips/777 rows). T-3''s +5% over T-2 (~10.9) cannot bridge to 21.36; T-4 already dead; T-5''s +3pp h on a 10.4 base irrelevant. Architect''s own stop rule (''MTP + CPU-MoE at 21.4 was most of what the rig had'') triggers here, one gate early. Correctness held (acceptance bit-stable 0.88194 vs control 0.86897 streams). Hygiene verified by leader: land commit 7e9cbdc40 real, -dirty = pre-existing 6-file dirt intact, combine diff left uncommitted per d-b090dc64c6. Open closeout Qs: revert gitlink or keep env-gated no-op; submodule 0fc51e039 unpushed; T-6 64K verify of what (nothing to verify).", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-12f409dc1c', 'p-7719544617', 't-d1cf43b723', '2026-09-16T03:04:20.097Z', 'Architect one-arm verdict: do NOT stop; exactly one directed engagement-gated arm (T-2b). T-2 read as non-measurement (both legs cache-only path; 10.40 predicted by model at 2.05x). Projection haircut ~40 -> ~36 (miss term 1.14x nominal, §5.1 in 0a77ac79b).', 'Architect: H1 unengaged + H2 skip-heavy = hybrid never ran; 10.40 sits on capacity-sweep line (N=36 10.36, N=42 10.84) and matches model prediction (2.05x vs predicted ~2x) — model not refuted. New evidence: shared fixed term F~29 (cache-on 29.14 w/ 278 hits vs CPU-MoE 28.34 w/ 0) => resident hit 0.0029ms vs miss 0.2842ms (99x) — tier-1 premise measured. Arm spec: per-dispatch CPU/GPU counter (permanent, auto-assert — third silent non-engagement on track), fix defer_completion under graphs-on, assert cpu_fraction ~= 0.42+-0.05 before any t/s; kill <30 engaged, continue >=30 -> T-3 live. Tree: keep env-gated no-op (control 21.23 vs 21.36 evidences no-op); push submodule commit today (dangling gitlink is the bad state); commit combine diff somewhere named.', 'user', 0, '', '{"id": "d-12f409dc1c", "ts": "2026-09-16T03:04:20.097Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect one-arm verdict: do NOT stop; exactly one directed engagement-gated arm (T-2b). T-2 read as non-measurement (both legs cache-only path; 10.40 predicted by model at 2.05x). Projection haircut ~40 -> ~36 (miss term 1.14x nominal, §5.1 in 0a77ac79b).", "rationale": "Architect: H1 unengaged + H2 skip-heavy = hybrid never ran; 10.40 sits on capacity-sweep line (N=36 10.36, N=42 10.84) and matches model prediction (2.05x vs predicted ~2x) — model not refuted. New evidence: shared fixed term F~29 (cache-on 29.14 w/ 278 hits vs CPU-MoE 28.34 w/ 0) => resident hit 0.0029ms vs miss 0.2842ms (99x) — tier-1 premise measured. Arm spec: per-dispatch CPU/GPU counter (permanent, auto-assert — third silent non-engagement on track), fix defer_completion under graphs-on, assert cpu_fraction ~= 0.42+-0.05 before any t/s; kill <30 engaged, continue >=30 -> T-3 live. Tree: keep env-gated no-op (control 21.23 vs 21.36 evidences no-op); push submodule commit today (dangling gitlink is the bad state); commit combine diff somewhere named.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d3debc3dbc', 'p-7719544617', 't-d1cf43b723', '2026-09-16T03:23:08.880Z', 'T-2b STOP (cpu_fraction 0.0074, assertion FAIL): split still unengaged after fix — 100% of skips at stage-3 plan-vs-tensor consistency; no throughput per rule. Design neither killed by kill-rule (needs engaged+<30) nor continued (>=30). Await architect: dead vs one surgical stage-3 arm with recalibrated band.', 'Worker complied exactly: fix runs under graphs (3601 completions attempted) but 96% skip, all 3456 at stage-3 plan-vs-tensor consistency in deferred path — a localized, mechanistically precise defect (plan declares misses the deferred tensor path can''t consume). Counter deliverable meets the durable-fix ask (permanent ungated atomics, auto-assert verdict + skip stages, zero stream ops) and is backed up pushed. Correctness: bit-identical md5 + acc 0.88194. Caveat carried: assertion band 0.42+-0.05 miscalibrated for this workload (plan-declared miss share 0.5445) — but 0.0074 fails any band, so STOP stands regardless. Next is architect''s call: (a) design dead, (b) one surgical stage-3-consistency arm with ~0.54 band, with the counter as the standing gate.', 'user', 0, '', '{"id": "d-d3debc3dbc", "ts": "2026-09-16T03:23:08.880Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T-2b STOP (cpu_fraction 0.0074, assertion FAIL): split still unengaged after fix — 100% of skips at stage-3 plan-vs-tensor consistency; no throughput per rule. Design neither killed by kill-rule (needs engaged+<30) nor continued (>=30). Await architect: dead vs one surgical stage-3 arm with recalibrated band.", "rationale": "Worker complied exactly: fix runs under graphs (3601 completions attempted) but 96% skip, all 3456 at stage-3 plan-vs-tensor consistency in deferred path — a localized, mechanistically precise defect (plan declares misses the deferred tensor path can''t consume). Counter deliverable meets the durable-fix ask (permanent ungated atomics, auto-assert verdict + skip stages, zero stream ops) and is backed up pushed. Correctness: bit-identical md5 + acc 0.88194. Caveat carried: assertion band 0.42+-0.05 miscalibrated for this workload (plan-declared miss share 0.5445) — but 0.0074 fails any band, so STOP stands regardless. Next is architect''s call: (a) design dead, (b) one surgical stage-3-consistency arm with ~0.54 band, with the counter as the standing gate.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d24d39ca9d', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:24:26.990Z', 'T-2c debug arm task-d6a8936b1e: veto forensics + residency-vs-demand trace before any further gate verdict.', 'Right-thing-right-time needs (a) which stage-3 sub-check vetoes each dispatch, (b) resident-set timestamp vs demand time per expert. No more gate verdicts on uninstrumented legs.', 'leader', 0, '', '{"id": "d-d24d39ca9d", "ts": "2026-09-16T04:24:26.990Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T-2c debug arm task-d6a8936b1e: veto forensics + residency-vs-demand trace before any further gate verdict.", "rationale": "Right-thing-right-time needs (a) which stage-3 sub-check vetoes each dispatch, (b) resident-set timestamp vs demand time per expert. No more gate verdicts on uninstrumented legs.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a8b4c6a9f0', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:24:29.977Z', 'Push back on tiering design, never drop it: instrument, debug, and change the design to improve the implementation.', 'Owner directive 2026-09-16: T-2b STOP is pushback input (stage-3 veto forensics), not a design obituary. T-3..T-6 re-framed as blocked-on-debug, not blocked-on-dead-call. Engineer mentality: never accept-as-is.', 'owner-directive', 0, '', '{"id": "d-a8b4c6a9f0", "ts": "2026-09-16T04:24:29.977Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Push back on tiering design, never drop it: instrument, debug, and change the design to improve the implementation.", "rationale": "Owner directive 2026-09-16: T-2b STOP is pushback input (stage-3 veto forensics), not a design obituary. T-3..T-6 re-framed as blocked-on-debug, not blocked-on-dead-call. Engineer mentality: never accept-as-is.", "source": "owner-directive", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-08dc6afb74', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:24:29.981Z', '3060 operating cap N=42 max: headroom reserved for MTP head + ctx size.', 'Owner directive 2026-09-16: supersedes N~53-57 ceiling language for 3060 legs. N=42 is the box, not a probe point.', 'owner-directive', 0, '', '{"id": "d-08dc6afb74", "ts": "2026-09-16T04:24:29.981Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "3060 operating cap N=42 max: headroom reserved for MTP head + ctx size.", "rationale": "Owner directive 2026-09-16: supersedes N~53-57 ceiling language for 3060 legs. N=42 is the box, not a probe point.", "source": "owner-directive", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b10518c1a5', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:41:47.869Z', 'Architect verdict: implementation-gap at moe-cache.cu:12601 (down_n1 width mismatch, plan vs node count routes in different MTP scopes); veto-fix first with cpu_fraction 0.42+-0.05 gate, static-pin to paper-design-only with holdout gate.', 'Consult 49f717e1 on T-2c veto log: stage3_vetoes=3456 all down_n1, first veto n_routes=30 vs down_ne1=10 (factor 3 = MTP ubatch width). Churn (6674/13546 never-resident, 80-97GB H2D) is accomplice. Static-pin needs new row-level machinery (experts 512 rows/tensor; whole-tensor claims would pin ~46GiB) and contradicts §2 transfer data (Jaccard 0.463). Unpriced risk: width-scope error may extend beyond stage-3 into T-3 denominators.', 'consult', 0, '', '{"id": "d-b10518c1a5", "ts": "2026-09-16T04:41:47.869Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect verdict: implementation-gap at moe-cache.cu:12601 (down_n1 width mismatch, plan vs node count routes in different MTP scopes); veto-fix first with cpu_fraction 0.42+-0.05 gate, static-pin to paper-design-only with holdout gate.", "rationale": "Consult 49f717e1 on T-2c veto log: stage3_vetoes=3456 all down_n1, first veto n_routes=30 vs down_ne1=10 (factor 3 = MTP ubatch width). Churn (6674/13546 never-resident, 80-97GB H2D) is accomplice. Static-pin needs new row-level machinery (experts 512 rows/tensor; whole-tensor claims would pin ~46GiB) and contradicts §2 transfer data (Jaccard 0.463). Unpriced risk: width-scope error may extend beyond stage-3 into T-3 denominators.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e7f3495fca', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:42:01.448Z', 'T-2c done: veto 100% down_n1 (MTP 3-position x topK10 = 30 routes vs 10-row reader node); fix = per-position-slice stage-3 validation. Engagement band recalibrates to ~0.54 (live miss 54%, not h=0.58). Global-42 static pins DEAD (6.4%/5% recall, ~0% transfer); per-layer-42 (61%) needs 4.3GiB, does not fit 3060 (425MiB free at decode). Fresh footprints retire 9293 ledger: load 10639/1273, decode ~11487/425.', 'T2cVetoTrace yield: 13546 pairs, token-sig OFF==ON 738173b6, rig idle, nothing committed. f_link recurrence test 0.2136 (~2x chance) weakens §3 rationale but does not kill it.', 'leader', 0, '', '{"id": "d-e7f3495fca", "ts": "2026-09-16T04:42:01.448Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T-2c done: veto 100% down_n1 (MTP 3-position x topK10 = 30 routes vs 10-row reader node); fix = per-position-slice stage-3 validation. Engagement band recalibrates to ~0.54 (live miss 54%, not h=0.58). Global-42 static pins DEAD (6.4%/5% recall, ~0% transfer); per-layer-42 (61%) needs 4.3GiB, does not fit 3060 (425MiB free at decode). Fresh footprints retire 9293 ledger: load 10639/1273, decode ~11487/425.", "rationale": "T2cVetoTrace yield: 13546 pairs, token-sig OFF==ON 738173b6, rig idle, nothing committed. f_link recurrence test 0.2136 (~2x chance) weakens §3 rationale but does not kill it.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-236b2c84e7', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:42:01.452Z', 'BLOCKER: cache-0 control OOMs on current tree+binary (47263 MiB CUDA0 alloc, measured twice); arm-000 21.23 floor does not load on current tree. Suspect S1/S2-era loader change in co-worker dirt (read-only). T-2d legs use cache>=32 (loads via host-pinned buffer); control re-entry gated on loader diagnosis, co-worker dirt untouched.', 'T2cVetoTrace control_note. Mechanism is [INFERENCE]; failure is measured. T-2b 09:49 control ran on older binary.', 'leader', 0, '', '{"id": "d-236b2c84e7", "ts": "2026-09-16T04:42:01.452Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "BLOCKER: cache-0 control OOMs on current tree+binary (47263 MiB CUDA0 alloc, measured twice); arm-000 21.23 floor does not load on current tree. Suspect S1/S2-era loader change in co-worker dirt (read-only). T-2d legs use cache>=32 (loads via host-pinned buffer); control re-entry gated on loader diagnosis, co-worker dirt untouched.", "rationale": "T2cVetoTrace control_note. Mechanism is [INFERENCE]; failure is measured. T-2b 09:49 control ran on older binary.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-043a21b1d1', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:48:40.263Z', 'Architect consult channel is 2731baf3 (owner-delegated from track start). 49f717e1 interim verdict stands as input, not authority; gaps consult re-sent to 2731baf3 for confirm/override.', 'Owner correction 2026-09-16: leader misrouted to 49f717e1 based on agent title. Schedule text naming 2731baf3 was correct.', 'owner-directive', 0, '', '{"id": "d-043a21b1d1", "ts": "2026-09-16T04:48:40.263Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect consult channel is 2731baf3 (owner-delegated from track start). 49f717e1 interim verdict stands as input, not authority; gaps consult re-sent to 2731baf3 for confirm/override.", "rationale": "Owner correction 2026-09-16: leader misrouted to 49f717e1 based on agent title. Schedule text naming 2731baf3 was correct.", "source": "owner-directive", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b4ea338955', 'p-7719544617', 't-d1cf43b723', '2026-09-16T04:52:08.444Z', 'Architect adjudication 2731baf3: CONFIRM veto-fix-first, OVERRIDE gate to self-consistent form (cpu_fraction>0.10 + agree own miss ledger ±0.05; relative continue ≥+30% vs same-binary control) + control-OOM diagnose-don''t-rebaseline (bisect 0fc51e039 clean base) + static global pins dead permanently, per-layer-42 needs heldout + VRAM-additionality answers. T-4 definitively dead (425MiB free). f_link=0.165 stands; 0.2136 is recurrence input to §8.', 'Unpriced facts: miss-rate 3x conflict (54% T-2c vs ~18% bank ledger) makes absolute gates spurious-STOP risks; 6.5% machinery tax standing line item; 47GB alloc is corrupted-size bug not capacity. Model good to 4% (t_cpu 0.0677 vs 0.0704); projections 30.2 t/s (54%) or ~51 (18%) — continue robust either way.', 'consult', 0, '', '{"id": "d-b4ea338955", "ts": "2026-09-16T04:52:08.444Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect adjudication 2731baf3: CONFIRM veto-fix-first, OVERRIDE gate to self-consistent form (cpu_fraction>0.10 + agree own miss ledger ±0.05; relative continue ≥+30% vs same-binary control) + control-OOM diagnose-don''t-rebaseline (bisect 0fc51e039 clean base) + static global pins dead permanently, per-layer-42 needs heldout + VRAM-additionality answers. T-4 definitively dead (425MiB free). f_link=0.165 stands; 0.2136 is recurrence input to §8.", "rationale": "Unpriced facts: miss-rate 3x conflict (54% T-2c vs ~18% bank ledger) makes absolute gates spurious-STOP risks; 6.5% machinery tax standing line item; 47GB alloc is corrupted-size bug not capacity. Model good to 4% (t_cpu 0.0677 vs 0.0704); projections 30.2 t/s (54%) or ~51 (18%) — continue robust either way.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-c9d1663074', 'p-7719544617', 't-d1cf43b723', '2026-09-16T05:09:58.938Z', 'T-2d done-unengaged: naive position-major slice fix FALSIFIED (98.6% of 3408 combine dispatches have no slice within 5e-2; resolved_combine=2, cpu_fraction 0.0069). Veto cause confirmed constructional (P-position plan vs K-row reader). Second wall: demand precedes residency in ALL 180 sampled rows — cache never ahead, f_link overlap 18.5%. Proposal: per-reader applicability check via plan''s own per-reader index (§7 contradicts §5).', 'T2cVetoTrace yield: OFF parity 738173b6, rig idle, nothing committed, oracle cost fully env-gated (8.67 vs 10.95). Self-consistent gate fails as predicted (0.0069 vs ~0.18) — reporting is honest, engagement is real-zero.', 'leader', 0, '', '{"id": "d-c9d1663074", "ts": "2026-09-16T05:09:58.938Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T-2d done-unengaged: naive position-major slice fix FALSIFIED (98.6% of 3408 combine dispatches have no slice within 5e-2; resolved_combine=2, cpu_fraction 0.0069). Veto cause confirmed constructional (P-position plan vs K-row reader). Second wall: demand precedes residency in ALL 180 sampled rows — cache never ahead, f_link overlap 18.5%. Proposal: per-reader applicability check via plan''s own per-reader index (§7 contradicts §5).", "rationale": "T2cVetoTrace yield: OFF parity 738173b6, rig idle, nothing committed, oracle cost fully env-gated (8.67 vs 10.95). Self-consistent gate fails as predicted (0.0069 vs ~0.18) — reporting is honest, engagement is real-zero.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e492d76091', 'p-7719544617', 't-d1cf43b723', '2026-09-16T05:11:42.694Z', 'Delta ruling accepted: audit+mapping+admission ONE workstream (T-2g), prefetch-first rejected (§2 already killed it; miss-non-resident IS tier-3''s job), f_link=0.165 stands with T2 selection arbitrary (18.5% kills compounding), parallel queue (bisect > audit > heldout), BUDGET one informed attempt then stop hybrid and close at 21.23.', '2731baf3 delta: audit is first half of mapping fix (3 candidates unresolved — no implementation against guesses); real second wall may be unconditional admission (§7.15) making cpu_fraction structurally ~0 — check lookup-vs-admission order, nearly free. 18.5% == Phase-0 transfer figure needs one glance. Owner frame bounded: engineer through ≠ engineer indefinitely.', 'consult', 0, '', '{"id": "d-e492d76091", "ts": "2026-09-16T05:11:42.694Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Delta ruling accepted: audit+mapping+admission ONE workstream (T-2g), prefetch-first rejected (§2 already killed it; miss-non-resident IS tier-3''s job), f_link=0.165 stands with T2 selection arbitrary (18.5% kills compounding), parallel queue (bisect > audit > heldout), BUDGET one informed attempt then stop hybrid and close at 21.23.", "rationale": "2731baf3 delta: audit is first half of mapping fix (3 candidates unresolved — no implementation against guesses); real second wall may be unconditional admission (§7.15) making cpu_fraction structurally ~0 — check lookup-vs-admission order, nearly free. 18.5% == Phase-0 transfer figure needs one glance. Owner frame bounded: engineer through ≠ engineer indefinitely.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e2f0702602', 'p-7719544617', 't-d1cf43b723', '2026-09-16T05:48:25.104Z', 'T-2g done, budget TRIGGERED: vetoes 0 (down_n1 eliminated) but engagement 0.0048 — mapping not reconstructible at finish time (no per-reader index survives; reader-ids garbage 98.6%; rows noncontiguous), admission lookup-after-unconditional makes any post-hoc splice duplication-only (kernel change beyond one attempt). A1 settled (18% excluded as import; same-leg 48.9%/54%). OOM base-owned (pre-existing at 0fc51e039, not dirt). Per-layer-42 heldout DEAD (0.406/0.421). Awaiting architect STOP-confirm.', 'T2cVetoTrace yield: OFF parity 738173b6, rig idle, nothing committed. Stand-in floor t2g-cpu32 10.374 same-binary. Worker verdict STOP per budget; closure needs architect confirm + owner call.', 'leader', 0, '', '{"id": "d-e2f0702602", "ts": "2026-09-16T05:48:25.104Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "T-2g done, budget TRIGGERED: vetoes 0 (down_n1 eliminated) but engagement 0.0048 — mapping not reconstructible at finish time (no per-reader index survives; reader-ids garbage 98.6%; rows noncontiguous), admission lookup-after-unconditional makes any post-hoc splice duplication-only (kernel change beyond one attempt). A1 settled (18% excluded as import; same-leg 48.9%/54%). OOM base-owned (pre-existing at 0fc51e039, not dirt). Per-layer-42 heldout DEAD (0.406/0.421). Awaiting architect STOP-confirm.", "rationale": "T2cVetoTrace yield: OFF parity 738173b6, rig idle, nothing committed. Stand-in floor t2g-cpu32 10.374 same-binary. Worker verdict STOP per budget; closure needs architect confirm + owner call.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-4d78811bc0', 'p-7719544617', 't-d1cf43b723', '2026-09-16T05:50:24.871Z', 'STOP confirmed by architect: hybrid terminated, closure put to owner. §5.2/§9 landed c0f0e2269 (proposed, pending owner). 21.23 recorded as measured-not-current (base-owned OOM, 64K never measured, depth-costed ~13 t/s at 64K under floor). Follow-ups: (i) base OOM as own issue, (ii) arm-000 at 64K. PR #131 unmerged.', '2731baf3 budget confirmation: two structural blockers (mapping nonexistent at finish time; lookup-after-admission) = epic not experiment. Durable finding: x4 link cache strictly worse than CPU-MoE (0.342 vs 0.0677ms, 5x); x16 slot would invert (f_link ~0.45) — purchasing not engineering decision.', 'consult', 0, '', '{"id": "d-4d78811bc0", "ts": "2026-09-16T05:50:24.871Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "STOP confirmed by architect: hybrid terminated, closure put to owner. §5.2/§9 landed c0f0e2269 (proposed, pending owner). 21.23 recorded as measured-not-current (base-owned OOM, 64K never measured, depth-costed ~13 t/s at 64K under floor). Follow-ups: (i) base OOM as own issue, (ii) arm-000 at 64K. PR #131 unmerged.", "rationale": "2731baf3 budget confirmation: two structural blockers (mapping nonexistent at finish time; lookup-after-admission) = epic not experiment. Durable finding: x4 link cache strictly worse than CPU-MoE (0.342 vs 0.0677ms, 5x); x16 slot would invert (f_link ~0.45) — purchasing not engineering decision.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-255055e394', 'p-7719544617', 't-d1cf43b723', '2026-09-16T05:53:48.243Z', 'PCIe x4 on the 3060 accepted as fixed constraint (no hardware change). Tiering premise permanently unviable on this rig: link 5x worse than DDR is structural, not budgetary. Close-out stands on x4 findings.', 'Owner directive 2026-09-16: x16 purchasing option rejected. f_link ~0.165 regime is the hardware truth; tier 2 cannot compete on this box regardless of implementation.', 'owner-directive', 0, '', '{"id": "d-255055e394", "ts": "2026-09-16T05:53:48.243Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "PCIe x4 on the 3060 accepted as fixed constraint (no hardware change). Tiering premise permanently unviable on this rig: link 5x worse than DDR is structural, not budgetary. Close-out stands on x4 findings.", "rationale": "Owner directive 2026-09-16: x16 purchasing option rejected. f_link ~0.165 regime is the hardware truth; tier 2 cannot compete on this box regardless of implementation.", "source": "owner-directive", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-c121d19f46', 'p-7719544617', 't-d1cf43b723', '2026-09-16T06:06:00.959Z', 'New workstream #132 tiered static hot/cold slab SUPERSEDES hybrid (stopped, not closed): keep VRAM head, drop cache machinery. §9 closure now historical record. Steps 1-2 = result, 3 refines, 4 optional. Leader pushback to worker: permute ALL per-expert-dim tensors (scales/biases, not just 3 weights); #128 verify-not-assume; OOM-at-load is stop-and-report.', 'Owner redesign-over-close + architect handoff. Loader check confirms expert index is outer dim (ne[2]) — slice + row-permutation correspondence is sound provided every per-expert tensor follows the same permutation.', 'leader', 0, '', '{"id": "d-c121d19f46", "ts": "2026-09-16T06:06:00.959Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "New workstream #132 tiered static hot/cold slab SUPERSEDES hybrid (stopped, not closed): keep VRAM head, drop cache machinery. §9 closure now historical record. Steps 1-2 = result, 3 refines, 4 optional. Leader pushback to worker: permute ALL per-expert-dim tensors (scales/biases, not just 3 weights); #128 verify-not-assume; OOM-at-load is stop-and-report.", "rationale": "Owner redesign-over-close + architect handoff. Loader check confirms expert index is outer dim (ne[2]) — slice + row-permutation correspondence is sound provided every per-expert tensor follows the same permutation.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-7af5e3dc95', 'p-7719544617', 't-d1cf43b723', '2026-09-16T07:07:54.469Z', 'S132-1 returns step1-incomplete-with-load-bearing-finding. (a) Read-only ggml_backend_tensor_get on 48 GPU gate_inp tensors shifts PPL 29.4183->27.8359 deterministically with zero writes — perturbation below memcpy abstraction, mechanism unidentified. (b) Sweep-plus-assertion holds with zero aborts; only 4 expert-dim tensors/layer exist on this quant path (_s/exp_probs_b/gate_up absent, TENSOR_NOT_REQUIRED). (c) PPL-identity unachievable in fp (softmax-reduction-order route flips); greedy-token identity confirmed as the correct gate. (d) Greedy gate NOT demonstrated (TSV text column empty) — 648/648 still open. (e) Endorsed pivot: loader-side pre-upload permutation (host proven neutral), keeps sweep assertion. Standing item (i) OOM not hit on --cpu-moe lineage (expected, not new info).', 'Worker evidence: getonly==identity==twice==gate-only-twice at 27.8359 vs control 29.4183 bit-identical runs; code-audited flat memcpy; twice-verify byte-identical. Host-path neutrality proven by gate-only==full. Architect consult sent in parallel; follow-up proceeds without blocking.', 'leader', 0, '', '{"id": "d-7af5e3dc95", "ts": "2026-09-16T07:07:54.469Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "S132-1 returns step1-incomplete-with-load-bearing-finding. (a) Read-only ggml_backend_tensor_get on 48 GPU gate_inp tensors shifts PPL 29.4183->27.8359 deterministically with zero writes — perturbation below memcpy abstraction, mechanism unidentified. (b) Sweep-plus-assertion holds with zero aborts; only 4 expert-dim tensors/layer exist on this quant path (_s/exp_probs_b/gate_up absent, TENSOR_NOT_REQUIRED). (c) PPL-identity unachievable in fp (softmax-reduction-order route flips); greedy-token identity confirmed as the correct gate. (d) Greedy gate NOT demonstrated (TSV text column empty) — 648/648 still open. (e) Endorsed pivot: loader-side pre-upload permutation (host proven neutral), keeps sweep assertion. Standing item (i) OOM not hit on --cpu-moe lineage (expected, not new info).", "rationale": "Worker evidence: getonly==identity==twice==gate-only-twice at 27.8359 vs control 29.4183 bit-identical runs; code-audited flat memcpy; twice-verify byte-identical. Host-path neutrality proven by gate-only==full. Architect consult sent in parallel; follow-up proceeds without blocking.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ed65f51526', 'p-7719544617', 't-d1cf43b723', '2026-09-16T07:35:39.623Z', 'AMENDS d-7af5e3dc95: WITHDRAWN the read-perturbation finding — chunk-count confound (1-chunk runs vs 8-chunk baseline), not a transfer effect; post-load path likely neutral all along (twice==unset now expected). Record instead: (a) S132-1b loader-side reverse DONE, sweep 192/192+4/4 zero aborts, --load-mode none REQUIRED (mmap-alias read-only segfault, now clear throw); (b) harness text bug fixed (reasoning_content, 805 chars); (c) greedy gate FAILS: reverse diverges at char 30 (78/805), control==control 805/805. Cause UNDECIDED between fp-cascade and missed-tensor — ORDERED margin test: top-1/top-2 logit gap at first-divergence position decides (tiny gap = fp noise, large gap = real misroute). No gate redefinition until margins measured.', 'Worker self-correction with receipts (unset-1ch == all S1 1-chunk runs at 27.8359). Correction strengthens the record; the margin test is the single discriminating experiment between the two live hypotheses.', 'leader', 0, '', '{"id": "d-ed65f51526", "ts": "2026-09-16T07:35:39.623Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "AMENDS d-7af5e3dc95: WITHDRAWN the read-perturbation finding — chunk-count confound (1-chunk runs vs 8-chunk baseline), not a transfer effect; post-load path likely neutral all along (twice==unset now expected). Record instead: (a) S132-1b loader-side reverse DONE, sweep 192/192+4/4 zero aborts, --load-mode none REQUIRED (mmap-alias read-only segfault, now clear throw); (b) harness text bug fixed (reasoning_content, 805 chars); (c) greedy gate FAILS: reverse diverges at char 30 (78/805), control==control 805/805. Cause UNDECIDED between fp-cascade and missed-tensor — ORDERED margin test: top-1/top-2 logit gap at first-divergence position decides (tiny gap = fp noise, large gap = real misroute). No gate redefinition until margins measured.", "rationale": "Worker self-correction with receipts (unset-1ch == all S1 1-chunk runs at 27.8359). Correction strengthens the record; the margin test is the single discriminating experiment between the two live hypotheses.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f780893d86', 'p-7719544617', 't-d1cf43b723', '2026-09-16T10:00:59.230Z', 'Margin-test interim: 33/255 top-1 flips (12.9%), min gap at flips 0.014 log units — 4 orders above 1e-6 fp-noise floor, median 0.906, cross-model max|d| 4.03. Verdict rule sharpened: a consistent permutation cannot flip ANY margin, so flips at 0.014 favor H2 (misroute) or a third mechanism (draft interplay — acceptance already differed 126/145 vs 123/151; dequant nondeterminism). Await worker''s gguf-py dequant byte-equality check; if bytes exactly relabeled, ordered next isolation is draft-OFF control-vs-reverse (removes MTP interplay, target-only comparison). Char-30 router-logit gap still open.', '0.014 >> fp-noise floor rules out H1-pure-fp; but draft acceptance already diverged, so target misroute is not yet isolated from draft interplay. Dequant check + draft-OFF leg discriminate cleanly.', 'leader', 0, '', '{"id": "d-f780893d86", "ts": "2026-09-16T10:00:59.230Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Margin-test interim: 33/255 top-1 flips (12.9%), min gap at flips 0.014 log units — 4 orders above 1e-6 fp-noise floor, median 0.906, cross-model max|d| 4.03. Verdict rule sharpened: a consistent permutation cannot flip ANY margin, so flips at 0.014 favor H2 (misroute) or a third mechanism (draft interplay — acceptance already differed 126/145 vs 123/151; dequant nondeterminism). Await worker''s gguf-py dequant byte-equality check; if bytes exactly relabeled, ordered next isolation is draft-OFF control-vs-reverse (removes MTP interplay, target-only comparison). Char-30 router-logit gap still open.", "rationale": "0.014 >> fp-noise floor rules out H1-pure-fp; but draft acceptance already diverged, so target misroute is not yet isolated from draft interplay. Dequant check + draft-OFF leg discriminate cleanly.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-abbb02d124', 'p-7719544617', 't-d1cf43b723', '2026-09-16T11:40:50.012Z', 'S132-1b gate verdict: H2 CONFIRMED. Dequant byte-check EXACT (all 4 blk.0 expert tensors, maxdiff 0.0) — permutation is data-preserving, so the bug is not in the bytes. Draft-OFF control-vs-reverse (822 vs 821 chars, first diff char 99) — flips PERSIST without draft, exonerating MTP interplay per the pre-registered rule in d-f780893d86. Conclusion: loader-side expert permutation changes target behavior through an unpermuted companion structure (router-side indexing, expert bias/scales, or device/assignment maps). Next: bisect companion structures — enumerate every expert-indexed array besides gate_inp/down/gate/up, permute candidates one at a time, re-run draft-OFF greedy until identity restores.', 'Exact bytes + persistent draft-OFF divergence isolates the fault to an order-dependent execution structure outside the permuted tensors. Draft acceptance split (126/145 vs 123/151) is downstream of the target divergence, not its cause.', 'leader', 0, '', '{"id": "d-abbb02d124", "ts": "2026-09-16T11:40:50.012Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "S132-1b gate verdict: H2 CONFIRMED. Dequant byte-check EXACT (all 4 blk.0 expert tensors, maxdiff 0.0) — permutation is data-preserving, so the bug is not in the bytes. Draft-OFF control-vs-reverse (822 vs 821 chars, first diff char 99) — flips PERSIST without draft, exonerating MTP interplay per the pre-registered rule in d-f780893d86. Conclusion: loader-side expert permutation changes target behavior through an unpermuted companion structure (router-side indexing, expert bias/scales, or device/assignment maps). Next: bisect companion structures — enumerate every expert-indexed array besides gate_inp/down/gate/up, permute candidates one at a time, re-run draft-OFF greedy until identity restores.", "rationale": "Exact bytes + persistent draft-OFF divergence isolates the fault to an order-dependent execution structure outside the permuted tensors. Draft acceptance split (126/145 vs 123/151) is downstream of the target divergence, not its cause.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-477fa232a5', 'p-7719544617', 't-d1cf43b723', '2026-09-16T11:56:10.394Z', 'S132-1b bisect verdict: BRANCH-3 (slot/execution-order coupling, not data). Enumeration (1224 tensors) finds no other expert-indexed arrays — only the 4 permuted families plus attention order-free 512-dims; no moe_stat/expert_map/side tables; backend native mm_id all dtypes, no repack; pristine-binary PPL==control (lineage clean). Single-family reversals all VISIBLE (PPL 424-798 vs 27.8359 control): every family reads live, no shadow copy; loader vs post-load reverse bit-identical. No data companion can restore identity. APPROVED next: rotation-permutation test (consistent non-involution relabel, temp tree edit + rebuild + 1 draft-OFF leg) with pre-registered rule — rotation exact (~27.8359) = reversal-specific bug (flip logic somewhere); rotation divergent = general slot-dependence (dispatch/device/cache slots), and #132 step-1 must then preserve slot assignment, not just data order.', 'Single-family reversal visibility is a double dissociation proving all families live; combined with complete tensor enumeration and clean lineage, data-side explanations are exhausted. Rotation discriminates reversal-specific from general slot-dependence with one leg.', 'leader', 0, '', '{"id": "d-477fa232a5", "ts": "2026-09-16T11:56:10.394Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "S132-1b bisect verdict: BRANCH-3 (slot/execution-order coupling, not data). Enumeration (1224 tensors) finds no other expert-indexed arrays — only the 4 permuted families plus attention order-free 512-dims; no moe_stat/expert_map/side tables; backend native mm_id all dtypes, no repack; pristine-binary PPL==control (lineage clean). Single-family reversals all VISIBLE (PPL 424-798 vs 27.8359 control): every family reads live, no shadow copy; loader vs post-load reverse bit-identical. No data companion can restore identity. APPROVED next: rotation-permutation test (consistent non-involution relabel, temp tree edit + rebuild + 1 draft-OFF leg) with pre-registered rule — rotation exact (~27.8359) = reversal-specific bug (flip logic somewhere); rotation divergent = general slot-dependence (dispatch/device/cache slots), and #132 step-1 must then preserve slot assignment, not just data order.", "rationale": "Single-family reversal visibility is a double dissociation proving all families live; combined with complete tensor enumeration and clean lineage, data-side explanations are exhausted. Rotation discriminates reversal-specific from general slot-dependence with one leg.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-94a36423ca', 'p-7719544617', 't-d1cf43b723', '2026-09-16T12:02:43.316Z', 'Rotation DIVERGENT: slot-dependence is general (rotate PPL 28.8585 vs control 27.8359 vs reversal 29.0470 — three distinct signatures; 51/255 flips, first-diff-65). Any consistent relabel changes the function. #132 step-1-as-designed FAILS its greedy-identity gate definitively. Prime suspect before any redesign: device-placement x kernel numerics — if legs run split GPU/CPU, permutation remaps which expert runs on which device''s GEMM kernel, and CPU/GPU rounding differs exactly at small margins (flips sit at 0.00269-0.014, never at large margins — the signature of rounding, not routing). Ordered discriminator: ONE all-GPU (fully offloaded, no CPU split) draft-OFF control-vs-reverse leg. Identity restores = convict device kernels (then #132 redesign keeps slot->device mapping fixed, data order free). Still divergent = true slot reader in code (then hunt index arithmetic in dispatch). Tree verified reverted (diff 366), binaries baseline, rig idle.', 'Margin-concentration of flips (small gaps only) plus three-distinct-signatures is the fingerprint of kernel rounding differences across devices, not of routing changes. The all-GPU leg splits these with zero tree edits.', 'leader', 0, '', '{"id": "d-94a36423ca", "ts": "2026-09-16T12:02:43.316Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Rotation DIVERGENT: slot-dependence is general (rotate PPL 28.8585 vs control 27.8359 vs reversal 29.0470 — three distinct signatures; 51/255 flips, first-diff-65). Any consistent relabel changes the function. #132 step-1-as-designed FAILS its greedy-identity gate definitively. Prime suspect before any redesign: device-placement x kernel numerics — if legs run split GPU/CPU, permutation remaps which expert runs on which device''s GEMM kernel, and CPU/GPU rounding differs exactly at small margins (flips sit at 0.00269-0.014, never at large margins — the signature of rounding, not routing). Ordered discriminator: ONE all-GPU (fully offloaded, no CPU split) draft-OFF control-vs-reverse leg. Identity restores = convict device kernels (then #132 redesign keeps slot->device mapping fixed, data order free). Still divergent = true slot reader in code (then hunt index arithmetic in dispatch). Tree verified reverted (diff 366), binaries baseline, rig idle.", "rationale": "Margin-concentration of flips (small gaps only) plus three-distinct-signatures is the fingerprint of kernel rounding differences across devices, not of routing changes. The all-GPU leg splits these with zero tree edits.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6b11889d00', 'p-7719544617', 't-d1cf43b723', '2026-09-16T12:06:39.630Z', 'Discriminator untestable, device-kernel hypothesis DEAD by placement data: all 144 expert weights uniformly on CUDA_Host (CPU), router on GPU — permutation cannot remap experts across device kernels, so cross-device rounding is out. All-GPU pair OOMs at load (47263 MiB, standing-OOM class, 0.8s clean abort). Confirmed path is brief-B: code hunt for expert-index arithmetic in CPU dispatch (arg.cpp:2841 plumbing, llama-model.cpp:477-518 split config, mm_id gather + per-expert staging in 0fc51e039/moe-cache.cu, read-only). Constraints: reversal 29.0470/33 flips, rotation 28.8585/51 flips, single-family 425-798, flips at small margins only. Note: uniform-device placement also bounds the mechanism — same-kernel same-op math must be order-exact, so the reader is index-dependent logic (tie-breaks, staging offsets, slot-keyed tables), not numerics.', 'Placement uniformity eliminates the only rounding-based suspect; remaining mechanisms must read the index itself. The margin pattern (small gaps flip, large never) fits an index-dependent selection difference, not noise.', 'leader', 0, '', '{"id": "d-6b11889d00", "ts": "2026-09-16T12:06:39.630Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Discriminator untestable, device-kernel hypothesis DEAD by placement data: all 144 expert weights uniformly on CUDA_Host (CPU), router on GPU — permutation cannot remap experts across device kernels, so cross-device rounding is out. All-GPU pair OOMs at load (47263 MiB, standing-OOM class, 0.8s clean abort). Confirmed path is brief-B: code hunt for expert-index arithmetic in CPU dispatch (arg.cpp:2841 plumbing, llama-model.cpp:477-518 split config, mm_id gather + per-expert staging in 0fc51e039/moe-cache.cu, read-only). Constraints: reversal 29.0470/33 flips, rotation 28.8585/51 flips, single-family 425-798, flips at small margins only. Note: uniform-device placement also bounds the mechanism — same-kernel same-op math must be order-exact, so the reader is index-dependent logic (tie-breaks, staging offsets, slot-keyed tables), not numerics.", "rationale": "Placement uniformity eliminates the only rounding-based suspect; remaining mechanisms must read the index itself. The margin pattern (small gaps flip, large never) fits an index-dependent selection difference, not noise.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b4fcc0c7dd', 'p-7719544617', 't-d1cf43b723', '2026-09-16T12:16:29.123Z', 'Brief-B read-only hunt: NO CONVICT (all sharpened classes symmetric — tie-breaks need bit-ties ruled out by margins, mmid DIRECT, reduction slot-sums identical, CPU mm_id direct indexing, moe-cache dirt inert, grouped machinery inactive). Two gaps before any tracing build: (a) byte-exactness was verified at blk.0 ONLY — a block-index bug in the permutation path (unpermuted/mis-permuted later blocks) is still open; (b) the layer-0 router induction (''must exact-reverse'') was never measured — a control-vs-reverse router top-k/weights comparison at layer 0 bisects the search space (router already differs = gather/top-k path; exact at layer 0 but divergent later = expert compute/staging). APPROVED bounded remainder in order: (1) full-model all-blocks dequant byte-check OFFLINE first (inequality = permutation-path bug, stop, name file:line); (2) layer-0 router-output bisection; (3) getrows.cu verify + fused-topk engagement proof; (4) empirical kernel-identity leg only if (1)-(3) clean. Tracing build/env approved bounded to (2)-(4). Stop rule: report after each step; do not batch.', 'Cheapest falsifiers first: blk.0-only sampling leaves the highest-probability data bug (block-index handling) untested, and the unmeasured layer-0 induction is load-bearing for the whole branch-3 conclusion. Both are cheaper than a tracing build.', 'leader', 0, '', '{"id": "d-b4fcc0c7dd", "ts": "2026-09-16T12:16:29.123Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Brief-B read-only hunt: NO CONVICT (all sharpened classes symmetric — tie-breaks need bit-ties ruled out by margins, mmid DIRECT, reduction slot-sums identical, CPU mm_id direct indexing, moe-cache dirt inert, grouped machinery inactive). Two gaps before any tracing build: (a) byte-exactness was verified at blk.0 ONLY — a block-index bug in the permutation path (unpermuted/mis-permuted later blocks) is still open; (b) the layer-0 router induction (''must exact-reverse'') was never measured — a control-vs-reverse router top-k/weights comparison at layer 0 bisects the search space (router already differs = gather/top-k path; exact at layer 0 but divergent later = expert compute/staging). APPROVED bounded remainder in order: (1) full-model all-blocks dequant byte-check OFFLINE first (inequality = permutation-path bug, stop, name file:line); (2) layer-0 router-output bisection; (3) getrows.cu verify + fused-topk engagement proof; (4) empirical kernel-identity leg only if (1)-(3) clean. Tracing build/env approved bounded to (2)-(4). Stop rule: report after each step; do not batch.", "rationale": "Cheapest falsifiers first: blk.0-only sampling leaves the highest-probability data bug (block-index handling) untested, and the unmeasured layer-0 induction is load-bearing for the whole branch-3 conclusion. Both are cheaper than a tracing build.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-72b6130e02', 'p-7719544617', 't-d1cf43b723', '2026-09-16T12:43:03.566Z', 'Architect consult (ArchConsult1) verdict: CONTINUE-REMAINDER. The 4-step bounded remainder stands; no close. Remainder already ordered under d-b4fcc0c7dd — no new orders needed.', 'Consult returned verdict-only (no reason/risk lines delivered); verdict matches the cheapest-falsifier-first ordering already in motion.', 'leader', 0, '', '{"id": "d-72b6130e02", "ts": "2026-09-16T12:43:03.566Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect consult (ArchConsult1) verdict: CONTINUE-REMAINDER. The 4-step bounded remainder stands; no close. Remainder already ordered under d-b4fcc0c7dd — no new orders needed.", "rationale": "Consult returned verdict-only (no reason/risk lines delivered); verdict matches the cheapest-falsifier-first ordering already in motion.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-92d52028fe', 'p-7719544617', 't-d1cf43b723', '2026-09-16T12:50:37.673Z', 'ArchConsult2 verdict CONTINUE-REMAINDER: 4-6h testing converted speculation into bounded facts (H2, branch-3, rotation-divergent, device-kernel dead, empty hunt); the two remaining gaps (blk.0-only sample, unmeasured layer-0) are narrow and cheap, remainder already in flight. Biggest risk: remainder merely re-proves step-1 dead without surfacing salvageable direction.', 'Failed gates argue against expansion, not against finishing cheap falsifiers before any close decision.', 'leader', 0, '', '{"id": "d-92d52028fe", "ts": "2026-09-16T12:50:37.673Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "ArchConsult2 verdict CONTINUE-REMAINDER: 4-6h testing converted speculation into bounded facts (H2, branch-3, rotation-divergent, device-kernel dead, empty hunt); the two remaining gaps (blk.0-only sample, unmeasured layer-0) are narrow and cheap, remainder already in flight. Biggest risk: remainder merely re-proves step-1 dead without surfacing salvageable direction.", "rationale": "Failed gates argue against expansion, not against finishing cheap falsifiers before any close decision.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b9793586e0', 'p-7719544617', 't-d1cf43b723', '2026-09-16T12:54:40.401Z', 'Architect 2731baf3 verdict CLOSE-NOW the diagnostic remainder (keep leg 1 offline only; drop legs 2-4): relabeling is not a symmetry (three perms, three PPLs, pre-registered rule fires stop rule by its own terms); flips concentrate at near-ties (index-order-dependent top-k, no permute fix reaches it); relabeling was never load-bearing — replace with static 512-entry residency/offset table per layer, routing bit-identical. Corrections: h>80% is old staged-cache break-even, #132 profits at any h>0 (miss=CPU 0.0677ms vs PCIe 0.342ms). Risk: fault may be loader-side rewrite path (split path untested) — gate redesign on degenerate splits N_hot=512 and N_hot=0 bit-identical to control.', 'Remainder cannot change what we build — under either why-answer the next design is identical; second prior risk note now realized.', 'leader', 0, '', '{"id": "d-b9793586e0", "ts": "2026-09-16T12:54:40.401Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect 2731baf3 verdict CLOSE-NOW the diagnostic remainder (keep leg 1 offline only; drop legs 2-4): relabeling is not a symmetry (three perms, three PPLs, pre-registered rule fires stop rule by its own terms); flips concentrate at near-ties (index-order-dependent top-k, no permute fix reaches it); relabeling was never load-bearing — replace with static 512-entry residency/offset table per layer, routing bit-identical. Corrections: h>80% is old staged-cache break-even, #132 profits at any h>0 (miss=CPU 0.0677ms vs PCIe 0.342ms). Risk: fault may be loader-side rewrite path (split path untested) — gate redesign on degenerate splits N_hot=512 and N_hot=0 bit-identical to control.", "rationale": "Remainder cannot change what we build — under either why-answer the next design is identical; second prior risk note now realized.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-3e4b0af635', 'p-7719544617', 't-d1cf43b723', '2026-09-16T13:07:16.338Z', 'Architect gate correction (binding): N_hot=0 bit-identical vs arm000; N_hot=all bit-identical vs ALL-GPU control (not arm000) — CPU/CUDA move changes FP accumulation order (docs/cuda.md:110-118, near-tie divergence with byte-exact weights); mixed split is not bit-identical by construction (PPL within noise + greedy agreement). Colibri confirms indirection-never-renumbering, miss path, link-width independence; step-3 patterns noted; do not import their numbers; dense-trunk lever deferred.', 'As originally written a correct implementation would have failed the gate; degenerate legs still prove machinery (single-device each).', 'leader', 0, '', '{"id": "d-3e4b0af635", "ts": "2026-09-16T13:07:16.338Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect gate correction (binding): N_hot=0 bit-identical vs arm000; N_hot=all bit-identical vs ALL-GPU control (not arm000) — CPU/CUDA move changes FP accumulation order (docs/cuda.md:110-118, near-tie divergence with byte-exact weights); mixed split is not bit-identical by construction (PPL within noise + greedy agreement). Colibri confirms indirection-never-renumbering, miss path, link-width independence; step-3 patterns noted; do not import their numbers; dense-trunk lever deferred.", "rationale": "As originally written a correct implementation would have failed the gate; degenerate legs still prove machinery (single-device each).", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-5046073744', 'p-7719544617', 't-d1cf43b723', '2026-09-16T14:17:44.007Z', 'OWNER-APPROVED track change: hybrid/MoE-cache line CLOSED, new track baseline-qwen4exp-mtp. No restart from upstream #28243 (draft-on-draft, and arm000''s decode-overlap/ple-prefetch have 0 upstream hits — clean start begins below our 21.23 floor). Sequence: Task1 C1 arm (blocking, gates rest) → Task2 branch baseline-qwen4exp-mtp at cdd11021b (not detached 12f294335) → Task3 strip MoE cache (3 files + 10-file API surface, keep decode-overlap/ple-prefetch pending Task1) → Task4 cherry-pick #28243 shared MTP modules only (+401/-73, measure VRAM delta vs 425MiB/N=42 constraint) → Task5 rebase for 47GB alloc bug. CI/CD only via gh workflow run, no bare git stash, no PR merges without owner confirm.', 'Fork delta 390 commits/+47.4k lines; cache is 30.6k (65%), other 16.8k lines are working parts (decode-overlap, ple-prefetch, MTP caps, Hydra endpoints, #469, RPC) — dropping branch breaks Hydra. Task1 isolates decode-overlap value before surgery.', 'owner-directive', 0, '', '{"id": "d-5046073744", "ts": "2026-09-16T14:17:44.007Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "OWNER-APPROVED track change: hybrid/MoE-cache line CLOSED, new track baseline-qwen4exp-mtp. No restart from upstream #28243 (draft-on-draft, and arm000''s decode-overlap/ple-prefetch have 0 upstream hits — clean start begins below our 21.23 floor). Sequence: Task1 C1 arm (blocking, gates rest) → Task2 branch baseline-qwen4exp-mtp at cdd11021b (not detached 12f294335) → Task3 strip MoE cache (3 files + 10-file API surface, keep decode-overlap/ple-prefetch pending Task1) → Task4 cherry-pick #28243 shared MTP modules only (+401/-73, measure VRAM delta vs 425MiB/N=42 constraint) → Task5 rebase for 47GB alloc bug. CI/CD only via gh workflow run, no bare git stash, no PR merges without owner confirm.", "rationale": "Fork delta 390 commits/+47.4k lines; cache is 30.6k (65%), other 16.8k lines are working parts (decode-overlap, ple-prefetch, MTP caps, Hydra endpoints, #469, RPC) — dropping branch breaks Hydra. Task1 isolates decode-overlap value before surgery.", "source": "owner-directive", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-305546753c', 'p-7719544617', 't-d1cf43b723', '2026-09-16T14:18:58.143Z', 'Architect C1 delta (binding, injected live into C1OverlapArm session): A/B extended to 2x2 with Arm C (--cpu-moe + --ple-prefetch) and Arm D (--cpu-moe + both = arm000 config), same binary/session. Rationale: C1 as designed had no ple-prefetch term (revisiting it would be inference not measurement) and no anchor to arm000; Arm D re-anchors harness (must land ~21.23) and supplies Task 3''s same-binary arm000 number. Still blocking: all four numbers before Task 2.', 'Two extra arms on built binary/configured harness; split-session rerun later would break same-binary comparability.', 'consult', 0, '', '{"id": "d-305546753c", "ts": "2026-09-16T14:18:58.143Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect C1 delta (binding, injected live into C1OverlapArm session): A/B extended to 2x2 with Arm C (--cpu-moe + --ple-prefetch) and Arm D (--cpu-moe + both = arm000 config), same binary/session. Rationale: C1 as designed had no ple-prefetch term (revisiting it would be inference not measurement) and no anchor to arm000; Arm D re-anchors harness (must land ~21.23) and supplies Task 3''s same-binary arm000 number. Still blocking: all four numbers before Task 2.", "rationale": "Two extra arms on built binary/configured harness; split-session rerun later would break same-binary comparability.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-4ae6f09842', 'p-7719544617', 't-d1cf43b723', '2026-09-16T14:29:03.220Z', 'C1 2x2 result (same binary md5 ca7a8adf, all 4 legs): A (overlap) FAIL 0 tok/s — ffn_moe_gate-0 MUL_MAT_ID backend error; B (plain) 16.34; C (ple) 16.75 (+2.5% decode, +14% prefill over B); D (both = arm000 config) FAIL same error. Anchor FAIL: best 16.75 vs 21.23 (-21%). Per architect delta this is STOP-and-report: harness problem, no surgery, Task 2+ held. decode-overlap is not ~nothing but NEGATIVE on this binary with --cpu-moe (hard-fail, ple does not rescue). Rig idle, worktree byte-intact.', 'Same-binary proof is solid; both overlap legs error identically while non-overlap legs run — the failure is in decode-overlap x cpu-moe dense, and the arm000 anchor does not transfer to this binary/config.', 'leader', 0, '', '{"id": "d-4ae6f09842", "ts": "2026-09-16T14:29:03.220Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "C1 2x2 result (same binary md5 ca7a8adf, all 4 legs): A (overlap) FAIL 0 tok/s — ffn_moe_gate-0 MUL_MAT_ID backend error; B (plain) 16.34; C (ple) 16.75 (+2.5% decode, +14% prefill over B); D (both = arm000 config) FAIL same error. Anchor FAIL: best 16.75 vs 21.23 (-21%). Per architect delta this is STOP-and-report: harness problem, no surgery, Task 2+ held. decode-overlap is not ~nothing but NEGATIVE on this binary with --cpu-moe (hard-fail, ple does not rescue). Rig idle, worktree byte-intact.", "rationale": "Same-binary proof is solid; both overlap legs error identically while non-overlap legs run — the failure is in decode-overlap x cpu-moe dense, and the arm000 anchor does not transfer to this binary/config.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f7dc4d53c4', 'p-7719544617', 't-d1cf43b723', '2026-09-16T14:49:52.725Z', 'Architect ranked direction (full verdict banked): anchor FAIL likely FALSE POSITIVE (authored spec contradiction: ''no MTP'' + ''= arm000 config''; B->arm000 ratio 1.30 = exactly MTP lift at acc 0.88). Ranked: (d) FIRST one re-anchor arm (C-leg + MTP, binary ca7a8adf) — decisive, prices overlap by subtraction; (b) SECOND strip now vs same-binary pre/post pair (C-leg 16.75 is reference, arm000 is target — never gate strip on arm000); (c) drop overlap CONDITIONAL on re-anchor ~=0; (a) rebase demoted unless re-anchor fails. Drop: overlap (conditional), #124 legacy-fallback path (guards deleted subsystem). Keep: ple (+2.5%/+14% sole clean fork perf receipt), MTP caps, Hydra endpoints, #469, RPC. Surgery checks: test-backend-ops.cpp/test-alloc.cpp may break; pre/post pair must include Arm C exactly (overlap fail at ffn_moe_gate-0 shares cache dispatch neighbourhood — strip could move cpu-moe behaviour).', 'Missing 21% is a missing feature (MTP), not missing binary performance; strip acceptance is a delta not a target; dropping overlap on C1 alone repeats the track''s inference-without-measurement failure mode.', 'consult', 0, '', '{"id": "d-f7dc4d53c4", "ts": "2026-09-16T14:49:52.725Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect ranked direction (full verdict banked): anchor FAIL likely FALSE POSITIVE (authored spec contradiction: ''no MTP'' + ''= arm000 config''; B->arm000 ratio 1.30 = exactly MTP lift at acc 0.88). Ranked: (d) FIRST one re-anchor arm (C-leg + MTP, binary ca7a8adf) — decisive, prices overlap by subtraction; (b) SECOND strip now vs same-binary pre/post pair (C-leg 16.75 is reference, arm000 is target — never gate strip on arm000); (c) drop overlap CONDITIONAL on re-anchor ~=0; (a) rebase demoted unless re-anchor fails. Drop: overlap (conditional), #124 legacy-fallback path (guards deleted subsystem). Keep: ple (+2.5%/+14% sole clean fork perf receipt), MTP caps, Hydra endpoints, #469, RPC. Surgery checks: test-backend-ops.cpp/test-alloc.cpp may break; pre/post pair must include Arm C exactly (overlap fail at ffn_moe_gate-0 shares cache dispatch neighbourhood — strip could move cpu-moe behaviour).", "rationale": "Missing 21% is a missing feature (MTP), not missing binary performance; strip acceptance is a delta not a target; dropping overlap on C1 alone repeats the track''s inference-without-measurement failure mode.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-44dae3f83d', 'p-7719544617', 't-d1cf43b723', '2026-09-16T14:53:43.708Z', 'Re-anchor arm LANDS 21.28 (binary ca7a8adf md5-matched, C-leg + MTP, acc 0.86897): binary+harness sound, overlap ~= 0 by subtraction (21.28 vs 21.23 arm000, vs 16.75 C-no-MTP). No must-fix carried overlap. Consequences per ranked direction: (c) overlap drop condition SATISFIED — drop it in the strip; (a) rebase stays demoted; (b) strip acceptance = same-binary pre/post delta vs C-leg reference. Tasks 2+3 await owner release.', 'Decisive single arm resolved both branches: no gap to chase, no 25-30% carried overlap, no lost build to recover.', 'leader', 0, '', '{"id": "d-44dae3f83d", "ts": "2026-09-16T14:53:43.708Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Re-anchor arm LANDS 21.28 (binary ca7a8adf md5-matched, C-leg + MTP, acc 0.86897): binary+harness sound, overlap ~= 0 by subtraction (21.28 vs 21.23 arm000, vs 16.75 C-no-MTP). No must-fix carried overlap. Consequences per ranked direction: (c) overlap drop condition SATISFIED — drop it in the strip; (a) rebase stays demoted; (b) strip acceptance = same-binary pre/post delta vs C-leg reference. Tasks 2+3 await owner release.", "rationale": "Decisive single arm resolved both branches: no gap to chase, no 25-30% carried overlap, no lost build to recover.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ade2cfc86b', 'p-7719544617', 't-d1cf43b723', '2026-09-16T15:12:40.891Z', 'Contract deviation owned: all track spawns used raw task tool, bypassing the spawn loop (fleet_recommend -> fleet_spawn_spec -> exact args_mcp -> post-spawn steps -> usage report). Registry check now shows dev top pick baseline/local (free, p1), paid muse rank 5. Remediation: StripBranch12 stands (identical task contract, respawn wastes running work); usage filed late (muse:1); ALL future spawns go through the registry loop with exact args_mcp.', 'Respawning a healthy running worker to satisfy procedure would destroy progress for form''s sake; the binding fix is forward compliance.', 'leader', 0, '', '{"id": "d-ade2cfc86b", "ts": "2026-09-16T15:12:40.891Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Contract deviation owned: all track spawns used raw task tool, bypassing the spawn loop (fleet_recommend -> fleet_spawn_spec -> exact args_mcp -> post-spawn steps -> usage report). Registry check now shows dev top pick baseline/local (free, p1), paid muse rank 5. Remediation: StripBranch12 stands (identical task contract, respawn wastes running work); usage filed late (muse:1); ALL future spawns go through the registry loop with exact args_mcp.", "rationale": "Respawning a healthy running worker to satisfy procedure would destroy progress for form''s sake; the binding fix is forward compliance.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-607ceddccf', 'p-7719544617', 't-d1cf43b723', '2026-09-16T15:19:13.482Z', 'Phase 1 finding (StripBranch12): strip scope ABSENT at cdd11021b — no cache/overlap/ple/fallback anywhere; strip satisfied by construction, no commit needed. Consequences: (a) Phase 3 acceptance re-anchors to B-plain 16.34 (ple flag doesn''t exist on new branch); (b) ple-prefetch — the sole clean fork perf receipt — is NOT carried by the base, must be cherry-picked (extends Task 4 scope); (c) ordered fork-part inventory (MTP draft? Hydra endpoints? #469? RPC?) to establish what else needs picking.', 'Base predates the cache line entirely; the ''carry 16.8k'' assumption is now an inventory question, not a given.', 'leader', 0, '', '{"id": "d-607ceddccf", "ts": "2026-09-16T15:19:13.482Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase 1 finding (StripBranch12): strip scope ABSENT at cdd11021b — no cache/overlap/ple/fallback anywhere; strip satisfied by construction, no commit needed. Consequences: (a) Phase 3 acceptance re-anchors to B-plain 16.34 (ple flag doesn''t exist on new branch); (b) ple-prefetch — the sole clean fork perf receipt — is NOT carried by the base, must be cherry-picked (extends Task 4 scope); (c) ordered fork-part inventory (MTP draft? Hydra endpoints? #469? RPC?) to establish what else needs picking.", "rationale": "Base predates the cache line entirely; the ''carry 16.8k'' assumption is now an inventory question, not a given.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-7f6a0f8f7d', 'p-7719544617', 't-d1cf43b723', '2026-09-16T15:27:33.887Z', 'Phase 3 VERIFIED: stripped-base B-plain leg 16.458 vs pre-strip 16.343 (+0.7% noise) — strip regresses nothing; -1.7% vs 16.75 fully accounted by absent ple-prefetch. Inventory sets Task 4 scope: PRESENT at base (draft-mtp, MTP caps, qwen4exp graph, cpu-moe, #747, UM-T3, checkpoints, RPC) / ABSENT (hydra-engine 77 commits incl #469/#451/#43/#44 + engine tools, PR #101, ple-prefetch; SKIP overlap/priors/early-router/moe_grouped). Task 4 dispatched via full registry loop (recommend baseline/local rank-1 -> exact args_mcp -> brief -> usage filed). StripBranch12 stood down clean.', 'Zero-diff strip + noise-level delta closes Tasks 2+3 with measurements; Task 4 is now a bounded pick list with per-pick VRAM accounting.', 'leader', 0, '', '{"id": "d-7f6a0f8f7d", "ts": "2026-09-16T15:27:33.887Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase 3 VERIFIED: stripped-base B-plain leg 16.458 vs pre-strip 16.343 (+0.7% noise) — strip regresses nothing; -1.7% vs 16.75 fully accounted by absent ple-prefetch. Inventory sets Task 4 scope: PRESENT at base (draft-mtp, MTP caps, qwen4exp graph, cpu-moe, #747, UM-T3, checkpoints, RPC) / ABSENT (hydra-engine 77 commits incl #469/#451/#43/#44 + engine tools, PR #101, ple-prefetch; SKIP overlap/priors/early-router/moe_grouped). Task 4 dispatched via full registry loop (recommend baseline/local rank-1 -> exact args_mcp -> brief -> usage filed). StripBranch12 stood down clean.", "rationale": "Zero-diff strip + noise-level delta closes Tasks 2+3 with measurements; Task 4 is now a bounded pick list with per-pick VRAM accounting.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-81444b5e76', 'p-7719544617', 't-d1cf43b723', '2026-09-16T15:35:27.248Z', 'baseline/local excluded from fleet picks until fixed (user: local baseline not working). Killed Task-4 worker c05d7d4b before it started; respawning Task 4 on registry top pick with baseline marked exhausted.', 'Dead model must not hold the Task 4 slot; registry loop re-run with quota exhausted routes around it.', 'user', 0, '', '{"id": "d-81444b5e76", "ts": "2026-09-16T15:35:27.248Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "baseline/local excluded from fleet picks until fixed (user: local baseline not working). Killed Task-4 worker c05d7d4b before it started; respawning Task 4 on registry top pick with baseline marked exhausted.", "rationale": "Dead model must not hold the Task 4 slot; registry loop re-run with quota exhausted routes around it.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-8ea300cf58', 'p-7719544617', 't-d1cf43b723', '2026-09-16T15:49:37.460Z', 'Task 4 BLOCKED report resolved as wrong-repo-level check: branch + stash live in submodule src/llama-cpp (where StripBranch12 worked), not parent. Directed worker to verify via git -C, checkout-or-create in submodule, treat missing stash as flag-not-block, M pointer expected uncommitted. Proceed to pick 1.', 'All three mismatch points are explained by parent-vs-submodule level confusion; no evidence of lost work yet.', 'leader', 0, '', '{"id": "d-8ea300cf58", "ts": "2026-09-16T15:49:37.460Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Task 4 BLOCKED report resolved as wrong-repo-level check: branch + stash live in submodule src/llama-cpp (where StripBranch12 worked), not parent. Directed worker to verify via git -C, checkout-or-create in submodule, treat missing stash as flag-not-block, M pointer expected uncommitted. Proceed to pick 1.", "rationale": "All three mismatch points are explained by parent-vs-submodule level confusion; no evidence of lost work yet.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d6a82caa40', 'p-7719544617', 't-d1cf43b723', '2026-09-16T15:53:15.367Z', 'Standing brief accepted: six-thinking-hats fires at PLAN step 4 before design/workers when (1) contested scope, (2) >=3-worker split, (3) gate/STOP fired, (4) escalation with owner unavailable. Decision mode (Blue-White-Black-Yellow-Blue) for go/no-go, Risk mode for ship-risk, never Full, Standard depth, White bullets labelled KNOWN/ASSUMED/UNKNOWN, output posted as GitHub issue comment (durable state). Worked example (drop overlap) already closed by re-anchor measurement (21.28, overlap ~=0) — no retroactive post; triggers are prospective from here.', 'Track''s three costliest errors were assumptions delegated as facts; White-hat labelling is the forcing function.', 'user', 0, '', '{"id": "d-d6a82caa40", "ts": "2026-09-16T15:53:15.367Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Standing brief accepted: six-thinking-hats fires at PLAN step 4 before design/workers when (1) contested scope, (2) >=3-worker split, (3) gate/STOP fired, (4) escalation with owner unavailable. Decision mode (Blue-White-Black-Yellow-Blue) for go/no-go, Risk mode for ship-risk, never Full, Standard depth, White bullets labelled KNOWN/ASSUMED/UNKNOWN, output posted as GitHub issue comment (durable state). Worked example (drop overlap) already closed by re-anchor measurement (21.28, overlap ~=0) — no retroactive post; triggers are prospective from here.", "rationale": "Track''s three costliest errors were assumptions delegated as facts; White-hat labelling is the forcing function.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f7989bea4d', 'p-7719544617', 't-d1cf43b723', '2026-09-16T15:54:07.608Z', 'Architect condition RELEASED (re-anchor 21.28 vs 21.23, same binary): three KNOWNs recorded — (1) no harness fault/lost binary (spec contradiction, MTP lift 1.30x explains all); (2) overlap ~=0, DROP (removes overlap path + hard-fail surface atop 30.6k cache); (3) strip acceptance reference = cpu-moe+ple+MTP 767tok ca7a8adf at 21.28 (never arm000). Task 5 stays demoted. Revised sequence strip->verify->MTP-pick->rebase-last. Applied to live state: strip/overlap both absent at base (satisfied); Task 4 final acceptance updated to 21.28-config leg once ple+MTP picks land. Cautions carried: ple/overlap separate paths (ple picked, not swept); ffn_moe_gate-0 neighbourhood watched via pre/post pair.', 'Condition satisfied by measurement; acceptance reference now names an exact reproducible config.', 'consult', 0, '', '{"id": "d-f7989bea4d", "ts": "2026-09-16T15:54:07.608Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect condition RELEASED (re-anchor 21.28 vs 21.23, same binary): three KNOWNs recorded — (1) no harness fault/lost binary (spec contradiction, MTP lift 1.30x explains all); (2) overlap ~=0, DROP (removes overlap path + hard-fail surface atop 30.6k cache); (3) strip acceptance reference = cpu-moe+ple+MTP 767tok ca7a8adf at 21.28 (never arm000). Task 5 stays demoted. Revised sequence strip->verify->MTP-pick->rebase-last. Applied to live state: strip/overlap both absent at base (satisfied); Task 4 final acceptance updated to 21.28-config leg once ple+MTP picks land. Cautions carried: ple/overlap separate paths (ple picked, not swept); ffn_moe_gate-0 neighbourhood watched via pre/post pair.", "rationale": "Condition satisfied by measurement; acceptance reference now names an exact reproducible config.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6323c84383', 'p-7719544617', 't-d1cf43b723', '2026-09-16T16:05:24.795Z', 'Pick 1b dependency call: option (B) — adapt to_fd wrapper to public buffered API, do NOT pull in 69d49e0a4 async machinery. Keeps build green, no scope expansion; zero-copy is a perf follow-up, not a correctness need.', '(A) imports behavioral async server-task scope beyond inventory; (C) drops E0 functionality; (B) is functionally correct with a noted perf caveat.', 'leader', 0, '', '{"id": "d-6323c84383", "ts": "2026-09-16T16:05:24.795Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Pick 1b dependency call: option (B) — adapt to_fd wrapper to public buffered API, do NOT pull in 69d49e0a4 async machinery. Keeps build green, no scope expansion; zero-copy is a perf follow-up, not a correctness need.", "rationale": "(A) imports behavioral async server-task scope beyond inventory; (C) drops E0 functionality; (B) is functionally correct with a noted perf caveat.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-69e6ead6f5', 'p-7719544617', 't-d1cf43b723', '2026-09-16T16:08:58.341Z', 'Task 4 worker migrated to paid muse-spark (free quota near limit, user-directed): killed free worker post-1a-commit (1b staged state handed off), respawned via loop (all-free exhausted -> paid rank 5 recommended), brief with handoff verification resent after turn-1 race; worker now verifying state.', 'Free-tier exhaustion mid-surgery would strand conflict-resolution work; paid q78 also fits the surgery quality need.', 'user', 0, '', '{"id": "d-69e6ead6f5", "ts": "2026-09-16T16:08:58.341Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Task 4 worker migrated to paid muse-spark (free quota near limit, user-directed): killed free worker post-1a-commit (1b staged state handed off), respawned via loop (all-free exhausted -> paid rank 5 recommended), brief with handoff verification resent after turn-1 race; worker now verifying state.", "rationale": "Free-tier exhaustion mid-surgery would strand conflict-resolution work; paid q78 also fits the surgery quality need.", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-c10a00d82c', 'p-7719544617', 't-d1cf43b723', '2026-09-16T16:21:15.679Z', 'Handoff verification caught out-of-order 1d cherry-pick (free worker skipped 1b/1c, conflicted state): approved abort-1d, rebuild 1b-option-B, then 1c->1d->1e in order. 1a verified committed; M pointer + stash untouched.', '1d''s base assumes 1b/1c context — resolving forward would contaminate all downstream picks; abort cost is minutes.', 'leader', 0, '', '{"id": "d-c10a00d82c", "ts": "2026-09-16T16:21:15.679Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Handoff verification caught out-of-order 1d cherry-pick (free worker skipped 1b/1c, conflicted state): approved abort-1d, rebuild 1b-option-B, then 1c->1d->1e in order. 1a verified committed; M pointer + stash untouched.", "rationale": "1d''s base assumes 1b/1c context — resolving forward would contaminate all downstream picks; abort cost is minutes.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-eab4c74fb5', 'p-7719544617', 't-d1cf43b723', '2026-09-16T16:36:01.180Z', 'Parallel speedup (user: max parallel, OMP harness, 3 GPUs, 128GB RAM binding): 3 streams in isolated git worktrees — main (hydra-engine stack 1b-1e, rescoped STOP at 1e after it landed ple redundantly), ple-worker (ple + #101 on 3060), mtpmods-worker (MTP modules + VRAM on P100). All builds capped -j6. Main worker owns final merge + 21.28 leg on explicit order only.', 'Stacked picks are serial per branch; independent picks parallelize across worktrees/GPUs; merge cost contained by file separation (server vs prefetch vs model files).', 'user', 0, '', '{"id": "d-eab4c74fb5", "ts": "2026-09-16T16:36:01.180Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Parallel speedup (user: max parallel, OMP harness, 3 GPUs, 128GB RAM binding): 3 streams in isolated git worktrees — main (hydra-engine stack 1b-1e, rescoped STOP at 1e after it landed ple redundantly), ple-worker (ple + #101 on 3060), mtpmods-worker (MTP modules + VRAM on P100). All builds capped -j6. Main worker owns final merge + 21.28 leg on explicit order only.", "rationale": "Stacked picks are serial per branch; independent picks parallelize across worktrees/GPUs; merge cost contained by file separation (server vs prefetch vs model files).", "source": "user", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-89e08cdf8f', 'p-7719544617', 't-d1cf43b723', '2026-09-16T16:53:18.316Z', 'Main stream 1-series GREEN at b627d3d81: revert executed, CPU build-check exposed phantom slot members (broken since 1a, never compiled) — fixed to stats equivalents. Merge base ready; merge ordered only when siblings report.', 'Pre-existing breakage caught before merge would have contaminated all downstream builds; fixup is +6/-6, minimal.', 'leader', 0, '', '{"id": "d-89e08cdf8f", "ts": "2026-09-16T16:53:18.316Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Main stream 1-series GREEN at b627d3d81: revert executed, CPU build-check exposed phantom slot members (broken since 1a, never compiled) — fixed to stats equivalents. Merge base ready; merge ordered only when siblings report.", "rationale": "Pre-existing breakage caught before merge would have contaminated all downstream builds; fixup is +6/-6, minimal.", "source": "leader", "irreversible": false, "author": ""}');
