INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-650baddc12', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:16:48.519Z', 'k8 + 64K both completed before tiering (d-6c88ad125d, turn 574) — not dropped, relay failure only. Resent with full numbers; 64K VRAM forwarded to TierDesign for §3/F-4. Collection state: halted after c02 for length-tiered v2 (owner length ruling); 64K already run, backfill trace still queued after collection.', 'Numbers existed in ledger; owner message crossed the report.', 'leader', 0, '', '{"id": "d-650baddc12", "ts": "2026-09-17T04:16:48.519Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "k8 + 64K both completed before tiering (d-6c88ad125d, turn 574) — not dropped, relay failure only. Resent with full numbers; 64K VRAM forwarded to TierDesign for §3/F-4. Collection state: halted after c02 for length-tiered v2 (owner length ruling); 64K already run, backfill trace still queued after collection.", "rationale": "Numbers existed in ledger; owner message crossed the report.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-5366601a9f', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:18:21.464Z', 'Owner §3 verdict executed: refit risk + A4 doubt retired; §3 filled with measured 4,441 MiB; N=36 operating point at 64K (N=42 ≤32K only); 48/49 elevated to ship/no-ship; GPU1 recorded with invariant; 1a range table as v2-settles. HPrefill re-emitting N=36 table offline. Goal question with owner; workstream unchanged.', '1.8% 32K->64K cost keeps the expert term dominant at target context.', 'leader', 0, '', '{"id": "d-5366601a9f", "ts": "2026-09-17T04:18:21.464Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Owner §3 verdict executed: refit risk + A4 doubt retired; §3 filled with measured 4,441 MiB; N=36 operating point at 64K (N=42 ≤32K only); 48/49 elevated to ship/no-ship; GPU1 recorded with invariant; 1a range table as v2-settles. HPrefill re-emitting N=36 table offline. Goal question with owner; workstream unchanged.", "rationale": "1.8% 32K->64K cost keeps the expert term dominant at target context.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-5a60ffb858', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:18:43.342Z', 'N=36 exact replay: coding h=0.3760 S=1.2728, general h=0.3885 S=1.2845 (n=1-provisional; interp within 0.003). Confirms owner''s ~0.37/~1.27 estimate almost exactly. Forwarded to note.', 'Exact replay, zero GPU; h30/h42 reproduce source json.', 'leader', 0, '', '{"id": "d-5a60ffb858", "ts": "2026-09-17T04:18:43.342Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "N=36 exact replay: coding h=0.3760 S=1.2728, general h=0.3885 S=1.2845 (n=1-provisional; interp within 0.003). Confirms owner''s ~0.37/~1.27 estimate almost exactly. Forwarded to note.", "rationale": "Exact replay, zero GPU; h30/h42 reproduce source json.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-dbb04682b1', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:21:16.813Z', 'v2 pack landed (44 prompts, M 551-588 / L 2505-2565 tiers, length-matched pairs, worst match 0.944); collection RESTARTED on v2, v1 traces kept as short-end coverage (S-tier absence accepted on that basis). C01/G01 anchors first.', 'Length confound designed out at the corpus level; truncation curve becomes cross-check, not primary.', 'leader', 0, '', '{"id": "d-dbb04682b1", "ts": "2026-09-17T04:21:16.813Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "v2 pack landed (44 prompts, M 551-588 / L 2505-2565 tiers, length-matched pairs, worst match 0.944); collection RESTARTED on v2, v1 traces kept as short-end coverage (S-tier absence accepted on that basis). C01/G01 anchors first.", "rationale": "Length confound designed out at the corpus level; truncation curve becomes cross-check, not primary.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-636802e0af', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:24:13.083Z', 'v2 collection running (43/44; g22 excluded on pack hash defect, fix requested). Token-density note: code+logs tokenize ~1.5x denser than chars/4 — M actual ~850-900, L ~3500-3800, fits -c 4096 (4056 < 4096 tight); loop escalates on breach. Anchors stand without re-collect.', 'Length spread holds shifted up; no spec impact.', 'leader', 0, '', '{"id": "d-636802e0af", "ts": "2026-09-17T04:24:13.083Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "v2 collection running (43/44; g22 excluded on pack hash defect, fix requested). Token-density note: code+logs tokenize ~1.5x denser than chars/4 — M actual ~850-900, L ~3500-3800, fits -c 4096 (4056 < 4096 tight); loop escalates on breach. Anchors stand without re-collect.", "rationale": "Length spread holds shifted up; no spec impact.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-59b95d3d32', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:26:13.199Z', 'g22 defect resolved (text won; table/manifest corrected to 10022/a68486; 44/44 verified). Admitted to loop — collection whole again.', 'Trailing-newline strip post-generation; file+fence agreed, stale hash outlier.', 'leader', 0, '', '{"id": "d-59b95d3d32", "ts": "2026-09-17T04:26:13.199Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "g22 defect resolved (text won; table/manifest corrected to 10022/a68486; 44/44 verified). Admitted to loop — collection whole again.", "rationale": "Trailing-newline strip post-generation; file+fence agreed, stale hash outlier.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1676067bae', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:43:11.087Z', 'Owner v3 executed: v2 halted (traces preserved); PromptPack authoring 15+ set with pre-clearance table; HPrefill re-emitting N=38; TierDesign recording goal/N/v3. Collection restarts only after owner clears the set.', 'n=1-per-subject is the defect that killed the last finding; goal is now deltas vs banked baselines.', 'leader', 0, '', '{"id": "d-1676067bae", "ts": "2026-09-17T04:43:11.087Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Owner v3 executed: v2 halted (traces preserved); PromptPack authoring 15+ set with pre-clearance table; HPrefill re-emitting N=38; TierDesign recording goal/N/v3. Collection restarts only after owner clears the set.", "rationale": "n=1-per-subject is the defect that killed the last finding; goal is now deltas vs banked baselines.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-3de397a99e', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:43:22.851Z', 'N=38 exact: coding h=0.3869 S=1.2829, general h=0.3978 S=1.2933 (n=1-provisional). 64K operating point set; forward to note.', 'Exact replay, zero GPU.', 'leader', 0, '', '{"id": "d-3de397a99e", "ts": "2026-09-17T04:43:22.851Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "N=38 exact: coding h=0.3869 S=1.2829, general h=0.3978 S=1.2933 (n=1-provisional). 64K operating point set; forward to note.", "rationale": "Exact replay, zero GPU.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-4e361eeb16', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:44:07.026Z', 'Third estimator-substitution error caught by owner: +28.3% struck as expected gain (within-sequence h quoted for a cross-prompt shipment). Note to carry range +9..+28% with no point estimate; standing rule (estimator + n on every h) enforced on all future edits. N=38 stands.', 'Same-direction error three times: easier-condition estimator substituted for the deployed one.', 'leader', 0, '', '{"id": "d-4e361eeb16", "ts": "2026-09-17T04:44:07.026Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Third estimator-substitution error caught by owner: +28.3% struck as expected gain (within-sequence h quoted for a cross-prompt shipment). Note to carry range +9..+28% with no point estimate; standing rule (estimator + n on every h) enforced on all future edits. N=38 stands.", "rationale": "Same-direction error three times: easier-condition estimator substituted for the deployed one.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ada57e4e63', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:47:23.777Z', 'v3 set reviewed: 18 prompts, triplet char-match >=0.989, full range overlap — structurally sound. One caveat for owner: ~tok is chars/4 and code tokenizes ~1.5x denser than prose, so char-matched triplets may be token-mismatched by 10-20%; collection must measure actual P_i per trace and report mismatch before analysis pools. Presented for clearance with that caveat.', 'Density lesson from v2 (876 actual vs 582 est) applies directly to triplet matching.', 'leader', 0, '', '{"id": "d-ada57e4e63", "ts": "2026-09-17T04:47:23.777Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "v3 set reviewed: 18 prompts, triplet char-match >=0.989, full range overlap — structurally sound. One caveat for owner: ~tok is chars/4 and code tokenizes ~1.5x denser than prose, so char-matched triplets may be token-mismatched by 10-20%; collection must measure actual P_i per trace and report mismatch before analysis pools. Presented for clearance with that caveat.", "rationale": "Density lesson from v2 (876 actual vs 582 est) applies directly to triplet matching.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6c9524e4e4', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:50:46.514Z', 'v4 executed: PromptPack authoring session set (pre-clearance); RouterRead spawned (Task B cluster + Task A spec/do); TierDesign recording estimator correction + v4 series + router row; v4 collection task added, gated on set clearance. Cross-prompt retired as deployment estimator; h_warm is the number.', 'Agent works same subject across turns — within-session residency is the shipped regime and should exceed 0.4062.', 'leader', 0, '', '{"id": "d-6c9524e4e4", "ts": "2026-09-17T04:50:46.514Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "v4 executed: PromptPack authoring session set (pre-clearance); RouterRead spawned (Task B cluster + Task A spec/do); TierDesign recording estimator correction + v4 series + router row; v4 collection task added, gated on set clearance. Cross-prompt retired as deployment estimator; h_warm is the number.", "rationale": "Agent works same subject across turns — within-session residency is the shipped regime and should exceed 0.4062.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-3a94031a13', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:53:51.769Z', 'v4 set reviewed: 30 turns (3x4 sessions, 3/3/2/2), real continuity (concatenation with real decodes, no fabricated assistant text), T1 char-matched across subjects with post-hoc 10% spread check, 21 FULL + 9 PRE, 4 subtypes/subject. Presented for owner clearance with the carried density caveat (char-match, token truth at collection).', 'Strong pack; token-match verified post-hoc by design.', 'leader', 0, '', '{"id": "d-3a94031a13", "ts": "2026-09-17T04:53:51.769Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "v4 set reviewed: 30 turns (3x4 sessions, 3/3/2/2), real continuity (concatenation with real decodes, no fabricated assistant text), T1 char-matched across subjects with post-hoc 10% spread check, 21 FULL + 9 PRE, 4 subtypes/subject. Presented for owner clearance with the carried density caveat (char-match, token truth at collection).", "rationale": "Strong pack; token-match verified post-hoc by design.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-33b70c906f', 'p-7719544617', 't-d1cf43b723', '2026-09-17T04:54:48.930Z', 'RouterRead done: Task B CONFIRMED (experts cluster all 48 layers; subject alignment modest, 48/48 layers, key-space separation predicts pinnability r=+0.72 — geometry is a prior, not a pin set). Task A STOP with exact unblock spec (router-input dump via one graph callback + forward pass, ~150MB/prompt; CPU-reimplementation and embedding-proxy both rejected with reasons). Presenting callback authorization to owner rather than dispatching fork work unilaterally.', 'Fork patch + rig run needs owner go; Task A may obsolete trace campaigns so the call matters.', 'leader', 0, '', '{"id": "d-33b70c906f", "ts": "2026-09-17T04:54:48.930Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "RouterRead done: Task B CONFIRMED (experts cluster all 48 layers; subject alignment modest, 48/48 layers, key-space separation predicts pinnability r=+0.72 — geometry is a prior, not a pin set). Task A STOP with exact unblock spec (router-input dump via one graph callback + forward pass, ~150MB/prompt; CPU-reimplementation and embedding-proxy both rejected with reasons). Presenting callback authorization to owner rather than dispatching fork work unilaterally.", "rationale": "Fork patch + rig run needs owner go; Task A may obsolete trace campaigns so the call matters.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-57dce91aa5', 'p-7719544617', 't-d1cf43b723', '2026-09-17T06:36:50.634Z', 'Architect verdict: v4 APPROVED after F1-F3 (F1 decode-only scoring is campaign-fatal; F2 last-turn-FULL needs set amendment — S2/S3/S4 end PRE; F3 paired controls). Task A DECLINED circular (PRE turns subsume it); Task B = turn-1 cold-start prior. Fixes in flight; owner clearance now covers the amended set.', 'Prefill re-read would manufacture a flattering h_warm that fails in production.', 'leader', 0, '', '{"id": "d-57dce91aa5", "ts": "2026-09-17T06:36:50.634Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect verdict: v4 APPROVED after F1-F3 (F1 decode-only scoring is campaign-fatal; F2 last-turn-FULL needs set amendment — S2/S3/S4 end PRE; F3 paired controls). Task A DECLINED circular (PRE turns subsume it); Task B = turn-1 cold-start prior. Fixes in flight; owner clearance now covers the amended set.", "rationale": "Prefill re-read would manufacture a flattering h_warm that fails in production.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-44d4cdf010', 'p-7719544617', 't-d1cf43b723', '2026-09-17T06:38:10.282Z', 'Amended set accepted for presentation: 30/30 FULL (pack over-complied F2 by removing PRE entirely — costs ~9 extra decodes, buys uniformity; flagged to owner as their cost call). F1/F3 binding, flags recorded, hashes agree. Presenting for clearance.', 'Uniformity over cleverness; rig time available.', 'leader', 0, '', '{"id": "d-44d4cdf010", "ts": "2026-09-17T06:38:10.282Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Amended set accepted for presentation: 30/30 FULL (pack over-complied F2 by removing PRE entirely — costs ~9 extra decodes, buys uniformity; flagged to owner as their cost call). F1/F3 binding, flags recorded, hashes agree. Presenting for clearance.", "rationale": "Uniformity over cleverness; rig time available.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-368d9b6d31', 'p-7719544617', 't-d1cf43b723', '2026-09-17T07:10:22.624Z', 'Architect set-review APPROVE with B1+B2: B1 turn-depth confound re-laid at zero cost; B2 adds the offline/global arms that let the campaign decide the build (without them warm-static measures adaptation, not the by-subject payoff). Flags binding. Set re-verification in flight.', 'Second architect catch that saves a campaign (F1 prefill-scoring, now B1 depth-confounds).', 'leader', 0, '', '{"id": "d-368d9b6d31", "ts": "2026-09-17T07:10:22.624Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect set-review APPROVE with B1+B2: B1 turn-depth confound re-laid at zero cost; B2 adds the offline/global arms that let the campaign decide the build (without them warm-static measures adaptation, not the by-subject payoff). Flags binding. Set re-verification in flight.", "rationale": "Second architect catch that saves a campaign (F1 prefill-scoring, now B1 depth-confounds).", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f4ab1309a8', 'p-7719544617', 't-d1cf43b723', '2026-09-17T07:12:55.587Z', 'Re-laid set accepted for presentation: B1 de-confounded (S1+S3 long/short 3-turn), B2 arms + flags recorded, 30/30 FULL verified. One boundary flagged: S3-T3 projected 3950-4050 (cap 4100) — ~1% over the 4000 spec top; owner''s call to accept or trim. Presenting for clearance.', 'Everything else within spec; single marginal cell.', 'leader', 0, '', '{"id": "d-f4ab1309a8", "ts": "2026-09-17T07:12:55.587Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Re-laid set accepted for presentation: B1 de-confounded (S1+S3 long/short 3-turn), B2 arms + flags recorded, 30/30 FULL verified. One boundary flagged: S3-T3 projected 3950-4050 (cap 4100) — ~1% over the 4000 spec top; owner''s call to accept or trim. Presenting for clearance.", "rationale": "Everything else within spec; single marginal cell.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ef912e22bb', 'p-7719544617', 't-d1cf43b723', '2026-09-17T07:18:01.858Z', 'Architect verification HOLD: B1 CLEAR, 6 fixes (H1 template contradiction + H2 EOS block collection; H3-H6 analysis/spec). S3-T3 accepted at 4100. Fixes in flight; collection stays gated.', 'Verification round caught a self-contradiction that would have shipped a degraded collection.', 'leader', 0, '', '{"id": "d-ef912e22bb", "ts": "2026-09-17T07:18:01.858Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect verification HOLD: B1 CLEAR, 6 fixes (H1 template contradiction + H2 EOS block collection; H3-H6 analysis/spec). S3-T3 accepted at 4100. Fixes in flight; collection stays gated.", "rationale": "Verification round caught a self-contradiction that would have shipped a degraded collection.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b85a68d92e', 'p-7719544617', 't-d1cf43b723', '2026-09-17T07:20:49.992Z', 'H1-H6 applied and re-verified (30/30 hashes, all FULL, template concatenation, EOS policy, train windows + matched-50s, h_allpool headline, continuous resident set, slip fixed; band 1000-4100). Set has survived F1-F3 + B1-B2 + H1-H6 across three architect passes. Presenting FINAL for owner clearance.', 'No further verification layers left; remaining risk is owner''s spec judgment.', 'leader', 0, '', '{"id": "d-b85a68d92e", "ts": "2026-09-17T07:20:49.992Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "H1-H6 applied and re-verified (30/30 hashes, all FULL, template concatenation, EOS policy, train windows + matched-50s, h_allpool headline, continuous resident set, slip fixed; band 1000-4100). Set has survived F1-F3 + B1-B2 + H1-H6 across three architect passes. Presenting FINAL for owner clearance.", "rationale": "No further verification layers left; remaining risk is owner''s spec judgment.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a214632ac9', 'p-7719544617', 't-d1cf43b723', '2026-09-17T07:41:18.288Z', 'Architect 1a-readiness: NOT IDLE — order 3→1→2→4 dispatched to rig worker (instrument; synthetic-pin G3 NOW in idle window, can kill 1a before collection spends; pin-file loader; scorer on banked traces). Collection clearance preempts all. Do-not-touch list enforced.', 'G3-on-synthetics converts h_warm from a second campaign into a curve lookup — and can obsolete collection''s urgency.', 'leader', 0, '', '{"id": "d-a214632ac9", "ts": "2026-09-17T07:41:18.288Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect 1a-readiness: NOT IDLE — order 3→1→2→4 dispatched to rig worker (instrument; synthetic-pin G3 NOW in idle window, can kill 1a before collection spends; pin-file loader; scorer on banked traces). Collection clearance preempts all. Do-not-touch list enforced.", "rationale": "G3-on-synthetics converts h_warm from a second campaign into a curve lookup — and can obsolete collection''s urgency.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-2216767bf5', 'p-7719544617', 't-d1cf43b723', '2026-09-17T08:01:07.322Z', 'G3 amended per architect: 4 arms (all-HIT added), 5 calibrated h values x 3 N, per-layer miss logging. Uniform/Task-B demoted to reference points. Dispatched before item-1 run — no wasted leg.', 'Kill at h<=0.3 alone would be challengeable; all-HIT makes it appeal-proof and checks the refit.', 'leader', 0, '', '{"id": "d-2216767bf5", "ts": "2026-09-17T08:01:07.322Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "G3 amended per architect: 4 arms (all-HIT added), 5 calibrated h values x 3 N, per-layer miss logging. Uniform/Task-B demoted to reference points. Dispatched before item-1 run — no wasted leg.", "rationale": "Kill at h<=0.3 alone would be challengeable; all-HIT makes it appeal-proof and checks the refit.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d44483e410', 'p-7719544617', 't-d1cf43b723', '2026-09-17T08:01:14.229Z', 'G3 amended per architect: 4 arms (all-HIT added), 5 calibrated h values x 3 N, per-layer miss logging. Uniform/Task-B demoted to reference points. Worker on item 3 reports zero counters (tensor-name mismatch suspected, investigating).', 'Kill at h<=0.3 alone challengeable; all-HIT appeal-proof + refit check.', 'leader', 0, '', '{"id": "d-d44483e410", "ts": "2026-09-17T08:01:14.229Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "G3 amended per architect: 4 arms (all-HIT added), 5 calibrated h values x 3 N, per-layer miss logging. Uniform/Task-B demoted to reference points. Worker on item 3 reports zero counters (tensor-name mismatch suspected, investigating).", "rationale": "Kill at h<=0.3 alone challengeable; all-HIT appeal-proof + refit check.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-8e8d5bdd80', 'p-7719544617', 't-d1cf43b723', '2026-09-17T08:41:26.648Z', 'G3 criteria pre-registered and bound: target corrected to 2.20; kill/pass/redesign lines on S(1.0); S(0.40)>=1.10 gate; variance+monotonicity gates; a/b fit decides redesign; fixed eval order. Serial noted strictly pessimal (concurrent = redesign path, not kill).', 'Criteria before numbers — no motivated reading.', 'leader', 0, '', '{"id": "d-8e8d5bdd80", "ts": "2026-09-17T08:41:26.648Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "G3 criteria pre-registered and bound: target corrected to 2.20; kill/pass/redesign lines on S(1.0); S(0.40)>=1.10 gate; variance+monotonicity gates; a/b fit decides redesign; fixed eval order. Serial noted strictly pessimal (concurrent = redesign path, not kill).", "rationale": "Criteria before numbers — no motivated reading.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-70b2c57300', 'p-7719544617', 't-d1cf43b723', '2026-09-17T08:48:58.737Z', 'G3 verdict CHALLENGED, not banked: h≡0 with ''no store ever built'' smells of ordering artifact (item 1 before its forcing mechanism), and S=1.00-unengaged cannot void the k8-confirmed α. Worker HELD on items 2/4; architect adjudicating validity + correct order.', 'A kill verdict from a leg that couldn''t engage is premise failure, not evidence — exactly what pre-registered criteria were meant to catch, applied one level up.', 'leader', 0, '', '{"id": "d-70b2c57300", "ts": "2026-09-17T08:48:58.737Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "G3 verdict CHALLENGED, not banked: h≡0 with ''no store ever built'' smells of ordering artifact (item 1 before its forcing mechanism), and S=1.00-unengaged cannot void the k8-confirmed α. Worker HELD on items 2/4; architect adjudicating validity + correct order.", "rationale": "A kill verdict from a leg that couldn''t engage is premise failure, not evidence — exactly what pre-registered criteria were meant to catch, applied one level up.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-32602528bc', 'p-7719544617', 't-d1cf43b723', '2026-09-17T08:50:00.230Z', 'Architect: G3 KILL INVALID (ordering artifact, prep order owned the error); α stands (k8 positive evidence beats null); correct order is -ot KILL screen then 2→1; liveness precondition (hit+miss>0) pre-registered for all future G3; dark-path overhead banked ~0. Dispatched.', 'Mechanism must run to be judged slow; -ot screen can kill today with zero code.', 'leader', 0, '', '{"id": "d-32602528bc", "ts": "2026-09-17T08:50:00.230Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect: G3 KILL INVALID (ordering artifact, prep order owned the error); α stands (k8 positive evidence beats null); correct order is -ot KILL screen then 2→1; liveness precondition (hit+miss>0) pre-registered for all future G3; dark-path overhead banked ~0. Dispatched.", "rationale": "Mechanism must run to be judged slow; -ot screen can kill today with zero code.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0332feef93', 'p-7719544617', 't-d1cf43b723', '2026-09-17T09:07:09.409Z', '-ot screen CANCELLED per architect reversal (5.6x VRAM → OOM/silent-fallback; honest version unreadable S=1.04 vs 8% noise). One leg ran pre-cancel: tg 24.05/pp 255.3 with ZERO override lines — unclaimed pending load-log binding proof (silent-baseline suspect + config-drift smell). Item 2 next.', 'Cancel arrived one leg late; extract only binding-verified value.', 'leader', 0, '', '{"id": "d-0332feef93", "ts": "2026-09-17T09:07:09.409Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "-ot screen CANCELLED per architect reversal (5.6x VRAM → OOM/silent-fallback; honest version unreadable S=1.04 vs 8% noise). One leg ran pre-cancel: tg 24.05/pp 255.3 with ZERO override lines — unclaimed pending load-log binding proof (silent-baseline suspect + config-drift smell). Item 2 next.", "rationale": "Cancel arrived one leg late; extract only binding-verified value.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-49c0ab9e64', 'p-7719544617', 't-d1cf43b723', '2026-09-17T09:11:44.566Z', 'Branch rules pre-registered: numbers exceed ceiling (+29%) so a premise is wrong; +33% must be explained via named config diff (MTP first) not dismissed; binding-proven win gates on 64K re-run (likely short-ctx denominator effect); transferable capped +29%; static-layer fork noted (may dominate item 2 if it loads at 64K). Worker executing binding+diff.', 'Unexplained 33% swing invalidates every downstream verdict in a 30%-thesis program.', 'leader', 0, '', '{"id": "d-49c0ab9e64", "ts": "2026-09-17T09:11:44.566Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Branch rules pre-registered: numbers exceed ceiling (+29%) so a premise is wrong; +33% must be explained via named config diff (MTP first) not dismissed; binding-proven win gates on 64K re-run (likely short-ctx denominator effect); transferable capped +29%; static-layer fork noted (may dominate item 2 if it loads at 64K). Worker executing binding+diff.", "rationale": "Unexplained 33% swing invalidates every downstream verdict in a 30%-thesis program.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6b49b6b43e', 'p-7719544617', 't-d1cf43b723', '2026-09-17T09:12:49.794Z', 'Binding PROVEN (20/28, 3-way corroborated); MTP ruled out; named difference = placement; short-ctx cap applied. Gate leg dispatched: same placement at 64K — loads+wins opens the static-layer fork (may obsolete ranking program); OOM kills fork, item 2 proceeds.', 'Branch rules executed exactly as pre-registered.', 'leader', 0, '', '{"id": "d-6b49b6b43e", "ts": "2026-09-17T09:12:49.794Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Binding PROVEN (20/28, 3-way corroborated); MTP ruled out; named difference = placement; short-ctx cap applied. Gate leg dispatched: same placement at 64K — loads+wins opens the static-layer fork (may obsolete ranking program); OOM kills fork, item 2 proceeds.", "rationale": "Branch rules executed exactly as pre-registered.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-8de1256077', 'p-7719544617', 't-d1cf43b723', '2026-09-17T09:14:31.210Z', '64K gate OOM: static-layer fork DEAD per rule (binding holds by contradiction; 26GB+ vs 27GB free — never deployable at 64K). Item 2 proceeds pending host-path call (A CPU-admission vs B dispatch-move) now with architect.', 'Pre-registered gate executed exactly; fork killed cleanly with no appeal.', 'leader', 0, '', '{"id": "d-8de1256077", "ts": "2026-09-17T09:14:31.210Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "64K gate OOM: static-layer fork DEAD per rule (binding holds by contradiction; 26GB+ vs 27GB free — never deployable at 64K). Item 2 proceeds pending host-path call (A CPU-admission vs B dispatch-move) now with architect.", "rationale": "Pre-registered gate executed exactly; fork killed cleanly with no appeal.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ddd622710c', 'p-7719544617', 't-d1cf43b723', '2026-09-17T09:15:34.520Z', 'Host-path A called: CPU-admission measurement-only first (H2D-on-miss stripped as Stage-2 leak, ~100ms/token fatal); 3-step liveness (degenerate, completeness, trace reconciliation) before any timing; N=38 ≈1.9GB unaffected by OOM. Dispatched.', 'Next increment must be structurally incapable of silent-no-op; B is a bet on zero data.', 'leader', 0, '', '{"id": "d-ddd622710c", "ts": "2026-09-17T09:15:34.520Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Host-path A called: CPU-admission measurement-only first (H2D-on-miss stripped as Stage-2 leak, ~100ms/token fatal); 3-step liveness (degenerate, completeness, trace reconciliation) before any timing; N=38 ≈1.9GB unaffected by OOM. Dispatched.", "rationale": "Next increment must be structurally incapable of silent-no-op; B is a bet on zero data.", "source": "leader", "irreversible": false, "author": ""}');
