INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b870fb99c6', 'p-7719544617', 't-d1cf43b723', '2026-09-17T12:15:25.022Z', 'Reasoning verdict: corr-null correction (coding −0.770 ≈ null −0.707, uninformative; reasoning −0.967 real-but-fragile, needs σ + jackknife); essay pre-reg (offline−static ≥ coding if coherence drives; S3/S4 dialogue natural experiment); warm reframed as variance-reducer; oracle +.713 licenses little.', 'Architect adjudication; statistics corrected before 3-leg.', 'leader', 0, '', '{"id": "d-b870fb99c6", "ts": "2026-09-17T12:15:25.022Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Reasoning verdict: corr-null correction (coding −0.770 ≈ null −0.707, uninformative; reasoning −0.967 real-but-fragile, needs σ + jackknife); essay pre-reg (offline−static ≥ coding if coherence drives; S3/S4 dialogue natural experiment); warm reframed as variance-reducer; oracle +.713 licenses little.", "rationale": "Architect adjudication; statistics corrected before 3-leg.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d06ecf8423', 'p-7719544617', 't-d1cf43b723', '2026-09-17T12:16:17.275Z', 'Verdict orders executed: coding corr uninformative (jackknife −0.804), reasoning real-but-fragile (−0.905, σ_warm halves spread 0.068 vs 0.133); essay pre-reg + S3/S4 experiment wired; mean+worst-case reframed; absolutes banked (coding offline>static, reasoning static>offline).', 'Statistics corrected; essay decides coherence.', 'leader', 0, '', '{"id": "d-d06ecf8423", "ts": "2026-09-17T12:16:17.275Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Verdict orders executed: coding corr uninformative (jackknife −0.804), reasoning real-but-fragile (−0.905, σ_warm halves spread 0.068 vs 0.133); essay pre-reg + S3/S4 experiment wired; mean+worst-case reframed; absolutes banked (coding offline>static, reasoning static>offline).", "rationale": "Statistics corrected; essay decides coherence.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-10d521756a', 'p-7719544617', 't-d1cf43b723', '2026-09-17T12:42:09.942Z', 'Essay 10/10 complete; scoring + pre-reg extras + 3-leg authoritative headline ordered.', 'Final subject; 3-leg unlocks D1 verdicts.', 'leader', 0, '', '{"id": "d-10d521756a", "ts": "2026-09-17T12:42:09.942Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Essay 10/10 complete; scoring + pre-reg extras + 3-leg authoritative headline ordered.", "rationale": "Final subject; 3-leg unlocks D1 verdicts.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d506eecf87', 'p-7719544617', 't-d1cf43b723', '2026-09-17T12:47:48.559Z', '3-leg COMPLETE (18/18): essay warm never-costs (+.024–+.144); coherence test NEGATIVE (1/6 vs coding 6/6); headline offline−allpool positive 14/18 but small (−.042..+.093). D1 verdict consult fired (build-vs-simplify).', 'Authoritative numbers landed; verdict needs adjudication.', 'leader', 0, '', '{"id": "d-d506eecf87", "ts": "2026-09-17T12:47:48.559Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "3-leg COMPLETE (18/18): essay warm never-costs (+.024–+.144); coherence test NEGATIVE (1/6 vs coding 6/6); headline offline−allpool positive 14/18 but small (−.042..+.093). D1 verdict consult fired (build-vs-simplify).", "rationale": "Authoritative numbers landed; verdict needs adjudication.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-2720fc65be', 'p-7719544617', 't-d1cf43b723', '2026-09-17T12:49:02.409Z', 'D1 BUILD warm+allpool, DROP subject machinery (payoff +2-3% not worth subsystem; threshold would-be +0.08/+6% missed); G3 BUILD (ceiling +28.6%, overhead ≤2%, liveness carried). Path-A build ordered.', 'Headline small (+.02-.04 typical), session effect 3x larger (+.10); essay falsified coherence as pre-reged.', 'leader', 0, '', '{"id": "d-2720fc65be", "ts": "2026-09-17T12:49:02.409Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "D1 BUILD warm+allpool, DROP subject machinery (payoff +2-3% not worth subsystem; threshold would-be +0.08/+6% missed); G3 BUILD (ceiling +28.6%, overhead ≤2%, liveness carried). Path-A build ordered.", "rationale": "Headline small (+.02-.04 typical), session effect 3x larger (+.10); essay falsified coherence as pre-reged.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-56a5664278', 'p-7719544617', 't-d1cf43b723', '2026-09-17T12:55:28.595Z', 'Stage-1 kernel approach = A masked dual-op (worker recommendation; G3 gate adjudicates physics); placement = this worktree submodule (per-action approval stands, dirt rule holds). Q1 answered via permission; Q2 pending worker re-prompt.', 'Gate kills by criterion; rebuild cost unjustified.', 'leader', 0, '', '{"id": "d-56a5664278", "ts": "2026-09-17T12:55:28.595Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Stage-1 kernel approach = A masked dual-op (worker recommendation; G3 gate adjudicates physics); placement = this worktree submodule (per-action approval stands, dirt rule holds). Q1 answered via permission; Q2 pending worker re-prompt.", "rationale": "Gate kills by criterion; rebuild cost unjustified.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d2b8a2d799', 'p-7719544617', 't-d1cf43b723', '2026-09-17T13:22:39.972Z', 'G3 reading rules bound (N=0-armed discriminator; bands ship/iterate-max2/kill; overhead budget 12.7%; monotonicity-void; deploy-ctx + measured-h). Push ordered now per owner.', 'Architect pre-reg; owner push directive.', 'leader', 0, '', '{"id": "d-d2b8a2d799", "ts": "2026-09-17T13:22:39.972Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "G3 reading rules bound (N=0-armed discriminator; bands ship/iterate-max2/kill; overhead budget 12.7%; monotonicity-void; deploy-ctx + measured-h). Push ordered now per owner.", "rationale": "Architect pre-reg; owner push directive.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-dfb6707bc7', 'p-7719544617', 't-d1cf43b723', '2026-09-17T13:26:33.335Z', 'Owner directive 2026-09-17: next fork workstream = port Colibri dashboard observability (Brain page, Atlas labels, measured topic affinity per colibri#175) into baseline-qwen4exp-mtp. Design staged A-E (telemetry -> RPC 0x33/HTTP /experts surface -> per-model experts.json artifact -> Brain page port -> Hydra engine registration per epic/697-final-verify rules), qwen4exp first, arch-agnostic via hparams/t_moe_topk (all MoE archs route through build_moe_ffn). Observability-only: no routing policy change, default-off env-gated (D1 subject-machinery drop stands). Sequenced AFTER in-flight Stage-1 dual-op store lands (same files/env namespace). Design at docs/design-colibri-expert-atlas.md. Open owner questions: UI hosting inside llama-server vs Hydra-side consumer; whether atlas later feeds placement priors.', '3-scout research (Colibri repo a8f2ca62, hydra_vortex epic/697-final-verify, local fork map): fork already has the full id-source + trace + counters + RPC surface; only missing surfaces are expert-state read endpoint, per-model atlas artifact, and UI. Colibri''s route_trace.h engine-id + probe confound protocol adopted as-is.', 'owner-directive', 0, 'ddvnguyen', '{"id": "d-dfb6707bc7", "ts": "2026-09-17T13:26:33.335Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Owner directive 2026-09-17: next fork workstream = port Colibri dashboard observability (Brain page, Atlas labels, measured topic affinity per colibri#175) into baseline-qwen4exp-mtp. Design staged A-E (telemetry -> RPC 0x33/HTTP /experts surface -> per-model experts.json artifact -> Brain page port -> Hydra engine registration per epic/697-final-verify rules), qwen4exp first, arch-agnostic via hparams/t_moe_topk (all MoE archs route through build_moe_ffn). Observability-only: no routing policy change, default-off env-gated (D1 subject-machinery drop stands). Sequenced AFTER in-flight Stage-1 dual-op store lands (same files/env namespace). Design at docs/design-colibri-expert-atlas.md. Open owner questions: UI hosting inside llama-server vs Hydra-side consumer; whether atlas later feeds placement priors.", "rationale": "3-scout research (Colibri repo a8f2ca62, hydra_vortex epic/697-final-verify, local fork map): fork already has the full id-source + trace + counters + RPC surface; only missing surfaces are expert-state read endpoint, per-model atlas artifact, and UI. Colibri''s route_trace.h engine-id + probe confound protocol adopted as-is.", "source": "owner-directive", "irreversible": false, "author": "ddvnguyen"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-717b6a03a2', 'p-7719544617', 't-d1cf43b723', '2026-09-17T13:37:24.230Z', 'leader model override: opencode-go/muse-spark-1.3-contributor', 'Owner-ordered leadership takeover in current live session 623a1037 on baseline-flash-next worktree (user: load current track, be next leader 2026-09-17). Same model as outgoing lead d6cc5704; track goal requires continuing llama.cpp fork for Qwen3.8-Flash-Next on live rig without model switch.', 'owner-directive', 0, '623a1037-b4d7-4186-9795-fa067c87058e', '{"id": "d-717b6a03a2", "ts": "2026-09-17T13:37:24.230Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "leader model override: opencode-go/muse-spark-1.3-contributor", "rationale": "Owner-ordered leadership takeover in current live session 623a1037 on baseline-flash-next worktree (user: load current track, be next leader 2026-09-17). Same model as outgoing lead d6cc5704; track goal requires continuing llama.cpp fork for Qwen3.8-Flash-Next on live rig without model switch.", "source": "owner-directive", "irreversible": false, "author": "623a1037-b4d7-4186-9795-fa067c87058e"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-075e1e3b9c', 'p-7719544617', 't-d1cf43b723', '2026-09-17T13:41:26.864Z', 'Atlas design rulings bound: (1) UI hosted by a SEPARATED service (parent-repo atlas-web/), not inside llama-server — fork ships read-only endpoints (RPC 0x33 EXPERT_META + HTTP GET /experts) and the service aggregates one or many engines (5060Ti/3060/P100) into one cortex view; (2) atlas artifact = TWO separated files: experts.json (observability tier, Colibri Brain schema + spec/reliability/provenance) and expert-ranks.json (ranking tier, per-layer hot-first ordered lists with per-subject scores, contract = exporter maps entries into in-tree pin-file format "L <il> <ids...>"). Design doc updated: docs/design-colibri-expert-atlas.md. Sequencing unchanged: after in-flight Stage-1 dual-op store lands.', 'Owner answers 2026-09-17 on d-dfb6707bc7 open questions. Separated service wins on multi-engine aggregation + minimal fork diff + standalone baseline use; two-file split keeps observability consumer (Brain tooltip) independent from future placement-prior consumer (pin-file exporter).', 'owner-directive', 0, 'ddvnguyen', '{"id": "d-075e1e3b9c", "ts": "2026-09-17T13:41:26.864Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Atlas design rulings bound: (1) UI hosted by a SEPARATED service (parent-repo atlas-web/), not inside llama-server — fork ships read-only endpoints (RPC 0x33 EXPERT_META + HTTP GET /experts) and the service aggregates one or many engines (5060Ti/3060/P100) into one cortex view; (2) atlas artifact = TWO separated files: experts.json (observability tier, Colibri Brain schema + spec/reliability/provenance) and expert-ranks.json (ranking tier, per-layer hot-first ordered lists with per-subject scores, contract = exporter maps entries into in-tree pin-file format \"L <il> <ids...>\"). Design doc updated: docs/design-colibri-expert-atlas.md. Sequencing unchanged: after in-flight Stage-1 dual-op store lands.", "rationale": "Owner answers 2026-09-17 on d-dfb6707bc7 open questions. Separated service wins on multi-engine aggregation + minimal fork diff + standalone baseline use; two-file split keeps observability consumer (Brain tooltip) independent from future placement-prior consumer (pin-file exporter).", "source": "owner-directive", "irreversible": false, "author": "ddvnguyen"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1849d2b80a', 'p-7719544617', 't-d1cf43b723', '2026-09-17T13:46:21.228Z', 'REAP relation bound into design (docs/design-colibri-expert-atlas.md §9): owner directive 2026-09-17 — we adopt REAP-style expert ranking but NEVER remove; lowest tier stays resident at RAM at runtime (cold tier = CPU-executed via existing hybrid cpu-moe split). REAP metric corrected from informal name: S_j = mean over selected tokens of (gate g_j * expert output L2 norm), NO attention term; removal-safety signal, not placement-demand. Evidence: frequency-based pruning collapses Qwen3-30B code-avg 0.470 vs REAP 0.557 @50%. expert-ranks.json carries BOTH scores (route-trace heat + reap_saliency); cold-tier membership = low placement-demand AND low removal-safety (intersection). EAN instrument gap noted: t_moe_topk has ids, gates available, output norms need env-gated reduction in MoE FFN path or REAP observer on HF checkpoint (Qwen3 MoE supported, qwen4exp needs MODEL_ATTRS entry).', 'Scout research of CerebrasResearch/reap (arXiv:2510.13999) + owner framing ''rank like REAP but keep lowest tier at RAM instead of removing''. The two rankings measure different failure modes (quality risk vs speed demand) and the intersection rule prevents both single-signal placement errors; mirrors the #175 complements-vs-substitutes discipline.', 'owner-directive', 0, 'ddvnguyen', '{"id": "d-1849d2b80a", "ts": "2026-09-17T13:46:21.228Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "REAP relation bound into design (docs/design-colibri-expert-atlas.md §9): owner directive 2026-09-17 — we adopt REAP-style expert ranking but NEVER remove; lowest tier stays resident at RAM at runtime (cold tier = CPU-executed via existing hybrid cpu-moe split). REAP metric corrected from informal name: S_j = mean over selected tokens of (gate g_j * expert output L2 norm), NO attention term; removal-safety signal, not placement-demand. Evidence: frequency-based pruning collapses Qwen3-30B code-avg 0.470 vs REAP 0.557 @50%. expert-ranks.json carries BOTH scores (route-trace heat + reap_saliency); cold-tier membership = low placement-demand AND low removal-safety (intersection). EAN instrument gap noted: t_moe_topk has ids, gates available, output norms need env-gated reduction in MoE FFN path or REAP observer on HF checkpoint (Qwen3 MoE supported, qwen4exp needs MODEL_ATTRS entry).", "rationale": "Scout research of CerebrasResearch/reap (arXiv:2510.13999) + owner framing ''rank like REAP but keep lowest tier at RAM instead of removing''. The two rankings measure different failure modes (quality risk vs speed demand) and the intersection rule prevents both single-signal placement errors; mirrors the #175 complements-vs-substitutes discipline.", "source": "owner-directive", "irreversible": false, "author": "ddvnguyen"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f57e5ecb7b', 'p-7719544617', 't-d1cf43b723', '2026-09-17T13:47:45.635Z', 'S2 reports M/X surface at update-window lengths {50,100,200,500}, not just ~500; S1''s answer selects the operative slice. If S2 is far along, it finishes 500 cleanly + short windows as follow-on, and M=0.10/X=10 stays unconfirmed until S1 reports.', 'S1 and S2 share an axis (update-window length vs M/X tuning regime). M/X tuned at 500-token windows may not transfer to the 50-200-token production regime; one extra loop in S2 makes the spikes compose instead of S1 invalidating S2. Sequencing challenge accepted: concurrent dispatch stands.', 'consult', 0, '', '{"id": "d-f57e5ecb7b", "ts": "2026-09-17T13:47:45.635Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "S2 reports M/X surface at update-window lengths {50,100,200,500}, not just ~500; S1''s answer selects the operative slice. If S2 is far along, it finishes 500 cleanly + short windows as follow-on, and M=0.10/X=10 stays unconfirmed until S1 reports.", "rationale": "S1 and S2 share an axis (update-window length vs M/X tuning regime). M/X tuned at 500-token windows may not transfer to the 50-200-token production regime; one extra loop in S2 makes the spikes compose instead of S1 invalidating S2. Sequencing challenge accepted: concurrent dispatch stands.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a0d9c5be99', 'p-7719544617', 't-d1cf43b723', '2026-09-17T13:53:14.729Z', 'Atlas workstream filed: hydra_vortex#771 (parent: decision tracking d-dfb6707bc7/d-075e1e3b9c/d-1849d2b80a + design stages A-E + gated implementation plan S-A1..S-E1) cross-linked with fork tracker ddvnguyen/llama.cpp#133 (C++ side: telemetry, 0x33 EXPERT_META + /experts, probe harness, two-file artifacts, pin-file exporter contract). Labels task+llama-fork+status:planning; fork issue labelled hydra-fork per docs/workflow/08. Epic-branch proposal (epic/{id}-colibri-atlas) pending owner go-ahead per CLAUDE.md large-work rule; Gate 0 = in-flight Stage-1 dual-op store lands first.', 'Owner requested a GitHub issue carrying the decision tracking, detailed design, and implementation plan. Two-repo flow followed: parent issue carries design/decisions/plan, fork issue carries the C++ scope with cross-link both ways.', 'leader', 0, 'ddvnguyen', '{"id": "d-a0d9c5be99", "ts": "2026-09-17T13:53:14.729Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Atlas workstream filed: hydra_vortex#771 (parent: decision tracking d-dfb6707bc7/d-075e1e3b9c/d-1849d2b80a + design stages A-E + gated implementation plan S-A1..S-E1) cross-linked with fork tracker ddvnguyen/llama.cpp#133 (C++ side: telemetry, 0x33 EXPERT_META + /experts, probe harness, two-file artifacts, pin-file exporter contract). Labels task+llama-fork+status:planning; fork issue labelled hydra-fork per docs/workflow/08. Epic-branch proposal (epic/{id}-colibri-atlas) pending owner go-ahead per CLAUDE.md large-work rule; Gate 0 = in-flight Stage-1 dual-op store lands first.", "rationale": "Owner requested a GitHub issue carrying the decision tracking, detailed design, and implementation plan. Two-repo flow followed: parent issue carries design/decisions/plan, fork issue carries the C++ scope with cross-link both ways.", "source": "leader", "irreversible": false, "author": "ddvnguyen"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-caa66e04b8', 'p-7719544617', 't-d1cf43b723', '2026-09-17T14:08:01.044Z', 'S2 CONFIRMED + S5 SHIP: S2 swept M×X×L (48 cells, 18 v4 windows + 19 v2 traces, N=38 k=10, eval decode[100,200)): flat plateau in M/X, structure only on L. S1''s landed 200-300-token regime selects the L=200 slice where M=0.10/X=10 (0.3424) sits -0.3pp off cell max (0.3454) — Stage-1 build constants VALIDATED, no move. S5 disjoint-half rebuild: Jaccard median 0.671 (48/48 layers >0.5), out-of-sample h deltas +0.9pp/-2.0pp (~1.2M slots each) — ranking stable, SHIP current allpool as-is, no more collection for the static pin set. Artifacts: /tmp/opencode/sweep_mx.py+sweep_mx.json, /tmp/opencode/s5-allpool-stability/. Throwaway scripts, nothing in repo.', '', 'leader', 0, '', '{"id": "d-caa66e04b8", "ts": "2026-09-17T14:08:01.044Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "S2 CONFIRMED + S5 SHIP: S2 swept M×X×L (48 cells, 18 v4 windows + 19 v2 traces, N=38 k=10, eval decode[100,200)): flat plateau in M/X, structure only on L. S1''s landed 200-300-token regime selects the L=200 slice where M=0.10/X=10 (0.3424) sits -0.3pp off cell max (0.3454) — Stage-1 build constants VALIDATED, no move. S5 disjoint-half rebuild: Jaccard median 0.671 (48/48 layers >0.5), out-of-sample h deltas +0.9pp/-2.0pp (~1.2M slots each) — ranking stable, SHIP current allpool as-is, no more collection for the static pin set. Artifacts: /tmp/opencode/sweep_mx.py+sweep_mx.json, /tmp/opencode/s5-allpool-stability/. Throwaway scripts, nothing in repo.", "rationale": "", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-bb1b5c3ca7', 'p-7719544617', 't-d1cf43b723', '2026-09-17T14:31:21.194Z', 'Consult verdict on d-caa66e04b8 (agent 4adb83c1, deepseek-v4.1-flash): (1) S2 hold CONFIRMED — M=0.10/X=10 justified as churn/h trade (true max M=0.05/X=10 +0.30pp costs 284 vs 252 swaps); amend ''flat in M/X'' claim to L<=200 only (X binds at L=500, +2.3pp); production 50-200 turns need S1 accumulation gate ~200-300 tokens, not re-tune; refitting lone short turn actively harmful. (2) S5 CHALLENGED in part — B->A -2.01pp CI[-3.28,-0.86] is significant half-composition sensitivity, not noise (A->B +0.91pp CI includes 0, is noise); ship union full-pool as-is stands, but ''no more collection'' WITHDRAWN — run >=2 disjoint splits (CPU-only) before claiming convergence. (3) Stage-1 proceed CONFIRMED — build does not depend on traces (atlas reads Stage-1 shapes after); serialize file edits (Stage-1 lands llama-context/route_trace hunks first, traces rebase onto it); owner pre-clearance only needed if wire protocol/schema touched; surface V4 H5 canonical call (200 vs 100) before Stage-1 numbers feed G3 gate.', '', 'consult', 0, '', '{"id": "d-bb1b5c3ca7", "ts": "2026-09-17T14:31:21.194Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Consult verdict on d-caa66e04b8 (agent 4adb83c1, deepseek-v4.1-flash): (1) S2 hold CONFIRMED — M=0.10/X=10 justified as churn/h trade (true max M=0.05/X=10 +0.30pp costs 284 vs 252 swaps); amend ''flat in M/X'' claim to L<=200 only (X binds at L=500, +2.3pp); production 50-200 turns need S1 accumulation gate ~200-300 tokens, not re-tune; refitting lone short turn actively harmful. (2) S5 CHALLENGED in part — B->A -2.01pp CI[-3.28,-0.86] is significant half-composition sensitivity, not noise (A->B +0.91pp CI includes 0, is noise); ship union full-pool as-is stands, but ''no more collection'' WITHDRAWN — run >=2 disjoint splits (CPU-only) before claiming convergence. (3) Stage-1 proceed CONFIRMED — build does not depend on traces (atlas reads Stage-1 shapes after); serialize file edits (Stage-1 lands llama-context/route_trace hunks first, traces rebase onto it); owner pre-clearance only needed if wire protocol/schema touched; surface V4 H5 canonical call (200 vs 100) before Stage-1 numbers feed G3 gate.", "rationale": "", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-eb232207d5', 'p-7719544617', 't-d1cf43b723', '2026-09-17T14:33:06.627Z', 'Architect verdict (2731baf3, authoritative; supersedes d-bb1b5c3ca7 where they differ): (1) S2 hold CONFIRMED, rationale corrected — +0.30pp inside sweep ±0.5pp resolution so unresolvable, NOT a churn/h trade (swaps overlapped into prefill ~free; 0.30pp = +0.2% tput). ''Flat for L<=200'' amendment load-bearing: X=10 binds at L=500, revisit X if S1 regime moves up. (2) S5 challenge CONFIRMED and strengthened — composition sensitivity real but -2.01pp ≈ -1.3% tput = monitor item; S5b must NOT gate Stage-1; extra splits STRATIFIED (subject, length tier, random), not random. (3) Stage-1 proceed CONFIRMED — POC already owner-authorized, no pre-clearance needed; added hard gate: measured-h-reported-alongside-S capability confirmed BEFORE G3 runs (the ''ran before it could measure'' failure voided 3 prior runs); V4 H5 canonical (200 vs 100) must be stated explicitly, architect could not verify reference from pack.', '', 'consult', 0, '', '{"id": "d-eb232207d5", "ts": "2026-09-17T14:33:06.627Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect verdict (2731baf3, authoritative; supersedes d-bb1b5c3ca7 where they differ): (1) S2 hold CONFIRMED, rationale corrected — +0.30pp inside sweep ±0.5pp resolution so unresolvable, NOT a churn/h trade (swaps overlapped into prefill ~free; 0.30pp = +0.2% tput). ''Flat for L<=200'' amendment load-bearing: X=10 binds at L=500, revisit X if S1 regime moves up. (2) S5 challenge CONFIRMED and strengthened — composition sensitivity real but -2.01pp ≈ -1.3% tput = monitor item; S5b must NOT gate Stage-1; extra splits STRATIFIED (subject, length tier, random), not random. (3) Stage-1 proceed CONFIRMED — POC already owner-authorized, no pre-clearance needed; added hard gate: measured-h-reported-alongside-S capability confirmed BEFORE G3 runs (the ''ran before it could measure'' failure voided 3 prior runs); V4 H5 canonical (200 vs 100) must be stated explicitly, architect could not verify reference from pack.", "rationale": "", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-75e70849b4', 'p-7719544617', 't-d1cf43b723', '2026-09-17T14:39:05.124Z', 'Re-sequencing per owner: fork-side stages (A/B/C engine bits) blocked behind in-flight Stage-1 dual-op store (Gate 0 unchanged); Colibri side STARTS FIRST fully offline in the parent repo: (1) tools/atlas/ pipeline porting Colibri analyze.py/validate.py onto existing trace corpus (/tmp/opencode/cnre-phase0/traces, TRACE_SPEC format) reusing phase0_rank.py machinery, acceptance = reproduce phase0_rank.json (d-bb2f0d3b29), emitting draft experts.json + expert-ranks.json for qwen4exp with reap_saliency reserved + pin-file exporter; (2) atlas-web scaffold with mock Stage B adapter. Worker dispatched for item 1. When task-4e0493edd2 multi-prompt collection completes, its traces upgrade the draft atlas.', 'Owner directive: a track is already working the llama fork (Stage-1 dirt in flight), so start at the Colibri part. Offline pipeline needs zero GPU and zero fork surface; existing traces + scorer already in /tmp/opencode.', 'owner-directive', 0, 'ddvnguyen', '{"id": "d-75e70849b4", "ts": "2026-09-17T14:39:05.124Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Re-sequencing per owner: fork-side stages (A/B/C engine bits) blocked behind in-flight Stage-1 dual-op store (Gate 0 unchanged); Colibri side STARTS FIRST fully offline in the parent repo: (1) tools/atlas/ pipeline porting Colibri analyze.py/validate.py onto existing trace corpus (/tmp/opencode/cnre-phase0/traces, TRACE_SPEC format) reusing phase0_rank.py machinery, acceptance = reproduce phase0_rank.json (d-bb2f0d3b29), emitting draft experts.json + expert-ranks.json for qwen4exp with reap_saliency reserved + pin-file exporter; (2) atlas-web scaffold with mock Stage B adapter. Worker dispatched for item 1. When task-4e0493edd2 multi-prompt collection completes, its traces upgrade the draft atlas.", "rationale": "Owner directive: a track is already working the llama fork (Stage-1 dirt in flight), so start at the Colibri part. Offline pipeline needs zero GPU and zero fork surface; existing traces + scorer already in /tmp/opencode.", "source": "owner-directive", "irreversible": false, "author": "ddvnguyen"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1658b58d60', 'p-7719544617', 't-d1cf43b723', '2026-09-17T14:42:30.902Z', 'S5b ACCEPTED (worker 829653e6, done): 4 stratified splits isolate the composition effect — length-tier split (16 short vs 35 long) collapses Jaccard to 0.462 with -4.5pp short-trained-on-long penalty, while long-trained transfers to short within noise; balanced splits symmetric at ~1pp floor vs full-pool-on-same-half. S5''s -2.0pp was eval-half difficulty + short-on-long, not pin instability. Verdict: monitor only (~-0.8% scale worst balanced), NO Stage-1 impact, no more collection. Artifacts /tmp/opencode/s5b-splits/ (s5b_splits.py, s5b_fullrel.py, results JSONs, REPORT.md). Caveat: turn-level bootstrap (CIs are lower bounds; session-level would widen).', '', 'leader', 0, '', '{"id": "d-1658b58d60", "ts": "2026-09-17T14:42:30.902Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "S5b ACCEPTED (worker 829653e6, done): 4 stratified splits isolate the composition effect — length-tier split (16 short vs 35 long) collapses Jaccard to 0.462 with -4.5pp short-trained-on-long penalty, while long-trained transfers to short within noise; balanced splits symmetric at ~1pp floor vs full-pool-on-same-half. S5''s -2.0pp was eval-half difficulty + short-on-long, not pin instability. Verdict: monitor only (~-0.8% scale worst balanced), NO Stage-1 impact, no more collection. Artifacts /tmp/opencode/s5b-splits/ (s5b_splits.py, s5b_fullrel.py, results JSONs, REPORT.md). Caveat: turn-level bootstrap (CIs are lower bounds; session-level would widen).", "rationale": "", "source": "leader", "irreversible": false, "author": ""}');
