INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-3f245ba4b7', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-17T14:46:54.502Z', '[carryover d-075e1e3b9c] UI hosted by a separated service (atlas-web/, parent repo), not inside llama-server — aggregates one or many engines into one cortex view; fork ships read-only endpoints only. Atlas = two separated files: experts.json (observability tier, Colibri Brain schema) + expert-ranks.json (ranking tier; exporter contract = in-tree pin-file format "L <il> <ids...>")', 'hydra_vortex#771 section 2', 'leader', 0, 'issue #771', '{"id": "d-3f245ba4b7", "ts": "2026-09-17T14:46:54.502Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[carryover d-075e1e3b9c] UI hosted by a separated service (atlas-web/, parent repo), not inside llama-server — aggregates one or many engines into one cortex view; fork ships read-only endpoints only. Atlas = two separated files: experts.json (observability tier, Colibri Brain schema) + expert-ranks.json (ranking tier; exporter contract = in-tree pin-file format \"L <il> <ids...>\")", "rationale": "hydra_vortex#771 section 2", "source": "leader", "irreversible": false, "author": "issue #771"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a20cf7cec0', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-17T14:46:54.520Z', '[carryover d-1849d2b80a] REAP bound into design: expert-ranks.json carries BOTH scores (route-trace heat + reap_saliency); cold-tier membership = low placement-demand AND low removal-safety (intersection); saliency S_j = mean over selected tokens of (gate g_j(x) * ||f_j(x)||2) — no attention term; frequency-based removal must not be conflated with placement-demand ranking', 'hydra_vortex#771 section 2; REAP arXiv:2510.13999', 'leader', 0, 'issue #771', '{"id": "d-a20cf7cec0", "ts": "2026-09-17T14:46:54.520Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[carryover d-1849d2b80a] REAP bound into design: expert-ranks.json carries BOTH scores (route-trace heat + reap_saliency); cold-tier membership = low placement-demand AND low removal-safety (intersection); saliency S_j = mean over selected tokens of (gate g_j(x) * ||f_j(x)||2) — no attention term; frequency-based removal must not be conflated with placement-demand ranking", "rationale": "hydra_vortex#771 section 2; REAP arXiv:2510.13999", "source": "leader", "irreversible": false, "author": "issue #771"}');
