INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1190aaa96d', 'p-7719544617', 't-d1cf43b723', '2026-09-17T15:56:48.266Z', 'Architect cross-build-null flag ADOPTED (session 2731baf3): same-binary KLD null (median 0) cannot band a different-binary candidate — false failures on benign kernel/dispatch differences (sha-gate error class, one level up). FIX: null_2 = A vs A_armed_N0 (apparatus compiled+firing, admitting nothing; semantically identical, carries real cross-build FP variation) becomes the BAND-SETTING null; null_1 (A vs A'') kept as sanity reference only; candidate A vs A_armed_N38 scored vs null_2. If null_2 ~= null_1, proof gained for free. Cost: one already-needed N=0 build + one KLD run. BAND SETTING BLOCKED until null_2 lands. Steered to builder; reply ADOPTED.', '', 'consult', 0, '', '{"id": "d-1190aaa96d", "ts": "2026-09-17T15:56:48.266Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Architect cross-build-null flag ADOPTED (session 2731baf3): same-binary KLD null (median 0) cannot band a different-binary candidate — false failures on benign kernel/dispatch differences (sha-gate error class, one level up). FIX: null_2 = A vs A_armed_N0 (apparatus compiled+firing, admitting nothing; semantically identical, carries real cross-build FP variation) becomes the BAND-SETTING null; null_1 (A vs A'') kept as sanity reference only; candidate A vs A_armed_N38 scored vs null_2. If null_2 ~= null_1, proof gained for free. Cost: one already-needed N=0 build + one KLD run. BAND SETTING BLOCKED until null_2 lands. Steered to builder; reply ADOPTED.", "rationale": "", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-ef9e17fb53', 'p-7719544617', 't-d1cf43b723', '2026-09-17T16:06:27.932Z', '3060 stock control BANKED (builder 2ac20e22): A_3060base fused dual-OFF prompt767 200tok => tg=14.53, pp=86.1 (vs 5060Ti fused 17.87 = 0.81x). Full offload fits 12GB, clean exit. All future 3060-comparison work measures against 14.53. VRAM-under-load missed (14s window vs 60s poll grid) — recapture with <=5s polling next leg. DESIGN IMPACT: decode MoE dispatch runs MMQ path (mmvq=0, mmq=987) — Phase-B kernel surgery must cover MMQ helper path; KL bar covers it. No improvement leg run or implied (dual-op ON parked behind null_2).', '', 'leader', 0, '', '{"id": "d-ef9e17fb53", "ts": "2026-09-17T16:06:27.932Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "3060 stock control BANKED (builder 2ac20e22): A_3060base fused dual-OFF prompt767 200tok => tg=14.53, pp=86.1 (vs 5060Ti fused 17.87 = 0.81x). Full offload fits 12GB, clean exit. All future 3060-comparison work measures against 14.53. VRAM-under-load missed (14s window vs 60s poll grid) — recapture with <=5s polling next leg. DESIGN IMPACT: decode MoE dispatch runs MMQ path (mmvq=0, mmq=987) — Phase-B kernel surgery must cover MMQ helper path; KL bar covers it. No improvement leg run or implied (dual-op ON parked behind null_2).", "rationale": "", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0a8f0b229e', 'p-7719544617', 't-d1cf43b723', '2026-09-17T16:21:22.398Z', 'Owner directive (standing rule): every custom mechanism added by this track must sit behind a param/flag/env config, default OFF, so it can be turned off when not needed. Applies to all Stage-1 hunks (store manager, counters, graph branch, N=0 discriminator, Phase-B skip incl. MMQ path) and any future work. Builder to audit current diff for bare (ungated) custom paths and gate them; byte-identical-OFF is the acceptance bar.', '', 'owner-directive', 0, '', '{"id": "d-0a8f0b229e", "ts": "2026-09-17T16:21:22.398Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Owner directive (standing rule): every custom mechanism added by this track must sit behind a param/flag/env config, default OFF, so it can be turned off when not needed. Applies to all Stage-1 hunks (store manager, counters, graph branch, N=0 discriminator, Phase-B skip incl. MMQ path) and any future work. Builder to audit current diff for bare (ungated) custom paths and gate them; byte-identical-OFF is the acceptance bar.", "rationale": "", "source": "owner-directive", "irreversible": false, "author": ""}');
