INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-cb784a9d9d', 'p-7719544617', 't-d1cf43b723', '2026-09-17T17:11:25.011Z', 'KLD-SERIES-DONE confirmed (builder): null_1 x3 zero spread (mean 0, max 5.3e-5, 99th 3.8e-5, median 0, same-top-p 100%); base 10 chunks PPL 16.18 complete. Clean rebuild-verify bit-identical to Q0 (449 units EXIT=0; Q0 saved aside with md5) — doubles as ladder rung 1. Builder''s claimed architect-blocker is STALE: 9b fix (add n_tokens==1), coupling hard-fail, and GAP deferrals were all ruled in d-0fb2d12ba8 + d-011dd7daf4. GO issued for step 2 (9b + coupling only; GAPs deferred).', '', 'leader', 0, '', '{"id": "d-cb784a9d9d", "ts": "2026-09-17T17:11:25.011Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "KLD-SERIES-DONE confirmed (builder): null_1 x3 zero spread (mean 0, max 5.3e-5, 99th 3.8e-5, median 0, same-top-p 100%); base 10 chunks PPL 16.18 complete. Clean rebuild-verify bit-identical to Q0 (449 units EXIT=0; Q0 saved aside with md5) — doubles as ladder rung 1. Builder''s claimed architect-blocker is STALE: 9b fix (add n_tokens==1), coupling hard-fail, and GAP deferrals were all ruled in d-0fb2d12ba8 + d-011dd7daf4. GO issued for step 2 (9b + coupling only; GAPs deferred).", "rationale": "", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e8a89d0025', 'p-7719544617', 't-d1cf43b723', '2026-09-17T17:13:03.459Z', 'SECTION 12 — architect 4-item adjudication. (A) Discriminator CONFIRM from source: sites llama-graph 2225/2251/2274/2383 all n_tokens-gated; site1 inside if(gate_up_exps), GGUF has separate tensors so block skipped — fire=[0,98,98,98] exactly predicted. GAP-1 innocent, series stands. CORRECTION 1: fallback citation is :2246 else-branch, NOT :3245 (build_attn)/model:3243 — fix bank. CORRECTION 2: 98!=96 residue unexplained; do NOT close 9a on rounding — require Q1 per-layer dump, name the 2, then close. Bonus: all graph sites gated confirms 9b is a real separate-path defect. (B) 9b FORCES null_2 re-run (armed binary changes; null_2 measures armed floor); null_1 unaffected, do not re-run. Queue order confirmed. (C) 10a CORRECTION (architect''s own error): +0.004 was per-layer-N ALLOCATION delta; RANKING headroom is +0.042 subject / +0.120 oracle (+7.6% decode). 10a amended: allocation stops consuming attention, ranking keeps headroom; session-warm mandate UNCHANGED. ReAP: (1) saliency worth testing only as RIDER on emitter widening (needs gate weights our emitter binarises away); do not reprioritise. (2) Irreducibility = background except CLOSES approximate-residency door (experts not substitutable) — record closed. (3) Keep KLD, reject their harness (engine change needs numeric instrument, not task-quality; vLLM stack we don''t run). (D) HELPER ADMITTED: cross divergence = same-GPU floor (2/38), zero added noise. Gates: (a) same-GPU-duplicate control per batch; (b) pin Jaccard vs control with every h; (c) running gate: cross > 2x same-GPU => stop+escalate. Tolerance math: 2-pin flip ~= 0.001-0.002h, 10-50x below 0.02-0.05 effects — holds. Mechanism: 51% = sampled-trajectory divergence; FIX THE SEQUENCE (teacher-forced/fixed tokens, as KLD does) for all helper collection; non-collapse under fixed sequence = escalate. Owner signs 2/38 tolerance + 3 gates.', '', 'consult', 0, '', '{"id": "d-e8a89d0025", "ts": "2026-09-17T17:13:03.459Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "SECTION 12 — architect 4-item adjudication. (A) Discriminator CONFIRM from source: sites llama-graph 2225/2251/2274/2383 all n_tokens-gated; site1 inside if(gate_up_exps), GGUF has separate tensors so block skipped — fire=[0,98,98,98] exactly predicted. GAP-1 innocent, series stands. CORRECTION 1: fallback citation is :2246 else-branch, NOT :3245 (build_attn)/model:3243 — fix bank. CORRECTION 2: 98!=96 residue unexplained; do NOT close 9a on rounding — require Q1 per-layer dump, name the 2, then close. Bonus: all graph sites gated confirms 9b is a real separate-path defect. (B) 9b FORCES null_2 re-run (armed binary changes; null_2 measures armed floor); null_1 unaffected, do not re-run. Queue order confirmed. (C) 10a CORRECTION (architect''s own error): +0.004 was per-layer-N ALLOCATION delta; RANKING headroom is +0.042 subject / +0.120 oracle (+7.6% decode). 10a amended: allocation stops consuming attention, ranking keeps headroom; session-warm mandate UNCHANGED. ReAP: (1) saliency worth testing only as RIDER on emitter widening (needs gate weights our emitter binarises away); do not reprioritise. (2) Irreducibility = background except CLOSES approximate-residency door (experts not substitutable) — record closed. (3) Keep KLD, reject their harness (engine change needs numeric instrument, not task-quality; vLLM stack we don''t run). (D) HELPER ADMITTED: cross divergence = same-GPU floor (2/38), zero added noise. Gates: (a) same-GPU-duplicate control per batch; (b) pin Jaccard vs control with every h; (c) running gate: cross > 2x same-GPU => stop+escalate. Tolerance math: 2-pin flip ~= 0.001-0.002h, 10-50x below 0.02-0.05 effects — holds. Mechanism: 51% = sampled-trajectory divergence; FIX THE SEQUENCE (teacher-forced/fixed tokens, as KLD does) for all helper collection; non-collapse under fixed sequence = escalate. Owner signs 2/38 tolerance + 3 gates.", "rationale": "", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-4b84f5d1d6', 'p-7719544617', 't-d1cf43b723', '2026-09-17T17:18:58.205Z', '8 v2 SHORT re-author drafts COMPLETE (fresh dev, d-e122f322ba): docs/evidence/reap-redraft/ — 8 texts + REDRAFT.md (provenance, manifest, pack recipe). Staged, no commit. ReAP survey: MoT-code + SWE-smith suitable (used c13/c19/c17), evol-codealpaca marginal (unused), xlam 401-excluded, quality-script absent-moot. Forced fits refused where unreal (rust/go/ts = c14-shape, labeled exactly). All UNVERIFIED — first decode adjudicates. OPEN CALL for owner review: new L drafts ~3.0k tok vs mates ~2.5k break the 92% pair-parity rule — accept asymmetry vs stretch mates. Dev note: filler-tail padding weakest lines, trimmable at pack time (recompute sha12).', '', 'leader', 0, '', '{"id": "d-4b84f5d1d6", "ts": "2026-09-17T17:18:58.205Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "8 v2 SHORT re-author drafts COMPLETE (fresh dev, d-e122f322ba): docs/evidence/reap-redraft/ — 8 texts + REDRAFT.md (provenance, manifest, pack recipe). Staged, no commit. ReAP survey: MoT-code + SWE-smith suitable (used c13/c19/c17), evol-codealpaca marginal (unused), xlam 401-excluded, quality-script absent-moot. Forced fits refused where unreal (rust/go/ts = c14-shape, labeled exactly). All UNVERIFIED — first decode adjudicates. OPEN CALL for owner review: new L drafts ~3.0k tok vs mates ~2.5k break the 92% pair-parity rule — accept asymmetry vs stretch mates. Dev note: filler-tail padding weakest lines, trimmable at pack time (recompute sha12).", "rationale": "", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b9cd48f3bf', 'p-7719544617', 't-d1cf43b723', '2026-09-17T17:39:34.236Z', 'c14 pair QUARANTINED (collector): tokens diverge @ byte 621 (same facts, different phrasing) — decode-window numbers void, prefill rows usable. Jaccard passes (train 0.90/0.90) but void for decode — gate alone insufficient, fixed-sequence mechanism required. TOOL GAP: llama-route-trace has NO teacher-force/replay flag; fixed-sequence needs a tool patch (KLD server token-id path = template). Architect to spec, builder to implement after step 2. CONTENTION: collector CVD=1 leg killed builder''s 00:36 Q1_negativetest server (mutual overlap; both gates passed at launch) — builder reruns that leg, not a real failure. Standing hole: pgrep polling can''t close mid-leg overlap; rig lockfile/heartbeat needed (no owner spend — builder-owned fix).', '', 'leader', 0, '', '{"id": "d-b9cd48f3bf", "ts": "2026-09-17T17:39:34.236Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "c14 pair QUARANTINED (collector): tokens diverge @ byte 621 (same facts, different phrasing) — decode-window numbers void, prefill rows usable. Jaccard passes (train 0.90/0.90) but void for decode — gate alone insufficient, fixed-sequence mechanism required. TOOL GAP: llama-route-trace has NO teacher-force/replay flag; fixed-sequence needs a tool patch (KLD server token-id path = template). Architect to spec, builder to implement after step 2. CONTENTION: collector CVD=1 leg killed builder''s 00:36 Q1_negativetest server (mutual overlap; both gates passed at launch) — builder reruns that leg, not a real failure. Standing hole: pgrep polling can''t close mid-leg overlap; rig lockfile/heartbeat needed (no owner spend — builder-owned fix).", "rationale": "", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-5411fdf0fd', 'p-7719544617', 't-d1cf43b723', '2026-09-17T17:41:35.713Z', 'SECTION 13 — teacher-force patch spec (architect, source-read from 75c879787; tool ABSENT from HEAD 86af0c9af, restore as tracked commit per 11c-note). 13a: divergence = greedy argmax loop flips on sub-ULP logit diff; prompt region safe (deterministic CPU), only continuation forced. 13b: two env vars default-OFF (LLAMA_ROUTE_TOKENS emit ids in decode_one; LLAMA_ROUTE_FORCE consume continuation ids, n_gen from forced.size()). 13c LOAD-BEARING: one token per llama_decode + assert batch.n_tokens==1 — batching forced tokens takes PREFILL path, admission sites never fire (G3 0/0 in new hat). 13d: satisfies flag bar (OFF path = original + one if; graph provably unchanged, logits readback omission only). 13e acceptance: OFF byte-identical; ON identical by construction; expect 51%->FP floor; FAILURE PRE-REGISTERED: >10% under forced sequence = genuinely nondeterministic routing, escalate, undermines all h; force-file sha in sidecar. 13f: 3060 free-run emits, replay both GPUs. Forwarded to builder (after step 2).', '', 'consult', 0, '', '{"id": "d-5411fdf0fd", "ts": "2026-09-17T17:41:35.713Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "SECTION 13 — teacher-force patch spec (architect, source-read from 75c879787; tool ABSENT from HEAD 86af0c9af, restore as tracked commit per 11c-note). 13a: divergence = greedy argmax loop flips on sub-ULP logit diff; prompt region safe (deterministic CPU), only continuation forced. 13b: two env vars default-OFF (LLAMA_ROUTE_TOKENS emit ids in decode_one; LLAMA_ROUTE_FORCE consume continuation ids, n_gen from forced.size()). 13c LOAD-BEARING: one token per llama_decode + assert batch.n_tokens==1 — batching forced tokens takes PREFILL path, admission sites never fire (G3 0/0 in new hat). 13d: satisfies flag bar (OFF path = original + one if; graph provably unchanged, logits readback omission only). 13e acceptance: OFF byte-identical; ON identical by construction; expect 51%->FP floor; FAILURE PRE-REGISTERED: >10% under forced sequence = genuinely nondeterministic routing, escalate, undermines all h; force-file sha in sidecar. 13f: 3060 free-run emits, replay both GPUs. Forwarded to builder (after step 2).", "rationale": "", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e4d761e21d', 'p-7719544617', 't-d1cf43b723', '2026-09-18T00:12:43.661Z', 'Stage-1 masked dual-op ON-path divergence methodology: token-signature match + EXACT PPL equality (same-binary, same-session) is sufficient; no KLD/logit-diff required. Requires >=3 steady-state legs (token-sig identical across all 3, PPL exact ON==OFF) PLUS one boundary-condition sequence at mask/tile-block split edge. All green = clear ON path without sha-gate. Any leg diverges = real divergence point, escalate before merging, never average/waive.', 'Sha-gate void on nondeterministic rig; Phase-B kernel skip already approved as correctness vehicle (PPL + greedy, no perf claim). Gap is sample coverage, not metric strength. Extends Combine S1+S2 precedent (3-leg OFF byte-identity: token-sig identical, PPL 31.7412 exact) with one addition: mask-boundary sequence, because Stage-1 is a mask-boundary op, not a toggle.', 'consult', 0, 'architect (consult ee8bb034, claude-sonnet-5)', '{"id": "d-e4d761e21d", "ts": "2026-09-18T00:12:43.661Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Stage-1 masked dual-op ON-path divergence methodology: token-signature match + EXACT PPL equality (same-binary, same-session) is sufficient; no KLD/logit-diff required. Requires >=3 steady-state legs (token-sig identical across all 3, PPL exact ON==OFF) PLUS one boundary-condition sequence at mask/tile-block split edge. All green = clear ON path without sha-gate. Any leg diverges = real divergence point, escalate before merging, never average/waive.", "rationale": "Sha-gate void on nondeterministic rig; Phase-B kernel skip already approved as correctness vehicle (PPL + greedy, no perf claim). Gap is sample coverage, not metric strength. Extends Combine S1+S2 precedent (3-leg OFF byte-identity: token-sig identical, PPL 31.7412 exact) with one addition: mask-boundary sequence, because Stage-1 is a mask-boundary op, not a toggle.", "source": "consult", "irreversible": false, "author": "architect (consult ee8bb034, claude-sonnet-5)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-37c2cfdfb6', 'p-7719544617', 't-d1cf43b723', '2026-09-18T00:16:44.757Z', 'Stalled-leg escalation rule: any running leg with no progress update or yield for >2h gets polled by the leader; no credible ETA/blocker within one tick = escalate to owner with facts. In-flight legs must report rate (units/hour) and ETA, not just percent. Triggered by task-4e0493edd2 sitting at 50% ~9h unflagged.', 'Owner caught a 9h stall the leader never flagged. Percent-without-rate hides stalls; polling in-flight legs each checkup and escalating past 2h closes that gap.', 'leader', 0, '', '{"id": "d-37c2cfdfb6", "ts": "2026-09-18T00:16:44.757Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Stalled-leg escalation rule: any running leg with no progress update or yield for >2h gets polled by the leader; no credible ETA/blocker within one tick = escalate to owner with facts. In-flight legs must report rate (units/hour) and ETA, not just percent. Triggered by task-4e0493edd2 sitting at 50% ~9h unflagged.", "rationale": "Owner caught a 9h stall the leader never flagged. Percent-without-rate hides stalls; polling in-flight legs each checkup and escalating past 2h closes that gap.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b6923b9e07', 'p-7719544617', 't-d1cf43b723', '2026-09-18T00:18:26.788Z', '8 SHORT re-authors SAFE only as 1-for-1 slot replacement (same bucket+subtype, >=20/>=20 preserved); length from task complexity, never instruction-forced padding; immediate-EOS loss flagged as corpus-shape deviation; subject-pool dedup vs accepted 36; inherits UNVERIFIED gate (owner review + pair-parity + sha256 pins in REDRAFT.md). Teacher-force patch confirmed prerequisite for HELPER decode windows; also blocking: 10c precondition unsatisfied (artifacts gone, redo ~15min), 13f sequencing (TARGET free-run reference before HELPER replay), patch lands after TARGET-lane step 2, byte-identical-OFF reverification (13d/9h) required, evidence discipline (9f/11c).', 'Padding biases the length-correlated h statistic; slot replacement preserves spec balance; EOS removal changes corpus shape vs real traffic and must be declared. Helper comparison needs fixed continuation (13a/12h) or divergence is confounded by argmax sub-ULP nondeterminism.', 'consult', 0, 'architect (consult 46bd027b, claude-sonnet-5)', '{"id": "d-b6923b9e07", "ts": "2026-09-18T00:18:26.788Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "8 SHORT re-authors SAFE only as 1-for-1 slot replacement (same bucket+subtype, >=20/>=20 preserved); length from task complexity, never instruction-forced padding; immediate-EOS loss flagged as corpus-shape deviation; subject-pool dedup vs accepted 36; inherits UNVERIFIED gate (owner review + pair-parity + sha256 pins in REDRAFT.md). Teacher-force patch confirmed prerequisite for HELPER decode windows; also blocking: 10c precondition unsatisfied (artifacts gone, redo ~15min), 13f sequencing (TARGET free-run reference before HELPER replay), patch lands after TARGET-lane step 2, byte-identical-OFF reverification (13d/9h) required, evidence discipline (9f/11c).", "rationale": "Padding biases the length-correlated h statistic; slot replacement preserves spec balance; EOS removal changes corpus shape vs real traffic and must be declared. Helper comparison needs fixed continuation (13a/12h) or divergence is confounded by argmax sub-ULP nondeterminism.", "source": "consult", "irreversible": false, "author": "architect (consult 46bd027b, claude-sonnet-5)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d5acf4302d', 'p-7719544617', 't-d1cf43b723', '2026-09-18T00:23:18.495Z', 'A: CONFIRM >=3 legs + boundary sequence + escalate-never-average; REJECT ''no KLD'' — token-sig+PPL are necessary cheap screens, KLD is the BINDING distributional backstop vs null ladder (null razor-thin: mean 1e-6, 99th 4.3e-5). BLOCKING: builder must state whether Stage-1 flag is mid-session togglable (a: exact equality achievable, stronger than KLD) or not (b: same-session premise void) BEFORE pre-registering. Boundary spec tightened: lengths at tile-multiple/-1/+1 for actual MMQ tile width read from kernel; N-dim boundaries explicitly excluded (owner-parked 38-42). B: CONFIRM re-author constraints + helper chain + 10c redo. BLOCKING: diagnose systematic EOS cause on ONE prompt (verify rendered token sequence, CPU-side) before any re-author. Re-authors validated n_gen>=threshold before corpus admission. Supersedes d-e4d761e21d (KLD subtraction rejected) and extends d-b6923b9e07.', 'Aggregates (token-sig, PPL) average away small localized defects; KLD ladder built for exactly that and costs nothing (instrument exists, in-run). 8 deterministic EOS is a pattern — systematic template/EOS/role cause must be excluded before burning 8 slots. Same-session premise fails for startup-read env flags.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-d5acf4302d", "ts": "2026-09-18T00:23:18.495Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "A: CONFIRM >=3 legs + boundary sequence + escalate-never-average; REJECT ''no KLD'' — token-sig+PPL are necessary cheap screens, KLD is the BINDING distributional backstop vs null ladder (null razor-thin: mean 1e-6, 99th 4.3e-5). BLOCKING: builder must state whether Stage-1 flag is mid-session togglable (a: exact equality achievable, stronger than KLD) or not (b: same-session premise void) BEFORE pre-registering. Boundary spec tightened: lengths at tile-multiple/-1/+1 for actual MMQ tile width read from kernel; N-dim boundaries explicitly excluded (owner-parked 38-42). B: CONFIRM re-author constraints + helper chain + 10c redo. BLOCKING: diagnose systematic EOS cause on ONE prompt (verify rendered token sequence, CPU-side) before any re-author. Re-authors validated n_gen>=threshold before corpus admission. Supersedes d-e4d761e21d (KLD subtraction rejected) and extends d-b6923b9e07.", "rationale": "Aggregates (token-sig, PPL) average away small localized defects; KLD ladder built for exactly that and costs nothing (instrument exists, in-run). 8 deterministic EOS is a pattern — systematic template/EOS/role cause must be excluded before burning 8 slots. Same-session premise fails for startup-read env flags.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-28dbb797c2', 'p-7719544617', 't-d1cf43b723', '2026-09-18T00:27:45.964Z', 'ITEM 1 (cross-session bar): CONFIRM armed-vs-armed controls; null_2 REDEFINED band-setting = A_armed_N0 vs A_armed_N0'' (min 3 pairs/6 runs); old A-vs-A_armed_N0 demoted to null_3 diagnostic (arming cost). Binding = KLD-within-null with EMPIRICAL bar (PASS <= max control medians/99ths + Same-top-p floor; VOID if controls span >10x). Screens asymmetric: match informative, mismatch uninformative (never escalate). Pre-reg AUTHORIZED once tile question answered (justify 64 vs 128 from kernel or add {127,128,129}); N-dim exclusion confirmed. ITEM 2 (bare-text): ALL 27 v2+v1 traces bare-text, not just 8 SHORTs. Measured impact: +0.009 matched / +0.038 within-cohort, inflating; static ceiling CONFIRMED on clean data (S 1.090 vs SHIP 1.10, still no-ship); S-spikes unaffected (v4-only). M-tier tails carry bounded EOS caveat, never pool silently. v1-built h@42 ~0.41 soft (reinforces section 6). Recommend (a) EXTENDED: 8 as separate templated arm + relabel v2+v1 BARE-TEXT with cohort as reported dimension; REJECT (b); (c) insufficient. Future collection must persist decoded text (degeneracy scoring unavailable from .log summaries).', 'Band must measure session noise on the same armed configuration the candidate uses; OFF-vs-ARMED conflates arming cost. Threshold invented pre-controls repeats the avoided error; empirical bar + VOID guard instead. Bare-text impact measured not assumed; clean-data ceiling strengthens the no-ship ruling.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-28dbb797c2", "ts": "2026-09-18T00:27:45.964Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "ITEM 1 (cross-session bar): CONFIRM armed-vs-armed controls; null_2 REDEFINED band-setting = A_armed_N0 vs A_armed_N0'' (min 3 pairs/6 runs); old A-vs-A_armed_N0 demoted to null_3 diagnostic (arming cost). Binding = KLD-within-null with EMPIRICAL bar (PASS <= max control medians/99ths + Same-top-p floor; VOID if controls span >10x). Screens asymmetric: match informative, mismatch uninformative (never escalate). Pre-reg AUTHORIZED once tile question answered (justify 64 vs 128 from kernel or add {127,128,129}); N-dim exclusion confirmed. ITEM 2 (bare-text): ALL 27 v2+v1 traces bare-text, not just 8 SHORTs. Measured impact: +0.009 matched / +0.038 within-cohort, inflating; static ceiling CONFIRMED on clean data (S 1.090 vs SHIP 1.10, still no-ship); S-spikes unaffected (v4-only). M-tier tails carry bounded EOS caveat, never pool silently. v1-built h@42 ~0.41 soft (reinforces section 6). Recommend (a) EXTENDED: 8 as separate templated arm + relabel v2+v1 BARE-TEXT with cohort as reported dimension; REJECT (b); (c) insufficient. Future collection must persist decoded text (degeneracy scoring unavailable from .log summaries).", "rationale": "Band must measure session noise on the same armed configuration the candidate uses; OFF-vs-ARMED conflates arming cost. Threshold invented pre-controls repeats the avoided error; empirical bar + VOID guard instead. Bare-text impact measured not assumed; clean-data ceiling strengthens the no-ship ruling.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f85aeb6e57', 'p-7719544617', 't-d1cf43b723', '2026-09-18T00:49:09.132Z', 'Campaign recheck policy: yield notification primary. T+75min liveness only (PID alive + log mtime advancing, binary wedged-vs-slow). T+3h45 hard deadline (1.5x nominal), no yield by then = escalate. No fixed-interval progress polling. NEVER read partial KLD output mid-flight (pre-registration bias); liveness reads mtime/PID, not numbers. Wedged campaign = VOID, re-runs clean, never salvaged from partial rows.', 'Mid-run progress percentage changes no decision; partial-result inspection biases run/cut calls that pre-registration exists to prevent.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-f85aeb6e57", "ts": "2026-09-18T00:49:09.132Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Campaign recheck policy: yield notification primary. T+75min liveness only (PID alive + log mtime advancing, binary wedged-vs-slow). T+3h45 hard deadline (1.5x nominal), no yield by then = escalate. No fixed-interval progress polling. NEVER read partial KLD output mid-flight (pre-registration bias); liveness reads mtime/PID, not numbers. Wedged campaign = VOID, re-runs clean, never salvaged from partial rows.", "rationale": "Mid-run progress percentage changes no decision; partial-result inspection biases run/cut calls that pre-registration exists to prevent.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0897d807f1', 'p-7719544617', 't-d1cf43b723', '2026-09-18T04:53:10.440Z', 'Arming-shifts-logits verdict: builder kernel account REFUTED (hydra_active gates counters only; pin redirect needs non-empty pins); real mechanism graph-side (build_hydra_mm_id masked sum always replaces fused op). 0.08 KLD unexplained by design = defect signal: prime suspect dropped per-expert scale w_s (build_hydra_mm_id takes no w_s; ffn_*_exps_s TENSOR_NOT_REQUIRED silent). Discriminator routed to builder (~2min CPU: ffn_*_exps_s non-null?). Campaign NOT void (scale cancels armed-vs-armed) but NARROWED: PASS proves admission-inert-given-armed only, never armed-safe-to-ship. Null audit: mean exactly 0.000000 vs smoke floor 1e-6 — confirm independent sessions or band is fake. Earlier ungated-prefill-redirect defect CLOSED (ne12==1 gate present). No candidate verdict until discriminator lands.', '0.08 KLD at zero admissions is impossible under the design (both paths bit-identical to OFF), so it is a defect signal; the dropped-scale hypothesis has an exact signature and a 2-minute CPU test. Campaign internal validity preserved (armed-vs-armed cancels) but ship-reading must be fenced now, before a PASS exists to be misread.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-0897d807f1", "ts": "2026-09-18T04:53:10.440Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Arming-shifts-logits verdict: builder kernel account REFUTED (hydra_active gates counters only; pin redirect needs non-empty pins); real mechanism graph-side (build_hydra_mm_id masked sum always replaces fused op). 0.08 KLD unexplained by design = defect signal: prime suspect dropped per-expert scale w_s (build_hydra_mm_id takes no w_s; ffn_*_exps_s TENSOR_NOT_REQUIRED silent). Discriminator routed to builder (~2min CPU: ffn_*_exps_s non-null?). Campaign NOT void (scale cancels armed-vs-armed) but NARROWED: PASS proves admission-inert-given-armed only, never armed-safe-to-ship. Null audit: mean exactly 0.000000 vs smoke floor 1e-6 — confirm independent sessions or band is fake. Earlier ungated-prefill-redirect defect CLOSED (ne12==1 gate present). No candidate verdict until discriminator lands.", "rationale": "0.08 KLD at zero admissions is impossible under the design (both paths bit-identical to OFF), so it is a defect signal; the dropped-scale hypothesis has an exact signature and a 2-minute CPU test. Campaign internal validity preserved (armed-vs-armed cancels) but ship-reading must be fenced now, before a PASS exists to be misread.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-8500ef271f', 'p-7719544617', 't-d1cf43b723', '2026-09-18T04:59:49.264Z', 'N-sweep probe ordered (KLD ARMED-N vs OFF at N={0,38,~256}, same binary, alongside 7-leg re-run): flat = intrinsic dual-construction term (N=0 reference valid); grows = store-fidelity bug; shrinks = miss-side divergence; any N-variation invalidates N=0 as reference leg (rebuild band vs armed matched-N). Corrections banked: N=0-ARMED runs full dual path h=0 (not inert); masks exact (soft-blend/OOB dead). Fallback: o_miss dump vs fused output if flat. Still no candidate verdict.', 'One probe discriminates the whole remaining mechanism space at once and simultaneously settles whether the campaign''s N=0 reference leg is valid — the decision-relevant question, not just the curiosity one.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-8500ef271f", "ts": "2026-09-18T04:59:49.264Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "N-sweep probe ordered (KLD ARMED-N vs OFF at N={0,38,~256}, same binary, alongside 7-leg re-run): flat = intrinsic dual-construction term (N=0 reference valid); grows = store-fidelity bug; shrinks = miss-side divergence; any N-variation invalidates N=0 as reference leg (rebuild band vs armed matched-N). Corrections banked: N=0-ARMED runs full dual path h=0 (not inert); masks exact (soft-blend/OOB dead). Fallback: o_miss dump vs fused output if flat. Still no candidate verdict.", "rationale": "One probe discriminates the whole remaining mechanism space at once and simultaneously settles whether the campaign''s N=0 reference leg is valid — the decision-relevant question, not just the curiosity one.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b014bb17c9', 'p-7719544617', 't-d1cf43b723', '2026-09-18T05:02:36.603Z', 'Admission never fired in Stage-1: all sites gated n_tokens==1, KLD legs run batched prefill, so build_hydra_mm_id never called (armed falls through to build_lora_mm_id) — flat N-sweep = same computation, not vindication. Probe closed NULL (no high arms; b/c foregone). Bank honest statement, not admission-inert. Fix without code change: re-run ladder with -ub 1 (gate live, confirm fire nonzero); null_2 + candidate from that instrument. 0.0798 armed-vs-OFF prefill offset is a real unexplained defect on the shipped path — file as issue now. Still no candidate verdict.', 'A verdict scored on these legs would certify a code path that never ran; the -ub 1 instrument measures the path actually shipped, and the prefill offset must not ride along as a known-unknown into Phase B.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-b014bb17c9", "ts": "2026-09-18T05:02:36.603Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Admission never fired in Stage-1: all sites gated n_tokens==1, KLD legs run batched prefill, so build_hydra_mm_id never called (armed falls through to build_lora_mm_id) — flat N-sweep = same computation, not vindication. Probe closed NULL (no high arms; b/c foregone). Bank honest statement, not admission-inert. Fix without code change: re-run ladder with -ub 1 (gate live, confirm fire nonzero); null_2 + candidate from that instrument. 0.0798 armed-vs-OFF prefill offset is a real unexplained defect on the shipped path — file as issue now. Still no candidate verdict.", "rationale": "A verdict scored on these legs would certify a code path that never ran; the -ub 1 instrument measures the path actually shipped, and the prefill offset must not ride along as a known-unknown into Phase B.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-10fbf0386d', 'p-7719544617', 't-d1cf43b723', '2026-09-18T05:04:47.321Z', 'Fire adjudication: [0,0,0,0] prediction withdrawn (machinery builds once) but conclusion survives — N0/N38 bit-identity proves h=0 on all scored tokens under either hypothesis; 7 identical [0,1,1,1] legs already prove one-time warmup build. -ub 1 pass/fail pre-registered: (1) fire must scale ~48/build or STOP; (2) hit+miss nonzero or second dead path; (3) N0/N38 must stop bit-identical (the real gate). Phase-B note: add graph-side hit counter. Site-fire-count oddity filed #774.', 'Pre-registering the three gates before the yield lands prevents reading the result into the conclusion; bit-identity is the independent evidence that keeps the null-result banking intact.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-10fbf0386d", "ts": "2026-09-18T05:04:47.321Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Fire adjudication: [0,0,0,0] prediction withdrawn (machinery builds once) but conclusion survives — N0/N38 bit-identity proves h=0 on all scored tokens under either hypothesis; 7 identical [0,1,1,1] legs already prove one-time warmup build. -ub 1 pass/fail pre-registered: (1) fire must scale ~48/build or STOP; (2) hit+miss nonzero or second dead path; (3) N0/N38 must stop bit-identical (the real gate). Phase-B note: add graph-side hit counter. Site-fire-count oddity filed #774.", "rationale": "Pre-registering the three gates before the yield lands prevents reading the result into the conclusion; bit-identity is the independent evidence that keeps the null-result banking intact.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-10375b2b82', 'p-7719544617', 't-d1cf43b723', '2026-09-18T07:01:02.930Z', 'Hard deadline for -ub 1 re-run: 4h30 from launch (~1.5x top of 1-3h ETA) — escalate if no yield by then. Launch ~05:05 UTC, deadline ~09:35 UTC.', 'Bounds the yield-watch so a wedged re-run cannot burn the rig night silently; escalation (not VOID) preserves the instrument while forcing a liveness answer.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-10375b2b82", "ts": "2026-09-18T07:01:02.930Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Hard deadline for -ub 1 re-run: 4h30 from launch (~1.5x top of 1-3h ETA) — escalate if no yield by then. Launch ~05:05 UTC, deadline ~09:35 UTC.", "rationale": "Bounds the yield-watch so a wedged re-run cannot burn the rig night silently; escalation (not VOID) preserves the instrument while forcing a liveness answer.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-3df100177c', 'p-7719544617', 't-d1cf43b723', '2026-09-18T07:28:30.129Z', 'First live admission verdict: ITERATE. All 3 gates PASS (fire 1515s, h=0.1457, identity broken) but pre-registered band test VOID (zero-width controls degenerate the max rule — architect''s own pre-reg error, owned). PPL +1.57% + heavy tail real under zero noise floor; same-top-p improvement rules out corruption — mechanism is CPU/GPU arithmetic mixture, inherent to hot/cold split, not a bug. h=0.1457 matches offline cross-domain (14.41/14.01 vs 14.57, within 0.2pp) — validates offline estimator, no constants move; S(0.1457)=0.952 fenced as non-shipping. Next: matched-corpus leg + N=42 non-monotone-PPL point. Quality cost filed #775 for owner acceptance.', 'Central tendency negligible but tail+PPL real with zero noise floor — neither PASS nor KILL is honest; matched-workload measurement prices both speedup and quality before G3 bands bite.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-3df100177c", "ts": "2026-09-18T07:28:30.129Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "First live admission verdict: ITERATE. All 3 gates PASS (fire 1515s, h=0.1457, identity broken) but pre-registered band test VOID (zero-width controls degenerate the max rule — architect''s own pre-reg error, owned). PPL +1.57% + heavy tail real under zero noise floor; same-top-p improvement rules out corruption — mechanism is CPU/GPU arithmetic mixture, inherent to hot/cold split, not a bug. h=0.1457 matches offline cross-domain (14.41/14.01 vs 14.57, within 0.2pp) — validates offline estimator, no constants move; S(0.1457)=0.952 fenced as non-shipping. Next: matched-corpus leg + N=42 non-monotone-PPL point. Quality cost filed #775 for owner acceptance.", "rationale": "Central tendency negligible but tail+PPL real with zero noise floor — neither PASS nor KILL is honest; matched-workload measurement prices both speedup and quality before G3 bands bite.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1969609825', 'p-7719544617', 't-d1cf43b723', '2026-09-18T08:46:36.877Z', 'Liveness checks authorized as distinct from result-polling (PID + mtime advancing is allowed; reading mid-flight results stays banned). Hard deadline 60min from launch for matched + N42 legs.', 'Distinguishes breathing-checks from pre-registration-biasing result reads; bounds the ITERATE follow-up legs.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-1969609825", "ts": "2026-09-18T08:46:36.877Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Liveness checks authorized as distinct from result-polling (PID + mtime advancing is allowed; reading mid-flight results stays banned). Hard deadline 60min from launch for matched + N42 legs.", "rationale": "Distinguishes breathing-checks from pre-registration-biasing result reads; bounds the ITERATE follow-up legs.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-0b4c224ea1', 'p-7719544617', 't-d1cf43b723', '2026-09-18T08:48:34.748Z', 'Matched-38 PASSES correctness (mean/max/same-top better; +1.37% PPL priced, owner acceptance via #775). h=0.4207 live-matched exactly reproduces offline self-heldout 42.07% — offline estimator validated at both ends, open question retired. S=1.1105 clears SHIP line but margins sub-7% on provisional alpha + contaminated O/D — NO ship declaration. Next: measured timed decode leg (armed N38-matched vs OFF tok/s) becomes the SHIP gate, retiring inference. Mixture account unconfirmed/unrefuted, banked as open note (fixed-pin sweep not worth rig time).', 'Inferring ship-readiness through two unconfirmed constants repeats the bare-text pooling error class; the directly observable quantity (tok/s) must be the gate.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-0b4c224ea1", "ts": "2026-09-18T08:48:34.748Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Matched-38 PASSES correctness (mean/max/same-top better; +1.37% PPL priced, owner acceptance via #775). h=0.4207 live-matched exactly reproduces offline self-heldout 42.07% — offline estimator validated at both ends, open question retired. S=1.1105 clears SHIP line but margins sub-7% on provisional alpha + contaminated O/D — NO ship declaration. Next: measured timed decode leg (armed N38-matched vs OFF tok/s) becomes the SHIP gate, retiring inference. Mixture account unconfirmed/unrefuted, banked as open note (fixed-pin sweep not worth rig time).", "rationale": "Inferring ship-readiness through two unconfirmed constants repeats the bare-text pooling error class; the directly observable quantity (tok/s) must be the gate.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-3b543bcfcf', 'p-7719544617', 't-d1cf43b723', '2026-09-18T08:53:34.831Z', 'NO-SHIP on graph-side dual construction (measured 0.82x). Structural, not overhead: build_hydra_mm_id runs TWO full MoE matmuls (o_miss uses unmodified full ids — cold side still fetches every expert over PCIe, pinning removes zero host traffic); h counts selections, not bytes saved. Cost model modeled a mechanism never built — retire S(h) as ship gate. Correct mechanism already dormant in fork: .cu per-expert pointer swap (:2208), unreachable because quantized decode takes MMVQ early return (:2089). Phase B = plumb pin store into MMVQ/MMQ, not tune dual-op. h=0.4207 work preserved as Phase-B input. N0 timed leg (~7min) dispatched to confirm structural account.', 'Measured 0.82x against predicted +11% is a 29-point gap no constant drift explains; source reading shows the bytes are never saved at any h, so no tuning of this construction can ship.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-3b543bcfcf", "ts": "2026-09-18T08:53:34.831Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "NO-SHIP on graph-side dual construction (measured 0.82x). Structural, not overhead: build_hydra_mm_id runs TWO full MoE matmuls (o_miss uses unmodified full ids — cold side still fetches every expert over PCIe, pinning removes zero host traffic); h counts selections, not bytes saved. Cost model modeled a mechanism never built — retire S(h) as ship gate. Correct mechanism already dormant in fork: .cu per-expert pointer swap (:2208), unreachable because quantized decode takes MMVQ early return (:2089). Phase B = plumb pin store into MMVQ/MMQ, not tune dual-op. h=0.4207 work preserved as Phase-B input. N0 timed leg (~7min) dispatched to confirm structural account.", "rationale": "Measured 0.82x against predicted +11% is a 29-point gap no constant drift explains; source reading shows the bytes are never saved at any h, so no tuning of this construction can ship.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-9d03c8ed6a', 'p-7719544617', 't-d1cf43b723', '2026-09-18T08:56:58.412Z', 'NO-SHIP CLOSED on measurement: N0 11.8281 vs N38 11.7490 (0.7% apart, both ~0.82x OFF) — dual-construction cost structural, confirmed not inferred. Stage-1 task closed done. h work survives (offline estimator validated both ends). Phase B = mechanism move to .cu pointer swap in MMVQ/MMQ. Owner items: accept NO-SHIP + scope Phase B; corpus (a)+relabel, teacher-force, redrafts still open. Ops rule filed as lesson (exact-PID-only).', 'N0~=N38 closes the last open branch; nothing further can be extracted from the dual-op construction, and the salvaged h work plus dormant .cu mechanism give Phase B a running start.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-9d03c8ed6a", "ts": "2026-09-18T08:56:58.412Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "NO-SHIP CLOSED on measurement: N0 11.8281 vs N38 11.7490 (0.7% apart, both ~0.82x OFF) — dual-construction cost structural, confirmed not inferred. Stage-1 task closed done. h work survives (offline estimator validated both ends). Phase B = mechanism move to .cu pointer swap in MMVQ/MMQ. Owner items: accept NO-SHIP + scope Phase B; corpus (a)+relabel, teacher-force, redrafts still open. Ops rule filed as lesson (exact-PID-only).", "rationale": "N0~=N38 closes the last open branch; nothing further can be extracted from the dual-op construction, and the salvaged h work plus dormant .cu mechanism give Phase B a running start.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-bbcb6d3201', 'p-7719544617', 't-d1cf43b723', '2026-09-18T13:46:37.713Z', 'Post-NO-SHIP reframe: corpus off critical path (nothing downstream consumes traces until .cu mechanism plumbed; 14h collector idle cost nothing; (a)/(b)/(c) can wait without blocking). Only open lane needing no owner hand: Phase-B scoping (source-only: pin-store reach into MMVQ/MMQ, layout survival). Leader dispatched scoping study to builder.', 'Idling the track on owner decisions while source-only scoping for the now-dependent workstream is available would waste the quiet window.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-bbcb6d3201", "ts": "2026-09-18T13:46:37.713Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Post-NO-SHIP reframe: corpus off critical path (nothing downstream consumes traces until .cu mechanism plumbed; 14h collector idle cost nothing; (a)/(b)/(c) can wait without blocking). Only open lane needing no owner hand: Phase-B scoping (source-only: pin-store reach into MMVQ/MMQ, layout survival). Leader dispatched scoping study to builder.", "rationale": "Idling the track on owner decisions while source-only scoping for the now-dependent workstream is available would waste the quiet window.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-82fc65b3f6', 'p-7719544617', 't-d1cf43b723', '2026-09-18T13:50:43.345Z', 'Phase-B plan WITHHELD: no approval, no A/B ruling until three measurements land — (1) buffer-name string (host-mapped vs VRAM settles the premise; device-accessible != VRAM-resident), (2) offload sweep (slope = addressable gain, ceiling = h x slope; flat kills Phase B on economics), (3) graphs-disabled cost (can kill compact-gather alone). Hard requirement: Phase B deletes build_hydra_mm_id. Conditional A/B framework banked (host+slope->A; host+flat->B+reframe; VRAM->B owner-level). Measure-before-build replaces model-before-build (+11 vs -18 lesson).', 'Approving a seam before knowing whether there is traffic to save repeats the dual-op error; all three questions are answerable by measurement with zero new code.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-82fc65b3f6", "ts": "2026-09-18T13:50:43.345Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Phase-B plan WITHHELD: no approval, no A/B ruling until three measurements land — (1) buffer-name string (host-mapped vs VRAM settles the premise; device-accessible != VRAM-resident), (2) offload sweep (slope = addressable gain, ceiling = h x slope; flat kills Phase B on economics), (3) graphs-disabled cost (can kill compact-gather alone). Hard requirement: Phase B deletes build_hydra_mm_id. Conditional A/B framework banked (host+slope->A; host+flat->B+reframe; VRAM->B owner-level). Measure-before-build replaces model-before-build (+11 vs -18 lesson).", "rationale": "Approving a seam before knowing whether there is traffic to save repeats the dual-op error; all three questions are answerable by measurement with zero new code.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a2a4b1bd00', 'p-7719544617', 't-d1cf43b723', '2026-09-18T14:34:38.857Z', 'Ruling A: PROCEED compact-gather first on single-GPU baseline. Ceiling: +5.94 tok/s projected (42.07 x 0.141, 1.33x; net 1.23-1.26x after graph tax, clear of 1.10). In-range justification: pinning is 5.6x better VRAM use than whole layers (measured). Graphs cost = 29% tax, not kill; ranking holds. Caveats: linearity extrapolation (add 3.4GB pin point if constructible); h-transfer assumption; pre-registered near-zero PPL check for pointer swap. Standalone: single-GPU 18.19 vs 14.39 (+26.4%, no code) to owner immediately; Phase-B baseline must be fast config.', 'Streaming premise confirmed (CUDA_Host), addressable slope measured, ceiling clears the line even net of graph tax — and the comparative VRAM-efficiency claim sits fully inside measured range.', 'consult', 0, 'architect 2731baf3 (standing, opus)', '{"id": "d-a2a4b1bd00", "ts": "2026-09-18T14:34:38.857Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Ruling A: PROCEED compact-gather first on single-GPU baseline. Ceiling: +5.94 tok/s projected (42.07 x 0.141, 1.33x; net 1.23-1.26x after graph tax, clear of 1.10). In-range justification: pinning is 5.6x better VRAM use than whole layers (measured). Graphs cost = 29% tax, not kill; ranking holds. Caveats: linearity extrapolation (add 3.4GB pin point if constructible); h-transfer assumption; pre-registered near-zero PPL check for pointer swap. Standalone: single-GPU 18.19 vs 14.39 (+26.4%, no code) to owner immediately; Phase-B baseline must be fast config.", "rationale": "Streaming premise confirmed (CUDA_Host), addressable slope measured, ceiling clears the line even net of graph tax — and the comparative VRAM-efficiency claim sits fully inside measured range.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus)"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-85fe48be11', 'p-7719544617', 't-d1cf43b723', '2026-09-18T14:47:20.967Z', 'STOP-AND-RESEQUENCE executed: compact-gather pilot parked (task-ff7f39af4d, context preserved); miss-side remap (miss_of twin table + ids_miss rewire, graph-side only) first with 3 pre-registered gates (KLD no-worse-than-0.089763; >0.82x toward 1.05-1.25x on 18.19 baseline; N0/N38 MUST diverge). L2-collapse assumption flagged to builder. -ot expert-ranking impossibility banked (single 3D tensor/layer/site; cross-layer volume flat; skew strictly intra-layer). Builder acked; fragment yields diagnosed as status misfires.', 'Afternoon graph-side fix with no graph loss de-risks the 200-line pilot; N0/N38 divergence is the discriminator that proves traffic actually falls.', 'consult', 0, 'architect 2731baf3 (standing, opus) + leader', '{"id": "d-85fe48be11", "ts": "2026-09-18T14:47:20.967Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "STOP-AND-RESEQUENCE executed: compact-gather pilot parked (task-ff7f39af4d, context preserved); miss-side remap (miss_of twin table + ids_miss rewire, graph-side only) first with 3 pre-registered gates (KLD no-worse-than-0.089763; >0.82x toward 1.05-1.25x on 18.19 baseline; N0/N38 MUST diverge). L2-collapse assumption flagged to builder. -ot expert-ranking impossibility banked (single 3D tensor/layer/site; cross-layer volume flat; skew strictly intra-layer). Builder acked; fragment yields diagnosed as status misfires.", "rationale": "Afternoon graph-side fix with no graph loss de-risks the 200-line pilot; N0/N38 divergence is the discriminator that proves traffic actually falls.", "source": "consult", "irreversible": false, "author": "architect 2731baf3 (standing, opus) + leader"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a46c46397e', 'p-7719544617', 't-d1cf43b723', '2026-09-18T17:02:57.289Z', 'STOP-FIX-1: ARM 006-prime refutes the weight-streaming premise (309x gap: 16.0 GB/s demanded by the model vs 113 MB/s measured; 62.2 KB/layer/tok is activation-sized, not weights). Fix 1 + PR #134 implementation ON HOLD (review only); ARM 005 blocked/may-be-moot; discriminator (CPU util t48 vs t40 same session + GPU util) queued behind task-9be0a9a07c. Banked as section 18, commit bda755ec7.', 'Hard physical bound, not an estimate: the weight-streaming model demands >2x the PCIe x4 link. If --n-cpu-moe runs expert FFN on the CPU backend, the phase redesigns around compute placement; building Fix 1 first would buy zero. Architect ruling, owner-designated 2731baf3.', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-a46c46397e", "ts": "2026-09-18T17:02:57.289Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "STOP-FIX-1: ARM 006-prime refutes the weight-streaming premise (309x gap: 16.0 GB/s demanded by the model vs 113 MB/s measured; 62.2 KB/layer/tok is activation-sized, not weights). Fix 1 + PR #134 implementation ON HOLD (review only); ARM 005 blocked/may-be-moot; discriminator (CPU util t48 vs t40 same session + GPU util) queued behind task-9be0a9a07c. Banked as section 18, commit bda755ec7.", "rationale": "Hard physical bound, not an estimate: the weight-streaming model demands >2x the PCIe x4 link. If --n-cpu-moe runs expert FFN on the CPU backend, the phase redesigns around compute placement; building Fix 1 first would buy zero. Architect ruling, owner-designated 2731baf3.", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-06ea2547fb', 'p-7719544617', 't-d1cf43b723', '2026-09-18T17:02:57.296Z', 'Standing rules adopted (banked §18, bda755ec7): (1) SAME-SESSION ANCHOR — cross-build A/B carries ~2.4% variance on this rig, every delta judged vs a same-session anchor, never another build number; (2) MEASURE-COST-FIRST — before building a mechanism that removes a cost, measure that the cost exists (ARM 006-prime should have been arm 001, not arm 007).', 'Methodological hardening from the ARM 006-prime refutation: third unmeasured premise on this track; the two rules prevent recurrence.', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-06ea2547fb", "ts": "2026-09-18T17:02:57.296Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Standing rules adopted (banked §18, bda755ec7): (1) SAME-SESSION ANCHOR — cross-build A/B carries ~2.4% variance on this rig, every delta judged vs a same-session anchor, never another build number; (2) MEASURE-COST-FIRST — before building a mechanism that removes a cost, measure that the cost exists (ARM 006-prime should have been arm 001, not arm 007).", "rationale": "Methodological hardening from the ARM 006-prime refutation: third unmeasured premise on this track; the two rules prevent recurrence.", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6fca48f692', 'p-7719544617', 't-d1cf43b723', '2026-09-18T17:12:26.506Z', 'RULING CONFIRMED (banked §18 amendment 5cedadb61): system is CPU-BOUND (CPU 94-98% saturated both configs, GPU 27-35% idle). --n-cpu-moe runs expert FFN on CPU; residency = compute migration. The pinning mechanism CREATED the PCIe traffic it aimed to remove (all-GPU expert compute forced cold weights across the bus). Thesis corrected: move expert COMPUTE to GPU at fine granularity bounded by VRAM; mechanism must select a BACKEND per expert, not a weight address. FIX 1 dead permanently in current form. ARM 006 reversed to RUN with prediction armed ~100x stock traffic (confirmation gate). ARM 005 blocked, design brief = CPU/GPU compute split. Projected prize survives: ~1.31x at h=0.4207 on 3.4GB, ~+74% ceiling.', 'Utilization LEVELS are decisive: CPU 97.8%/94.0% of observed max, GPU never >35% sm, link at 1-3%. The -8% CPU delta reconciles with 16.7% expert-work cut iff expert FFN is ~half of CPU time. Architect ruling on owner-designated consult; standing rule upgraded: measure cost existence AND utilization of every unit involved.', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-6fca48f692", "ts": "2026-09-18T17:12:26.506Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "RULING CONFIRMED (banked §18 amendment 5cedadb61): system is CPU-BOUND (CPU 94-98% saturated both configs, GPU 27-35% idle). --n-cpu-moe runs expert FFN on CPU; residency = compute migration. The pinning mechanism CREATED the PCIe traffic it aimed to remove (all-GPU expert compute forced cold weights across the bus). Thesis corrected: move expert COMPUTE to GPU at fine granularity bounded by VRAM; mechanism must select a BACKEND per expert, not a weight address. FIX 1 dead permanently in current form. ARM 006 reversed to RUN with prediction armed ~100x stock traffic (confirmation gate). ARM 005 blocked, design brief = CPU/GPU compute split. Projected prize survives: ~1.31x at h=0.4207 on 3.4GB, ~+74% ceiling.", "rationale": "Utilization LEVELS are decisive: CPU 97.8%/94.0% of observed max, GPU never >35% sm, link at 1-3%. The -8% CPU delta reconciles with 16.7% expert-work cut iff expert FFN is ~half of CPU time. Architect ruling on owner-designated consult; standing rule upgraded: measure cost existence AND utilization of every unit involved.", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-c4c5372f76', 'p-7719544617', 't-d1cf43b723', '2026-09-18T18:10:42.336Z', 'Section 19 banked (c5e078d97, 2026-09-19T01:09:25+07:00): ARM 006 ruled VOID not refuted (hook on MMVQ branch, decode dispatches MMQ — zero engagements by construction; architect WITHDREW the 100x prediction test as archaeology on a deleted mechanism; account held best-explanation-untested). Baseline legs data STRUCK (empty-output sha256, vacuous PARITY_OK — measurement not re-run, cache thesis closed). Known dispatch facts added to bank (decode=MMQ; fused path bypasses thunk hook; check mmid counters non-zero before reading mechanism measurements). Defects filed: #135 D1 gate-cannot-fail (SEVERE), #136 D2 counter leak, #137 D3 unlogged load failure, #138 D4 26-min load hang. PR #134 comment posted (MMQ/MMVQ headline). New live gate: THREAD SWEEP t48+t40 x -t 2/4/6/8/12 with pre-registered CPU-bound predictions, dispatched to builder. Standing rule: A GATE MUST BE ABLE TO FAIL.', 'You cannot refute a prediction about a working mechanism by measuring one that never ran; and re-running a baseline for a closed thesis buys data for a question no longer asked. The gates-must-fail rule closes the third false-PASS class on this track.', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-c4c5372f76", "ts": "2026-09-18T18:10:42.336Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Section 19 banked (c5e078d97, 2026-09-19T01:09:25+07:00): ARM 006 ruled VOID not refuted (hook on MMVQ branch, decode dispatches MMQ — zero engagements by construction; architect WITHDREW the 100x prediction test as archaeology on a deleted mechanism; account held best-explanation-untested). Baseline legs data STRUCK (empty-output sha256, vacuous PARITY_OK — measurement not re-run, cache thesis closed). Known dispatch facts added to bank (decode=MMQ; fused path bypasses thunk hook; check mmid counters non-zero before reading mechanism measurements). Defects filed: #135 D1 gate-cannot-fail (SEVERE), #136 D2 counter leak, #137 D3 unlogged load failure, #138 D4 26-min load hang. PR #134 comment posted (MMQ/MMVQ headline). New live gate: THREAD SWEEP t48+t40 x -t 2/4/6/8/12 with pre-registered CPU-bound predictions, dispatched to builder. Standing rule: A GATE MUST BE ABLE TO FAIL.", "rationale": "You cannot refute a prediction about a working mechanism by measuring one that never ran; and re-running a baseline for a closed thesis buys data for a question no longer asked. The gates-must-fail rule closes the third false-PASS class on this track.", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-c236edf809', 'p-7719544617', 't-d1cf43b723', '2026-09-18T18:25:53.751Z', 'Section 20 banked (3847babe8, 2026-09-19T01:25:23+07:00): CPU-BOUND CONFIRMED (main pre-registered branch: not flat, t2->t12 +75%/+74%); sub-prediction FAILED and refined — CPU side is MEMORY-BANDWIDTH-BOUND (51% efficiency collapse t2->t12, identical relative curves both configs). Residency gain robust (t40>t48 at every thread count, ~+2.1-2.3 constant; 0.289 t/s/layer at t12 — third independent agreement); re-priced ranked pinning 1.292x at h=0.4207. UNTUNED-BASELINE FINDING: no plateau at t12, best 22.27 vs 18.19 = +22% from a thread flag; stacked with topology +26%, two zero-code config wins exceed everything the mechanism delivered. GATE: ARM 005 must be measured against BEST stock configuration (not 18.19). Queue: sweep extension t16/24/32 with GPU sm% (dispatched), re-anchor ARM 003/004 at best thread setting, ARM 005 blocked on compute-split design + best-config gate. OWNER STANDING ITEM: threads +22% and topology +26% are measured, unclaimed, zero-code — landing them is the owner call.', 'The untuned-baseline error flatters mechanisms by 20-25% — same class as the §17c/G4 syncing-vs-graphs error; the best-config gate prevents repeating it. The bandwidth refinement explains why both configs share one ceiling and redirects ARM 005 design reasoning (VRAM residency relieves RAM bandwidth too).', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-c236edf809", "ts": "2026-09-18T18:25:53.751Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Section 20 banked (3847babe8, 2026-09-19T01:25:23+07:00): CPU-BOUND CONFIRMED (main pre-registered branch: not flat, t2->t12 +75%/+74%); sub-prediction FAILED and refined — CPU side is MEMORY-BANDWIDTH-BOUND (51% efficiency collapse t2->t12, identical relative curves both configs). Residency gain robust (t40>t48 at every thread count, ~+2.1-2.3 constant; 0.289 t/s/layer at t12 — third independent agreement); re-priced ranked pinning 1.292x at h=0.4207. UNTUNED-BASELINE FINDING: no plateau at t12, best 22.27 vs 18.19 = +22% from a thread flag; stacked with topology +26%, two zero-code config wins exceed everything the mechanism delivered. GATE: ARM 005 must be measured against BEST stock configuration (not 18.19). Queue: sweep extension t16/24/32 with GPU sm% (dispatched), re-anchor ARM 003/004 at best thread setting, ARM 005 blocked on compute-split design + best-config gate. OWNER STANDING ITEM: threads +22% and topology +26% are measured, unclaimed, zero-code — landing them is the owner call.", "rationale": "The untuned-baseline error flatters mechanisms by 20-25% — same class as the §17c/G4 syncing-vs-graphs error; the best-config gate prevents repeating it. The bandwidth refinement explains why both configs share one ceiling and redirects ARM 005 design reasoning (VRAM residency relieves RAM bandwidth too).", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6f7c2ef2a2', 'p-7719544617', 't-d1cf43b723', '2026-09-18T18:39:09.052Z', 'Section 20b banked (71d093d9d, 2026-09-19T01:38:02+07:00): ROOT CAUSE found — host is hybrid P/E (i7-12700K, CPUs 0-15 = 8 P-cores SMT @5100MHz, CPUs 16-19 = 4 E-cores @3900MHz), all sweep points ran unpinned so OS placement confounds mechanism readings; peak at t16 = exactly P-core logical thread count; past t16 E-core spill drags per-node barriers (tok/s AND CPU% fall together). P3 PROCEED branch (GPU ~65% idle structural at 33-35% sm%). P1 knee location right, shape wrong, definition defective -> method lesson banked (plateau = argmax + two consecutive non-improving steps). P2 falsifier did not fire but test inadequate -> §20.2 bandwidth refinement UNFALSIFIED BUT UNDER SERIOUS DOUBT. P4 landed in unregistered gap (+1.58 at peak) -> pre-registration design lesson banked. ARM 005 RE-PRICED DOWN: 1.292x -> ~1.145x (0.1975 tok/s/layer at peak, -32% vs t12) — the §20.4 best-stock gate caught the architect own number. ARM 005 NOT signed for build; stays blocked, compute-split brief stands, gated on the pre-registered affinity discriminator (A: taskset 0-15 t16; B: taskset 0,2,..,14 t8 no-SMT; C: unpinned t16 control). RE-ANCHOR: ARM 005 reference = t40/-t16 @ 23.00 tok/s; ARM 003/004 residency numbers to be restated at t16. OWNER: best stock 23.00 vs default split 14.39 = 1.60x from two flags, zero code — land threads + topology together now that plateau known, then re-anchor (owner call).', 'The unpinned-scheduler confound voids core-vs-bandwidth adjudication from the sweep; only a pinned discriminator can set the ARM 005 ceiling properly, and the ceiling already fell 12% once the baseline was corrected. The architect refused to bank a confounded P2 pass — evidence quality over narrative.', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-6f7c2ef2a2", "ts": "2026-09-18T18:39:09.052Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Section 20b banked (71d093d9d, 2026-09-19T01:38:02+07:00): ROOT CAUSE found — host is hybrid P/E (i7-12700K, CPUs 0-15 = 8 P-cores SMT @5100MHz, CPUs 16-19 = 4 E-cores @3900MHz), all sweep points ran unpinned so OS placement confounds mechanism readings; peak at t16 = exactly P-core logical thread count; past t16 E-core spill drags per-node barriers (tok/s AND CPU% fall together). P3 PROCEED branch (GPU ~65% idle structural at 33-35% sm%). P1 knee location right, shape wrong, definition defective -> method lesson banked (plateau = argmax + two consecutive non-improving steps). P2 falsifier did not fire but test inadequate -> §20.2 bandwidth refinement UNFALSIFIED BUT UNDER SERIOUS DOUBT. P4 landed in unregistered gap (+1.58 at peak) -> pre-registration design lesson banked. ARM 005 RE-PRICED DOWN: 1.292x -> ~1.145x (0.1975 tok/s/layer at peak, -32% vs t12) — the §20.4 best-stock gate caught the architect own number. ARM 005 NOT signed for build; stays blocked, compute-split brief stands, gated on the pre-registered affinity discriminator (A: taskset 0-15 t16; B: taskset 0,2,..,14 t8 no-SMT; C: unpinned t16 control). RE-ANCHOR: ARM 005 reference = t40/-t16 @ 23.00 tok/s; ARM 003/004 residency numbers to be restated at t16. OWNER: best stock 23.00 vs default split 14.39 = 1.60x from two flags, zero code — land threads + topology together now that plateau known, then re-anchor (owner call).", "rationale": "The unpinned-scheduler confound voids core-vs-bandwidth adjudication from the sweep; only a pinned discriminator can set the ARM 005 ceiling properly, and the ceiling already fell 12% once the baseline was corrected. The architect refused to bank a confounded P2 pass — evidence quality over narrative.", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-163ef38d9c', 'p-7719544617', 't-d1cf43b723', '2026-09-18T18:51:35.973Z', 'Section 20c banked (f5e6399a2, 2026-09-19T01:50:06+07:00): (1) RETRACTION — the section 20b E-core barrier-drag root cause is refuted (unpinned leg C with E-core participation is fastest; t16=P-core-count was a numerical coincidence, third instance of the coincidence-as-finding error shape); replaced by plain oversubscription (20 logical CPUs, t24/t32 exceed); t16-t24 gap untested. (2) CONFIRMED — RAM-BANDWIDTH WALL via 3 signatures (SMT +0.14% for +71% CPU; leg B threads idle 52% on exclusive cores; throughput tracks distinct physical cores 8->12 = 21.00->23.94). (3) TRACK SCORING RULE — every future proposal scored first by: does it reduce bytes read from system RAM per token? (4) D1 GATE mandatory — mechanical sampler non-empty + token-count assertions per leg, VOID if failed; D2 unique-port + serving-PID assert; lead audit result: ALL banked decode numbers taken without the gate (post-hoc corroboration only). (5) REFERENCE IS A CONFIGURATION — ARM 005 ref = t40 unpinned -t16, never a scalar; C did NOT reproduce (4.1% > 2.4% rule, rule not softened). (6) ARM 005 ceiling ~1.14x BLOCKED not killed; architect declined to cash own conditional (flattery prevention). (7) D/E/F pre-registered BEFORE dispatch and dispatched: D = all 12 physical cores -t12, E = unpinned -t20, F = unpinned -t18; predictions E-or-F beats C (peak 18-20), D within 3% of C at ~600% CPU (ship config), D materially below C refutes signature-1.', 'The retraction and the confirmation banked together preserve evidence quality: the bandwidth claim stands on direct signatures while the mechanism that predicted it dies. The scoring rule converts the finding into a standing filter for all future arm proposals, and the D1 gate converts the 41.81 incident from a caught flake into an impossible event class.', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-163ef38d9c", "ts": "2026-09-18T18:51:35.973Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Section 20c banked (f5e6399a2, 2026-09-19T01:50:06+07:00): (1) RETRACTION — the section 20b E-core barrier-drag root cause is refuted (unpinned leg C with E-core participation is fastest; t16=P-core-count was a numerical coincidence, third instance of the coincidence-as-finding error shape); replaced by plain oversubscription (20 logical CPUs, t24/t32 exceed); t16-t24 gap untested. (2) CONFIRMED — RAM-BANDWIDTH WALL via 3 signatures (SMT +0.14% for +71% CPU; leg B threads idle 52% on exclusive cores; throughput tracks distinct physical cores 8->12 = 21.00->23.94). (3) TRACK SCORING RULE — every future proposal scored first by: does it reduce bytes read from system RAM per token? (4) D1 GATE mandatory — mechanical sampler non-empty + token-count assertions per leg, VOID if failed; D2 unique-port + serving-PID assert; lead audit result: ALL banked decode numbers taken without the gate (post-hoc corroboration only). (5) REFERENCE IS A CONFIGURATION — ARM 005 ref = t40 unpinned -t16, never a scalar; C did NOT reproduce (4.1% > 2.4% rule, rule not softened). (6) ARM 005 ceiling ~1.14x BLOCKED not killed; architect declined to cash own conditional (flattery prevention). (7) D/E/F pre-registered BEFORE dispatch and dispatched: D = all 12 physical cores -t12, E = unpinned -t20, F = unpinned -t18; predictions E-or-F beats C (peak 18-20), D within 3% of C at ~600% CPU (ship config), D materially below C refutes signature-1.", "rationale": "The retraction and the confirmation banked together preserve evidence quality: the bandwidth claim stands on direct signatures while the mechanism that predicted it dies. The scoring rule converts the finding into a standing filter for all future arm proposals, and the D1 gate converts the 41.81 incident from a caught flake into an impossible event class.", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a849c19627', 'p-7719544617', 't-d1cf43b723', '2026-09-18T18:59:09.071Z', 'Section 20d banked (3ee7a39fe, 2026-09-19T01:58:15+07:00, H/I/J pre-registration in same commit BEFORE dispatch): (1) RETRACTION #2 — the section 20c RAM-bandwidth wall is RETRACTED, status UNPROVEN; signature 1 (SMT buys nothing) VOID as evidence (A and B both at 0 spare = shared artificial ceiling), signature 3 (throughput tracks physical cores) REFUTED (D 12-phys 20.76 < B 8-phys 21.00), signature 2 (52% idle => memory-starved) replaced by simpler unbanked account (CPU/GPU phase alternation per layer explains both 52% CPU stall and 65% GPU idle). (2) The section 20c TRACK SCORING RULE (bytes from system RAM per token) is STRUCK — resting on nothing. (3) Six legs separate PERFECTLY on SPARE CPU CAPACITY (avail logical minus compute threads): 0 spare = 20.32-21.00, 2+ spare = 23.94-23.99, ratio 1.154, zero overlap, not core count/thread count/SMT/pinning; spare-capacity mechanism banked as HYPOTHESIS ONLY with decisive control pre-registered (H: pinned all-20 t18 -> H~24 spares the hypothesis, H~21 kills it; I: 2 spare inside small mask, predicted 22-23; J: unpinned t19 = 1 spare, predicted ~23.5); nothing downstream may cite it until the control returns. (4) OPERATIONAL: ship -t 16 unpinned (ties t18 at ~24, keeps 4 CPUs margin vs the 15% cliff at t20; robustness decides between tied configs). (5) ARM 005 unchanged ~1.14x BLOCKED; bandwidth support retracted; rests on measured per-layer number + structural GPU idle; residency figure measured inside good cluster, uncontaminated. (6) D1/D2 gates held mechanically first outing (builder commended). OWNER: best stock ~23.99 vs 14.39 = 1.67x unchanged.', 'Two banked conclusions retracted in two rounds share one root cause: mechanisms banked before their test. The retraction is paired with the replacement discipline — sort the full leg set by candidate variables before drawing pair signatures, and bank hypotheses only with their decisive control pre-registered. The scoring rule is struck because a wrong steering rule costs years, not runs.', 'leader', 0, 'architect-2731baf3/owner-directive', '{"id": "d-a849c19627", "ts": "2026-09-18T18:59:09.071Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Section 20d banked (3ee7a39fe, 2026-09-19T01:58:15+07:00, H/I/J pre-registration in same commit BEFORE dispatch): (1) RETRACTION #2 — the section 20c RAM-bandwidth wall is RETRACTED, status UNPROVEN; signature 1 (SMT buys nothing) VOID as evidence (A and B both at 0 spare = shared artificial ceiling), signature 3 (throughput tracks physical cores) REFUTED (D 12-phys 20.76 < B 8-phys 21.00), signature 2 (52% idle => memory-starved) replaced by simpler unbanked account (CPU/GPU phase alternation per layer explains both 52% CPU stall and 65% GPU idle). (2) The section 20c TRACK SCORING RULE (bytes from system RAM per token) is STRUCK — resting on nothing. (3) Six legs separate PERFECTLY on SPARE CPU CAPACITY (avail logical minus compute threads): 0 spare = 20.32-21.00, 2+ spare = 23.94-23.99, ratio 1.154, zero overlap, not core count/thread count/SMT/pinning; spare-capacity mechanism banked as HYPOTHESIS ONLY with decisive control pre-registered (H: pinned all-20 t18 -> H~24 spares the hypothesis, H~21 kills it; I: 2 spare inside small mask, predicted 22-23; J: unpinned t19 = 1 spare, predicted ~23.5); nothing downstream may cite it until the control returns. (4) OPERATIONAL: ship -t 16 unpinned (ties t18 at ~24, keeps 4 CPUs margin vs the 15% cliff at t20; robustness decides between tied configs). (5) ARM 005 unchanged ~1.14x BLOCKED; bandwidth support retracted; rests on measured per-layer number + structural GPU idle; residency figure measured inside good cluster, uncontaminated. (6) D1/D2 gates held mechanically first outing (builder commended). OWNER: best stock ~23.99 vs 14.39 = 1.67x unchanged.", "rationale": "Two banked conclusions retracted in two rounds share one root cause: mechanisms banked before their test. The retraction is paired with the replacement discipline — sort the full leg set by candidate variables before drawing pair signatures, and bank hypotheses only with their decisive control pre-registered. The scoring rule is struck because a wrong steering rule costs years, not runs.", "source": "leader", "irreversible": false, "author": "architect-2731baf3/owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-8fa4b900c9', 'p-7719544617', 't-d1cf43b723', '2026-09-19T01:15:49.216Z', 'Section 20f banked (507ab5d0f, 2026-09-19T08:15:18+07:00, pre-registration BEFORE dispatch): OWNER DECISIONS binding — (1) reduced 3-point n-cpu-moe residency sweep APPROVED (L1=48/0 resident anchor, L2=36/12 resident, L3=lowest-that-fits via VRAM probe; all -t 16 unpinned, context+batch IDENTICAL across legs or STOP; same-session rule, no reuse of earlier t40/t48 numbers), (2) config wins (threads + topology) DO NOT LAND until after the sweep — standing item. Pre-registered verdicts by slope_2/slope_1: LINEAR 0.75-1.25 -> 1.14x stands, arm BLOCKED; SUBLINEAR <0.75 -> extrapolation dishonest, ARM 005 KILLED not blocked (committed in advance); SUPERLINEAR >1.25 -> arm worth more than 1.14x. Prediction: LINEAR slope 0.15-0.25; secondary falsifiable: L3 fastest else residency saturates below VRAM limit. SCOPE LIMIT on record: sweep validates LAYER-residency extrapolation only — the h=0.4207 expert-transfer remains an untested assumption.', 'Three points is the minimum for a linearity verdict and answers the honesty question without locating the VRAM optimum; the owner reduced rig time to the decisive measurement. Committing the KILL condition in the bank before the data prevents post-hoc softening.', 'leader', 0, 'owner-via-architect-2731baf3', '{"id": "d-8fa4b900c9", "ts": "2026-09-19T01:15:49.216Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Section 20f banked (507ab5d0f, 2026-09-19T08:15:18+07:00, pre-registration BEFORE dispatch): OWNER DECISIONS binding — (1) reduced 3-point n-cpu-moe residency sweep APPROVED (L1=48/0 resident anchor, L2=36/12 resident, L3=lowest-that-fits via VRAM probe; all -t 16 unpinned, context+batch IDENTICAL across legs or STOP; same-session rule, no reuse of earlier t40/t48 numbers), (2) config wins (threads + topology) DO NOT LAND until after the sweep — standing item. Pre-registered verdicts by slope_2/slope_1: LINEAR 0.75-1.25 -> 1.14x stands, arm BLOCKED; SUBLINEAR <0.75 -> extrapolation dishonest, ARM 005 KILLED not blocked (committed in advance); SUPERLINEAR >1.25 -> arm worth more than 1.14x. Prediction: LINEAR slope 0.15-0.25; secondary falsifiable: L3 fastest else residency saturates below VRAM limit. SCOPE LIMIT on record: sweep validates LAYER-residency extrapolation only — the h=0.4207 expert-transfer remains an untested assumption.", "rationale": "Three points is the minimum for a linearity verdict and answers the honesty question without locating the VRAM optimum; the owner reduced rig time to the decisive measurement. Committing the KILL condition in the bank before the data prevents post-hoc softening.", "source": "leader", "irreversible": false, "author": "owner-via-architect-2731baf3"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-7edb0d6e29', 'p-7719544617', 't-d1cf43b723', '2026-09-19T01:28:07.051Z', 'OWNER DIRECTIVE (banked 42e863a29, 2026-09-19T08:27:39+07:00): GOAL REASSERTED — the track optimizes the MoE; the 3060 is the MAIN TEST TARGET. 5060 Ti AND P100 approved for test legs. The single-GPU 5060-Ti config (23.99 tok/s, -t 16 unpinned) is acknowledged as nice but is NOT the destination — landing it as-is would exclude the 3060 the epic exists to exploit (COMBINED/expert-split). All §20-era measurements stand as single-GPU reference only; the thread/spare-CPU rule is topology-orthogonal. Successor arms (ARM 005 successor included) must be designed and measured with the 3060 in the compute loop; architect tasked with the 3060-in-loop arm design (candidate frame: multi-GPU expert-coverage pool with expert pinning per the coverage model).', 'The epics purpose is heterogeneous multi-GPU MoE (per architecture docs: 5060 Ti + 3060 wired for COMBINED engine mode). A single-GPU optimum that removes the 3060 optimizes the wrong objective; the owner redirected before the track mistook the config win for the goal.', 'leader', 0, 'owner-directive', '{"id": "d-7edb0d6e29", "ts": "2026-09-19T01:28:07.051Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "OWNER DIRECTIVE (banked 42e863a29, 2026-09-19T08:27:39+07:00): GOAL REASSERTED — the track optimizes the MoE; the 3060 is the MAIN TEST TARGET. 5060 Ti AND P100 approved for test legs. The single-GPU 5060-Ti config (23.99 tok/s, -t 16 unpinned) is acknowledged as nice but is NOT the destination — landing it as-is would exclude the 3060 the epic exists to exploit (COMBINED/expert-split). All §20-era measurements stand as single-GPU reference only; the thread/spare-CPU rule is topology-orthogonal. Successor arms (ARM 005 successor included) must be designed and measured with the 3060 in the compute loop; architect tasked with the 3060-in-loop arm design (candidate frame: multi-GPU expert-coverage pool with expert pinning per the coverage model).", "rationale": "The epics purpose is heterogeneous multi-GPU MoE (per architecture docs: 5060 Ti + 3060 wired for COMBINED engine mode). A single-GPU optimum that removes the 3060 optimizes the wrong objective; the owner redirected before the track mistook the config win for the goal.", "source": "leader", "irreversible": false, "author": "owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e158cc205d', 'p-7719544617', 't-d1cf43b723', '2026-09-19T01:28:55.818Z', 'OWNER CADENCE DIRECTIVE (2026-09-19): quieter leader-architect communication — no routine acks/confirmations between architect and leader (the bank is visible via git; read-backs happen only when the architect explicitly requests sha+timestamp); 6-min lead CHECKUP ticks act ONLY on blocking questions (no routine consults, no chatter); the 24-min DEEP tick carries the summary check/rebuild and lesson reconciliation as before. Substantive architect exchanges remain: rulings in, raw yields out, arm designs, and owner-directed escalations.', 'Owner directive: reduce message volume between leader and consult to substantive-only; keep the quiet-tick discipline already in force and keep summary maintenance on the deep tick cadence.', 'leader', 0, 'owner-directive', '{"id": "d-e158cc205d", "ts": "2026-09-19T01:28:55.818Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "OWNER CADENCE DIRECTIVE (2026-09-19): quieter leader-architect communication — no routine acks/confirmations between architect and leader (the bank is visible via git; read-backs happen only when the architect explicitly requests sha+timestamp); 6-min lead CHECKUP ticks act ONLY on blocking questions (no routine consults, no chatter); the 24-min DEEP tick carries the summary check/rebuild and lesson reconciliation as before. Substantive architect exchanges remain: rulings in, raw yields out, arm designs, and owner-directed escalations.", "rationale": "Owner directive: reduce message volume between leader and consult to substantive-only; keep the quiet-tick discipline already in force and keep summary maintenance on the deep tick cadence.", "source": "leader", "irreversible": false, "author": "owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1c38e00d92', 'p-7719544617', 't-d1cf43b723', '2026-09-19T01:39:16.273Z', 'OWNER RIG-TIME GRANTED for ARM 007 Stage 1 (2026-09-19, post-§21): dispatch authorized. Stage 1 = zero-code 3060-in-loop expert pool via -ot (12 expert layers CUDA1, 10 CUDA0, 26 CPU; 45.8% coverage), same-session matched control at the single-GPU reference, -t16 vs -t14 spare-threshold check (P3), full §21 Part D protocol (D1/D2 gates, serve-probe not boot-probe, per-device VRAM + sm%, context identical or STOP). Pre-registration §21 Part C governs: >=25.5 confirms, 23.9-25.5 weak pass, <23.9 kills the multi-GPU thesis. Config-wins landing deferred until after Stage 1 (land once).', 'Owner granted rig time after the architect recommendation to run Stage 1 before landing config wins (land once, not twice).', 'leader', 0, 'owner-directive', '{"id": "d-1c38e00d92", "ts": "2026-09-19T01:39:16.273Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "OWNER RIG-TIME GRANTED for ARM 007 Stage 1 (2026-09-19, post-§21): dispatch authorized. Stage 1 = zero-code 3060-in-loop expert pool via -ot (12 expert layers CUDA1, 10 CUDA0, 26 CPU; 45.8% coverage), same-session matched control at the single-GPU reference, -t16 vs -t14 spare-threshold check (P3), full §21 Part D protocol (D1/D2 gates, serve-probe not boot-probe, per-device VRAM + sm%, context identical or STOP). Pre-registration §21 Part C governs: >=25.5 confirms, 23.9-25.5 weak pass, <23.9 kills the multi-GPU thesis. Config-wins landing deferred until after Stage 1 (land once).", "rationale": "Owner granted rig time after the architect recommendation to run Stage 1 before landing config wins (land once, not twice).", "source": "leader", "irreversible": false, "author": "owner-directive"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-e69f76837e', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-19T06:41:52.620Z', 'Owner approved: new repo ddvnguyen/expert-metrics (schema+tools+data, runs+artifacts granularity) records expert analysis — Colibri probe metrics, REAP saliency, Edge0 prerouter predictability; atlas-web Brain gains a Metrics panel fed by experts.json schema v2 (single artifact, honest not-wired badges for unwired observers).', 'Owner directive with 3 options confirmed (repo scope, granularity, display). Seeded with the live P100 honest-OFF run (30 probes); validator enforces honest-state + engine-id refusal; fork analyze.py emits schema v2 (63f0cb4bb); atlas-web Metrics panel + ?engine= UI wiring + 504 fix (f0f8a80a3).', 'leader', 0, 'ddvnguyen', '{"id": "d-e69f76837e", "ts": "2026-09-19T06:41:52.620Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "Owner approved: new repo ddvnguyen/expert-metrics (schema+tools+data, runs+artifacts granularity) records expert analysis — Colibri probe metrics, REAP saliency, Edge0 prerouter predictability; atlas-web Brain gains a Metrics panel fed by experts.json schema v2 (single artifact, honest not-wired badges for unwired observers).", "rationale": "Owner directive with 3 options confirmed (repo scope, granularity, display). Seeded with the live P100 honest-OFF run (30 probes); validator enforces honest-state + engine-id refusal; fork analyze.py emits schema v2 (63f0cb4bb); atlas-web Metrics panel + ?engine= UI wiring + 504 fix (f0f8a80a3).", "source": "leader", "irreversible": false, "author": "ddvnguyen"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6259fd2bed', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-19T13:15:37.721Z', '[carryover d-dfb6707bc7/d-075e1e3b9c/d-1849d2b80a] New atlas engine build: cherry-pick Stage B (938fe8f1d) + topk stash (86af0c9af) from fork/hydra-771-colibri-atlas onto efd26f235, then implement Stage A counters (HYDRA_EXPERT_STATS, per-layer expert counts/heat from t_moe_topk, decode-only, MTP-excluded) as new fork-local code. Deploy to /home/vm1/atlas-sm60 with user unit hydra-atlas-engine. Alternative fresh-rewrite rejected: re-invents working geometry.', '', 'leader', 0, '', '{"id": "d-6259fd2bed", "ts": "2026-09-19T13:15:37.721Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[carryover d-dfb6707bc7/d-075e1e3b9c/d-1849d2b80a] New atlas engine build: cherry-pick Stage B (938fe8f1d) + topk stash (86af0c9af) from fork/hydra-771-colibri-atlas onto efd26f235, then implement Stage A counters (HYDRA_EXPERT_STATS, per-layer expert counts/heat from t_moe_topk, decode-only, MTP-excluded) as new fork-local code. Deploy to /home/vm1/atlas-sm60 with user unit hydra-atlas-engine. Alternative fresh-rewrite rejected: re-invents working geometry.", "rationale": "", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a8363cd8eb', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-19T16:50:50.169Z', 'Owner-directed handoff: gaps (1. live routing hits all-zero - no Stage-A telemetry; 2. experts.json 404 - no atlas artifact for real engine) filed as hydra_vortex#783 with evidence + collision-file constraint + acceptance criteria; implementation handed to agent dc1874da (paseo, muse-spark) with full work order.', 'Both gaps funnel into Stage-A telemetry which was blocked by the narrowed Gate 0 collision set; the handoff explicitly requires a collision-free design or owner sign-off before touching llama-graph/context files.', 'leader', 0, 'ddvnguyen', '{"id": "d-a8363cd8eb", "ts": "2026-09-19T16:50:50.169Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "Owner-directed handoff: gaps (1. live routing hits all-zero - no Stage-A telemetry; 2. experts.json 404 - no atlas artifact for real engine) filed as hydra_vortex#783 with evidence + collision-file constraint + acceptance criteria; implementation handed to agent dc1874da (paseo, muse-spark) with full work order.", "rationale": "Both gaps funnel into Stage-A telemetry which was blocked by the narrowed Gate 0 collision set; the handoff explicitly requires a collision-free design or owner sign-off before touching llama-graph/context files.", "source": "leader", "irreversible": false, "author": "ddvnguyen"}');
