INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-2a650552cc', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-20T05:24:01.801Z', '[owner ruling 2026-09-20] #787 epic: leader owns branch+dispatch execution; owner gates merge to main and verifies implement on epic. Epic branch work may proceed; main stays owner-gated.', 'Owner answer to grill: leader''s call on epic execution; merge-to-main + implement verification stay owner-gated.', 'owner-directive', 0, '', '{"id": "d-2a650552cc", "ts": "2026-09-20T05:24:01.801Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[owner ruling 2026-09-20] #787 epic: leader owns branch+dispatch execution; owner gates merge to main and verifies implement on epic. Epic branch work may proceed; main stays owner-gated.", "rationale": "Owner answer to grill: leader''s call on epic execution; merge-to-main + implement verification stay owner-gated.", "source": "owner-directive", "irreversible": false, "author": ""}');
