INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6f5910f718', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-20T05:24:10.166Z', 'Unblock S-C3 via REAP-observer route (option b) while Gate 0 stays closed', 'Gate 0 has held S-A1/S-A2 (and with them real spectra + LOP run + S-C2 completion) for 2.5+ hours of ticks; Stage-1 dual-op store landing time is outside this track control. Zero-collision alternative for S-C3 (multi-domain atlas): run the REAP-style offline observer on the HF checkpoint (design doc section 9) — CPU-only, touches no llama.cpp files, no Gate 0 dependency, produces draft multi-domain expert-ranks for the atlas-web Brain while Stage-1 matures. Owner decision needed: approve REAP-observer run now (est. several hours CPU on the 35B HF checkpoint) or keep strict stage order (C3 waits for multi-domain real spectra). Recommend approving: it de-risks the atlas-web demo path and gives validate.py real-ish spectra to chew on.', 'leader', 0, '34364388-dca6-49d4-a643-0d4c161825d0', '{"id": "d-6f5910f718", "ts": "2026-09-20T05:24:10.166Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "Unblock S-C3 via REAP-observer route (option b) while Gate 0 stays closed", "rationale": "Gate 0 has held S-A1/S-A2 (and with them real spectra + LOP run + S-C2 completion) for 2.5+ hours of ticks; Stage-1 dual-op store landing time is outside this track control. Zero-collision alternative for S-C3 (multi-domain atlas): run the REAP-style offline observer on the HF checkpoint (design doc section 9) — CPU-only, touches no llama.cpp files, no Gate 0 dependency, produces draft multi-domain expert-ranks for the atlas-web Brain while Stage-1 matures. Owner decision needed: approve REAP-observer run now (est. several hours CPU on the 35B HF checkpoint) or keep strict stage order (C3 waits for multi-domain real spectra). Recommend approving: it de-risks the atlas-web demo path and gives validate.py real-ish spectra to chew on.", "source": "leader", "irreversible": false, "author": "34364388-dca6-49d4-a643-0d4c161825d0"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1ac7080fdb', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-20T05:24:14.458Z', '[owner ruling 2026-09-20] S-C3 EAN: dispatch now (not tied to #787 completion). Dispatch order: S-C3 EAN instrument + approved REAP observer + #786 predictor work per consult plan; #787 epic branch setup runs in parallel.', 'Owner: dispatch S-C3 now; leader''s call on epic execution.', 'owner-directive', 0, '', '{"id": "d-1ac7080fdb", "ts": "2026-09-20T05:24:14.458Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[owner ruling 2026-09-20] S-C3 EAN: dispatch now (not tied to #787 completion). Dispatch order: S-C3 EAN instrument + approved REAP observer + #786 predictor work per consult plan; #787 epic branch setup runs in parallel.", "rationale": "Owner: dispatch S-C3 now; leader''s call on epic execution.", "source": "owner-directive", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-6c28825d1a', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-20T05:47:52.707Z', '[consult handoff 2026-09-20] #788 filed: per-expert EMAP tier false for llama.cpp — counted experts hardcoded tier 1 (RAM), never-counted tier 0 (Disk); live VM decode under -ngl 99 shows {1:8918, 0:1578} vs truth {2:10496}. Fix: tier from model-load residency (device=2, n-cpu-moe covered=1, Disk unused), all cells regardless of heat, honest-omit fallback. #785 covers aggregate /health only. Routing: #785 agent dc1874da natural owner (already in server-atlas.cpp) — leader decides dispatch.', 'Architect consult handoff per owner directive; defect verified with live VM evidence; fix is server-layer, no collision files.', 'leader', 0, '', '{"id": "d-6c28825d1a", "ts": "2026-09-20T05:47:52.707Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[consult handoff 2026-09-20] #788 filed: per-expert EMAP tier false for llama.cpp — counted experts hardcoded tier 1 (RAM), never-counted tier 0 (Disk); live VM decode under -ngl 99 shows {1:8918, 0:1578} vs truth {2:10496}. Fix: tier from model-load residency (device=2, n-cpu-moe covered=1, Disk unused), all cells regardless of heat, honest-omit fallback. #785 covers aggregate /health only. Routing: #785 agent dc1874da natural owner (already in server-atlas.cpp) — leader decides dispatch.", "rationale": "Architect consult handoff per owner directive; defect verified with live VM evidence; fix is server-layer, no collision files.", "source": "leader", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-54c2927769', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-20T05:50:38.776Z', '[gate clarification 2026-09-20, consult -> leader] #783 collision-protocol sign-off authority is OWNER, not consult. Consult role on Edge0 capture gate is PRE-REVIEW: worker posts proposal on issue + pings consult; consult returns architecture review (capture-point soundness, honest-state, schema impact) fast so owner decision is one read. Edge0 task parks on OWNER sign-off, not on consult.', 'Prevent stall from misrouting Edge0 gate onto consult; consult explicitly declined gate ownership and defined pre-review lane.', 'leader', 0, '', '{"id": "d-54c2927769", "ts": "2026-09-20T05:50:38.776Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[gate clarification 2026-09-20, consult -> leader] #783 collision-protocol sign-off authority is OWNER, not consult. Consult role on Edge0 capture gate is PRE-REVIEW: worker posts proposal on issue + pings consult; consult returns architecture review (capture-point soundness, honest-state, schema impact) fast so owner decision is one read. Edge0 task parks on OWNER sign-off, not on consult.", "rationale": "Prevent stall from misrouting Edge0 gate onto consult; consult explicitly declined gate ownership and defined pre-review lane.", "source": "leader", "irreversible": false, "author": ""}');
