INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-fcd33a56fa', 'p-58c3ab092b', 't-d94162d3f0', '2026-09-20T11:50:05.832Z', '[consult verify 2026-09-20] S-A2 0660735d6 REJECTED narrowly: FLAG1 branch ACCEPT (clean descendant of 696e222d4, FF-merge into epic/787-per-turn-telemetry, do NOT push new branch; one-epic-branch rule); FLAG2 triples ACCEPT as superseded (no consumer reads .coli_usage, analyze.py uses .route; flush+reset+sidecar covers function; rider: README line stating subsumption); FLAG3 outdir REJECTED blocking (engine defaults HYDRA_CAPTURE_OUTDIR to ''.'' at startup; sweep.sh SIDECAR_DIR=$OUT/sidecars never exported/verified -> E2E broken by default; fix a/b/c: flush echoes path + sweep fails loudly, or sweep refuses sidecar mode w/o outdir confirm, or README hard-require export + sweep validates); GATE independently VERIFIED (diff + runtime: capture_enabled guards block, capture_hidden early-return, reset clears, real build no-env -> flush 503 zero files; dump format matches load_sidecars exactly); capture leg UNVERIFIED-live (no supported MoE GGUF on host; 35B-A3B VM-only; S-E1 P100 live leg must run build-at-merged-SHA/sm60/capture-on/decode/flush/analyze unmodified); non-blocking: 2 comment-only edits rode along (keep next commit clean). After one-file fix: merge-ready; do NOT merge before FLAG3 fixed.', '', 'consult', 0, '', '{"id": "d-fcd33a56fa", "ts": "2026-09-20T11:50:05.832Z", "track_id": "t-d94162d3f0", "project_id": "p-58c3ab092b", "decision": "[consult verify 2026-09-20] S-A2 0660735d6 REJECTED narrowly: FLAG1 branch ACCEPT (clean descendant of 696e222d4, FF-merge into epic/787-per-turn-telemetry, do NOT push new branch; one-epic-branch rule); FLAG2 triples ACCEPT as superseded (no consumer reads .coli_usage, analyze.py uses .route; flush+reset+sidecar covers function; rider: README line stating subsumption); FLAG3 outdir REJECTED blocking (engine defaults HYDRA_CAPTURE_OUTDIR to ''.'' at startup; sweep.sh SIDECAR_DIR=$OUT/sidecars never exported/verified -> E2E broken by default; fix a/b/c: flush echoes path + sweep fails loudly, or sweep refuses sidecar mode w/o outdir confirm, or README hard-require export + sweep validates); GATE independently VERIFIED (diff + runtime: capture_enabled guards block, capture_hidden early-return, reset clears, real build no-env -> flush 503 zero files; dump format matches load_sidecars exactly); capture leg UNVERIFIED-live (no supported MoE GGUF on host; 35B-A3B VM-only; S-E1 P100 live leg must run build-at-merged-SHA/sm60/capture-on/decode/flush/analyze unmodified); non-blocking: 2 comment-only edits rode along (keep next commit clean). After one-file fix: merge-ready; do NOT merge before FLAG3 fixed.", "rationale": "", "source": "consult", "irreversible": false, "author": ""}');
