INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-9ebe94d3aa', 'p-7719544617', 't-d1cf43b723', '2026-09-21T13:57:39.385Z', '§121 accepted: implement demand-gated admission (B) on baseline-flash-next. Declined runbook Paseo/omp spawns (owner directive 2026-09-21 outranks runbook v1.7.0); no new leader heartbeats created (not a Paseo agent; existing checkup ec1a7d54/deep 1a2d3006 flagged not-stale).', 'Owner standing grant: full rig time + implement freely; only gate = merge epic into main. Work done in-session.', 'owner-directive', 0, 'claude-sonnet5-lead-20260921', '{"id": "d-9ebe94d3aa", "ts": "2026-09-21T13:57:39.385Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "§121 accepted: implement demand-gated admission (B) on baseline-flash-next. Declined runbook Paseo/omp spawns (owner directive 2026-09-21 outranks runbook v1.7.0); no new leader heartbeats created (not a Paseo agent; existing checkup ec1a7d54/deep 1a2d3006 flagged not-stale).", "rationale": "Owner standing grant: full rig time + implement freely; only gate = merge epic into main. Work done in-session.", "source": "owner-directive", "irreversible": false, "author": "claude-sonnet5-lead-20260921"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f1f12ad4e5', 'p-7719544617', 't-d1cf43b723', '2026-09-21T19:09:58.913Z', 'Section 125: do NOT accept Gen1-fitted I=45-57 as break-even input; neither build Option A nor shelve until I is identified (Gen4 rerun). Prefill collapse reopened only as free rider on post-fix rerun. Route 3060 link retrain to owner.', 'At Gen1 the slope term (587 ms) dwarfs I (~52), so the intercept is barely identified; the 123 shelve rule assumed a measured ceiling.', 'consult', 0, '', '{"id": "d-f1f12ad4e5", "ts": "2026-09-21T19:09:58.913Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Section 125: do NOT accept Gen1-fitted I=45-57 as break-even input; neither build Option A nor shelve until I is identified (Gen4 rerun). Prefill collapse reopened only as free rider on post-fix rerun. Route 3060 link retrain to owner.", "rationale": "At Gen1 the slope term (587 ms) dwarfs I (~52), so the intercept is barely identified; the 123 shelve rule assumed a measured ceiling.", "source": "consult", "irreversible": false, "author": ""}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-556c6cc692', 'p-7719544617', 't-d1cf43b723', '2026-09-23T04:04:38.012Z', '[owner directive 2026-09-23] Colibri track t-d94162d3f0 folded into baseline-flash-next. Fork branch feat/flash-next-colibri (ee13fdaa6) = a2c46384b + 16 Colibri commits 86af0c9af..35f83661c (topk outputs, Stage A/B/C, #783/#785/#786/#787.1/#788, S-A2). Stage B RPC 0x33 NOT ported (lineage has no Hydra RPC listener); HTTP GET /experts kept. Parent branch feat/flash-next-colibri (4a6614cc8) = bcba9fc43 + merge origin/epic/787-per-turn-telemetry, tools/atlas taken from Colibri (reproduce.py PASS), submodule -> ee13fdaa6. node-p100.yaml S-E1 hunk (prod telemetry ON + MTP model swap) held back for owner. Unbuilt: CUDA build + OFF-parity pending until no rig measurement in flight.', 'Owner: ''with data from Colibri we will able optimize llama.cpp ranking experts better''. Cherry-pick not branch merge because epic/787 carries 109 baseline-qwen4exp-mtp lineage commits we deliberately left.', 'consult', 0, 'claude-opus-5.5-consult', '{"id": "d-556c6cc692", "ts": "2026-09-23T04:04:38.012Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "[owner directive 2026-09-23] Colibri track t-d94162d3f0 folded into baseline-flash-next. Fork branch feat/flash-next-colibri (ee13fdaa6) = a2c46384b + 16 Colibri commits 86af0c9af..35f83661c (topk outputs, Stage A/B/C, #783/#785/#786/#787.1/#788, S-A2). Stage B RPC 0x33 NOT ported (lineage has no Hydra RPC listener); HTTP GET /experts kept. Parent branch feat/flash-next-colibri (4a6614cc8) = bcba9fc43 + merge origin/epic/787-per-turn-telemetry, tools/atlas taken from Colibri (reproduce.py PASS), submodule -> ee13fdaa6. node-p100.yaml S-E1 hunk (prod telemetry ON + MTP model swap) held back for owner. Unbuilt: CUDA build + OFF-parity pending until no rig measurement in flight.", "rationale": "Owner: ''with data from Colibri we will able optimize llama.cpp ranking experts better''. Cherry-pick not branch merge because epic/787 carries 109 baseline-qwen4exp-mtp lineage commits we deliberately left.", "source": "consult", "irreversible": false, "author": "claude-opus-5.5-consult"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-74484fc66d', 'p-7719544617', 't-d1cf43b723', '2026-09-23T13:01:57.156Z', 'Owner directed: act as leader, orchestrate more, delegate implementation to dev agents rather than doing it myself. Corrected two contract gaps: (1) missing [#Leader] reply prefix (binding per owner 2026-09-15), now applied; (2) dispatching implementation via the generic Agent tool / ad-hoc SendMessage instead of Paseo (create_agent/send_agent_prompt), which the leader runbook marks dispatch-only-by-paseo (binding per owner 2026-09-15). The prior ad-hoc dev agent (a356ff8cbfe63bf44) was stopped by the owner and not resumed. Replacement dev work now dispatched via fleet_recommend/fleet_spawn_spec/create_agent (dev position e7827231, opencode/muse-spark-1.3-contributor-free).', '', 'owner-directive', 0, '', '{"id": "d-74484fc66d", "ts": "2026-09-23T13:01:57.156Z", "track_id": "t-d1cf43b723", "project_id": "p-7719544617", "decision": "Owner directed: act as leader, orchestrate more, delegate implementation to dev agents rather than doing it myself. Corrected two contract gaps: (1) missing [#Leader] reply prefix (binding per owner 2026-09-15), now applied; (2) dispatching implementation via the generic Agent tool / ad-hoc SendMessage instead of Paseo (create_agent/send_agent_prompt), which the leader runbook marks dispatch-only-by-paseo (binding per owner 2026-09-15). The prior ad-hoc dev agent (a356ff8cbfe63bf44) was stopped by the owner and not resumed. Replacement dev work now dispatched via fleet_recommend/fleet_spawn_spec/create_agent (dev position e7827231, opencode/muse-spark-1.3-contributor-free).", "rationale": "", "source": "owner-directive", "irreversible": false, "author": ""}');
