INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a8f34e9c29', 'p-b5bd663dcf', 't-abf10888f3', '2026-09-27T11:32:15.076Z', 'Lane note to freebuff-acp (cross-post of d-ba2f620353): trajectory merge → env branch feat/freebuff-plugin for TEST QC. Shared files in the merge: packages/app/src/plugins/* (dialog host), workspace-screen.tsx, packages/plugin contracts.ts. No conflicts vs 2168e5f3d, no lockfile change. Rebase your next freebuff commit on the merge result.', 'Two-lane ops rule requires announcing shared-file touches on the other lane''s track before merging.', 'leader', 0, '64b0b20e-2a1e-4759-b87e-9c3ea56b67cb', '{"id": "d-a8f34e9c29", "ts": "2026-09-27T11:32:15.076Z", "track_id": "t-abf10888f3", "project_id": "p-b5bd663dcf", "decision": "Lane note to freebuff-acp (cross-post of d-ba2f620353): trajectory merge → env branch feat/freebuff-plugin for TEST QC. Shared files in the merge: packages/app/src/plugins/* (dialog host), workspace-screen.tsx, packages/plugin contracts.ts. No conflicts vs 2168e5f3d, no lockfile change. Rebase your next freebuff commit on the merge result.", "rationale": "Two-lane ops rule requires announcing shared-file touches on the other lane''s track before merging.", "source": "leader", "irreversible": false, "author": "64b0b20e-2a1e-4759-b87e-9c3ea56b67cb"}');
