INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-893c722f28', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-09-27T15:57:58.137Z', 'C3 design APPROVED with leader calls on the 3 delegated questions: (Q1 surface) = Option A timeline chip via addTimelineRenderer + timeline.append — matches the owner''s task wording "in the chat view", fleet-proven, plugin-first, core-edit option D rejected; must carry the C2b flex fix (fleet''s chip ships flexShrink:1 WITHOUT minWidth:0 — verbatim reuse would reintroduce the web overflow). (Q2 preview privacy) = length + hash + MCP-names ONLY, NO stored 200-char preview — diverges from fleet issue #46''s in-memory preview contract because under option A the row becomes persisted+relayed chat history; aligns with this lane''s owner-approved T1 convention (prompt/text stored as length only, shared/fold.ts). Reversible pre-code choice; owner may override to restore a preview. (Q3 localization) = plugin-local i18n with a small locale map, English content initially — matches repo i18n convention without a core change (plugins can''t reach the app bundle). Also noted as design facts: the true effective daemon prompt is unobservable to plugins (reference.md:601-608 ordering) so the tooltip must say configured-context-not-complete; unknowns render ''—'', never fabricated; 2-stage capture (pendingCreateFacts 60s TTL correlate) per fleet''s ctx-capture pattern.', 'All three are reversible pre-code implementation choices within the announced plugin-first scope; Q2 resolves a contract tension in favor of this repo''s existing owner-approved privacy convention.', 'leader', 0, '64b0b20e-2a1e-4759-b87e-9c3ea56b67cb', '{"id": "d-893c722f28", "ts": "2026-09-27T15:57:58.137Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "C3 design APPROVED with leader calls on the 3 delegated questions: (Q1 surface) = Option A timeline chip via addTimelineRenderer + timeline.append — matches the owner''s task wording \"in the chat view\", fleet-proven, plugin-first, core-edit option D rejected; must carry the C2b flex fix (fleet''s chip ships flexShrink:1 WITHOUT minWidth:0 — verbatim reuse would reintroduce the web overflow). (Q2 preview privacy) = length + hash + MCP-names ONLY, NO stored 200-char preview — diverges from fleet issue #46''s in-memory preview contract because under option A the row becomes persisted+relayed chat history; aligns with this lane''s owner-approved T1 convention (prompt/text stored as length only, shared/fold.ts). Reversible pre-code choice; owner may override to restore a preview. (Q3 localization) = plugin-local i18n with a small locale map, English content initially — matches repo i18n convention without a core change (plugins can''t reach the app bundle). Also noted as design facts: the true effective daemon prompt is unobservable to plugins (reference.md:601-608 ordering) so the tooltip must say configured-context-not-complete; unknowns render ''—'', never fabricated; 2-stage capture (pendingCreateFacts 60s TTL correlate) per fleet''s ctx-capture pattern.", "rationale": "All three are reversible pre-code implementation choices within the announced plugin-first scope; Q2 resolves a contract tension in favor of this repo''s existing owner-approved privacy convention.", "source": "leader", "irreversible": false, "author": "64b0b20e-2a1e-4759-b87e-9c3ea56b67cb"}');
