INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a71c7c0748', 'p-b5bd663dcf', 't-62504d3c56', '2026-10-03T01:16:43.885Z', 'OWNER RULES 2026-10-03 (two) + EXECUTION + DIAGNOSIS. (1) WORKTREE CONTRACT TIGHTENED: the skill/runbook phrasing ''never git worktree add into /tmp or ad-hoc root-disk paths'' wrongly implied other paths were allowed vs the owner''s latest change request. Now absolute: isolated checkouts ONLY via paseo create_worktree; NEVER git worktree add in ANY location (no path carve-outs). Surfaces aligned: skill rule 5 (hardlinked, live now), runbook principle (v1.10.0, serves at owner-gated backend restart), hermes hermes-lead-template references/shared-worktree.md source + install-contracts.sh re-run (pointer mode; references read from source). (2) TURN_REPORT CAP RULING: 1000 tokens OK, leaders aim ~500. config TURN_DELTA_TOKEN_MAX 300->1000, runbook budgets+END step, skill closing line, DESIGN.md:220, reporting hint de-hardcoded to interpolate config (frozen-copies lesson applied); overflow test scaled (5400/7200 chars); version pins to 1.10.0 (test_doc_sync + test_leader x3). Suite 533 green after changes. (3) b7bec94b MISSING-TOOL REPORT DIAGNOSED: cwd worktrees/paseo-trajectory had no .mcp.json (not a registered git worktree; paseo-created worktrees get it provisioned) -> session spawned supportsMcpServers=false -> REST fallback (sanctioned by skill). Provisioned main .mcp.json there (4 servers incl. orchestration); notified the agent: current session MCP is spawn-time, respawn restores tools. (4) LIVE SQLITE EVOLVED: orchestration.sqlite already carries note+detail_amendments (E''s ensure-column fired via a new-code session Store open - old backend process from Oct 1 unaffected, schema additive, all 11 prior cols intact); live-sqlite rehearsal test re-aimed: normalize copy to pre-migration shape (DROP the two cols on the copy) + live-untouched check upgraded to sha256 byte equality. (5) QUIET COMPLIANCE FIX: lean-tick template drops quota FIGURES entirely (binding: owner 2026-10-01 - availability usable/not-usable only; prior ticks reported percentages, corrected now).', 'Owner messaged the three rulings directly 2026-10-03; defects (worktree carve-out, b7bec94b MCP, cap drift) verified by probe before each fix; suite re-run green (533).', 'owner-directive', 0, '4774f61c-0dca-4331-9a91-46e0ee32b238', '{"id": "d-a71c7c0748", "ts": "2026-10-03T01:16:43.885Z", "track_id": "t-62504d3c56", "project_id": "p-b5bd663dcf", "decision": "OWNER RULES 2026-10-03 (two) + EXECUTION + DIAGNOSIS. (1) WORKTREE CONTRACT TIGHTENED: the skill/runbook phrasing ''never git worktree add into /tmp or ad-hoc root-disk paths'' wrongly implied other paths were allowed vs the owner''s latest change request. Now absolute: isolated checkouts ONLY via paseo create_worktree; NEVER git worktree add in ANY location (no path carve-outs). Surfaces aligned: skill rule 5 (hardlinked, live now), runbook principle (v1.10.0, serves at owner-gated backend restart), hermes hermes-lead-template references/shared-worktree.md source + install-contracts.sh re-run (pointer mode; references read from source). (2) TURN_REPORT CAP RULING: 1000 tokens OK, leaders aim ~500. config TURN_DELTA_TOKEN_MAX 300->1000, runbook budgets+END step, skill closing line, DESIGN.md:220, reporting hint de-hardcoded to interpolate config (frozen-copies lesson applied); overflow test scaled (5400/7200 chars); version pins to 1.10.0 (test_doc_sync + test_leader x3). Suite 533 green after changes. (3) b7bec94b MISSING-TOOL REPORT DIAGNOSED: cwd worktrees/paseo-trajectory had no .mcp.json (not a registered git worktree; paseo-created worktrees get it provisioned) -> session spawned supportsMcpServers=false -> REST fallback (sanctioned by skill). Provisioned main .mcp.json there (4 servers incl. orchestration); notified the agent: current session MCP is spawn-time, respawn restores tools. (4) LIVE SQLITE EVOLVED: orchestration.sqlite already carries note+detail_amendments (E''s ensure-column fired via a new-code session Store open - old backend process from Oct 1 unaffected, schema additive, all 11 prior cols intact); live-sqlite rehearsal test re-aimed: normalize copy to pre-migration shape (DROP the two cols on the copy) + live-untouched check upgraded to sha256 byte equality. (5) QUIET COMPLIANCE FIX: lean-tick template drops quota FIGURES entirely (binding: owner 2026-10-01 - availability usable/not-usable only; prior ticks reported percentages, corrected now).", "rationale": "Owner messaged the three rulings directly 2026-10-03; defects (worktree carve-out, b7bec94b MCP, cap drift) verified by probe before each fix; suite re-run green (533).", "source": "owner-directive", "irreversible": false, "author": "4774f61c-0dca-4331-9a91-46e0ee32b238"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-82938fffe0', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T01:20:16.280Z', 'Owner directives 2026-10-03 enter track record: (1) ''implement limit ctx size default limit to 280K, default is K not M'' -> T10 task-50455802ba, interpreted as placeholder/default-hint ''280 K'' + bare-number=K parse (empty remains No limit per owner''s own T7-F spec; interpretation flagged in task for design-note confirmation); (2) ''prefix model name in opencode is not handled for all sub provider, split into multiple sections with per-sub-provider prefix config'' -> T11 task-a6ae0e82b5.', '', 'owner-directive', 0, 'b7bec94b-5394-453f-987a-6cb49107ad71', '{"id": "d-82938fffe0", "ts": "2026-10-03T01:20:16.280Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "Owner directives 2026-10-03 enter track record: (1) ''implement limit ctx size default limit to 280K, default is K not M'' -> T10 task-50455802ba, interpreted as placeholder/default-hint ''280 K'' + bare-number=K parse (empty remains No limit per owner''s own T7-F spec; interpretation flagged in task for design-note confirmation); (2) ''prefix model name in opencode is not handled for all sub provider, split into multiple sections with per-sub-provider prefix config'' -> T11 task-a6ae0e82b5.", "rationale": "", "source": "owner-directive", "irreversible": false, "author": "b7bec94b-5394-453f-987a-6cb49107ad71"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-bc8144c6ca', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T01:23:06.070Z', 'SHARED-FILE ANNOUNCE (d-12a0c8b77a) for T10: I will edit ONLY packages/app/src/i18n/resources/{ar,en,es,fr,ja,ko,pt-BR,ru,zh-CN}.ts (settings.providers.maxContext.placeholder "100 M" -> "280 K"). NOT touching provider-diagnostic-sheet.tsx — verified it only mounts ProviderMaxContextField with no unit copy, so that shared host file needs no change.', 'i18n resources are a packages/app host surface shared across the lane (T11 also plans 9-locale edits); announcing the exact paths + the fact that the diagnostic sheet is NOT touched keeps T11 from colliding.', 'leader', 0, '556e5438-ddf9-403b-b71f-21eee8e2b5d6', '{"id": "d-bc8144c6ca", "ts": "2026-10-03T01:23:06.070Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "SHARED-FILE ANNOUNCE (d-12a0c8b77a) for T10: I will edit ONLY packages/app/src/i18n/resources/{ar,en,es,fr,ja,ko,pt-BR,ru,zh-CN}.ts (settings.providers.maxContext.placeholder \"100 M\" -> \"280 K\"). NOT touching provider-diagnostic-sheet.tsx — verified it only mounts ProviderMaxContextField with no unit copy, so that shared host file needs no change.", "rationale": "i18n resources are a packages/app host surface shared across the lane (T11 also plans 9-locale edits); announcing the exact paths + the fact that the diagnostic sheet is NOT touched keeps T11 from colliding.", "source": "leader", "irreversible": false, "author": "556e5438-ddf9-403b-b71f-21eee8e2b5d6"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-33fb1d21a9', 'p-b5bd663dcf', 't-ce60b8b8ea', '2026-10-03T01:24:29.757Z', 'drop coder; skip all disabled units; passwordless sudo + key ssh into cachyos-dev authorized', '', 'owner-directive', 0, '19b2b435-4187-465f-bf7d-02d1c9caf2ed', '{"id": "d-33fb1d21a9", "ts": "2026-10-03T01:24:29.757Z", "track_id": "t-ce60b8b8ea", "project_id": "p-b5bd663dcf", "decision": "drop coder; skip all disabled units; passwordless sudo + key ssh into cachyos-dev authorized", "rationale": "", "source": "owner-directive", "irreversible": false, "author": "19b2b435-4187-465f-bf7d-02d1c9caf2ed"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-1d2a916b4d', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T01:25:21.376Z', 'Dispatch hardening for t-f3ba82ac9c (from T10 turn-1 incidents, 2026-10-03): (1) worker turn_report author_agent must be the worker''s OWN paseo id — spawn briefs must state the literal id in the prompt (a spawned opencode agent cannot discover it); (2) fleet dispatch_note items (e.g. MCP_ORCH_TIER=dev) are post-spawn obligations EVEN WHEN not in the post_spawn_steps array; (3) create_workspace baseBranch resolves LOCAL refs — always fetch and base off origin/<branch> for lane worktrees.', '', 'leader', 0, 'b7bec94b-5394-453f-987a-6cb49107ad71', '{"id": "d-1d2a916b4d", "ts": "2026-10-03T01:25:21.376Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "Dispatch hardening for t-f3ba82ac9c (from T10 turn-1 incidents, 2026-10-03): (1) worker turn_report author_agent must be the worker''s OWN paseo id — spawn briefs must state the literal id in the prompt (a spawned opencode agent cannot discover it); (2) fleet dispatch_note items (e.g. MCP_ORCH_TIER=dev) are post-spawn obligations EVEN WHEN not in the post_spawn_steps array; (3) create_workspace baseBranch resolves LOCAL refs — always fetch and base off origin/<branch> for lane worktrees.", "rationale": "", "source": "leader", "irreversible": false, "author": "b7bec94b-5394-453f-987a-6cb49107ad71"}');
