INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-174ddc7eda', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T01:49:11.760Z', 'SHARED-FILE ANNOUNCE (d-12a0c8b77a) — T11 actually touched these host surfaces, superseding the T10 announce which scoped the diagnostic sheet out: packages/protocol/src/messages.ts + provider-config.ts (additive optional modelPrefixes, nullable per-key on the patch entry), packages/server/src/server/daemon-config-store.ts (nested-map delete in both merge paths), packages/app/src/components/provider-diagnostic-sheet.tsx (section per served sub-provider + per-sub save), packages/app/src/composer/agent-controls/index.tsx (fallback tag read), all 9 i18n resource files, docs/custom-providers.md.', 'These are the exact files other lane work may collide on; naming them with what changed lets T12+ sequence safely.', 'leader', 0, '2eb265f4-6ec0-49f5-97f4-52a1a4b161df', '{"id": "d-174ddc7eda", "ts": "2026-10-03T01:49:11.760Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "SHARED-FILE ANNOUNCE (d-12a0c8b77a) — T11 actually touched these host surfaces, superseding the T10 announce which scoped the diagnostic sheet out: packages/protocol/src/messages.ts + provider-config.ts (additive optional modelPrefixes, nullable per-key on the patch entry), packages/server/src/server/daemon-config-store.ts (nested-map delete in both merge paths), packages/app/src/components/provider-diagnostic-sheet.tsx (section per served sub-provider + per-sub save), packages/app/src/composer/agent-controls/index.tsx (fallback tag read), all 9 i18n resource files, docs/custom-providers.md.", "rationale": "These are the exact files other lane work may collide on; naming them with what changed lets T12+ sequence safely.", "source": "leader", "irreversible": false, "author": "2eb265f4-6ec0-49f5-97f4-52a1a4b161df"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-d478886d82', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T02:51:17.463Z', 'SHARED-FILE MERGE ANNOUNCEMENT (lane rule d-12a0c8b77a, announced for t-abf10888f3 visibility): batch merged to env/p0-sdk-integration as 6927d72ac, pushed as origin/feat/freebuff-plugin. Touches SHARED surfaces: packages/protocol (provider-config.ts modelPrefixes additive, messages.ts patch), packages/server (daemon-config-store.ts map-null delete paths), packages/app (provider-diagnostic-sheet.tsx sections, provider-model-prefix-field*, provider-selection, provider-max-context*, 9 i18n locales), pnpm-workspace.yaml. TEST deploy via pipeline 37091169039 now; PROD NOT dispatched (owner approval required). Feature branches pushed for provenance: ci-freebuff-baseline (contains feat/t10-max-context-defaults + feat/t11-subprovider-prefix history).', '', 'leader', 0, 'b7bec94b-5394-453f-987a-6cb49107ad71', '{"id": "d-d478886d82", "ts": "2026-10-03T02:51:17.463Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "SHARED-FILE MERGE ANNOUNCEMENT (lane rule d-12a0c8b77a, announced for t-abf10888f3 visibility): batch merged to env/p0-sdk-integration as 6927d72ac, pushed as origin/feat/freebuff-plugin. Touches SHARED surfaces: packages/protocol (provider-config.ts modelPrefixes additive, messages.ts patch), packages/server (daemon-config-store.ts map-null delete paths), packages/app (provider-diagnostic-sheet.tsx sections, provider-model-prefix-field*, provider-selection, provider-max-context*, 9 i18n locales), pnpm-workspace.yaml. TEST deploy via pipeline 37091169039 now; PROD NOT dispatched (owner approval required). Feature branches pushed for provenance: ci-freebuff-baseline (contains feat/t10-max-context-defaults + feat/t11-subprovider-prefix history).", "rationale": "", "source": "leader", "irreversible": false, "author": "b7bec94b-5394-453f-987a-6cb49107ad71"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-02c802adde', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T04:57:06.239Z', 'Owner directive 2026-10-03: maxContextTokens must be REAL ENFORCEMENT (harness-level constraint at the configured ceiling), chosen explicitly over display-only clamping — prior ''cap'' semantics (registry label, no consumer, no enforcement) are insufficient. Design must include meter truth (display max = min(runtime, cap)) so enforcement is verifiable, and must honestly document non-enforceable harnesses (claude CLI has no known external context-limit knob — to be proven/disproven in Phase A).', '', 'leader', 0, 'b7bec94b-5394-453f-987a-6cb49107ad71', '{"id": "d-02c802adde", "ts": "2026-10-03T04:57:06.239Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "Owner directive 2026-10-03: maxContextTokens must be REAL ENFORCEMENT (harness-level constraint at the configured ceiling), chosen explicitly over display-only clamping — prior ''cap'' semantics (registry label, no consumer, no enforcement) are insufficient. Design must include meter truth (display max = min(runtime, cap)) so enforcement is verifiable, and must honestly document non-enforceable harnesses (claude CLI has no known external context-limit knob — to be proven/disproven in Phase A).", "rationale": "", "source": "leader", "irreversible": false, "author": "b7bec94b-5394-453f-987a-6cb49107ad71"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b29fda6b03', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T05:05:57.980Z', 'Owner directive 2026-10-03 (verbatim): ''the implement prefix for sub provider -> should break list models into sub-provider below the prefix setting. fix it deploy to paseo TEST.'' — the provider sheet''s flat models list becomes per-sub-provider groups rendered below each sub-provider''s prefix section; TEST deploy required (web-only pipeline stages expected).', '', 'owner-directive', 0, 'b7bec94b-5394-453f-987a-6cb49107ad71', '{"id": "d-b29fda6b03", "ts": "2026-10-03T05:05:57.980Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "Owner directive 2026-10-03 (verbatim): ''the implement prefix for sub provider -> should break list models into sub-provider below the prefix setting. fix it deploy to paseo TEST.'' — the provider sheet''s flat models list becomes per-sub-provider groups rendered below each sub-provider''s prefix section; TEST deploy required (web-only pipeline stages expected).", "rationale": "", "source": "owner-directive", "irreversible": false, "author": "b7bec94b-5394-453f-987a-6cb49107ad71"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-72e6179469', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T05:21:53.122Z', 'SHARED-FILE ANNOUNCE + HANDOFF (lane rule d-12a0c8b77a). T13 code half COMPLETE on feat/t13-subprovider-model-groups: d3e62e1e6 / 768370583 / d67e1cdb2 off 6927d72ac, tree clean, no PR.
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-b727f6ee85', 'p-b5bd663dcf', 't-a124729a8a', '2026-10-03T05:26:12.576Z', 'RULED THE COLLECTOR''S HYPOTHESIS OUT, CORRECTED MY OWN LAST TURN, AND PERSISTED THE WORK OUT OF THIS SESSION. The collector proposed that a second leader editing the same checkout caused both the base divergence and the duplicated FoldState, and framed it as a hypothesis to test cheaply. I tested it against committed objects rather than the working tree. Each committed ledger-screen.tsx declares FoldState exactly ONCE: mine at :37, base at :33, common ancestor 870b21495 at :26. Base b7c5b81e0 is internally consistent, with 9 closedTurns/ALL_OPEN references and 0 openTurns references, so it is a coherent committed file and not a half-edited working tree. And b7c5b81e0 is a published commit contained on ci-freebuff-baseline, env/p0-sdk-integration, feat/t10, feat/t11 and feat/t12. Conclusion: the base is clean and the duplication was produced by git''s merge, which landed base''s declaration in a region my branch never touched while the copy inside the conflicted region was resolved separately. Dead end, correctly framed as a hypothesis by the collector. Incidental correction while testing: env/p0-sdk-integration DOES exist locally and contains b7c5b81e0. I had earlier recorded it as absent from this remote, which was wrong, and it is the likely PROD integration branch. SECOND, I CORRECTED MY OWN LAST TURN. n34 described two open owner questions. It is one. Keying is forced, not chosen: S4 prepends older history, turn numbers renumber on prepend, and the base keys closedTurns by turn.turn, so a collapsed turn''s state would migrate to whichever turn slid into its slot. The only genuine product call is the default presentation, and it has an asymmetry that should settle it: PROD already ships all-open, while PR #30 silently flips it to all-folded, so adopting all-open changes no shipped behaviour AND fixes a real defect in my own lane, namely that an open-set seeded at mount leaves every turn arriving afterwards collapsed. I recommend all-open, with the caveat already recorded that S4''s load-older control was designed for the folded presentation. THIRD, AND THIS IS THE POINT THE COLLECTOR WAS RIGHT ABOUT: the collector noted my track had been at n34 for three wakes while a full night of work reached it only as prose. That is correct and it is the second time this session I have let durable knowledge live only in a session. I have now written the complete resolution knowledge into task-c90d30c62b: every per-hunk resolution for all five files, the FoldState migration from open-tracking to closed-tracking keyed by identity, the decision to keep calibrated heights and getItemLayout and followRef while adopting the Setup-bucket numbering, the note that their recordId fix supersedes mine and why, the additive resolutions for the other files, the fact that I completed and structurally verified the 13-hunk resolution before destroying it with an abort-and-remerge cycle, and the two process lessons including that git add on marker-bearing files clears the conflict flag while keeping the markers so git reported zero conflicted files and typecheck caught 29 TS1185 errors. A fresh session can now finish this in one pass without redoing the analysis. STATE IS HONEST AND UNCHANGED WHERE IT MATTERS: tree clean at 08339ff37, backup ref backup/render-list-08339ff37 intact, PR #30 untouched, nothing deployed, and GitHub now reporting mergeable=CONFLICTING mergeState=DIRTY which matches the merge-tree prediction made before it happened. The paging truncation defect remains live in PROD.', '', 'leader', 0, 'e6e9642e-6e48-4b67-8773-3dd3967b9f1a', '{"id": "d-b727f6ee85", "ts": "2026-10-03T05:26:12.576Z", "track_id": "t-a124729a8a", "project_id": "p-b5bd663dcf", "decision": "RULED THE COLLECTOR''S HYPOTHESIS OUT, CORRECTED MY OWN LAST TURN, AND PERSISTED THE WORK OUT OF THIS SESSION. The collector proposed that a second leader editing the same checkout caused both the base divergence and the duplicated FoldState, and framed it as a hypothesis to test cheaply. I tested it against committed objects rather than the working tree. Each committed ledger-screen.tsx declares FoldState exactly ONCE: mine at :37, base at :33, common ancestor 870b21495 at :26. Base b7c5b81e0 is internally consistent, with 9 closedTurns/ALL_OPEN references and 0 openTurns references, so it is a coherent committed file and not a half-edited working tree. And b7c5b81e0 is a published commit contained on ci-freebuff-baseline, env/p0-sdk-integration, feat/t10, feat/t11 and feat/t12. Conclusion: the base is clean and the duplication was produced by git''s merge, which landed base''s declaration in a region my branch never touched while the copy inside the conflicted region was resolved separately. Dead end, correctly framed as a hypothesis by the collector. Incidental correction while testing: env/p0-sdk-integration DOES exist locally and contains b7c5b81e0. I had earlier recorded it as absent from this remote, which was wrong, and it is the likely PROD integration branch. SECOND, I CORRECTED MY OWN LAST TURN. n34 described two open owner questions. It is one. Keying is forced, not chosen: S4 prepends older history, turn numbers renumber on prepend, and the base keys closedTurns by turn.turn, so a collapsed turn''s state would migrate to whichever turn slid into its slot. The only genuine product call is the default presentation, and it has an asymmetry that should settle it: PROD already ships all-open, while PR #30 silently flips it to all-folded, so adopting all-open changes no shipped behaviour AND fixes a real defect in my own lane, namely that an open-set seeded at mount leaves every turn arriving afterwards collapsed. I recommend all-open, with the caveat already recorded that S4''s load-older control was designed for the folded presentation. THIRD, AND THIS IS THE POINT THE COLLECTOR WAS RIGHT ABOUT: the collector noted my track had been at n34 for three wakes while a full night of work reached it only as prose. That is correct and it is the second time this session I have let durable knowledge live only in a session. I have now written the complete resolution knowledge into task-c90d30c62b: every per-hunk resolution for all five files, the FoldState migration from open-tracking to closed-tracking keyed by identity, the decision to keep calibrated heights and getItemLayout and followRef while adopting the Setup-bucket numbering, the note that their recordId fix supersedes mine and why, the additive resolutions for the other files, the fact that I completed and structurally verified the 13-hunk resolution before destroying it with an abort-and-remerge cycle, and the two process lessons including that git add on marker-bearing files clears the conflict flag while keeping the markers so git reported zero conflicted files and typecheck caught 29 TS1185 errors. A fresh session can now finish this in one pass without redoing the analysis. STATE IS HONEST AND UNCHANGED WHERE IT MATTERS: tree clean at 08339ff37, backup ref backup/render-list-08339ff37 intact, PR #30 untouched, nothing deployed, and GitHub now reporting mergeable=CONFLICTING mergeState=DIRTY which matches the merge-tree prediction made before it happened. The paging truncation defect remains live in PROD.", "rationale": "", "source": "leader", "irreversible": false, "author": "e6e9642e-6e48-4b67-8773-3dd3967b9f1a"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-f2bbbfcd54', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T06:50:17.917Z', 'Mirror opencode''s own catalog limit.output into the fragment; skip a model with no usable output limit rather than inventing one.', 'The schema has no default for `output` - it is required, not defaulted - so the only non-inverted source is the value opencode itself resolves for that model. Empirically confirmed several real catalog models already ship output >= context (grok-4.7 500000/500000, space-bunny-free 1048576/524288), so mirroring is consistent with opencode''s own data while a clamp would invent a value opencode never had.', 'leader', 0, '0ff28a85-9de1-44af-baa9-84cf76a60d0d', '{"id": "d-f2bbbfcd54", "ts": "2026-10-03T06:50:17.917Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "Mirror opencode''s own catalog limit.output into the fragment; skip a model with no usable output limit rather than inventing one.", "rationale": "The schema has no default for `output` - it is required, not defaulted - so the only non-inverted source is the value opencode itself resolves for that model. Empirically confirmed several real catalog models already ship output >= context (grok-4.7 500000/500000, space-bunny-free 1048576/524288), so mirroring is consistent with opencode''s own data while a clamp would invent a value opencode never had.", "source": "leader", "irreversible": false, "author": "0ff28a85-9de1-44af-baa9-84cf76a60d0d"}');
INSERT INTO orch_decisions(id, project_id, track_id, ts, decision, rationale, source, irreversible, author, payload) VALUES('d-a8766651a9', 'p-b5bd663dcf', 't-f3ba82ac9c', '2026-10-03T07:44:29.936Z', 'Keep the provider-wide modelPrefix fallback chain intact; the field removal is visual only.', 'resolveModelPrefixTags is perSubProvider ?? providerWide, so a saved global tag keeps decorating rows with no per-sub tag; deleting the read path would orphan saved values, which req 2 forbids. No COMPAT tag needed — schema and config key unchanged, only a UI affordance went away.', 'leader', 0, '2eb265f4-6ec0-49f5-97f4-52a1a4b161df', '{"id": "d-a8766651a9", "ts": "2026-10-03T07:44:29.936Z", "track_id": "t-f3ba82ac9c", "project_id": "p-b5bd663dcf", "decision": "Keep the provider-wide modelPrefix fallback chain intact; the field removal is visual only.", "rationale": "resolveModelPrefixTags is perSubProvider ?? providerWide, so a saved global tag keeps decorating rows with no per-sub tag; deleting the read path would orphan saved values, which req 2 forbids. No COMPAT tag needed — schema and config key unchanged, only a UI affordance went away.", "source": "leader", "irreversible": false, "author": "2eb265f4-6ec0-49f5-97f4-52a1a4b161df"}');
